<body>
  <div id="sysbox-console">
    <div class="sysbox-header">
      <div class="sysbox-title">
        ⚙ 系统变量配置
        <small>SYSBOX CONFIG</small>
      </div>
      <span class="sysbox-badge">v2.0</span>
    </div>

    <div class="module-tabs">
      <div class="module-tab active" data-module="character">🧑 角色编辑</div>
      <div class="module-tab" data-module="story">📖 剧情相关</div>
      <div class="module-tab" data-module="combat">⚔ 战斗系统</div>
      <div class="module-tab" data-module="grade">⚙ 等级配置</div>
      <div class="module-tab" data-module="template">📋 模板导入</div>
    </div>

    <!-- ========== 角色编辑 面板 ========== -->
    <div id="panel-character" class="config-panel active">
      <div class="char-select-row">
        <select id="char-select"></select>
        <span class="char-type-badge" id="char-type-badge">主角</span>
        <button class="char-create-btn" id="char-create-btn">➕ 新建角色</button>
      </div>

      <!-- 创建角色对话框（默认隐藏） -->
      <div class="create-dialog" id="create-dialog" style="display:none;">
        <div class="form-row">
          <label>姓名</label>
          <input type="text" id="create-name" placeholder="输入角色姓名" style="width:200px;" />
        </div>
        <div class="form-row">
          <label>类型</label>
          <select id="create-type">
            <option value="冒险者">冒险者</option>
            <option value="NPC">NPC</option>
            <option value="异端儿">异端儿</option>
          </select>
        </div>
        <div class="dialog-btns">
          <button class="dialog-btn-ok" id="create-ok">✓ 创建</button>
          <button class="dialog-btn-cancel" id="create-cancel">取消</button>
        </div>
      </div>

      <!-- 基础信息 -->
      <div class="section-header"><span class="icon">📋</span> 基础信息</div>
      <div class="field-grid" id="basic-grid">
        <div class="field-item"><label>姓名</label><input type="text" id="f-name" data-types="*" /></div>
        <div class="field-item"><label>类型</label><input type="text" id="f-type" data-types="*" readonly /></div>
        <div class="field-item"><label>种族</label><input type="text" id="f-race" data-types="*" /></div>
