        <span class="save-status" id="save-status"></span>
      </div>
      <div class="save-error-msg" id="save-error-msg" style="display:none;"></div>
      📌 sysbox 系统变量容器 — 存储游戏引擎配置，由前端脚本维护，AI 不应直接修改<br />
      修改后点击「保存全部配置」即写入当前楼层变量
    </div>
  </div>

  <script>
    (async function () {
      await waitGlobalInitialized("Mvu");
      await waitGlobalInitialized("DungeonUtils");

      // 统一数据写回：优先使用 CommandUtils.saveData（含 recalc），回退到 replaceMvuData
      async function saveData(vars, opts) {
        var C = window.top.CommandUtils || window.CommandUtils;
        if (C && C.saveData) {
          return await C.saveData(vars, opts);
        }
        return await Mvu.replaceMvuData(vars, opts);
      }

      // ── DOM 引用 ──
      const featDivisor = document.getElementById("feat-divisor");
      const overlevelBonus = document.getElementById("overlevel-bonus");
      const manualReview = document.getElementById("manual-review");
      const tierTbody = document.getElementById("tier-tbody");
      const addTierBtn = document.getElementById("add-tier-btn");
      const floorTbody = document.getElementById("floor-tbody");
      const addFloorBtn = document.getElementById("add-floor-btn");
      const levelCoeff = document.getElementById("level-coeff");
      const levelExample = document.getElementById("level-example");
      const rarityCommonCoeff = document.getElementById("rarity-common-coeff");
      const rarityCommonProb = document.getElementById("rarity-common-prob");
      const rarityEliteCoeff = document.getElementById("rarity-elite-coeff");
      const rarityEliteProb = document.getElementById("rarity-elite-prob");
      const rarityVariantCoeff = document.getElementById("rarity-variant-coeff");
      const rarityVariantProb = document.getElementById("rarity-variant-prob");
      const rarityLordCoeff = document.getElementById("rarity-lord-coeff");

      const saveBtn = document.getElementById("save-btn");
      const saveStatus = document.getElementById("save-status");
      const saveErrorMsg = document.getElementById("save-error-msg");
      const skillGradeTbody = document.getElementById("skill-grade-tbody");
      const equipQualityTbody = document.getElementById("equip-quality-tbody");
      const consumableQualityTbody = document.getElementById("consumable-quality-tbody");

      // ── 角色编辑器 DOM 引用 ──
      const charSelect = document.getElementById("char-select");
      const charTypeBadge = document.getElementById("char-type-badge");
      const charCreateBtn = document.getElementById("char-create-btn");
      const createDialog = document.getElementById("create-dialog");
      const createName = document.getElementById("create-name");
      const createType = document.getElementById("create-type");
      const createOk = document.getElementById("create-ok");
      const createCancel = document.getElementById("create-cancel");

      // 装备子表单
      const eqName = document.getElementById("eq-name");
      const eqQuality = document.getElementById("eq-quality");
      const eqSlot = document.getElementById("eq-slot");
      const eqDims = document.getElementById("eq-dims");
      const eqPreview = document.getElementById("eq-preview");
      const eqGenerateBtn = document.getElementById("eq-generate-btn");
      const equipSelect = document.getElementById("equip-select");
      const equipEditCard = document.getElementById("equip-edit-card");

      // 技能子表单
      const skName = document.getElementById("sk-name");
      const skType = document.getElementById("sk-type");
      const skGrade = document.getElementById("sk-grade");
      const skSkilltype = document.getElementById("sk-skilltype");
      const skDims = document.getElementById("sk-dims");
      const skDesc = document.getElementById("sk-desc");
      const skPreview = document.getElementById("sk-preview");
      const skGenerateBtn = document.getElementById("sk-generate-btn");
      const skActiveRows = document.getElementById("sk-active-rows");
      const skillSelect = document.getElementById("skill-select");
      const skillEditCard = document.getElementById("skill-edit-card");

      const inventoryContainer = document.getElementById("inventory-container");
      const inventoryHeader = document.getElementById("inventory-header");

      // Form field IDs for quick access
      const FORM_IDS = {
        name: "f-name", type: "f-type", race: "f-race", gender: "f-gender",
        personality: "f-personality", appearance: "f-appearance", hair: "f-hair",
        build: "f-build", outfit: "f-outfit", aura: "f-aura", savings: "f-savings",
        negStatus: "f-neg-status", rarity: "f-rarity", title: "f-title",
        hpmax: "s-hpmax", hpcur: "s-hpcur", spmax: "s-spmax", spcur: "s-spcur",
        mpmax: "s-mpmax", mpcur: "s-mpcur", mood: "s-mood", location: "s-location",
        rep: "s-rep", rest: "s-rest", purity: "s-purity",
        body: "s-body", eval: "s-eval",
        relation: "r-relation", affection: "r-affection",
        level: "a-level", grade: "a-grade", feat: "a-feat",
        familia: "a-familia", jobs: "a-jobs", floor: "a-floor", polian: "a-polian",
      };

      // ── 角色编辑器 缓存 ──
      var _characterEditCache = {};
      var _currentCharKey = null;
      var _currentCharType = null;
      var _allCharacters = null; // { 主角, 人物名录 } from MVU
      var _charNameList = []; // [{name, type, key}]

      const FIVE_STATS = ["力量","耐力","灵巧","敏捷","魔力"];

      // ── 工具函数 ──
      function readNumInput(inp) {
        const raw = inp.value.trim();
        if (raw === "") return null;
        const num = parseFloat(raw);
        return isNaN(num) ? null : num;
      }

      // ---------- 通用组件：带兜底的多行配置（对象数组，每项有 是否兜底） ----------
      /**
       * 创建数值输入框（带保留一位小数逻辑）
       */
      function createNumberInput(value, step = "0.1") {
        const inp = document.createElement("input");
        inp.type = "number";
        inp.step = step;
        inp.className = "num-input";
        inp.style.width = "70px";
        inp.value = value != null ? value : 0;
        inp.addEventListener("input", function () {
          const raw = this.value;
          if (raw === "") return;
          const num = parseFloat(raw);
          if (!isNaN(num)) this.value = step === "1" ? Math.round(num) : Math.round(num * 10) / 10;
        });
        inp.addEventListener("blur", function () {
          const num = parseFloat(this.value);
          if (isNaN(num)) this.value = 0;
        });
        return inp;
      }

      /**
       * 创建删除按钮（不可用于兜底行）
       */
      function createDelBtn(onClick) {
        const btn = document.createElement("button");
        btn.className = "del-btn";
        btn.textContent = "✕";
        btn.addEventListener("click", onClick);
        return btn;
      }

      // ---------- 战斗系统：颜色档位（无兜底） ----------
      function createTierRow(tier) {
        const tr = document.createElement("tr");
        const tdName = document.createElement("td");
        const nameInput = document.createElement("input");
        nameInput.type = "text"; nameInput.className = "text-input"; nameInput.style.width = "100%";
        nameInput.value = tier.颜色名 || ""; nameInput.dataset.key = "颜色名";
        tdName.appendChild(nameInput); tr.appendChild(tdName);

        const tdColor = document.createElement("td");
        const colorPicker = document.createElement("input");
        colorPicker.type = "color"; colorPicker.className = "color-input";
        colorPicker.value = tier.颜色值 || "#667788"; colorPicker.dataset.key = "颜色值";
        tdColor.appendChild(colorPicker); tr.appendChild(tdColor);

        const tdLabel = document.createElement("td");
        const labelInput = document.createElement("input");
        labelInput.type = "text"; labelInput.className = "text-input"; labelInput.style.width = "100%";
        labelInput.value = tier.难度名称 || ""; labelInput.dataset.key = "难度名称";
        tdLabel.appendChild(labelInput); tr.appendChild(tdLabel);

        const tdRatio = document.createElement("td");
        const ratioInput = document.createElement("input");
        ratioInput.type = "number"; ratioInput.className = "num-input"; ratioInput.step = "0.1";
        ratioInput.value = tier.战损比最低 != null ? tier.战损比最低 : 0; ratioInput.dataset.key = "战损比最低";
        tdRatio.appendChild(ratioInput); tr.appendChild(tdRatio);

        const tdExp = document.createElement("td");
        const expWrap = document.createElement("div");
        expWrap.style.display = "flex"; expWrap.style.alignItems = "center"; expWrap.style.gap = "4px";
        const expMin = document.createElement("input");
        expMin.type = "number"; expMin.className = "number-range"; expMin.step = "1"; expMin.min = 0;
        expMin.value = tier.经验值最低 != null ? tier.经验值最低 : 1; expMin.dataset.key = "经验值最低";
        const expSep = document.createElement("span"); expSep.textContent = "~"; expSep.style.color = "var(--text-dim)"; expSep.style.fontSize = "12px";
        const expMax = document.createElement("input");
        expMax.type = "number"; expMax.className = "number-range"; expMax.step = "1"; expMax.min = 0;
        expMax.value = tier.经验值最高 != null ? tier.经验值最高 : 1; expMax.dataset.key = "经验值最高";
        expWrap.appendChild(expMin); expWrap.appendChild(expSep); expWrap.appendChild(expMax);
        tdExp.appendChild(expWrap); tr.appendChild(tdExp);

        const tdDel = document.createElement("td");
        const delBtn = createDelBtn(() => tr.remove());
        tdDel.appendChild(delBtn); tr.appendChild(tdDel);

        return tr;
      }

      function renderTiers(tiers) {
        tierTbody.innerHTML = "";
        if (!tiers || tiers.length === 0) return;
        tiers.forEach(tier => tierTbody.appendChild(createTierRow(tier)));
      }

      function addTierRow() {
        const defaultTier = {
          颜色名: "新档位",
          颜色值: "#667788",
          难度名称: "新难度",
          战损比最低: 1.0,
          经验值最低: 1,
          经验值最高: 1,
        };
        tierTbody.appendChild(createTierRow(defaultTier));
      }

      // ---------- 楼层补正（已有兜底，保持原有清晰实现） ----------
      function createFloorRow(row, isCatchall) {
        const tr = document.createElement("tr");
        if (isCatchall) tr.style.background = "rgba(212, 168, 83, 0.06)";

        const tdMin = document.createElement("td");
        const minInput = createNumberInput(row.层数最低 ?? 0, "1");
        minInput.dataset.key = "层数最低";
        tdMin.appendChild(minInput); tr.appendChild(tdMin);

        const tdMax = document.createElement("td");
        const maxInput = createNumberInput(row.层数最高 ?? 10, "1");
        maxInput.dataset.key = "层数最高";
        if (isCatchall) { maxInput.disabled = true; maxInput.value = 9999; }
        tdMax.appendChild(maxInput); tr.appendChild(tdMax);

        const tdVal = document.createElement("td");
        const valInput = createNumberInput(row.补正值 ?? 1.0, "0.01");
        valInput.dataset.key = "补正值";
        tdVal.appendChild(valInput); tr.appendChild(tdVal);

        const tdDel = document.createElement("td");
        if (!isCatchall) {
          const delBtn = createDelBtn(() => tr.remove());
          tdDel.appendChild(delBtn);
        } else {
          const span = document.createElement("span");
          span.style.color = "var(--text-dim)";
          span.style.fontSize = "11px";
          span.textContent = "兜底";
          tdDel.appendChild(span);
          tr.dataset.catchall = "true";
        }
        tr.appendChild(tdDel);
        return tr;
      }

      function renderFloorRows(rows) {
        floorTbody.innerHTML = "";
        if (!rows || rows.length === 0) return;
        const normal = rows.filter(r => !r.是否兜底);
        const catchall = rows.filter(r => r.是否兜底);
        normal.forEach(r => floorTbody.appendChild(createFloorRow(r, false)));
        catchall.forEach(r => floorTbody.appendChild(createFloorRow(r, true)));
      }

      function addFloorRow() {
        const defaultFloor = { 层数最低: 0, 层数最高: 10, 补正值: 1.0 };
        const newRow = createFloorRow(defaultFloor, false);
        // 插入到兜底行之前
        const catchallRow = floorTbody.querySelector("tr[data-catchall='true']");
        if (catchallRow) {
          floorTbody.insertBefore(newRow, catchallRow);
        } else {
          floorTbody.appendChild(newRow);
        }
      }

      function collectFloor() {
        const rows = floorTbody.querySelectorAll("tr");
        const result = [];
        rows.forEach(tr => {
          const inputs = tr.querySelectorAll("input");
          const row = {};
          inputs.forEach(inp => { if (inp.dataset.key) row[inp.dataset.key] = readNumInput(inp); });
          row.是否兜底 = tr.dataset.catchall === "true" || undefined;
          result.push(row);
        });
        return result;
      }

      // ---------- 收集完整剧情/战斗表单 ----------
      function collectStoryForm() {
        return {
          剧情相关: {
            伟业换算: parseInt(featDivisor.value, 10) || 100,
            越级经验补偿: parseInt(overlevelBonus.value, 10) || 500,
            手动审查: manualReview.checked,
            每步时间: parseInt(document.getElementById("step-time").value, 10) || 1,
            每轮战斗时间: parseInt(document.getElementById("combat-time").value, 10) || 5,
          },
        };
      }

      function collectCombatForm() {
        const 等级补正 = { 等级系数: readNumInput(levelCoeff) || 1000 };
        const 楼层补正 = collectFloor();
        const 稀有度补正 = {
          普通: { 系数: readNumInput(rarityCommonCoeff) || 1, 概率: parseInt(rarityCommonProb.value, 10) || 75 },
          精英: { 系数: readNumInput(rarityEliteCoeff) || 1.2, 概率: parseInt(rarityEliteProb.value, 10) || 20 },
          变异: { 系数: readNumInput(rarityVariantCoeff) || 1.5, 概率: parseInt(rarityVariantProb.value, 10) || 5 },
          楼层主: { 系数: readNumInput(rarityLordCoeff) || 2.0 },
        };
        const 颜色档位 = [];
        tierTbody.querySelectorAll("tr").forEach(tr => {
          const inputs = tr.querySelectorAll("input, select");
          const tier = {};
          inputs.forEach(inp => {
            const key = inp.dataset.key;
            if (!key) return;
            tier[key] = inp.type === "number" ? readNumInput(inp) : inp.value;
          });
          if (tier.颜色名) 颜色档位.push(tier);
        });
        return { 战斗系统: { 颜色档位, 等级补正, 楼层补正, 稀有度补正 } };
      }

      // ---------- 等级配置渲染 ----------
      const SKILL_GRADES = ["I","H","G","F","E","D","C","B","A","S","SS","SSS"];
      const SKILL_FIELDS = ["加成最低","加成最高","伤害比例最低","伤害比例最高","消耗MP最低","消耗MP最高","消耗SP最低","消耗SP最高","回复HP最低","回复HP最高","回复SP最低","回复SP最高","回复MP最低","回复MP最高"];
      const EQUIP_TIERS = [1,2,3,4,5];
      const EQUIP_FIELDS = ["加成最低","加成最高"];
      const CONSUMABLE_TIERS = [1,2,3,4,5];
      const CONSUMABLE_FIELDS = ["回复HP","回复SP","回复MP"];

      function renderSkillGradeTable(cfg) {
        skillGradeTbody.innerHTML = "";
        SKILL_GRADES.forEach((grade) => {
          const row = cfg && cfg[grade] ? cfg[grade] : {};
          const tr = document.createElement("tr");
          const tdGrade = document.createElement("td");
          tdGrade.textContent = grade;
          tdGrade.style.fontWeight = "700";
          tr.appendChild(tdGrade);
          SKILL_FIELDS.forEach((field) => {
            const td = document.createElement("td");
            const inp = document.createElement("input");
            inp.type = "number";
            inp.step = "0.01";
            inp.min = "0";
            inp.className = "num-input";
            inp.style.width = "68px";
            // 根据字段类型设置 max 约束（与 zod schema 一致）
            if (field.startsWith("伤害比例")) inp.max = "10";
            else if (field.startsWith("消耗MP") || field.startsWith("消耗SP")) inp.max = "1";
            else if (field.startsWith("回复HP") || field.startsWith("回复SP") || field.startsWith("回复MP")) inp.max = "10";
            inp.value = row[field] != null ? row[field] : 0;
            inp.dataset.grade = grade;
            inp.dataset.field = field;
            td.appendChild(inp);
            tr.appendChild(td);
          });
          skillGradeTbody.appendChild(tr);
        });
      }

      function renderEquipQualityTable(cfg) {
        equipQualityTbody.innerHTML = "";
        EQUIP_TIERS.forEach((tier) => {
          const row = cfg && cfg[tier] ? cfg[tier] : {};
          const tr = document.createElement("tr");
          const tdTier = document.createElement("td");
          tdTier.textContent = tier;
          tdTier.style.fontWeight = "700";
          tr.appendChild(tdTier);
          EQUIP_FIELDS.forEach((field) => {
            const td = document.createElement("td");
            const inp = document.createElement("input");
            inp.type = "number";
            inp.step = "0.01";
            inp.min = "0";
            inp.className = "num-input";
            inp.style.width = "68px";
            inp.value = row[field] != null ? row[field] : 0;
            inp.dataset.tier = tier;
            inp.dataset.field = field;
            td.appendChild(inp);
            tr.appendChild(td);
          });
          equipQualityTbody.appendChild(tr);
        });
      }

      function renderConsumableQualityTable(cfg) {
        consumableQualityTbody.innerHTML = "";
        CONSUMABLE_TIERS.forEach((tier) => {
          const row = cfg && cfg[tier] ? cfg[tier] : {};
          const tr = document.createElement("tr");
          const tdTier = document.createElement("td");
          tdTier.textContent = tier;
          tdTier.style.fontWeight = "700";
          tr.appendChild(tdTier);
          CONSUMABLE_FIELDS.forEach((field) => {
            const td = document.createElement("td");
            const inp = document.createElement("input");
            inp.type = "number";
            inp.step = "0.01";
            inp.min = "0";
            inp.max = "1";
            inp.className = "num-input";
            inp.style.width = "72px";
            inp.value = row[field] != null ? row[field] : 0;
            inp.dataset.tier = tier;
            inp.dataset.field = field;
            td.appendChild(inp);
            tr.appendChild(td);
          });
          consumableQualityTbody.appendChild(tr);
        });
      }

      function collectGradeForm() {
        const skillCfg = {};
        skillGradeTbody.querySelectorAll("tr").forEach((tr) => {
          const inputs = tr.querySelectorAll("input");
          const grade = inputs[0].dataset.grade;
          const entry = {};
          inputs.forEach((inp) => { entry[inp.dataset.field] = parseFloat(inp.value) || 0; });
          skillCfg[grade] = entry;
        });
        const equipCfg = {};
        equipQualityTbody.querySelectorAll("tr").forEach((tr) => {
          const inputs = tr.querySelectorAll("input");
          const tier = parseInt(inputs[0].dataset.tier, 10);
          const entry = {};
          inputs.forEach((inp) => { entry[inp.dataset.field] = parseFloat(inp.value) || 0; });
          equipCfg[tier] = entry;
        });
        const consumableCfg = {};
        consumableQualityTbody.querySelectorAll("tr").forEach((tr) => {
          const inputs = tr.querySelectorAll("input");
          const tier = parseInt(inputs[0].dataset.tier, 10);
          const entry = {};
          inputs.forEach((inp) => { entry[inp.dataset.field] = parseFloat(inp.value) || 0; });
          consumableCfg[tier] = entry;
        });
        return {
          技能系统: { 等级配置: skillCfg },
          装备系统: { 品质配置: equipCfg },
          消耗品系统: { 品质配置: consumableCfg },
        };
      }

      // ──────────── 角色编辑器 核心函数 ────────────

      function getEl(id) { return document.getElementById(id); }
      function readField(id) { const el = getEl(id); return el ? el.value : ""; }
      function writeField(id, val) { const el = getEl(id); if (el) el.value = val != null ? val : ""; }
      function readNumField(id) { const v = parseFloat(readField(id)); return isNaN(v) ? 0 : v; }

      function readFiveDim(className) {
        const obj = {};
        document.querySelectorAll("." + className).forEach(inp => {
          obj[inp.dataset.stat] = parseFloat(inp.value) || 0;
        });
        return obj;
      }
      function writeFiveDim(className, obj) {
        document.querySelectorAll("." + className).forEach(inp => {
          inp.value = (obj && obj[inp.dataset.stat] != null) ? obj[inp.dataset.stat] : 0;
        });
      }

      function detectCharType(char) {
        const t = char?.基础信息?.类型 || "NPC";
        // 类型为"怪物"且有"关系"字段的为异端儿（FriendlyMonsterSchema）
        if (t === "怪物" && char?.关系) return "异端儿";
        // 兼容旧数据：类型被错误地存为"异端儿"
        if (t === "异端儿") return "异端儿";
        return t;
      }

      function applyFieldLocking(type) {
        _currentCharType = type;
        // 所有带 data-types 的字段
        document.querySelectorAll("#panel-character [data-types]").forEach(el => {
          const allowed = el.dataset.types.split(",");
          el.disabled = !allowed.includes("*") && !allowed.includes(type);
        });

        // 区块显隐
        // 关系区：非主角显示
        const showRelation = type !== "主角";
        getEl("relation-header").style.display = showRelation ? "" : "none";
        getEl("relation-grid").style.display = showRelation ? "" : "none";

        // 个人属性区：NPC 只显示所属眷族/身份职业/到达层数（无五维），异端儿无潜在/积累经验值/当前伟业/所属眷族/身份职业/到达层数
        const showAttr = type !== "NPC";
        const isXeno = type === "异端儿";
        getEl("attr-header").style.display = "";
        // attr-top-grid: 全类型显示（data-types 控制单个字段）
        document.querySelectorAll("#base-grid, #potential-grid, #exp-grid").forEach(g => { g.style.display = showAttr ? "" : "none"; });
        getEl("potential-grid").style.display = (showAttr && !isXeno) ? "" : "none";
        getEl("exp-grid").style.display = (showAttr && !isXeno) ? "" : "none";
        // 异端儿隐藏：潜在能力、积累经验值、当前伟业、所属眷族、身份职业、到达层数
        // NPC 额外隐藏：当前伟业
        ["familia-item","jobs-item","floor-item"].forEach(id => {
          const el = getEl(id);
          if (el) el.style.display = isXeno ? "none" : "";
        });
        if (getEl("feat-item")) getEl("feat-item").style.display = (isXeno || type === "NPC") ? "none" : "";
        document.querySelectorAll(".five-title").forEach(el => {
          const d5 = el.dataset.five;
          if (d5 === "base") {
            el.style.display = showAttr ? "" : "none";
          } else if (d5 === "potential" || d5 === "exp") {
            el.style.display = (showAttr && !isXeno) ? "" : "none";
          }
        });

        // 称号：仅主角
        getEl("title-section").style.display = type === "主角" ? "" : "none";

        // 稀有度：仅异端儿
        getEl("rarity-item").style.display = type === "异端儿" ? "" : "none";

        // 主角专属状态
        ["rep-item","rest-item","purity-item"].forEach(id => {
          getEl(id).style.display = type === "主角" ? "" : "none";
        });
        // 身体状况/评价：仅冒险者/NPC 有（异端儿也用 StateCoreSchema，无此二字段）
        ["body-item","eval-item"].forEach(id => {
          getEl(id).style.display = (type === "冒险者" || type === "NPC") ? "" : "none";
        });

        // 经验权重：主角 + 冒险者 + 异端儿
        getEl("weight-section").style.display = (type === "主角" || type === "冒险者" || type === "异端儿") ? "" : "none";
        // 成长期望：仅冒险者
        getEl("growth-section").style.display = type === "冒险者" ? "" : "none";
        // 破限：主角 + 冒险者
        getEl("a-polian-item").style.display = (type === "主角" || type === "冒险者") ? "" : "none";

        // 潜在能力：冒险者自动计算（zod transform: floor((lv-1)*成长期望/2)），设为只读
        document.querySelectorAll(".five-pot").forEach(el => {
          el.readOnly = type === "冒险者";
          el.style.opacity = type === "冒险者" ? "0.6" : "";
        });

        // 持有物品：全类型统一
        inventoryHeader.style.display = "";

        // 技能列表：全类型均有（BaseInfoSchema 含 技能列表）

        // 类型标签
        charTypeBadge.textContent = type;
      }

      // ── 构建装备索引（装备栏 + 持有物品中的装备）──
      function buildEquipIndex(char) {
        const list = [];
        const equip = char.装备栏 || {};
        ["主手","副手","头部","身体","护手","鞋子","饰品1","饰品2"].forEach(slot => {
          const item = equip[slot];
          if (item?.名称) list.push({ key: "eq:" + slot, label: "[" + slot + "] " + item.名称, item, source: "装备栏", slot: slot });
        });
        (equip.特殊 || []).forEach((item, i) => {
          if (item?.名称) list.push({ key: "eq:特殊:" + i, label: "[特殊] " + item.名称, item, source: "装备栏", slot: "特殊", idx: i });
        });
        const inv = char.持有物品 || {};
        Object.keys(inv).forEach(name => {
          const item = inv[name];
          if (item && (item.类别 === "装备" || item.装备属性)) {
            list.push({ key: "inv:" + name, label: "[持有] " + name, item, source: "持有物品", invName: name });
          }
        });
        return list;
      }

      // ── 填充装备下拉框 ──
      function populateEquipSelect(char) {
        const list = buildEquipIndex(char);
        const curVal = equipSelect.value;
        equipSelect.innerHTML = '<option value="">-- 选择装备 --</option>';
        list.forEach(entry => {
          const opt = document.createElement("option");
          opt.value = entry.key;
          opt.textContent = entry.label;
          equipSelect.appendChild(opt);
        });
        // 恢复选中（如果之前选中的装备还存在）
        if (curVal && list.some(e => e.key === curVal)) equipSelect.value = curVal;
      }

      // ── 渲染装备编辑卡片 ──
      function renderEquipCard(key) {
        if (!key) { equipEditCard.style.display = "none"; return; }
        const char = _characterEditCache[_currentCharKey];
        if (!char) return;
        const list = buildEquipIndex(char);
        const entry = list.find(e => e.key === key);
        if (!entry) { equipEditCard.style.display = "none"; return; }

        const item = entry.item;
        const bonus = item.装备属性?.加成 || {};
        const slot = item.装备属性?.部位 || "主手";
        let bonusHtml = '<div style="font-size:11px;color:var(--text-dim);margin:8px 0 4px;">加成</div>';
        FIVE_STATS.forEach(stat => {
          const has = bonus[stat] != null;
          bonusHtml += '<div class="bonus-row" data-eb-row="' + stat + '">' +
            '<input type="checkbox" ' + (has ? ' checked' : '') + ' />' +
            '<label>' + stat + '</label>' +
            '<input type="number" class="num-input eq-bonus-val" value="' + (has ? bonus[stat] : 0) + '" step="1" style="width:70px;" />' +
            '</div>';
        });

        equipEditCard.innerHTML =
          '<div class="section-header" style="margin-top:0;">✏️ 编辑装备</div>' +
          '<div class="field-grid">' +
          '<div class="field-item"><label>名称</label><input type="text" id="eq-edit-name" value="' + _escHtml(item.名称 || "") + '" /></div>' +
          '<div class="field-item"><label>品质</label><select id="eq-edit-quality">' +
          [1,2,3,4,5].map(q => '<option value="' + q + '"' + ((item.品质||1) === q ? ' selected' : '') + '>' + q + '</option>').join('') +
          '</select></div>' +
          '<div class="field-item"><label>部位</label><select id="eq-edit-slot">' +
          ["主手","副手","头部","身体","护手","鞋子","饰品1","饰品2","特殊","持有物品"].map(s =>
            '<option value="' + s + '"' + (slot === s ? ' selected' : '') + '>' + s + '</option>'
          ).join('') +
          '</select></div>' +
          '</div>' +
          bonusHtml +
          '<div class="card-actions">' +
          '<button class="card-btn-save" id="eq-save-btn">保存</button>' +
          '<button class="card-btn-del" id="eq-del-btn">删除</button>' +
          '</div>';
        equipEditCard.style.display = "block";

        document.getElementById("eq-save-btn").addEventListener("click", saveEquipEdit);
        document.getElementById("eq-del-btn").addEventListener("click", deleteEquipEdit);
      }

      function _escHtml(s) { return String(s).replace(/[&<>"]/g, function(c) { return { "&": "&" + "amp;", "<": "&" + "lt;", ">": "&" + "gt;", '"': "&" + "quot;" }[c]; }); }

      function saveEquipEdit() {
        const key = equipSelect.value;
        if (!key || !_currentCharKey) return;
        const char = _characterEditCache[_currentCharKey];
        const list = buildEquipIndex(char);
        const entry = list.find(e => e.key === key);
        if (!entry) return;

        const item = entry.item;
        const newName = document.getElementById("eq-edit-name").value.trim();
        if (!newName) return;
        const newQuality = parseInt(document.getElementById("eq-edit-quality").value, 10);
        const newSlot = document.getElementById("eq-edit-slot").value;

        const newBonus = {};
        FIVE_STATS.forEach(stat => {
          const row = equipEditCard.querySelector('[data-eb-row="' + stat + '"]');
          if (!row) return;
          const cb = row.querySelector("input[type='checkbox']");
          const valInput = row.querySelector("input.eq-bonus-val");
          if (cb && cb.checked) {
            newBonus[stat] = parseFloat(valInput?.value) || 0;
          }
        });

        // 1. 从旧位置移除
        if (entry.source === "装备栏") {
          if (entry.slot === "特殊") char.装备栏.特殊.splice(entry.idx, 1);
          else char.装备栏[entry.slot] = null;
        } else {
          delete char.持有物品[entry.invName];
        }

        // 2. 更新装备数据
        item.名称 = newName;
        item.品质 = newQuality;
        if (!item.装备属性) item.装备属性 = {};
        item.装备属性.部位 = newSlot;
        item.装备属性.加成 = newBonus;

        // 3. 放入新位置
        if (newSlot === "持有物品") {
          if (!char.持有物品) char.持有物品 = {};
          char.持有物品[newName] = item;
        } else {
          if (!char.装备栏) char.装备栏 = {};
          if (newSlot === "特殊") {
            if (!char.装备栏.特殊) char.装备栏.特殊 = [];
            char.装备栏.特殊.push(item);
          } else {
            const old = char.装备栏[newSlot];
            if (old?.名称) {
              if (!char.持有物品) char.持有物品 = {};
              char.持有物品[old.名称] = old;
            }
            char.装备栏[newSlot] = item;
          }
        }

        populateEquipSelect(char);
        renderInventory(char);
        equipEditCard.style.display = "none";
        equipSelect.value = "";
      }

      function deleteEquipEdit() {
        const key = equipSelect.value;
        if (!key || !_currentCharKey) return;
        const char = _characterEditCache[_currentCharKey];
        const list = buildEquipIndex(char);
        const entry = list.find(e => e.key === key);
        if (!entry) return;

        if (entry.source === "装备栏") {
          if (entry.slot === "特殊") char.装备栏.特殊.splice(entry.idx, 1);
          else char.装备栏[entry.slot] = null;
        } else {
          delete char.持有物品[entry.invName];
        }

        populateEquipSelect(char);
        renderInventory(char);
        equipEditCard.style.display = "none";
        equipSelect.value = "";
      }

      // ── 技能下拉框 ──
      function populateSkillSelect(char) {
