        const curVal = skillSelect.value;
        skillSelect.innerHTML = '<option value="">-- 选择技能 --</option>';
        Object.keys(skills).forEach(name => {
          if (!skills[name]) return;
          const opt = document.createElement("option");
          opt.value = name;
          opt.textContent = name + " (" + (skills[name].类型||"技能") + " Lv." + (skills[name].等级||"I") + ")";
          skillSelect.appendChild(opt);
        });
        if (curVal && skills[curVal]) skillSelect.value = curVal;
      }

      // ── 渲染技能编辑卡片 ──
      function renderSkillCard(name) {
