        let activeFields = '<div id="sk-active-fields" style="' + (isPassive ? 'display:none;' : '') + '">' +
            '<div class="field-grid" style="margin-top:8px;">' +
            '<div class="field-item"><label>伤害比例</label><input type="number" id="sk-edit-damage" value="' + (sk.伤害比例||0) + '" step="0.1" min="0" max="10" /></div>' +
            '<div class="field-item"><label>MP消耗%</label><input type="number" id="sk-edit-mp" value="' + Math.round((sk.消耗MP百分比||0)*100) + '" step="1" min="0" max="100" /></div>' +
            '<div class="field-item"><label>SP消耗%</label><input type="number" id="sk-edit-sp" value="' + Math.round((sk.消耗SP百分比||0)*100) + '" step="1" min="0" max="100" /></div>' +
            '</div>' +
            '<div class="field-grid" style="margin-top:8px;">' +
            '<div class="field-item"><label>回复HP比例</label><input type="number" id="sk-edit-healhp" value="' + (sk.回复HP比例||0) + '" step="0.1" min="0" max="10" /></div>' +
            '<div class="field-item"><label>回复SP比例</label><input type="number" id="sk-edit-healsp" value="' + (sk.回复SP比例||0) + '" step="0.1" min="0" max="10" /></div>' +
            '<div class="field-item"><label>回复MP比例</label><input type="number" id="sk-edit-healmp" value="' + (sk.回复MP比例||0) + '" step="0.1" min="0" max="10" /></div>' +
            '</div>' +
            '</div>';

        skillEditCard.innerHTML =
          '<div class="section-header" style="margin-top:0;">✏️ 编辑技能</div>' +
          '<div class="field-grid">' +
          '<div class="field-item"><label>名称</label><input type="text" id="sk-edit-name" value="' + _escHtml(name) + '" /></div>' +
          '<div class="field-item"><label>类型</label><select id="sk-edit-type">' +
          ["技能","魔法","发展能力"].map(t => '<option value="' + t + '"' + (sk.类型===t ? ' selected' : '') + '>' + t + '</option>').join('') +
          '</select></div>' +
          '<div class="field-item"><label>等级</label><select id="sk-edit-grade">' +
          SKILL_GRADES.map(g => '<option value="' + g + '"' + (sk.等级===g ? ' selected' : '') + '>' + g + '</option>').join('') +
          '</select></div>' +
          '<div class="field-item"><label>技能类型</label><select id="sk-edit-skilltype">' +
          ["主动","被动"].map(t => '<option value="' + t + '"' + (sk.技能类型===t ? ' selected' : '') + '>' + t + '</option>').join('') +
          '</select></div>' +
          '</div>' +
          '<div class="field-item" style="margin-top:6px;"><label>效果描述</label><input type="text" id="sk-edit-desc" value="' + _escHtml(sk.效果描述||"") + '" style="width:100%;" /></div>' +
          bonusHtml +
          activeFields +
          '<div class="card-actions">' +
          '<button class="card-btn-save" id="sk-save-btn">保存</button>' +
          '<button class="card-btn-del" id="sk-del-btn">删除</button>' +
          '</div>';
        skillEditCard.style.display = "block";

        document.getElementById("sk-save-btn").addEventListener("click", saveSkillEdit);
        document.getElementById("sk-del-btn").addEventListener("click", deleteSkillEdit);
        // 被动/主动切换：仅切换显隐，保留编辑内容
        document.getElementById("sk-edit-skilltype").addEventListener("change", function () {
          const isPassive = this.value === "被动";
          const af = document.getElementById("sk-active-fields");
          if (af) af.style.display = isPassive ? "none" : "";
        });
      }

      function saveSkillEdit() {
        const name = skillSelect.value;
        if (!name || !_currentCharKey) return;
        const char = _characterEditCache[_currentCharKey];
        const skills = char.基础信息?.技能列表 || {};
        const oldSkill = skills[name];
        if (!oldSkill) return;

        const newName = document.getElementById("sk-edit-name").value.trim();
        if (!newName) return;
        const newType = document.getElementById("sk-edit-type").value;
        const newGrade = document.getElementById("sk-edit-grade").value;
        const newSkilltype = document.getElementById("sk-edit-skilltype").value;

        const newBonus = {};
        FIVE_STATS.forEach(stat => {
          const row = skillEditCard.querySelector('[data-sb-row="' + stat + '"]');
          if (!row) return;
          const cb = row.querySelector("input[type='checkbox']");
          const valInput = row.querySelector("input.sk-bonus-val");
          if (cb && cb.checked) {
            newBonus[stat] = parseFloat(valInput?.value) || 0;
          }
        });

        let damageRatio = 0, mpCost = 0, spCost = 0, hpHeal = 0, spHeal = 0, mpHeal = 0;
        if (newSkilltype === "主动") {
          damageRatio = parseFloat(document.getElementById("sk-edit-damage")?.value) || 0;
          mpCost = (parseFloat(document.getElementById("sk-edit-mp")?.value) || 0) / 100;
          spCost = (parseFloat(document.getElementById("sk-edit-sp")?.value) || 0) / 100;
          hpHeal = parseFloat(document.getElementById("sk-edit-healhp")?.value) || 0;
          spHeal = parseFloat(document.getElementById("sk-edit-healsp")?.value) || 0;
          mpHeal = parseFloat(document.getElementById("sk-edit-healmp")?.value) || 0;
        }

        const skill = {
          名称: newName, 类型: newType, 等级: newGrade,
          效果描述: document.getElementById("sk-edit-desc").value,
          技能类型: newSkilltype,
          消耗MP百分比: mpCost, 消耗SP百分比: spCost, 伤害比例: damageRatio,
          回复HP比例: hpHeal, 回复SP比例: spHeal, 回复MP比例: mpHeal,
        };
        if (Object.keys(newBonus).length > 0) skill.加成 = newBonus;

        delete skills[name];
        skills[newName] = skill;

        populateSkillSelect(char);
        skillEditCard.style.display = "none";
        skillSelect.value = "";
      }

      function deleteSkillEdit() {
        const name = skillSelect.value;
        if (!name || !_currentCharKey) return;
        const char = _characterEditCache[_currentCharKey];
        const skills = char.基础信息?.技能列表 || {};
        delete skills[name];
        populateSkillSelect(char);
        skillEditCard.style.display = "none";
        skillSelect.value = "";
      }

      // ── 持有物品 渲染（统一）──
      function renderInventory(char) {
        const items = char?.持有物品 || {};
        let html = "";
        Object.keys(items).forEach(name => {
          const item = items[name];
          if (!item) return;
          const cat = item.类别 || "";
          html += '<div class="inv-item-row"><span class="inv-name">' + _escHtml(name) + '</span>' +
            '<span class="inv-qty">' + (cat ? cat + ' ' : '') + '×' + (item.数量||1) + '</span></div>';
        });
        inventoryContainer.innerHTML = html || '<div style="font-size:12px;color:var(--text-dim)">无物品</div>';
      }

      // ── 主渲染函数 ──
      function renderSelectedCharacter(key) {
        if (!key) return;
        _currentCharKey = key;

        // 从缓存取，没有则从 _allCharacters 获取（已是纯对象，直接浅拷贝足够）
        let char = _characterEditCache[key];
        if (!char) {
          if (key === "主角") {
            char = JSON.parse(JSON.stringify(_allCharacters.主角 || {}));
          } else {
            char = JSON.parse(JSON.stringify(_allCharacters.人物名录?.[key] || {}));
          }
          _characterEditCache[key] = char;
        }

        const type = detectCharType(char);
        applyFieldLocking(type);
        const bi = char.基础信息 || {};
        const st = char.状态 || {};
        const rel = char.关系 || {};
        const attr = char.个人属性 || {};
        const equip = char.装备栏 || {};

        // 基础信息
        writeField(FORM_IDS.name, bi.姓名);
        // 修正旧数据中类型被错误存为"异端儿"，并统一显示为"异端儿"
        if (bi.类型 === "异端儿") bi.类型 = "怪物";
        writeField(FORM_IDS.type, _currentCharType === "异端儿" ? "异端儿" : bi.类型);
        writeField(FORM_IDS.race, bi.种族);
        writeField(FORM_IDS.gender, bi.性别);
        writeField(FORM_IDS.personality, Array.isArray(bi.性格) ? bi.性格.join(",") : (bi.性格 || ""));
        writeField(FORM_IDS.appearance, bi.样貌);
        writeField(FORM_IDS.hair, bi.发型);
        writeField(FORM_IDS.build, bi.身材);
        writeField(FORM_IDS.outfit, bi.服装);
        writeField(FORM_IDS.aura, bi.气质);
        writeField(FORM_IDS.savings, bi.资产?.存款 ?? 0);
        writeField(FORM_IDS.negStatus, Array.isArray(bi.负面状态) ? bi.负面状态.join(",") : (bi.负面状态 || ""));
        writeField(FORM_IDS.rarity, bi.稀有度 || "");

        // 状态
        writeField(FORM_IDS.hpmax, st.HP上限 ?? 500);
        writeField(FORM_IDS.hpcur, st.HP当前值 ?? st.HP上限 ?? 500);
        writeField(FORM_IDS.spmax, st.SP上限 ?? 100);
        writeField(FORM_IDS.spcur, st.SP当前值 ?? st.SP上限 ?? 100);
        writeField(FORM_IDS.mpmax, st.MP上限 ?? 100);
        writeField(FORM_IDS.mpcur, st.MP当前值 ?? st.MP上限 ?? 100);
        const bi2 = char.基础信息 || {};
        writeField(FORM_IDS.mood, bi2.心境 || "");
        writeField(FORM_IDS.location, bi2.所在位置 || "");
        writeField(FORM_IDS.rep, st.声誉值 ?? 0);
        writeField(FORM_IDS.rest, st.休息 ?? 0);
        writeField(FORM_IDS.purity, st.灵魂纯洁度 ?? 0);
        writeField(FORM_IDS.body, st.身体状况 ?? 100);
        writeField(FORM_IDS.eval, st.评价 || "");

        // 关系
        writeField(FORM_IDS.relation, rel.当前关系 || "");
        writeField(FORM_IDS.affection, rel.情深值 ?? 0);

        // 个人属性
        writeField(FORM_IDS.level, attr.等级 ?? 0);
        writeField(FORM_IDS.grade, attr.整体评价 || "I");
        writeField(FORM_IDS.feat, attr.当前伟业 ?? 0);
        writeField(FORM_IDS.familia, attr.所属眷族 || "");
        writeField(FORM_IDS.jobs, Array.isArray(attr.身份职业) ? attr.身份职业.join(",") : (attr.身份职业 || ""));
        writeField(FORM_IDS.floor, attr.到达层数 ?? 0);

        writeFiveDim("five-base", attr.基础能力 || {});
        writeFiveDim("five-pot", attr.潜在能力 || {});
        writeFiveDim("five-exp", attr.积累经验值 || {});
        writeFiveDim("five-weight", attr.经验权重 || {});
        writeFiveDim("five-growth", attr.成长期望 || {});
        getEl("a-polian").value = (attr.破限 === true) ? "1" : "0";

        // 称号
        writeField(FORM_IDS.title, char.称号 || "");

        // 渲染子组件
        populateEquipSelect(char);
        populateSkillSelect(char);
        renderInventory(char);
        equipEditCard.style.display = "none";
        skillEditCard.style.display = "none";
      }

      // ── 构建角色名称列表并填充下拉框 ──
      function rebuildCharNameList() {
        _charNameList = [];
        // 主角
        const playerName = _allCharacters.主角?.基础信息?.姓名;
        if (playerName) {
          _charNameList.push({ name: playerName, type: "主角", key: "主角" });
        }
        // 人物名录（可能包含 cache 中的新角色）
        const allNames = new Set(Object.keys(_allCharacters.人物名录 || {}));
        Object.keys(_characterEditCache).forEach(k => { if (k !== "主角") allNames.add(k); });
        allNames.forEach(name => {
          const c = _characterEditCache[name] || _allCharacters.人物名录?.[name];
          _charNameList.push({ name, type: c?.基础信息?.类型 || "未知", key: name });
        });
        _charNameList.sort((a, b) => {
          if (a.type === "主角") return -1;
          if (b.type === "主角") return 1;
          return a.name.localeCompare(b.name, "zh");
        });
      }

      function populateCharSelect() {
        rebuildCharNameList();
        charSelect.innerHTML = "";
        _charNameList.forEach(entry => {
          const opt = document.createElement("option");
          opt.value = entry.key;
          opt.textContent = entry.name + " (" + entry.type + ")";
          charSelect.appendChild(opt);
        });
        if (_charNameList.length > 0 && !_currentCharKey) {
          charSelect.value = _charNameList[0].key;
          renderSelectedCharacter(_charNameList[0].key);
        } else if (_currentCharKey) {
          charSelect.value = _currentCharKey;
        }
      }

      function onCharChange() {
        const newKey = charSelect.value;
        if (!newKey || newKey === _currentCharKey) return;
        // 缓存当前编辑（切换前自动填充默认值，避免空值存入）
        if (_currentCharKey) {
          fillDefaults();
          _characterEditCache[_currentCharKey] = collectSingleCharacterForm();
        }
        renderSelectedCharacter(newKey);
        // 清除错误状态
        getEl("save-error-msg").style.display = "none";
        document.querySelectorAll(".field-error").forEach(el => el.classList.remove("field-error"));
      }

      // ── 收集当前角色表单 ──
      function collectSingleCharacterForm() {
        const cache = _characterEditCache[_currentCharKey];
        if (!cache) return null;

        const bi = cache.基础信息 || {};
        bi.姓名 = readField(FORM_IDS.name);
        bi.类型 = _currentCharType === "异端儿" ? "怪物" : readField(FORM_IDS.type);
        bi.种族 = readField(FORM_IDS.race);
        bi.性别 = readField(FORM_IDS.gender);
        if (_currentCharType !== "主角") {
          bi.性格 = readField(FORM_IDS.personality).split(",").map(s => s.trim()).filter(Boolean);
          bi.样貌 = readField(FORM_IDS.appearance);
          bi.发型 = readField(FORM_IDS.hair);
          bi.身材 = readField(FORM_IDS.build);
          bi.服装 = readField(FORM_IDS.outfit);
          bi.气质 = readField(FORM_IDS.aura);
        }
        if (!bi.资产) bi.资产 = {};
        bi.资产.存款 = readNumField(FORM_IDS.savings);
        bi.负面状态 = readField(FORM_IDS.negStatus).split(",").map(s => s.trim()).filter(Boolean);
        if (_currentCharType === "异端儿") bi.稀有度 = readField(FORM_IDS.rarity);
        cache.基础信息 = bi;

        const st = cache.状态 || {};
        st.HP上限 = readNumField(FORM_IDS.hpmax);
        st.HP当前值 = readNumField(FORM_IDS.hpcur);
        st.SP上限 = readNumField(FORM_IDS.spmax);
        st.SP当前值 = readNumField(FORM_IDS.spcur);
        st.MP上限 = readNumField(FORM_IDS.mpmax);
        st.MP当前值 = readNumField(FORM_IDS.mpcur);
        if (_currentCharType !== "主角") {
          bi.心境 = readField(FORM_IDS.mood);
          bi.所在位置 = readField(FORM_IDS.location);
        }
        if (_currentCharType === "主角") {
          st.声誉值 = readNumField(FORM_IDS.rep);
          st.休息 = readNumField(FORM_IDS.rest);
          st.灵魂纯洁度 = readNumField(FORM_IDS.purity);
        }
        if (_currentCharType === "冒险者" || _currentCharType === "NPC") {
          st.身体状况 = readNumField(FORM_IDS.body);
          st.评价 = readField(FORM_IDS.eval);
        }
        cache.状态 = st;

        if (_currentCharType !== "主角") {
          const rel = cache.关系 || {};
          rel.当前关系 = readField(FORM_IDS.relation);
          rel.情深值 = readNumField(FORM_IDS.affection);
          cache.关系 = rel;
        }

        if (_currentCharType === "NPC") {
          const attr = cache.个人属性 || {};
          attr.所属眷族 = readField(FORM_IDS.familia);
          attr.身份职业 = readField(FORM_IDS.jobs).split(",").map(s => s.trim()).filter(Boolean);
          attr.到达层数 = readNumField(FORM_IDS.floor);
          cache.个人属性 = attr;
        } else if (_currentCharType === "异端儿") {
          const attr = cache.个人属性 || {};
          attr.等级 = readNumField(FORM_IDS.level);
          attr.基础能力 = readFiveDim("five-base");
          attr.经验权重 = readFiveDim("five-weight");
          cache.个人属性 = attr;
        } else {
          const attr = cache.个人属性 || {};
          attr.等级 = readNumField(FORM_IDS.level);
          attr.当前伟业 = parseFloat(readField(FORM_IDS.feat)) || 0;
          attr.所属眷族 = readField(FORM_IDS.familia);
          attr.身份职业 = readField(FORM_IDS.jobs).split(",").map(s => s.trim()).filter(Boolean);
          attr.到达层数 = readNumField(FORM_IDS.floor);
          attr.基础能力 = readFiveDim("five-base");
          attr.潜在能力 = readFiveDim("five-pot");
          attr.积累经验值 = readFiveDim("five-exp");
          if (_currentCharType === "主角" || _currentCharType === "冒险者") attr.经验权重 = readFiveDim("five-weight");
          if (_currentCharType === "冒险者") attr.成长期望 = readFiveDim("five-growth");
          if (_currentCharType === "主角" || _currentCharType === "冒险者") attr.破限 = getEl("a-polian").value === "1";
          cache.个人属性 = attr;
        }

        if (_currentCharType === "主角") {
          cache.称号 = readField(FORM_IDS.title);
        }

        // 更新缓存中的姓名 key（如果改名了）
        const newName = bi.姓名;
        if (newName && newName !== _currentCharKey && _currentCharKey !== "主角") {
          _characterEditCache[newName] = cache;
          delete _characterEditCache[_currentCharKey];
          _currentCharKey = newName;
        }

        return cache;
      }

      // ── 生成装备 ──
      function updateEqPreview() {
        const gradeForm = collectGradeForm();
        const quality = parseInt(eqQuality.value, 10);
        const qCfg = gradeForm.装备系统?.品质配置?.[quality];
        if (!qCfg) { eqPreview.textContent = ""; return; }
        const checkedDims = eqDims.querySelectorAll("input:checked");
        let preview = "";
        checkedDims.forEach(cb => {
          const stat = cb.value;
          preview += stat + ": ×" + (qCfg.加成最低||0) + "~×" + (qCfg.加成最高||0) + "  ";
        });
        eqPreview.textContent = preview ? "系数范围: " + preview : "";
      }

      function generateEquipment() {
        const name = eqName.value.trim();
        if (!name) return;
        if (!_currentCharKey || !_characterEditCache[_currentCharKey]) return;
        const char = _characterEditCache[_currentCharKey];
        const gradeForm = collectGradeForm();
        const quality = parseInt(eqQuality.value, 10);
        const qCfg = gradeForm.装备系统?.品质配置?.[quality];
        if (!qCfg) return;
        const slot = eqSlot.value;
        const dims = [...eqDims.querySelectorAll("input:checked")].map(cb => cb.value);

        const bonus = {};
        dims.forEach(stat => {
          const lo = qCfg.加成最低 || 0;
          const hi = qCfg.加成最高 || 0;
          const coeff = hi > lo ? lo + Math.random() * (hi - lo) : lo;
          bonus[stat] = Math.round(coeff * 100) / 100;
        });

        const item = {
          名称: name,
          数量: 1,
          描述: "",
          品质: quality,
          类别: "装备",
          单价: 0,
          装备属性: { 部位: slot, 加成: bonus },
        };

        // 直接放入持有物品
        if (!char.持有物品) char.持有物品 = {};
        char.持有物品[name] = item;

        eqName.value = "";
        populateEquipSelect(char);
        renderInventory(char);
      }

      // ── 生成技能 ──
      function updateSkPreview() {
        const gradeForm = collectGradeForm();
        const grade = skGrade.value;
        const gCfg = gradeForm.技能系统?.等级配置?.[grade];
        if (!gCfg) { skPreview.textContent = ""; return; }
        const checkedDims = skDims.querySelectorAll("input:checked");
        const isPassive = skSkilltype.value === "被动";
        let preview = "";
        checkedDims.forEach(cb => {
          const stat = cb.value;
          preview += stat + ": ×" + (gCfg.加成最低||0) + "~×" + (gCfg.加成最高||0) + "  ";
        });
        if (!isPassive) {
          var dmgCbs = document.querySelectorAll("#sk-damage-types input:checked");
          var healCbs = document.querySelectorAll("#sk-heal-types input:checked");
          var costCbs = document.querySelectorAll("#sk-cost-types input:checked");
          if (dmgCbs.length > 0) preview += "| 伤害: " + (gCfg.伤害比例最低||0) + "~" + (gCfg.伤害比例最高||0) + "x";
          if (healCbs.length > 0) {
            healCbs.forEach(function(cb) {
              var rKey = "回复" + cb.value;
              preview += " " + cb.value + "回复: " + ((gCfg[rKey + "最低"]||0)*100).toFixed(0) + "~" + ((gCfg[rKey + "最高"]||0)*100).toFixed(0) + "%";
            });
            if (dmgCbs.length > 0) preview += " (吸收:回复减半)";
          }
          costCbs.forEach(function(cb) {
            var cKey = "消耗" + cb.value;
            preview += " " + cb.value + "消耗: " + Math.round((gCfg[cKey + "最低"]||0)*100) + "~" + Math.round((gCfg[cKey + "最高"]||0)*100) + "%";
          });
        }
        skPreview.textContent = preview ? "系数范围: " + preview : "";
      }

      function generateSkill() {
        const name = skName.value.trim();
        if (!name) return;
        if (!_currentCharKey || !_characterEditCache[_currentCharKey]) return;
        const char = _characterEditCache[_currentCharKey];
        const gradeForm = collectGradeForm();
        const grade = skGrade.value;
        const gCfg = gradeForm.技能系统?.等级配置?.[grade];
        if (!gCfg) return;
        const isPassive = skSkilltype.value === "被动";

        const bonus = {};
        const checkedDims = skDims.querySelectorAll("input:checked");
        if (isPassive && checkedDims.length === 0) return;
        checkedDims.forEach(cb => {
          const stat = cb.value;
          const lo = gCfg.加成最低 || 0;
          const hi = gCfg.加成最高 || 0;
          const coeff = hi > lo ? lo + Math.random() * (hi - lo) : lo;
          bonus[stat] = Math.round(coeff * 100) / 100;
        });

        // 主动技能：伤害/回复/消耗 根据三组复选框从配置范围随机
        var rollRng = function(lo, hi, decimals) { return hi > lo ? Math.round((lo + Math.random() * (hi - lo)) * Math.pow(10, decimals||2)) / Math.pow(10, decimals||2) : lo; };
        let damageRatio = 0, mpCost = 0, spCost = 0, hpHeal = 0, spHeal = 0, mpHeal = 0;
        if (!isPassive) {
          // 读取三组 checkbox
          var dmgCbs = document.querySelectorAll("#sk-damage-types input:checked");
          var healCbs = document.querySelectorAll("#sk-heal-types input:checked");
          var costCbs = document.querySelectorAll("#sk-cost-types input:checked");

          // 伤害：有选中则 roll
          if (dmgCbs.length > 0) {
            damageRatio = rollRng(gCfg.伤害比例最低 || 0, gCfg.伤害比例最高 || 0, 1);
          }

          // 消耗：遍历选中项 roll
          costCbs.forEach(function(cb) {
            var res = cb.value;
            if (res === "SP") spCost = rollRng(gCfg.消耗SP最低 || 0, gCfg.消耗SP最高 || 0);
            if (res === "MP") mpCost = rollRng(gCfg.消耗MP最低 || 0, gCfg.消耗MP最高 || 0);
          });

          // 回复：遍历选中项 roll
          healCbs.forEach(function(cb) {
            var res = cb.value;
            var rLo = gCfg["回复" + res + "最低"] || 0;
            var rHi = gCfg["回复" + res + "最高"] || 0;
            var val = rollRng(rLo, rHi, 2);
            // 吸收减半：同时有伤害和回复
            if (damageRatio > 0) val = Math.round(val * 50) / 100;
            if (res === "HP") hpHeal = val;
            if (res === "SP") spHeal = val;
            if (res === "MP") mpHeal = val;
          });
        }

        const skill = {
          名称: name,
          类型: skType.value,
          等级: grade,
          效果描述: skDesc.value.trim(),
          技能类型: isPassive ? "被动" : "主动",
          消耗MP百分比: mpCost,
          消耗SP百分比: spCost,
          伤害比例: damageRatio,
          回复HP比例: hpHeal,
          回复SP比例: spHeal,
          回复MP比例: mpHeal,
        };
        if (Object.keys(bonus).length > 0) skill.加成 = bonus;

        if (!char.基础信息) char.基础信息 = {};
        if (!char.基础信息.技能列表) char.基础信息.技能列表 = {};
        char.基础信息.技能列表[name] = skill;

        skName.value = "";
        skDesc.value = "";
        populateSkillSelect(char);
      }

