      function createNewCharacter() {
        const name = createName.value.trim();
        if (!name) return;
        const type = createType.value;
        // 检查重名
        if (_characterEditCache[name] || (_allCharacters.人物名录 && _allCharacters.人物名录[name])) {
          alert("角色 \"" + name + "\" 已存在");
          return;
        }
        const template = DEFAULT_CHAR_TEMPLATES[type];
        const newChar = JSON.parse(JSON.stringify(template));
        newChar.基础信息.姓名 = name;
        _characterEditCache[name] = newChar;
        // 确保 _allCharacters.人物名录 中有占位
        if (!_allCharacters.人物名录) _allCharacters.人物名录 = {};
        if (!_allCharacters.人物名录[name]) _allCharacters.人物名录[name] = newChar;

        hideCreateDialog();
        rebuildCharNameList();
        populateCharSelect();
        charSelect.value = name;
        renderSelectedCharacter(name);
      }
      // ── 数据校验 ──
      function validateCharacterForm() {
        const errors = [];
        const errMsg = getEl("save-error-msg");
        // 清除旧错误标记
        document.querySelectorAll(".field-error").forEach(el => el.classList.remove("field-error"));
        if (errMsg) errMsg.style.display = "none";

        // 姓名必填
        const nameEl = getEl(FORM_IDS.name);
        if (nameEl && !nameEl.disabled && !nameEl.readOnly) {
          if (!nameEl.value.trim()) {
            errors.push({ el: nameEl, msg: "姓名不能为空" });
          }
        }
        // 种族必填
        const raceEl = getEl(FORM_IDS.race);
        if (raceEl && !raceEl.disabled && !raceEl.readOnly) {
          if (!raceEl.value.trim()) {
            errors.push({ el: raceEl, msg: "种族不能为空" });
          }
        }
        // 性别必填
        const genderEl = getEl(FORM_IDS.gender);
        if (genderEl && !genderEl.disabled && !genderEl.readOnly) {
          if (!genderEl.value.trim()) {
            errors.push({ el: genderEl, msg: "性别不能为空" });
          }
        }

        if (errors.length > 0) {
          errors.forEach(e => { e.el.classList.add("field-error"); e.el.title = e.msg; });
          if (errMsg) {
            errMsg.textContent = "⚠ " + errors.map(e => e.msg).join("；");
            errMsg.style.display = "";
          }
        }
        return errors;
      }

      // ── 保存前自动填充默认值 ──
      function fillDefaults() {
        // 为非必填但建议有值的字段填入默认值（姓名/种族/性别由校验强制填写，不在此填充）
        if (!readField(FORM_IDS.mood).trim()) writeField(FORM_IDS.mood, "未知");
        if (!readField(FORM_IDS.location).trim()) writeField(FORM_IDS.location, "未知");
        if (_currentCharType !== "主角" && !readField(FORM_IDS.relation).trim()) writeField(FORM_IDS.relation, "陌生");
        if (!readField(FORM_IDS.jobs).trim() && _currentCharType !== "异端儿") writeField(FORM_IDS.jobs, "冒险者");
      }

      async function saveAll() {
        saveBtn.disabled = true;
        saveStatus.textContent = "⏳ 保存中…";
        try {
          // 校验（基于 DOM 当前值，在收集到缓存前检查）
          const errors = validateCharacterForm();
          if (errors.length > 0) {
            saveStatus.textContent = "✗ 请修正上方标红的必填字段";
            saveStatus.className = "save-status err";
            saveBtn.disabled = false;
            return;
          }

          // 填充可选字段默认值，然后收集到缓存
          if (_currentCharKey) {
            fillDefaults();
            _characterEditCache[_currentCharKey] = collectSingleCharacterForm();
          }

          const variables = Mvu.getMvuData({ type: "message", message_id: getCurrentMessageId() });

          // 写入所有脏缓存中的角色数据
          Object.keys(_characterEditCache).forEach((key) => {
            const charData = _characterEditCache[key];
            if (!charData) return;
            if (key === "主角") {
              variables.stat_data.主角 = charData;
            } else {
              _.set(variables, "stat_data.人物名录." + key, charData);
            }
          });

          const storyData = collectStoryForm();
          const combatData = collectCombatForm();
          const gradeData = collectGradeForm();
          _.set(variables, "stat_data.sysbox.剧情相关", storyData.剧情相关);
          _.set(variables, "stat_data.sysbox.战斗系统", combatData.战斗系统);
          _.set(variables, "stat_data.sysbox.技能系统", gradeData.技能系统);
          _.set(variables, "stat_data.sysbox.装备系统", gradeData.装备系统);
          _.set(variables, "stat_data.sysbox.消耗品系统", gradeData.消耗品系统);
          await saveData(variables, { type: "message", message_id: getCurrentMessageId() });
          saveStatus.textContent = "✓ 全部配置已保存";
          saveStatus.className = "save-status ok";
        } catch (e) {
          saveStatus.textContent = "✗ 保存失败：" + e.message;
          saveStatus.className = "save-status err";
        } finally {
          saveBtn.disabled = false;
        }
      }

      // ---------- UI 刷新总控 ----------
      function refreshUI() {
        const sysbox = DungeonUtils.loadSysboxData(getCurrentMessageId());

        // ── 加载角色数据（仅首次初始化，避免覆盖正在编辑的表单）──
        if (!_allCharacters) {
          const charData = DungeonUtils.loadCharacterData(getCurrentMessageId());
          if (charData) {
            _allCharacters = charData;
            populateCharSelect();
          }
        }

        // 等级配置表始终渲染（角色编辑器生成装备/技能时需要读取）
        renderSkillGradeTable(sysbox?.技能系统?.等级配置);
        renderEquipQualityTable(sysbox?.装备系统?.品质配置);
        renderConsumableQualityTable(sysbox?.消耗品系统?.品质配置);

        if (!sysbox) {
          saveStatus.textContent = "⚠ 无法读取变量";
          saveStatus.className = "save-status err";
