          { 层数最低: 17, 层数最高: 20, 补正值: 1.6 },
          { 层数最低: 21, 层数最高: 24, 补正值: 1.7 },
          { 层数最低: 25, 层数最高: 28, 补正值: 1.8 },
          { 层数最低: 29, 层数最高: 33, 补正值: 1.95 },
          { 层数最低: 34, 层数最高: 36, 补正值: 2.15 },
          { 层数最低: 37, 层数最高: 45, 补正值: 2.5 },
          { 层数最低: 46, 层数最高: 55, 补正值: 3.0 },
