      }

      function updateLevelExample() {
        const coeff = parseFloat(levelCoeff.value) || 1000;
        const examples = [1, 2, 3, 5, 10].map(lv => {
          const val = Math.max((lv - 1) * coeff, 100);
          return "Lv." + lv + "=" + val;
        });
        levelExample.textContent = "示例: " + examples.join(", ");
      }
      levelCoeff.addEventListener("input", updateLevelExample);

      // ── 事件绑定 ──
      addTierBtn.addEventListener("click", addTierRow);
      addFloorBtn.addEventListener("click", addFloorRow);
      saveBtn.addEventListener("click", saveAll);

