      equipSelect.addEventListener("change", function () { renderEquipCard(this.value); });
      skillSelect.addEventListener("change", function () { renderSkillCard(this.value); });

      document.querySelectorAll(".module-tab").forEach(tab => {
        tab.addEventListener("click", function () {
          document.querySelectorAll(".module-tab").forEach(t => t.classList.remove("active"));
          this.classList.add("active");
          document.querySelectorAll(".config-panel").forEach(p => p.classList.remove("active"));
          document.getElementById("panel-" + this.dataset.module).classList.add("active");
          if (this.dataset.module === "template") loadTemplateList();
        });
      });

      // ═══════════════════ 模板导入 ═══════════════════
      const tmplTypeSelect = document.getElementById("template-type-select");
      const tmplRefreshBtn = document.getElementById("template-refresh-btn");
      const tmplListContainer = document.getElementById("template-list-container");
      const tmplSelectAll = document.getElementById("template-select-all");
      const tmplDeselectAll = document.getElementById("template-deselect-all");
      const tmplImportSelected = document.getElementById("template-import-selected");
      const tmplImportAll = document.getElementById("template-import-all");
      const tmplStatus = document.getElementById("template-import-status");
      const dungeonFloorRow = document.getElementById("dungeon-floor-row");
      const dungeonFloorSelect = document.getElementById("dungeon-floor-select");
      const tmplImportFloor = document.getElementById("template-import-floor");

      var _currentTemplates = []; // { name, extra, checked }
      var _allDungeonFloors = []; // [{ name: "1", extra: {...} }] 所有楼层模板
      var _currentDungeonFloor = null; // 当前选中的楼层名

      // 关键词 → category 映射
      var TYPE_TO_CATEGORY = { character: "character", dungeon: "dungeon", equip: "equip", skill: "skill" };

      function setTmplStatus(msg, isErr) {
        tmplStatus.textContent = msg || "";
        tmplStatus.style.color = isErr ? "var(--hp-color)" : "var(--text-dim)";
      }

      /** 渲染模板列表 */
      function renderTemplateList() {
        tmplListContainer.innerHTML = "";
        if (!_currentTemplates.length) {
          tmplListContainer.innerHTML = '<div class="template-empty">未找到模板，请确认世界书已创建并包含条目</div>';
          return;
        }
        var table = document.createElement("table");
        table.className = "tier-table";
        table.innerHTML = "<thead><tr><th style=\"width:36px;\">选择</th><th>名称</th><th>摘要</th></tr></thead>";
        var tbody = document.createElement("tbody");
        for (var i = 0; i < _currentTemplates.length; i++) {
          var t = _currentTemplates[i];
          var summary = getTemplateSummary(t);
          var row = document.createElement("tr");
          var cbCell = document.createElement("td");
          var cb = document.createElement("input");
          cb.type = "checkbox";
          cb.checked = t.checked;
          cb.dataset.index = i;
          cb.addEventListener("change", function() {
            _currentTemplates[parseInt(this.dataset.index)].checked = this.checked;
          });
          cbCell.appendChild(cb);
          var nameCell = document.createElement("td");
          nameCell.textContent = t.name;
          var summaryCell = document.createElement("td");
          summaryCell.textContent = summary;
          summaryCell.style.fontSize = "12px";
          summaryCell.style.color = "var(--text-dim)";
          row.appendChild(cbCell);
          row.appendChild(nameCell);
          row.appendChild(summaryCell);
          tbody.appendChild(row);
        }
        table.appendChild(tbody);
        tmplListContainer.appendChild(table);
      }

      /** 生成模板摘要 */
      function getTemplateSummary(tmpl) {
        var e = tmpl.extra;
        if (!e) return "(无数据)";
        var cat = TYPE_TO_CATEGORY[tmplTypeSelect.value] || "character";
        if (cat === "character") {
          return [e.类型 || "冒险者", "Lv." + (e.等级 != null ? e.等级 : "?"), e.种族 || "", e.所属眷族 || ""].filter(Boolean).join(" · ");
        } else if (cat === "dungeon") {
          // 地下城类型显示怪物摘要
          var lvRange = e.等级范围 || {};
          var lvStr = "";
          if (lvRange.最低 != null && lvRange.最高 != null) {
            lvStr = "Lv." + lvRange.最低 + "-" + lvRange.最高;
          } else if (lvRange.最低 != null) {
            lvStr = "Lv." + lvRange.最低 + "+";
          }
          return [lvStr, e.稀有度 || "普通", e.种族 || "未知"].filter(Boolean).join(" · ");
        } else if (cat === "equip") {
          return [e.类别 || "装备", "品质" + (e.品质 || 1), e.部位 || "", (e.加成维度 || []).join("/")].filter(Boolean).join(" · ");
        } else if (cat === "skill") {
          return [e.类型 || "技能", e.等级 || "I", e.技能类型 || "", e.效果描述 || ""].filter(Boolean).join(" · ");
        }
        return "";
      }

      /** 加载模板列表 */
      async function loadTemplateList() {
        var cat = TYPE_TO_CATEGORY[tmplTypeSelect.value];
        if (!cat) return;
        setTmplStatus("正在加载...");
        try {
          if (cat === "dungeon") {
            // 地下城：加载所有楼层，填充楼层下拉
            var floorTemplates = await DungeonUtils.loadTemplates("dungeon");
            _allDungeonFloors = floorTemplates;
            // 按楼层号排序
            _allDungeonFloors.sort(function(a, b) { return (parseInt(a.name) || 0) - (parseInt(b.name) || 0); });
            // 填充楼层下拉
            dungeonFloorSelect.innerHTML = "";
            for (var fi = 0; fi < _allDungeonFloors.length; fi++) {
              var opt = document.createElement("option");
              opt.value = _allDungeonFloors[fi].name;
              opt.textContent = "第" + _allDungeonFloors[fi].name + "层 (" + Object.keys(_allDungeonFloors[fi].extra || {}).length + "种怪物)";
              dungeonFloorSelect.appendChild(opt);
            }
            // 显示楼层选择器
            dungeonFloorRow.style.display = "";
            // 默认选第一层
            if (_allDungeonFloors.length > 0) {
              dungeonFloorSelect.value = _allDungeonFloors[0].name;
              _currentDungeonFloor = _allDungeonFloors[0].name;
              loadMonstersForFloor(_currentDungeonFloor);
            } else {
              _currentTemplates = [];
              renderTemplateList();
            }
            setTmplStatus("已加载 " + _allDungeonFloors.length + " 个楼层");
          } else {
            // 非地下城：隐藏楼层选择器，原逻辑
            dungeonFloorRow.style.display = "none";
            var templates = await DungeonUtils.loadTemplates(cat);
            _currentTemplates = templates.map(function(t) {
              return { name: t.name, extra: t.extra, checked: false };
            });
            renderTemplateList();
            setTmplStatus("已加载 " + _currentTemplates.length + " 个模板");
          }
        } catch (e) {
          setTmplStatus("加载失败: " + e.message, true);
          _currentTemplates = [];
          _allDungeonFloors = [];
          dungeonFloorRow.style.display = "none";
          renderTemplateList();
        }
      }

      /** 从指定楼层加载怪物列表到 _currentTemplates */
      function loadMonstersForFloor(floorName) {
        var floorTmpl = _allDungeonFloors.find(function(f) { return f.name === floorName; });
        if (!floorTmpl || !floorTmpl.extra) {
          _currentTemplates = [];
          renderTemplateList();
          return;
        }
        var monsters = floorTmpl.extra;
        var names = Object.keys(monsters);
        _currentTemplates = names.map(function(n) {
          return { name: n, extra: monsters[n], _floor: floorName, checked: false };
        });
        _currentDungeonFloor = floorName;
        renderTemplateList();
      }

      /** 获取当前 sysbox 配置 */
      function getCurrentSysbox() {
        return DungeonUtils.loadSysboxData(getCurrentMessageId());
      }

      /** 导入单个角色模板到人物名录 */
      async function importCharacter(name) {
        var sysbox = getCurrentSysbox();
        var char = await DungeonUtils.createCharacterFromTemplate(name, sysbox);
        if (!char) return null;
        var vars = Mvu.getMvuData({ type: "message", message_id: getCurrentMessageId() });
        if (!vars.stat_data) vars.stat_data = {};
        if (!vars.stat_data.人物名录) vars.stat_data.人物名录 = {};
        vars.stat_data.人物名录[name] = char;
        await saveData(vars, { type: "message", message_id: getCurrentMessageId() });
        return char;
      }

      /** 导入楼层数据到当前地下城区域 */
      async function importFloorToDungeon(floorName) {
        var floorTmpl = _allDungeonFloors.find(function(f) { return f.name === floorName; });
        if (!floorTmpl || !floorTmpl.extra) return null;
        var vars = Mvu.getMvuData({ type: "message", message_id: getCurrentMessageId() });
        if (!vars.stat_data) vars.stat_data = {};
        // 写入当前地下城区域：设置层数 + 怪物数组（供快速探索渲染）+ 怪物模板（供敌人创建校验）
        var area = vars.stat_data.当前地下城区域 || {};
        area.层数 = parseInt(floorName, 10) || 1;
        area.怪物模板 = floorTmpl.extra; // 存储整层怪物模板供后续使用
        // 转换模板格式为怪物数组：{ "哥布林": {...} } → [{ 名字:"哥布林", 等级范围:{...}, 能力值范围:{...} }]
        var monsterNames = Object.keys(floorTmpl.extra);
        area.怪物 = monsterNames.map(function(name) {
          var m = floorTmpl.extra[name];
          return {
            名字: name,
            等级范围: m.等级范围 || { 最低: 1, 最高: 1 },
            能力值范围: m.能力值范围 || {},
          };
        });
        vars.stat_data.当前地下城区域 = area;
        await saveData(vars, { type: "message", message_id: getCurrentMessageId() });
        return { floor: floorName, monsters: monsterNames.length };
      }

      /** 导入单个怪物到敌人信息 */
      async function importDungeonMonsterToEnemy(name) {
        var tmpl = _currentTemplates.find(function(t) { return t.name === name; });
        if (!tmpl || !tmpl.extra) return null;
        var sysbox = getCurrentSysbox();
        var skillConfig = sysbox?.技能系统?.等级配置;
        var monTmpl = { key: name, data: tmpl.extra };
        var validated = DungeonUtils.validateAndRollMonster(name, { 等级: 0, 基础能力: {} }, monTmpl);
        var enemy = {
          基础信息: {
            姓名: name, 类型: "怪物",
            种族: validated.种族 || "未知", 稀有度: validated.稀有度 || "普通",
            技能列表: {},
          },
          状态: {},
          个人属性: {
            等级: validated.等级,
            基础能力: validated.基础能力,
            潜在能力: { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
            积累经验值: { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
            当前伟业: 0,
          },
          是否击败: false,
        };
        if (validated.技能列表) {
          var skillNames = Object.keys(validated.技能列表);
          for (var si = 0; si < skillNames.length; si++) {
            var skName = skillNames[si];
            var skMeta = validated.技能列表[skName];
            if (!skMeta) continue;
            var gradeConfig = skillConfig ? skillConfig[skMeta.等级] : null;
            if (!gradeConfig) continue;
            var skill = DungeonUtils.rollSkillValues({
              name: skName, type: skMeta.类型, grade: skMeta.等级,
              skill_type: skMeta.技能类型, dims: skMeta.加成维度,
              damage_types: skMeta.伤害类型, cost_types: skMeta.消耗类型,
              heal_types: skMeta.恢复类型, desc: skMeta.效果描述,
            }, gradeConfig);
            enemy.基础信息.技能列表[skName] = skill;
          }
        }
        var vars = Mvu.getMvuData({ type: "message", message_id: getCurrentMessageId() });
        if (!vars.stat_data) vars.stat_data = {};
        if (!vars.stat_data.敌人信息) vars.stat_data.敌人信息 = [];
        vars.stat_data.敌人信息.push(enemy);
        await saveData(vars, { type: "message", message_id: getCurrentMessageId() });
        return enemy;
      }

      /** 导入单个装备模板到主角持有物品 */
      async function importEquip(name) {
        var sysbox = getCurrentSysbox();
        var equip = await DungeonUtils.createEquipFromTemplate(name, sysbox);
        if (!equip) return null;
        var vars = Mvu.getMvuData({ type: "message", message_id: getCurrentMessageId() });
        if (!vars.stat_data) vars.stat_data = {};
        if (!vars.stat_data.主角) vars.stat_data.主角 = {};
        if (!vars.stat_data.主角.持有物品) vars.stat_data.主角.持有物品 = {};
        vars.stat_data.主角.持有物品[name] = equip;
        await saveData(vars, { type: "message", message_id: getCurrentMessageId() });
        return equip;
      }

      /** 导入单个技能模板到主角技能列表 */
      async function importSkill(name) {
        var sysbox = getCurrentSysbox();
        var skill = await DungeonUtils.createSkillFromTemplate(name, sysbox);
        if (!skill) return null;
        var vars = Mvu.getMvuData({ type: "message", message_id: getCurrentMessageId() });
        if (!vars.stat_data) vars.stat_data = {};
        if (!vars.stat_data.主角) vars.stat_data.主角 = {};
        if (!vars.stat_data.主角.基础信息) vars.stat_data.主角.基础信息 = {};
        if (!vars.stat_data.主角.基础信息.技能列表) vars.stat_data.主角.基础信息.技能列表 = {};
        vars.stat_data.主角.基础信息.技能列表[name] = skill;
        await saveData(vars, { type: "message", message_id: getCurrentMessageId() });
        return skill;
      }

      var IMPORT_FN = {
        character: importCharacter,
        dungeon: importDungeonMonsterToEnemy,
        equip: importEquip,
        skill: importSkill,
      };

      var IMPORT_LABEL = {
        character: "角色",
        dungeon: "怪物",
        equip: "装备",
        skill: "技能",
      };

      /** 导入选中的模板 */
      tmplImportSelected.addEventListener("click", async function() {
        var cat = TYPE_TO_CATEGORY[tmplTypeSelect.value];
        var importFn = IMPORT_FN[cat];
        if (!importFn) return;
        var selected = _currentTemplates.filter(function(t) { return t.checked; });
        if (!selected.length) { setTmplStatus("未选择任何模板", true); return; }
        setTmplStatus("正在导入 " + selected.length + " 个" + IMPORT_LABEL[cat] + "...");
        var ok = 0, fail = 0;
        for (var i = 0; i < selected.length; i++) {
          try {
            var result = await importFn(selected[i].name);
            if (result) ok++; else fail++;
          } catch (e) { fail++; }
        }
        setTmplStatus("导入完成: " + ok + " 成功" + (fail ? ", " + fail + " 失败" : ""));
      });

      /** 全部导入 */
      tmplImportAll.addEventListener("click", async function() {
        var cat = TYPE_TO_CATEGORY[tmplTypeSelect.value];
        var importFn = IMPORT_FN[cat];
        if (!importFn) return;
        if (!_currentTemplates.length) { setTmplStatus("没有可导入的模板", true); return; }
        setTmplStatus("正在全部导入 " + _currentTemplates.length + " 个" + IMPORT_LABEL[cat] + "...");
        var ok = 0, fail = 0;
        for (var i = 0; i < _currentTemplates.length; i++) {
          try {
            var result = await importFn(_currentTemplates[i].name);
            if (result) ok++; else fail++;
          } catch (e) { fail++; }
        }
        setTmplStatus("全部导入完成: " + ok + " 成功" + (fail ? ", " + fail + " 失败" : ""));
      });

      /** 导入楼层到当前地下城 */
      tmplImportFloor.addEventListener("click", async function() {
        if (!_currentDungeonFloor) { setTmplStatus("未选择楼层", true); return; }
        setTmplStatus("正在导入第" + _currentDungeonFloor + "层到当前地下城...");
        try {
          var result = await importFloorToDungeon(_currentDungeonFloor);
          if (result) {
            setTmplStatus("已导入第" + _currentDungeonFloor + "层 (" + result.monsters + "种怪物) 到当前地下城区域");
          } else {
            setTmplStatus("导入失败", true);
          }
        } catch (e) {
          setTmplStatus("导入失败: " + e.message, true);
        }
      });

      /** 楼层切换时重新加载怪物列表 */
      dungeonFloorSelect.addEventListener("change", function() {
        if (this.value) {
          _currentDungeonFloor = this.value;
          loadMonstersForFloor(this.value);
        }
      });

      // 全选 / 取消全选
      tmplSelectAll.addEventListener("click", function() {
        for (var i = 0; i < _currentTemplates.length; i++) { _currentTemplates[i].checked = true; }
        renderTemplateList();
      });
      tmplDeselectAll.addEventListener("click", function() {
        for (var i = 0; i < _currentTemplates.length; i++) { _currentTemplates[i].checked = false; }
        renderTemplateList();
      });

      // 类型切换时自动刷新
      tmplTypeSelect.addEventListener("change", loadTemplateList);
      tmplRefreshBtn.addEventListener("click", loadTemplateList);

      refreshUI();
      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => refreshUI());
    })();
  </script>
</body>

</html>
