    const LOOT_TABLE = {
      普通:   { common: 1,    rare: 0,    legendary: 0,    unique: 0    },
      良好:   { common: 0.2,  rare: 0.7,  legendary: 0.1,  unique: 0    },
      上等:   { common: 0,    rare: 0.2,  legendary: 0.7,  unique: 0.1  },
      异化:   { common: 0,    rare: 0,    legendary: 0.2,  unique: 0.8  },
    };

    var RARITY_MAP = { "精英": "良好", "变异": "上等", "楼层主": "异化" };
    function calcLootByRarity(rarity) {
      var key = RARITY_MAP[rarity] || rarity;
      var rates = LOOT_TABLE[key] || LOOT_TABLE["普通"];
      var r = Math.random();
      var cum = 0;
      if (r < (cum += rates.common)) return "common";
      if (r < (cum += rates.rare)) return "rare";
      if (r < (cum += rates.legendary)) return "legendary";
      return "unique";
    }

