    function formatInstruction(inst) {
      if (!inst || !inst.指令) return "未知指令";
      var cmd = inst.指令;
      var target = inst.目标 || "";
      var parts = [];
      // Key params by command type
      switch (cmd) {
        case "状态变动":
          if (inst.HP变动 != null) parts.push("HP " + (inst.HP变动 > 0 ? "+" : "") + inst.HP变动 + "%");
          if (inst.SP变动 != null) parts.push("SP " + (inst.SP变动 > 0 ? "+" : "") + inst.SP变动 + "%");
          if (inst.MP变动 != null) parts.push("MP " + (inst.MP变动 > 0 ? "+" : "") + inst.MP变动 + "%");
          if (inst.身体状况变动 != null) parts.push("身体状况 " + (inst.身体状况变动 > 0 ? "+" : "") + inst.身体状况变动);
          if (inst.灵魂纯洁度变动 != null) parts.push("灵魂纯洁度 " + (inst.灵魂纯洁度变动 > 0 ? "+" : "") + inst.灵魂纯洁度变动);
          if (inst.声誉值变动 != null) parts.push("声誉 " + (inst.声誉值变动 > 0 ? "+" : "") + inst.声誉值变动);
          break;
        case "存款变更":
          if (inst.变动 != null) parts.push((inst.变动 > 0 ? "+" : "") + inst.变动 + " 法利");
          break;
        case "属性设置":
          if (inst.所属眷族 != null) parts.push("眷族→" + inst.所属眷族);
          if (inst.到达层数 != null) parts.push("到达层数→" + inst.到达层数);
          if (inst.破限 != null) parts.push("破限→" + inst.破限);
          if (inst.伟业变动 != null) parts.push("伟业 " + (inst.伟业变动 > 0 ? "+" : "") + inst.伟业变动);
          if (inst.身份职业 != null) parts.push("职业→" + inst.身份职业.join(","));
          if (inst.移除身份职业 != null) parts.push("移除职业: " + inst.移除身份职业.join(","));
          if (inst.成长期望 != null) parts.push("成长期望已设置");
          break;
        case "经验积累":
          ["力量","耐力","灵巧","敏捷","魔力"].forEach(function(k) {
            if (inst[k] != null && inst[k] > 0) parts.push(k + " +" + inst[k]);
          });
          break;
        case "角色信息":
          if (inst.称号 != null) parts.push("称号→" + inst.称号);
          if (inst.所在位置 != null) parts.push("位置→" + inst.所在位置);
          if (inst.心境 != null) parts.push("心境→" + inst.心境);
          if (inst.评价 != null) parts.push("评价→" + inst.评价);
          if (inst.负面状态 != null) parts.push("负面状态: " + inst.负面状态.join(","));
          if (inst.移除负面状态 != null) parts.push("移除负面: " + inst.移除负面状态.join(","));
          break;
        case "关系变更":
          if (inst.情深变动 != null) parts.push("情深 " + (inst.情深变动 > 0 ? "+" : "") + inst.情深变动);
          if (inst.当前关系 != null) parts.push("关系→" + inst.当前关系);
          break;
        case "眷族设置":
          if (inst.据点 != null) parts.push("据点→" + inst.据点);
          if (inst.财务变动 != null) parts.push("财务 " + (inst.财务变动 > 0 ? "+" : "") + inst.财务变动);
          if (inst.眷族等级 != null) parts.push("等级→" + inst.眷族等级);
          if (inst.到达层数 != null) parts.push("到达层数→" + inst.到达层数);
          break;
        case "地下城设置":
          if (inst.层数 != null) parts.push("进入第" + inst.层数 + "层");
          if (inst.怪物 != null) parts.push(inst.怪物.length + "种怪物");
          break;
        case "角色创建":
          parts.push((inst.角色类型 || "NPC") + " | " + (inst.种族 || "?"));
          if (inst.性别) parts.push(inst.性别);
          if (inst.等级 != null) parts.push("Lv." + inst.等级);
          break;
        case "敌人创建":
          parts.push("Lv." + (inst.等级 || "?") + " | " + (inst.种族 || "?"));
          if (inst.稀有度) parts.push(inst.稀有度);
          break;
        case "敌人移除":
          parts.push("移除 " + target);
          break;
        case "敌人被击败":
          parts.push("击败 " + target);
          break;
        case "组队加入":
          parts.push(target + " 加入队伍");
          break;
        case "组队离开":
          parts.push(target + " 离开队伍");
          break;
        case "加入眷族":
          parts.push("主神: " + (inst.主神 || "?"));
          break;
        case "装备生成":
          parts.push((inst.名称 || "?") + " | " + (inst.部位 || ""));
          if (inst.品质) parts.push("品质" + inst.品质);
          break;
        case "技能生成":
          parts.push((inst.名称 || "?") + " | " + (inst.类型 || ""));
          if (inst.等级) parts.push(inst.等级);
          break;
        case "物品添加":
          parts.push((inst.名称 || "?") + " x" + (inst.数量 || 1));
          break;
        case "物品增减":
          parts.push((inst.物品名称 || "?") + " " + (inst.数量 > 0 ? "+" : "") + (inst.数量 || 0));
          break;
        case "物品转移":
          parts.push((inst.物品名称 || "?") + " ← " + (inst.来源 || ""));
          break;
        default:
          // Show all non-empty params
          Object.keys(inst).forEach(function(k) {
            if (k === "指令" || k === "目标") return;
            var v = inst[k];
            if (v != null && v !== "" && v !== false) {
              if (Array.isArray(v)) parts.push(k + ": [" + v.join(",") + "]");
              else if (typeof v === "object") parts.push(k + ": {...}");
              else parts.push(k + ": " + v);
            }
          });
      }
      var summary = parts.length > 0 ? parts.join(" | ") : "(无参数)";
      return { cmd: cmd, target: target, summary: summary };
    }

    function renderReview() {
      var container = document.getElementById("review-container");
      if (!container) return;
      var all = getFullVariables();
      var sd = _.get(all, "stat_data", {});
      var instructions = sd.操作指令 || [];
      var manualReview = _.get(sd, "sysbox.剧情相关.手动审查", false);

      var html = "";
      if (!manualReview && instructions.length === 0) {
        html = "<div style=\"padding:20px;color:#605040;text-align:center;font-size:13px;\">审查模式未开启，指令将自动执行</div>";
      } else if (instructions.length === 0) {
        html = "<div style=\"padding:20px;color:#8a8070;text-align:center;font-size:13px;\">暂无待审查的指令</div>";
      } else {
        html += "<div style=\"padding:6px 12px;color:#b89b6b;font-size:12px;margin-bottom:8px;\">共 " + instructions.length + " 条待审查指令</div>";
        for (var i = 0; i < instructions.length; i++) {
          var inst = instructions[i];
          var fmt = formatInstruction(inst);
          html += "<div class=\"review-card\">";
          html += "<div class=\"review-card-left\">";
          html += "<span class=\"review-idx\">#" + (i + 1) + "</span>";
          html += "<span class=\"review-cmd\">" + escHtml(fmt.cmd) + "</span>";
          if (fmt.target) html += "<span class=\"review-target\">→ " + escHtml(fmt.target) + "</span>";
          html += "<span class=\"review-summary\">" + escHtml(fmt.summary) + "</span>";
          html += "</div>";
          html += "<button class=\"review-del-btn\" data-review-delete=\"" + i + "\" title=\"删除此指令\">×</button>";
          html += "</div>";
        }
        html += "<div style=\"display:flex;gap:10px;justify-content:center;margin-top:12px;padding-top:10px;border-top:1px solid rgba(212,168,83,0.15);\">";
        html += "<button class=\"page-btn\" data-review-execute=\"1\" style=\"border-color:#50c878;color:#50c878;\">执行全部</button>";
        html += "<button class=\"page-btn\" data-review-clear=\"1\" style=\"border-color:#e05050;color:#e05050;\">清空全部</button>";
        html += "</div>";
      }
      container.innerHTML = html;
    }

    function escHtml(s) {
      if (!s) return "";
      var A = String.fromCharCode(38);
      return String(s)
        .replace(/&/g, A + "amp;")
        .replace(/</g, A + "lt;")
        .replace(/>/g, A + "gt;")
        .replace(/"/g, A + "quot;");
    }

    function deleteReviewCommand(index) {
      var all = getFullVariables();
      var sd = _.get(all, "stat_data", {});
      if (sd.操作指令 && index >= 0 && index < sd.操作指令.length) {
        sd.操作指令.splice(index, 1);
        saveVariablesToMvu(all);
        renderReview();
      }
    }

    function clearAllReviewCommands() {
      var all = getFullVariables();
      var sd = _.get(all, "stat_data", {});
      if (sd.操作指令 && sd.操作指令.length > 0) {
        sd.操作指令 = [];
        saveVariablesToMvu(all);
        renderReview();
      }
    }

    function executeReviewedCommands() {
      var all = getFullVariables();
      var sd = _.get(all, "stat_data", {});
      if (!sd.操作指令 || sd.操作指令.length === 0) return;
      var cmdUtils = window.top?.CommandUtils || window.CommandUtils;
      if (!cmdUtils) {
        console.error("[审查] CommandUtils 未就绪");
        return;
      }
      cmdUtils.fullTransform(sd, { forceExecute: true });
      saveVariablesToMvu(all);
      scheduleRender();
    }

