              "</span>" +
              "<span>能力 | 力:" +
              formatRange(range.力量) +
              " 耐:" +
              formatRange(range.耐力) +
              " 灵:" +
              formatRange(range.灵巧) +
              " 敏:" +
              formatRange(range.敏捷) +
              " 魔:" +
              formatRange(range.魔力) +
