      const partyKeys = Object.keys(partyMap);

      if (!partyKeys.length) {
        DOM.partyPanel.html('<div class="empty-hint">当前没有组队成员</div>');
        return;
      }

      // 根据姓名从人物名录获取完整数据
      const partyEntries = partyKeys
        .map((name) => {
          const full = npcList[name];
          return full ? { name, data: full } : null;
        })
        .filter(Boolean);

      if (!partyEntries.length) {
        DOM.partyPanel.html(
          '<div class="empty-hint">无法获取队友详细数据</div>',
        );
        return;
      }

      // 分页
      const totalPages = Math.ceil(partyEntries.length / PARTY_PER_PAGE);
      partyPage = _.clamp(partyPage, 0, Math.max(0, totalPages - 1));
      const pageEntries = partyEntries.slice(
        partyPage * PARTY_PER_PAGE,
        (partyPage + 1) * PARTY_PER_PAGE,
      );

      // 生成队友卡片 HTML
      const cardsHtml = pageEntries
        .map(({ name, data }) => {
          const info = data.基础信息 || {};
          const attr = data.个人属性 || {};
          const status = data.状态 || {};
          const equip = data.装备栏 || {};
          const skills = data.基础信息?.技能列表 || {};
          const baseStats = attr.基础能力 || {};
          const growth = attr.成长期望 || {};

          // 基本属性
          const level = attr.等级 || 0;
          const grade =
            attr.整体评价 ||
            U.getGrade(
              Math.max(
                baseStats.力量 || 0,
                baseStats.耐力 || 0,
                baseStats.灵巧 || 0,
                baseStats.敏捷 || 0,
                baseStats.魔力 || 0,
              ),
            );
          const feats = attr.当前伟业 || 0;
          const racial = info.种族 || "？";
          const gender = info.性别 || "？";

          // 能力值行
          const statsRows = STAT_KEYS.map((k) => {
            const val = baseStats[k] || 0;
            const g = U.getGrade(val);
            return `<div class="party-stat-item"><span class="party-stat-label">${STAT_LABELS[k]}</span><span class="party-stat-grade">${g}</span><span class="party-stat-value">${val}</span></div>`;
          }).join("");

          // 成长期望行
          const growthRows = STAT_KEYS.map((k) => {
            const v = growth[k.replace("值", "")] || 0;
            return v > 0 ? `<span>${STAT_LABELS[k]}+${v}</span>` : "";
          })
            .filter(Boolean)
            .join(" ");
          const growthHtml = growthRows
            ? `<div class="party-sub-title">📈 成长期望</div><div class="party-growth">${growthRows}</div>`
            : "";

          // 装备列表
          const equipSlots = [
            "主手",
            "副手",
            "头部",
            "身体",
            "护手",
            "鞋子",
            "饰品1",
            "饰品2",
          ];
          const equipItems = [];
          equipSlots.forEach((slot) => {
            const item = equip[slot];
            if (item && item.名称) {
              const bonuses = item.装备属性?.加成 || {};
              const bonusText = STAT_KEYS.map((k) => {
                const val = bonuses[k];
                if (val && val !== 0) {
                  const sign = val > 0 ? "+" : "";
                  return `<span class="${val > 0 ? "positive" : "negative"}">${STAT_LABELS[k]}${sign}${(val * 100).toFixed(1)}%</span>`;
                }
                return "";
              })
                .filter(Boolean)
                .join(" ");
              equipItems.push(
                `<div class="party-equip-item">${slot}：${item.名称} ${bonusText}</div>`,
              );
            }
          });
          (equip.特殊 || []).forEach((item) => {
            if (!item || !item.名称) return;
            const bonuses = item.装备属性?.加成 || {};
            const bonusText = STAT_KEYS.map((k) => {
              const val = bonuses[k];
              if (val && val !== 0) {
                const sign = val > 0 ? "+" : "";
                return `<span class="${val > 0 ? "positive" : "negative"}">${STAT_LABELS[k]}${sign}${(val * 100).toFixed(1)}%</span>`;
              }
              return "";
            })
              .filter(Boolean)
              .join(" ");
            equipItems.push(
              `<div class="party-equip-item">✨：${item.名称} ${bonusText}</div>`,
            );
          });
          const equipHtml = equipItems.length
            ? `<div class="party-sub-title">⚔️ 装备</div><div class="party-equip-list">${equipItems.join("")}</div>`
            : '<div class="party-sub-title">⚔️ 装备</div><div style="color:#555;font-size:11px;">无装备</div>';

          // 技能列表
          const skillEntries = Object.entries(skills);
          const skillsHtml = skillEntries.length
            ? `<div class="party-sub-title">📜 技能</div><div class="party-skill-list">${skillEntries
              .map(([skName, sk]) => {
                const skBonus = sk.加成 || {};
                const skBonusText = STAT_KEYS.map((k) => {
                  if (k === "特殊") {
                    return `<span style="color:var(--gold)">${skBonus[k]}</span>`; // 直接展示金色文字
                  }
                  const val = skBonus[k];
                  if (val && val !== 0) {
                    const sign = val > 0 ? "+" : "";
                    return `<span class="${val > 0 ? "positive" : "negative"}">${STAT_LABELS[k]}${sign}${(val * 100).toFixed(1)}%</span>`;
                  }
                  return "";
                })
                  .filter(Boolean)
                  .join(" ");
                const skCostHeal = [
                  sk.伤害比例 ? `<span style="color:#e8c070">伤害×${Math.round(sk.伤害比例*100)}%</span>` : "",
                  sk.回复HP比例||sk.回复SP比例||sk.回复MP比例
                    ? `<span style="color:#50c878">回复:${sk.回复HP比例?" HP×"+Math.round(sk.回复HP比例*100)+"%":""}${sk.回复SP比例?" SP×"+Math.round(sk.回复SP比例*100)+"%":""}${sk.回复MP比例?" MP×"+Math.round(sk.回复MP比例*100)+"%":""}</span>`
                    : "",
                  sk.消耗SP百分比||sk.消耗MP百分比
                    ? `<span style="color:#a0c8e6">消耗:${sk.消耗SP百分比?" SP"+Math.round(sk.消耗SP百分比*100)+"%":""}${sk.消耗MP百分比?" MP"+Math.round(sk.消耗MP百分比*100)+"%":""}</span>`
                    : "",
                ].filter(Boolean).join(" ");
                return `<div class="party-skill-item">${skName} <span style="color:var(--gold)">${sk.等级 || "I"}</span> ${sk.技能类型 === "被动" ? "🛡️" : "⚡"} ${skBonusText} ${skCostHeal}</div>`;
              })
              .join("")}</div>`
            : '<div class="party-sub-title">📜 技能</div><div style="color:#555;font-size:11px;">无技能</div>';

          const curHp = status.HP当前值 ?? 0;
          const maxHp = status.HP上限 ?? 0;
          const curSp = status.SP当前值 ?? 0;
          const maxSp = status.SP上限 ?? 0;
          const curMp = status.MP当前值 ?? 0;
          const maxMp = status.MP上限 ?? 0;

          return `
        <div class="party-card">
          <div class="party-head">
            <div>
              <span class="party-name">${name}</span>
              <span style="font-size:10px;color:var(--text-dim);margin-left:4px;">${racial} ${gender}</span>
            </div>
            <span class="party-grade">${grade}</span>
          </div>
          <div style="display:flex;gap:10px;margin-bottom:6px;font-size:12px;">
            <span>HP <span style="color:var(--hp-color);font-weight:bold;">${curHp}/${maxHp}</span></span>
            <span>SP <span style="color:var(--sp-color);font-weight:bold;">${curSp}/${maxSp}</span></span>
            <span>MP <span style="color:var(--mp-color);font-weight:bold;">${curMp}/${maxMp}</span></span>
          </div>
          <div class="party-stats">
            <div class="party-stat-item"><span class="party-stat-label">等级</span><span class="party-stat-value">Lv.${level}</span></div>
            <div class="party-stat-item"><span class="party-stat-label">伟业</span><span class="party-stat-value">${feats}</span></div>
          </div>
          <div class="party-detail">
            <div class="party-sub-title">📊 基础能力</div>
            <div class="party-stats">${statsRows}</div>
            ${growthHtml}
            ${equipHtml}
            ${skillsHtml}
            <button class="party-manage-btn" data-party-name="${name.replace(/"/g, '&amp;quot;')}">管理</button>
            <button class="party-remove-btn" data-party-name="${name.replace(/"/g, '&amp;quot;')}">移出队伍</button>
          </div>
        </div>
      `;
        })
        .join("");

      // 分页按钮
      const paginationHtml =
        totalPages > 1
          ? `<div class="pagination">
        <button class="page-btn" id="party-prev-btn" ${partyPage <= 0 ? "disabled" : ""}>◀ 上页</button>
        <span style="color:var(--text-dim);font-size:12px;">${partyPage + 1} / ${totalPages}</span>
        <button class="page-btn" id="party-next-btn" ${partyPage >= totalPages - 1 ? "disabled" : ""}>下页 ▶</button>
       </div>`
          : "";

      DOM.partyPanel.html(
        `<div class="party-grid">${cardsHtml}</div>${paginationHtml}`,
      );

      // 绑定分页按钮事件
      $("#party-prev-btn")
        .off("click")
        .on("click", () => {
          if (partyPage > 0) {
            partyPage--;
            renderParty(sd);
          }
        });
      $("#party-next-btn")
        .off("click")
        .on("click", () => {
          const maxPage = Math.ceil(partyEntries.length / PARTY_PER_PAGE) - 1;
          if (partyPage < maxPage) {
            partyPage++;
            renderParty(sd);
          }
        });
    }

    function renderInventory() {
      var total = Math.ceil(invData.length / INV_PER_PAGE);
      invPage = _.clamp(invPage, 0, Math.max(0, total - 1));
      DOM.invPageInfo.text(
        (invData.length ? invPage + 1 : 0) + " / " + total,
      );
      if (!invData.length) {
        DOM.invContainer.html('<div class="empty-hint">物品栏为空</div>');
        return;
      }
      var pageItems = invData.slice(
        invPage * INV_PER_PAGE,
        (invPage + 1) * INV_PER_PAGE,
      );
      var html = pageItems
        .map((entry) => {
          var iName = entry[0],
            iData = entry[1];
          var equippable = isItemEquippable(iData);
          var consumable = isItemConsumable(iData);
          var consumableDetailHtml = "";
          var useBtnHtml = "";
          if (consumable) {
            var eff = iData.消耗效果 || {};
            var parts = [];
            if (eff.回复HP) parts.push("HP+" + eff.回复HP);
            if (eff.回复SP) parts.push("SP+" + eff.回复SP);
            if (eff.回复MP) parts.push("MP+" + eff.回复MP);
            if (eff.回复HP百分比)
              parts.push("HP+" + Math.round(eff.回复HP百分比 * 100) + "%");
            if (eff.回复SP百分比)
              parts.push("SP+" + Math.round(eff.回复SP百分比 * 100) + "%");
            if (eff.回复MP百分比)
              parts.push("MP+" + Math.round(eff.回复MP百分比 * 100) + "%");
            consumableDetailHtml =
              "<div>🧪 效果: " + parts.join(" ") + "</div>";
            useBtnHtml =
              '<button class="item-use-btn" data-item-name="' +
              iName.replace(/"/g, '"') +
              '">🧪 使用</button>';
          }
          var equipDetailHtml = "";
          var equipBtnHtml = "";
          if (equippable) {
            var equipProp = iData.装备属性 || {};
            var part = equipProp.部位 || "?";
            var bonuses = equipProp.加成 || {};
            var bonusStr = "";
            Object.keys(bonuses).forEach(function (bk) {
              var val = bonuses[bk];
              if (val && val !== 0) {
                var sign = val > 0 ? "+" : "";
                bonusStr +=
                  '<span style="color:' +
                  (val > 0 ? "#50c878" : "#e05050") +
                  '">' +
                  (STAT_LABELS[bk] || bk) +
                  sign +
                  val +
                  "</span> ";
              }
            });
            var effectName = equipProp.效果名称 || "";
            equipDetailHtml =
              "<div>⚔ 部位: " +
              part +
              "</div>" +
              (bonusStr ? "<div>加成: " + bonusStr + "</div>" : "") +
              (effectName
                ? "<div>✨ 效果: " + effectName + "</div>"
                : "");
            equipBtnHtml =
              '<button class="item-equip-btn" data-item-name="' +
              iName.replace(/"/g, '"') +
              '">⚔ 装备</button>';
          }
          return (
            '<div class="item-card quality-' +
            (iData.品质 || 1) +
            ' item-toggle" data-item-name="' +
            iName.replace(/"/g, '"') +
            '">' +
            '<button class="item-delete-btn" data-item-name="' +
            iName.replace(/"/g, '"') +
            '" title="删除物品">✕</button>' +
            '<div style="font-weight:bold">' +
            iName +
            " x" +
            iData.数量 +
            "</div>" +
            '<div class="item-details">' +
            "<div>📌 类别: " +
            (iData.类别 || "杂物") +
            "</div>" +
            "<div>💰 单价: " +
            FMT.format(iData.单价 || 0) +
            " 法利</div>" +
            (iData.描述 ? '<div style="margin-top:2px;">📝 ' + iData.描述 + "</div>" : "") +
            (iData.效果描述
              ? '<div style="margin-top:2px;color:var(--gold);font-weight:bold">✨ ' + iData.效果描述 + "</div>"
              : "") +
            (consumableDetailHtml
              ? '<div style="margin-top:4px;padding-top:4px;border-top:1px dashed rgba(255,255,255,0.1);font-size:12px;">' +
              consumableDetailHtml +
              "</div>"
              : "") +
            (useBtnHtml
              ? '<div style="margin-top:4px;">' + useBtnHtml + "</div>"
              : "") +
            (equipDetailHtml
              ? '<div style="margin-top:4px;padding-top:4px;border-top:1px dashed rgba(255,255,255,0.1);font-size:12px;">' +
              equipDetailHtml +
              "</div>"
              : "") +
            (equipBtnHtml
              ? '<div style="margin-top:4px;">' + equipBtnHtml + "</div>"
              : "") +
            '<div style="margin-top:4px;"><button class="item-transfer-btn page-btn" data-item-name="' + iName.replace(/"/g, '"') + '" style="font-size:11px;padding:2px 8px;color:#eacd92;">转移</button></div>' +
            "</div></div>"
          );
        })
        .join("");
      DOM.invContainer.html('<div class="item-list">' + html + '</div>');
    }

    // ========== 装备栏交互系统 ==========
    var EQUIP_SLOT_KEYS = [
      "主手",
      "副手",
      "头部",
      "身体",
      "护手",
      "鞋子",
      "饰品1",
      "饰品2",
    ];
    var EQUIP_SLOT_LABELS = {
      主手: "主手",
      副手: "副手",
      头部: "头部",
      身体: "身体",
      护手: "护手",
      鞋子: "鞋子",
      饰品1: "饰品①",
      饰品2: "饰品②",
    };
    var EQUIP_SLOT_ICONS = {
      主手: "⚔",
      副手: "🛡",
      头部: "⛑",
      身体: "🦺",
      护手: "✊",
      鞋子: "👢",
      饰品1: "💍",
      饰品2: "💍",
    };

    // 判断物品是否为可装备
    function isItemEquippable(item) {
      if (!item || !item.装备属性) return false;
      var part = item.装备属性.部位;
      if (!part || part === "无法装备" || part === "杂物") return false;
      return true;
    }

    // 判断物品是否为可消耗品（有消耗效果且至少一项回复值>0）
    function isItemConsumable(item) {
      if (!item || !item.消耗效果) return false;
      var eff = item.消耗效果;
      return (
        (eff.回复HP || 0) > 0 ||
        (eff.回复SP || 0) > 0 ||
        (eff.回复MP || 0) > 0 ||
        (eff.回复HP百分比 || 0) > 0 ||
        (eff.回复SP百分比 || 0) > 0 ||
        (eff.回复MP百分比 || 0) > 0
      );
    }

    // 使用消耗品
    function useConsumableItem(itemName, itemData, charName) {
      charName = charName || "主角";
      if (!isItemConsumable(itemData)) return false;
      var eff = itemData.消耗效果;
      var variables = getFullVariables();
      if (!variables) {
        console.warn('[小游戏] 无法获取当前楼层变量，操作取消');
        return false;
      }
      var statData = _.get(variables, "stat_data", {});
      // 主角和人物名录角色的数据路径不同
      var charObj, statusPath, invPath;
      if (charName === "主角") {
        charObj = _.get(statData, "主角", {});
        statusPath = "主角.状态";
        invPath = "主角.持有物品";
      } else {
        charObj = _.get(statData, "人物名录." + charName, {});
        statusPath = "人物名录." + charName + ".状态";
        invPath = "人物名录." + charName + ".持有物品";
      }
      var status = charObj.状态 || {};
      var inv = charObj.持有物品 || {};
      var invItem = inv[itemName];
      if (!invItem || invItem.数量 <= 0) return false;
      var maxHp = status.HP上限 || 100;
      var maxSp = status.SP上限 || 100;
      var maxMp = status.MP上限 || 50;
      var hpHeal =
        (eff.回复HP || 0) + Math.floor(maxHp * (eff.回复HP百分比 || 0));
      var spHeal =
        (eff.回复SP || 0) + Math.floor(maxSp * (eff.回复SP百分比 || 0));
      var mpHeal =
        (eff.回复MP || 0) + Math.floor(maxMp * (eff.回复MP百分比 || 0));
      if (hpHeal <= 0 && spHeal <= 0 && mpHeal <= 0)
        return false;
      status.HP当前值 = Math.min(maxHp, (status.HP当前值 || 0) + hpHeal);
      status.SP当前值 = Math.min(maxSp, (status.SP当前值 || 0) + spHeal);
      status.MP当前值 = Math.min(maxMp, (status.MP当前值 || 0) + mpHeal);
      invItem.数量 -= 1;
      if (invItem.数量 <= 0) {
        delete inv[itemName];
      }
      _.set(statData, statusPath + ".HP当前值", status.HP当前值);
      _.set(statData, statusPath + ".SP当前值", status.SP当前值);
      _.set(statData, statusPath + ".MP当前值", status.MP当前值);
      _.set(statData, invPath, inv);
      saveVariablesToMvu(variables);
      return true;
    }

    // 根据部位确定装备槽位 key
    function getTargetSlotKey(part) {
      if (part === "饰品") return null; // 需要特殊处理
      if (part === "特殊") return "特殊";
      if (EQUIP_SLOT_KEYS.indexOf(part) !== -1) return part;
      return null;
    }

    // 找到可用的饰品槽位
    function findOrReplaceAccessorySlot(equip) {
      if (!equip["饰品1"]) return "饰品1";
      if (!equip["饰品2"]) return "饰品2";
      return "饰品1"; // 都满了，顶替饰品1
    }

    // 获取当前楼层变量的安全函数
    function getFullVariables() {
      try {
        const messageId = getCurrentMessageId();
        if (messageId == null) return {};
        const data = Mvu.getMvuData({ type: 'message', message_id: messageId });
        if (data && _.has(data, 'stat_data')) {
          return _.cloneDeep(data);
        }
      } catch (e) {
        console.warn('getFullVariables 失败:', e);
      }
      return {};
    }
    // 写回变量到楼层（只允许当前楼层）
    async function saveVariablesToMvu(data) {
      try {
        const messageId = getCurrentMessageId();
        if (messageId == null) {
          console.error('[小游戏] 获取楼层ID失败，无法保存变量');
          return;
        }
        var C = window.top?.CommandUtils || window.CommandUtils;
        if (C && C.saveData) {
          await C.saveData(data, { type: "message", message_id: messageId });
        } else {
          await Mvu.replaceMvuData(data, { type: "message", message_id: messageId });
        }
      } catch (e) {
        console.error("saveVariablesToMvu failed:", e);
      }
    }
    // 装备物品：从持有物品到装备栏
    function equipItem(itemName, itemData) {
      if (!isItemEquippable(itemData)) return false;

      var part = itemData.装备属性.部位;
      var slotKey = getTargetSlotKey(part);

      var variables = getFullVariables();
      var statData = _.get(variables, "stat_data", {});
      var inv = _.get(statData, "主角.持有物品", {});
      var equip = _.get(statData, "主角.装备栏", {});

      if (!equip.特殊) equip.特殊 = [];

      var invItem = inv[itemName];
      if (!invItem || invItem.数量 <= 0) return false;

      var targetSlot;
      if (slotKey === "特殊") {
        targetSlot = "特殊";
      } else if (slotKey === null && part === "饰品") {
        targetSlot = findOrReplaceAccessorySlot(equip);
      } else if (slotKey) {
        targetSlot = slotKey;
      } else {
        return false;
      }

      var equipItemCopy = _.cloneDeep(invItem);
      equipItemCopy.名称 = itemName;
      equipItemCopy.数量 = 1;

      if (targetSlot === "特殊") {
        var sameNameItem = equip.特殊.some(function (si) {
          return si.名称 === equipItemCopy.名称;
        });
        if (sameNameItem) {
          console.warn("同名特殊装备不能重复装备:", equipItemCopy.名称);
          return false;
        }
        equip.特殊.push(equipItemCopy);
      } else {
        var oldItem = equip[targetSlot];
        if (oldItem) {
          if (!inv[oldItem.名称]) {
            inv[oldItem.名称] = _.cloneDeep(oldItem);
          } else {
            inv[oldItem.名称].数量 += oldItem.数量;
          }
        }
        equip[targetSlot] = equipItemCopy;
      }

      invItem.数量 -= 1;
      if (invItem.数量 <= 0) {
        delete inv[itemName];
      }

      _.set(statData, "主角.持有物品", inv);
      _.set(statData, "主角.装备栏", equip);
      saveVariablesToMvu(variables);

      return true;
    }

    // 卸下装备：从装备栏回持有物品
    function unequipItem(slotKey, specialIndex) {
      var variables = getFullVariables();
      var statData = _.get(variables, "stat_data", {});
      var inv = _.get(statData, "主角.持有物品", {});
      var equip = _.get(statData, "主角.装备栏", {});

      if (!equip.特殊) equip.特殊 = [];

      var itemToRemove = null;
      if (slotKey === "特殊") {
        if (specialIndex < 0 || specialIndex >= equip.特殊.length)
          return false;
        itemToRemove = equip.特殊[specialIndex];
        equip.特殊.splice(specialIndex, 1);
      } else {
        itemToRemove = equip[slotKey];
        if (!itemToRemove) return false;
        equip[slotKey] = null;
      }

      if (!itemToRemove.名称) {
        itemToRemove.名称 =
          slotKey === "特殊" ? "特殊物品" + (specialIndex + 1) : slotKey;
      }

      if (!inv[itemToRemove.名称]) {
        inv[itemToRemove.名称] = _.cloneDeep(itemToRemove);
      } else {
        inv[itemToRemove.名称].数量 += itemToRemove.数量;
      }

      _.set(statData, "主角.持有物品", inv);
      _.set(statData, "主角.装备栏", equip);
      saveVariablesToMvu(variables);

      return true;
    }

