      // 构建目标角色下拉列表
      var all = getFullVariables();
      var sd = _.get(all, "stat_data", {});
      var optionsHtml = "";
      if (sourceCharName !== "主角") {
        optionsHtml += '<option value="主角">主角</option>';
      }
      var npcList = sd.人物名录 || {};
      Object.keys(npcList).forEach(function (name) {
