    function executeItemTransfer() {
      if (!transferSourceChar || !transferItemName) return;
      var qty = parseInt($("#transfer-qty-input").val()) || 0;
      if (qty <= 0 || qty > transferMaxQty) return;
      var targetName = $("#transfer-target-select").val();
      if (!targetName) return;

      var all = getFullVariables();
      var sd = _.get(all, "stat_data", {});

      // 获取来源角色的持有物品
      var sourceObj, sourceInvPath;
      if (transferSourceChar === "主角") {
        sourceObj = _.get(sd, "主角", {});
        sourceInvPath = "主角.持有物品";
      } else {
        sourceObj = _.get(sd, "人物名录." + transferSourceChar);
        sourceInvPath = "人物名录." + transferSourceChar + ".持有物品";
      }
      // 获取目标角色的持有物品
      var targetObj, targetInvPath;
      if (targetName === "主角") {
        targetObj = _.get(sd, "主角", {});
        targetInvPath = "主角.持有物品";
      } else {
        targetObj = _.get(sd, "人物名录." + targetName);
        targetInvPath = "人物名录." + targetName + ".持有物品";
      }
      if (!sourceObj || !targetObj) return;

      var sourceInv = sourceObj.持有物品 || {};
      var targetInv = targetObj.持有物品 || {};
      var sourceItem = sourceInv[transferItemName];
      if (!sourceItem || sourceItem.数量 < qty) return;

      // 从来源扣减
      sourceItem.数量 -= qty;
      if (sourceItem.数量 <= 0) delete sourceInv[transferItemName];

      // 向目标添加
      if (targetInv[transferItemName]) {
        targetInv[transferItemName].数量 += qty;
      } else {
        var transferItem = _.cloneDeep(sourceItem);
        transferItem.数量 = qty;
        targetInv[transferItemName] = transferItem;
      }

      _.set(sd, sourceInvPath, sourceInv);
      _.set(sd, targetInvPath, targetInv);
      saveVariablesToMvu(all);
      $("#item-transfer-modal").hide();

      // 刷新当前面板
      if (partyManageCharName) {
        all = getFullVariables();
        sd = _.get(all, "stat_data", {});
        var npc = _.get(sd, "人物名录." + partyManageCharName);
        if (npc) {
          renderPartyManageEquipBar(npc);
          partyManageInvData = Object.entries(_.get(npc, "持有物品", {}));
          renderPartyManageInventory();
        }
      } else {
        // 主角物品栏刷新
        all = getFullVariables();
        sd = _.get(all, "stat_data", {});
        var plInv = _.get(sd, "主角.持有物品", {});
        invData = Object.entries(plInv);
        invPage = 0;
        renderInventory();
      }
    }

    // 计算装备总加成
    function calculateTotalBonuses(equip) {
      // 乘算因子（战斗中的实际运算方式）
      var multipliers = {
        力量: 1,
        耐力: 1,
        灵巧: 1,
        敏捷: 1,
        魔力: 1,
      };
      if (!equip) {
        // 返回全0加成（因为乘算增益为0%）
        return { 力量: 0, 耐力: 0, 灵巧: 0, 敏捷: 0, 魔力: 0 };
      }

      var keys = ["力量", "耐力", "灵巧", "敏捷", "魔力"];

      function applyItem(item) {
        if (!item || !item.装备属性 || !item.装备属性.加成) return;
        var bonuses = item.装备属性.加成;
        keys.forEach(function (k) {
          if (typeof bonuses[k] === "number" && bonuses[k] !== 0) {
            multipliers[k] *= 1 + bonuses[k];
          }
        });
      }

      // 常规装备槽
      [
        "主手",
        "副手",
        "头部",
        "身体",
        "护手",
        "鞋子",
        "饰品1",
        "饰品2",
      ].forEach(function (slot) {
        applyItem(equip[slot]);
      });

      // 特殊装备槽
      (equip.特殊 || []).forEach(function (item) {
        applyItem(item);
      });

      // 转换回"总加成百分比"，保留一位小数
      var totals = {};
      keys.forEach(function (k) {
        var rawPct = (multipliers[k] - 1) * 100;
        // 保留一位小数，四舍五入
        totals[k] = Math.round(rawPct * 10) / 10;
      });
      return totals;
    }
