            skillHtml += skillEntries.map(function ([skName, sk]) {
              return '<div>• ' + skName + ' <span style="color:var(--gold)">(' + (sk.等级 || 'I') + ')</span></div>';
            }).join('');
            skillHtml += '</div></div>';
          }

          var growthHtml = "";
