            growthHtml =
              '<div class="npc-sub-group"><strong>📈 成长期望</strong><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:2px;color:#8ab4d6;">' +
              "<span>力:" +
              (growth.力量 || 0) +
              "</span>" +
              "<span>耐:" +
              (growth.耐力 || 0) +
              "</span>" +
              "<span>灵:" +
              (growth.灵巧 || 0) +
              "</span>" +
              "<span>敏:" +
              (growth.敏捷 || 0) +
              "</span>" +
              "<span>魔:" +
              (growth.魔力 || 0) +
              "</span>" +
              "</div></div>";
          }

          // 持有物品（杂物）
          var belongings = data.持有物品 || {};
          var belongHtml = Object.keys(belongings).length
            ? Object.entries(belongings)
              .map(function (e) {
                var item = e[1];
                return '<div>• ' + e[0] + ' x' + (item.数量 || 1) + '</div>';
              })
              .join("")
            : "无";

          var tags = (binfo.性格 || [])
            .map((t) => '<span class="tag">' + t + "</span>")
            .join("");

          return (
            '<div class="npc-card item-toggle-npc' +
            (npcDeleteMode ? " selectable" : "") +
            (npcDeleteSet.has(name) ? " selected-for-delete" : "") +
            '" data-npc-name="' + name + '">' +
            '<div class="npc-head">' +
            "<span>" +
            name +
            ' <span style="color:var(--gold);font-weight:bold;font-size:12px">(' +
            (st.评价 || "-") +
            ")</span></span>" +
            '<span style="color:' +
            getRelColor(intimacy) +
            '">' +
            intimacy +
            "</span>" +
            "</div>" +
            '<div class="npc-brief">' +
            "<div>🤝 关系: " +
            (rel.当前关系 || "陌生") +
            "</div>" +
            "<div>❤️ HP: " +
            (st.身体状况 != null ? st.身体状况 : 100) +
            " | 📍 " +
            (binfo.所在位置 || "?") +
            "</div>" +
            "<div>💭 心境: " +
            (binfo.心境 || "-") +
            "</div>" +
            "<div>⚠ 负面状态: " +
            (binfo.负面状态?.length
              ? binfo.负面状态.map(function(d) { return '<span class=\"debuff-tag\">' + d + '</span>'; }).join('')
              : '<span style=\"color:#555\">无</span>') +
            "</div>" +
            "</div>" +
            '<div class="npc-details">' +
            '<div class="npc-sub-group"><strong>种族:</strong> ' +
            (binfo.种族 || "未知") +
            "</div>" +
            '<div class="npc-sub-group"><strong>性别:</strong> ' +
            (binfo.性别 || "?") +
            "</div>" +
            '<div class="npc-sub-group"><strong>气质:</strong> ' +
            (binfo.气质 || "--") +
            "</div>" +
            '<div class="npc-sub-group"><strong>发型:</strong> ' +
            (binfo.发型 || "未知") +
            "</div>" +
            '<div class="npc-sub-group"><strong>外貌:</strong> ' +
            (binfo.样貌 || "--") +
            "</div>" +
            '<div class="npc-sub-group"><strong>身材:</strong> ' +
            (binfo.身材 || "--") +
            "</div>" +
            '<div class="npc-sub-group"><strong>服装:</strong> ' +
            (binfo.服装 || "--") +
            "</div>" +
            '<div class="npc-sub-group"><strong>性格:</strong> ' +
            (tags || "--") +
            "</div>" +
            '<div style="border-top:1px dashed rgba(255,255,255,0.1);margin-top:5px;padding-top:4px">' +
            familiaHtml +
            "</div>" +
            '<div class="npc-sub-group"><strong>💰 存款:</strong> ' +
            FMT.format(asset.存款 || 0) +
            " 法利</div>" +
            '<div class="npc-sub-group"><strong>🎒 持有物品:</strong><div style="padding-left:8px;font-size:0.9em;color:#aaa">' +
            belongHtml +
            "</div></div>" +
            skillHtml +
            (function () {
              var attr = data.个人属性 || {};
              var ab = st.能力值;
              if (
                !ab ||
                !(ab.力量 || ab.耐力 || ab.灵巧 || ab.敏捷 || ab.魔力)
              ) {
                ab = attr.基础能力;
              }
              if (
                ab &&
                (ab.力量 || ab.耐力 || ab.灵巧 || ab.敏捷 || ab.魔力)
              ) {
                return (
                  '<div class="npc-sub-group"><strong>📊 能力值</strong><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:2px;">' +
                  "<span>力:" +
                  (ab.力量 || 0) +
                  "</span>" +
                  "<span>耐:" +
                  (ab.耐力 || 0) +
                  "</span>" +
                  "<span>灵:" +
                  (ab.灵巧 || 0) +
                  "</span>" +
                  "<span>敏:" +
                  (ab.敏捷 || 0) +
                  "</span>" +
                  "<span>魔:" +
                  (ab.魔力 || 0) +
                  "</span>" +
                  "</div></div>"
                );
              }
              return "";
            })() +
            growthHtml +
            "</div></div>"
          );
        })
        .join("");
      DOM.npcContainer.html(html);
