    // ===== NPC 删除模式 =====
    function enterNpcDeleteMode() {
      npcDeleteMode = true;
      $("#npc-delete-toggle").hide();
      $("#npc-delete-confirm, #npc-delete-cancel").show();
      renderNpcs();
    }

    function exitNpcDeleteMode() {
      npcDeleteMode = false;
      npcDeleteSet.clear();
      $("#npc-delete-toggle").show();
      $("#npc-delete-confirm, #npc-delete-cancel").hide();
      renderNpcs();
    }

    function toggleNpcSelection(name) {
      if (!npcDeleteMode) return;
      if (npcDeleteSet.has(name)) {
        npcDeleteSet.delete(name);
      } else {
        npcDeleteSet.add(name);
      }
      renderNpcs();
    }

    async function executeNpcDelete() {
      if (!npcDeleteSet.size) return;
      var names = [...npcDeleteSet];
      if (!confirm("确定删除 " + names.join("、") + "？\n此操作不可撤销，同时会清理组队成员引用。")) return;
      if (U && U.removeCharactersFromDirectory) {
        await U.removeCharactersFromDirectory(names, getCurrentMessageId());
      }
      // 刷新本地 npcData，确保 renderNpcs 读取最新数据
      var all = getFullVariables();
      var sd = _.get(all, "stat_data", {});
      npcData = Object.entries(_.get(sd, "人物名录", {}));
      exitNpcDeleteMode();
    }

    // ===== 战斗记录渲染（前端实时计算奖励，显示基础→期望→总能力→HP/SP/MP）=====
    function renderRecords() {
      var all = getFullVariables();
      var sd = _.get(all, "stat_data", {});
      var pl = _.get(sd, "主角", {});
      var enemyInfo = sd.敌人信息 || [];
      var config = _.get(sd, "sysbox.战斗系统", {});

      // 用序列化对比检测变化（避免每次渲染都重置分页）
      if (JSON.stringify(enemyInfo) !== JSON.stringify(recordsData)) {
        recordsData = enemyInfo;
        recordsPage = 0;
      }

      var total = Math.ceil(recordsData.length / RECORDS_PER_PAGE);
      recordsPage = _.clamp(recordsPage, 0, Math.max(0, total - 1));
      DOM.recordsPageInfo.text(
        (recordsData.length ? recordsPage + 1 : 0) + " / " + total,
      );

      if (!recordsData.length) {
        DOM.recordsContainer.html(
          '<div class="empty-hint">暂无战斗记录</div>',
        );
        return;
      }

      var pageItems = recordsData.slice(
        recordsPage * RECORDS_PER_PAGE,
        (recordsPage + 1) * RECORDS_PER_PAGE,
      );

      var area = _.get(sd, "当前地下城区域", {});
      var floor = area.层数 != null ? area.层数 : 1;

      var html = pageItems
        .map(function (enemy, pageIdx) {
          var actualIdx = recordsPage * RECORDS_PER_PAGE + pageIdx;
          var statusColor = enemy.是否击败 ? "#50c878" : "#e05050";
          var statusText = enemy.是否击败 ? "✅ 已击败" : "❌ 未击败";
          var rarityText =
            enemy.基础信息?.稀有度 && enemy.基础信息.稀有度 !== "普通"
              ? " (" + enemy.基础信息.稀有度 + ")"
              : "";

          // === 1) 基础能力值 ===
          var stats = enemy.个人属性?.基础能力 || {};
          var baseStatsHtml = STAT_KEYS.map(function (k) {
            return (
              '<span style="color:#aaa">' +
              STAT_LABELS[k] +
              ":" +
              (stats[k] || 0) +
              "</span>"
            );
          }).join(" ");

          // === 2) 成长期望 ===
          var hope = enemy.个人属性?.成长期望 || {};
          var hopeParts = [];
          STAT_KEYS.forEach(function (k) {
            var v = hope[k];
            if (v && v > 0) {
              hopeParts.push(STAT_LABELS[k] + "+" + v);
            }
          });
          var hopeHtml = hopeParts.length
            ? '<span style="color:#8ab4d6">成长期望: ' +
            hopeParts.join(" ") +
            "</span>"
            : "";

          // === 3) 总能力值（直接从 Zod 维护的 总能力 读取）===
          var totalStats = enemy.个人属性?.总能力 || {};
          var totalSum = STAT_KEYS.reduce(function (acc, k) {
            return acc + (totalStats[k] || 0);
          }, 0);
          var totalStatsHtml = STAT_KEYS.map(function (k) {
            return (
              '<span style="color:#f7e3b0">' +
              STAT_LABELS[k] +
              ":" +
              (totalStats[k] || 0) +
              "</span>"
            );
          }).join(" ");

          // === 4) HP/SP/MP===
          var hp = enemy.状态?.HP当前值 ?? 0;
          var maxHp = enemy.状态?.HP上限 ?? 0;
          var sp = enemy.状态?.SP当前值 ?? 0;
          var maxSp = enemy.状态?.SP上限 ?? 0;
          var mp = enemy.状态?.MP当前值 ?? 0;
          var maxMp = enemy.状态?.MP上限 ?? 0;
          var hpSpMpHtml =
            "<span>❤️" +
            hp +
            "/" +
            maxHp +
            "</span>" +
            " <span>⚡" +
            sp +
            "/" +
            maxSp +
            "</span>" +
            " <span>✨" +
            mp +
            "/" +
            maxMp +
            "</span>";

          // === 5) 直接读取结算经验和伟业 ===
          var exp = enemy.结算经验 ?? 0;
          var feat = enemy.结算伟业 ?? 0;
          var tierColor = enemy.是否击败 ? "#50c878" : "#666"; // 已击败用绿色

          var expFeatsHtml =
            '<span style="color:#f7e3b0">⭐经验: ' + exp + "</span>" +
            ' <span style="color:#e8c070">🏆伟业: ' + feat + "</span>";

          return (
            '<div class="monster-card item-toggle-record' +
            (recordsDeleteMode ? " selectable" : "") +
            (recordsDeleteSet.has(actualIdx) ? " selected-for-delete" : "") +
            '" data-record-index="' + actualIdx + '" style="margin-bottom:6px;border-left:3px solid ' +
            (enemy.是否击败 ? '#50c878' : '#e05050') +
            ';">' +
            '<div class="monster-name" style="font-size:14px;margin-bottom:4px;">' +
            (enemy.基础信息?.类型 === "冒险者" ? "🧑" : "👹") +
            " " +
            (enemy.基础信息?.姓名 || "???") +
            rarityText +
            ' <span style="font-size:12px;color:#aaa">Lv.' +
            (enemy.个人属性?.等级 || 1) +
            "</span>" +
            ' <span style="font-size:12px;color:' +
            statusColor +
            '">' +
            statusText +
            "</span>" +
            "</div>" +
            // 第一行：基础能力值
            '<div class="monster-detail" style="font-size:12px;gap:10px;">' +
            '<span style="color:#777">基础</span> ' +
            baseStatsHtml +
            "</div>" +
            // 第二行：成长期望（如果有）
            (hopeHtml
              ? '<div class="monster-detail" style="font-size:12px;gap:10px;margin-top:2px;color:#8ab4d6;">' +
              hopeHtml +
              "</div>"
              : "") +
            // 第三行：总能力值
            '<div class="monster-detail" style="font-size:12px;gap:10px;margin-top:2px;">' +
            '<span style="color:#d4a853">总能力(' +
            totalSum +
            ")</span> " +
            totalStatsHtml +
            "</div>" +
            // 第四行：HP/SP/MP
            '<div class="monster-detail" style="font-size:12px;gap:10px;margin-top:2px;">' +
            hpSpMpHtml +
            "</div>" +
            // --- 敌人装备 ---
            (function () {
              const equip = enemy.装备栏;
              if (!equip) return "";
              const slots = [
                "主手",
                "副手",
                "头部",
                "身体",
                "护手",
                "鞋子",
                "饰品1",
                "饰品2",
              ];
              const eqItems = [];
              slots.forEach((s) => {
                if (equip[s]?.名称) eqItems.push(`${s}：${equip[s].名称}`);
              });
              (equip.特殊 || []).forEach((i) => {
                if (i?.名称) eqItems.push(`✨：${i.名称}`);
              });
              return eqItems.length
                ? '<div class="monster-detail" style="font-size:11px;gap:6px;margin-top:2px;color:#b89b6b;">⚔️ ' +
                eqItems.join(" | ") +
                "</div>"
                : "";
            })() +
            // --- 敌人技能 ---
            (function () {
              const skills = enemy.个人属性?.技能列表;
              if (!skills) return "";
              const skEntries = Object.entries(skills);
              if (!skEntries.length) return "";
              const skList = skEntries
                .map(([name, s]) => `${name} ${s.等级 || "I"}`)
                .join(" | ");
              return (
                '<div class="monster-detail" style="font-size:11px;gap:6px;margin-top:2px;color:#7b68ee;">📜 ' +
                skList +
                "</div>"
              );
            })() +
            // 第五行：奖励
            '<div class="monster-detail" style="font-size:12px;gap:10px;margin-top:2px;">' +
            expFeatsHtml +
            "</div>" +
            "</div>"
          );
        })
        .join("");

      // 自动结算状态提示（Zod transform 检测全击败后自动结算）
      var allDefeated =
        enemyInfo.length > 0 &&
        enemyInfo.every(function (e) {
          return e.是否击败;
        });
      if (allDefeated) {
        html +=
          '<div style="text-align:center;margin-top:10px;padding-top:10px;border-top:1px solid rgba(212,168,83,0.2);">' +
          '<span style="color:#d4a853;font-size:13px;">所有敌人已击败，将在下次变量更新时自动结算</span>' +
          "</div>";
      }

      DOM.recordsContainer.html(html);
    }

    // ===== 战斗记录删除模式 =====
    function enterRecordsDeleteMode() {
      recordsDeleteMode = true;
      $("#records-delete-toggle").hide();
      $("#records-delete-confirm, #records-delete-cancel").show();
      renderRecords();
    }

    function exitRecordsDeleteMode() {
      recordsDeleteMode = false;
      recordsDeleteSet.clear();
      $("#records-delete-toggle").show();
      $("#records-delete-confirm, #records-delete-cancel").hide();
      renderRecords();
    }

    function toggleRecordsSelection(index) {
      if (!recordsDeleteMode) return;
      if (recordsDeleteSet.has(index)) {
        recordsDeleteSet.delete(index);
      } else {
        recordsDeleteSet.add(index);
      }
      renderRecords();
    }

    function executeRecordsDelete() {
      if (!recordsDeleteSet.size) return;
      var indices = [...recordsDeleteSet].sort(function(a, b) { return b - a; });
      if (!confirm("确定删除 " + indices.length + " 条战斗记录？\n此操作不可撤销。")) return;
      var all = getFullVariables();
      var sd = _.get(all, "stat_data", {});
      var enemyInfo = sd.敌人信息 || [];
      indices.forEach(function(i) {
        if (i >= 0 && i < enemyInfo.length) {
          enemyInfo.splice(i, 1);
        }
      });
      _.set(all, "stat_data.敌人信息", enemyInfo);
      saveVariablesToMvu(all);
      // 刷新本地缓存
      recordsData = enemyInfo;
      recordsPage = 0;
      exitRecordsDeleteMode();
    }

    function loadAvatar() {
      try {
        var saved = null;
        if (typeof localStorage !== "undefined" && localStorage) {
          saved = localStorage.getItem("danmachi_avatar");
        }
        if (saved) {
          DOM.avatarBox.html('<img src="' + saved + '" alt="avatar" />');
        } else {
          DOM.avatarBox.html(
            '<div class="avatar-placeholder">点击上传<br/>头像</div>',
          );
        }
      } catch (e) {
        DOM.avatarBox.html(
          '<div class="avatar-placeholder">点击上传<br/>头像</div>',
        );
      }
    }

    // 刷新技能面板（仅在skills区域刷新）— 只展示不装备
    function refreshSkillList() {
      var all = getFullVariables();
      var sd = _.get(all, "stat_data", {});
      var pl = _.get(sd, "主角", {});
      var attr = _.get(pl, "个人属性", {});
      var skills = Object.entries(pl.基础信息?.技能列表 || {});
      if (skills.length) {
        DOM.skillList.html(
          skills
            .map((entry) => {
              var k = entry[0],
                v = entry[1];
              var bonusHtml = "";
              var bonuses = v.加成 || {};
              Object.keys(bonuses).forEach(function (bk) {
                var val = bonuses[bk];
                if (val == null || val === "") return;
                if (bk === "特殊") {
                  bonusHtml +=
                    '<span class="bonus-item" style="color:var(--gold)">' +
                    val +
                    "</span> ";
                } else if (typeof val === "number" && val !== 0) {
                  var rawPct = val * 100;
                  var pctStr =
                    rawPct < 1 && rawPct > -1 && rawPct !== 0
                      ? rawPct.toFixed(1)
                      : Math.round(rawPct);
                  bonusHtml +=
                    '<span class="bonus-item ' +
                    (val > 0 ? "positive" : "negative") +
                    '">' +
                    (STAT_LABELS[bk] || bk) +
                    (val > 0 ? "+" : "") +
                    pctStr +
                    "%</span> ";
                }
              });

              return (
                '<div class="tech-card item-toggle">' +
                '<div class="tech-head"><span>' +
                k +
                '</span><span class="tech-grade">' +
                (v.等级 || "I") +
                "</span></div>" +
                '<div class="tech-body">' +
                "<div>类型: " +
                (v.类型 || "--") +
                " · " +
                (v.技能类型 || "被动") +
                "</div>" +
                "<div>效果: " +
                (v.效果描述 || "--") +
                "</div>" +
                (v.消耗SP百分比 || v.消耗MP百分比
                  ? '<div style="margin-top:3px;font-size:12px;color:#b3a1d9">消耗: ' +
                  (v.消耗SP百分比
                    ? "SP" + Math.round(v.消耗SP百分比 * 100) + "% "
                    : "") +
                  (v.消耗MP百分比
                    ? "MP" + Math.round(v.消耗MP百分比 * 100) + "%"
                    : "") +
                  "</div>"
                  : "") +
                (v.伤害比例
                  ? '<div style="margin-top:2px;font-size:12px;color:#e8c070">伤害: ' +
                  (v.类型 === "魔法" ? "魔力" : "力量") +
                  "×" +
                  Math.round(v.伤害比例 * 100) +
                  "%" +
                  "</div>"
                  : "") +
                (v.回复HP比例 || v.回复SP比例 || v.回复MP比例
                  ? '<div style="margin-top:2px;font-size:12px;color:#50c878">回复: ' +
                  (v.回复HP比例 ? "HP×" + Math.round(v.回复HP比例 * 100) + "% " : "") +
                  (v.回复SP比例 ? "SP×" + Math.round(v.回复SP比例 * 100) + "% " : "") +
                  (v.回复MP比例 ? "MP×" + Math.round(v.回复MP比例 * 100) + "%" : "") +
                  "</div>"
                  : "") +
                (bonusHtml
                  ? '<div style="margin-top:3px;font-size:12px;color:var(--gold)">加成: ' +
                  bonusHtml +
                  "</div>"
                  : "") +
                "</div></div>"
              );
            })
            .join(""),
        );
      } else {
        DOM.skillList.html('<div class="empty-hint">尚未习得任何技能</div>');
      }
    }

