    function startTopGame() {
      const all = getFullVariables();
      const sd = _.get(all, "stat_data", {});
      const pl = _.get(sd, "主角", {});
      const attr = _.get(pl, "个人属性", {});
      const status = _.get(pl, "状态", {});
      const area = _.get(sd, "当前地下城区域", {});
      const lv = attr.等级 || 1;
      const floor = area.层数 || 1;
      const monsters = area.怪物 || [];
      if (monsters.length === 0) {
        alert("当前层没有怪物信息，无法开始探索。");
        return;
      }
      // 上限直接读取 Zod 已存入的字段，各能力值从总能力读取
      const maxHp = status.HP上限 || 500;
      const maxSp = status.SP上限 || 100;
      const maxMp = status.MP上限 || 50;
      const totalStats = attr.总能力 || {};
      const totalStr = totalStats.力量 || 0;
      const totalVit = totalStats.耐力 || 0;
      const totalDex = totalStats.灵巧 || 0;
      const totalAgi = totalStats.敏捷 || 0;
      const totalMag = totalStats.魔力 || 0;
      const hp = Math.min(status.HP当前值 ?? 100, maxHp);
      const sp = Math.min(status.SP当前值 ?? 100, maxSp);
      const mp = Math.min(status.MP当前值 ?? 50, maxMp);
      const roomCount = Math.floor(Math.random() * 4) + 3;
      const monsterTemplates = monsters.map((m) => ({
        name: m.名字,
        rarity: m.稀有度 || null,
        lv:
          Math.floor(
            Math.random() *
            ((m.等级范围?.最高 || 1) - (m.等级范围?.最低 || 1) + 1),
          ) + (m.等级范围?.最低 || 1),
        statRanges: {
          str: {
            min: m.能力值范围?.力量?.最低 ?? 0,
            max: m.能力值范围?.力量?.最高 ?? 0,
          },
          vit: {
            min: m.能力值范围?.耐力?.最低 ?? 0,
            max: m.能力值范围?.耐力?.最高 ?? 0,
          },
          dex: {
            min: m.能力值范围?.灵巧?.最低 ?? 0,
            max: m.能力值范围?.灵巧?.最高 ?? 0,
          },
          agi: {
            min: m.能力值范围?.敏捷?.最低 ?? 0,
            max: m.能力值范围?.敏捷?.最高 ?? 0,
          },
          mag: {
            min: m.能力值范围?.魔力?.最低 ?? 0,
            max: m.能力值范围?.魔力?.最高 ?? 0,
          },
        },
      }));

      const gameData = {
        char: pl,
        name: pl.基础信息?.姓名 || "主角",
        lv,
        hp,
        sp,
        mp,
        maxHp,
        maxSp,
        maxMp,
        floor,
        roomCount,
        monsters: monsterTemplates,
        equipData: pl.装备栏 || {},
        skillList: pl.基础信息?.技能列表 || {},
      };

      const idMap = {
        canvasId: "topGridCanvas",
        hpId: "topHpVal",
        hpBarId: "topHpBar",
        spId: "topSpVal",
        spBarId: "topSpBar",
        mpId: "topMpVal",
        mpBarId: "topMpBar",
        dungeonFloorId: "topDungeonFloor",
        roomIndexId: "topRoomIndex",
        roomTotalId: "topRoomTotal",
        commonId: "topCommonCount",
        rareId: "topRareCount",
        legendaryId: "topLegendaryCount",
        uniqueId: "topUniqueCount",
        logBoxId: "topLogBox2",
        enemyStatsId: "topEnemyStats",
        abortBtnId: "topAbortBtn",
        closeBtnId: "top-close-btn",
        expValId: "topExpVal",
        featsValId: "topFeatsVal",
        skillModalBtnId: "topSkillModalBtn",
        timerId: "topTimer",
        activeSkillsId: "topActiveSkills",
      };
      // ... 在原有 new DungeonGame(gameData, { canvasId: ..., hpId: ... }) 处替换为传入 idMap

      let targetDoc;
      try {
        targetDoc = window.top.document;
      } catch (e) {
        targetDoc = document;
      }

      if (topOverlay) {
        topOverlay.remove();
        topGame = null;
      }
      topOverlay = createTopOverlay(gameData, targetDoc);

      // === 技能三分类：攻击方式、加成技能、被动技能 ===
      var allSkills = Object.entries(pl.基础信息?.技能列表 || {});
      var attackMethods = [];
      var buffSkills = [];
      var passiveSkills = [];
      // 1. 攻击方式：有伤害比例的技能/魔法（技能类基于力量值，魔法类基于魔力值）
      allSkills.forEach(function (e) {
        var k = e[0],
          v = e[1];
        var dmgRatio = v.伤害比例 || 0;
        if (dmgRatio > 0) {
          var isSkillType = v.类型 === "技能";
          attackMethods.push({
            name: k,
            type: isSkillType ? "normal" : "magic",
            baseStat: isSkillType ? "str" : "mag",
            ratio: dmgRatio,
            mpCost: v.消耗MP百分比 || 0,
            spCost: v.消耗SP百分比 || 0,
            desc:
              (isSkillType ? "力量" : "魔力") +
              "×" +
              dmgRatio * 100 +
              "%伤害",
            level: v.等级 || "I",
            rawSkill: v,
          });
        }
      });
      // 2. 加成技能：主动技能(有加成)
      allSkills.forEach(function (e) {
        var k = e[0],
          v = e[1];
        var skillType = v.技能类型 || "被动";
        if (skillType !== "主动") return;
        var bonuses = v.加成 || {};
        var hasBonus = false;
        Object.keys(bonuses).forEach(function (bk) {
          if (bonuses[bk] && bonuses[bk] !== 0) hasBonus = true;
        });
        if (hasBonus) {
          buffSkills.push({
            name: k,
            desc:
              (v.消耗MP百分比
                ? "MP" + Math.round(v.消耗MP百分比 * 100) + "%"
                : "") +
              (v.消耗MP百分比 && v.消耗SP百分比 ? "+" : "") +
              (v.消耗SP百分比
                ? "SP" + Math.round(v.消耗SP百分比 * 100) + "%"
                : ""),
            bonuses: v.加成 || {},
            mpCost: v.消耗MP百分比 || 0,
            spCost: v.消耗SP百分比 || 0,
            level: v.等级 || "I",
            skillType: "主动",
            active: false,
            isBuff: true,
            dmgBuff: 0,
          });
        }
      });
      // 3. 被动技能：被动技能（有加成，自动生效）
      allSkills.forEach(function (e) {
        var k = e[0],
          v = e[1];
        if (v.技能类型 !== "被动") return;
        var bonuses = v.加成 || {};
        var hasBonus = false;
        Object.keys(bonuses).forEach(function (bk) {
          if (bonuses[bk] && bonuses[bk] !== 0) hasBonus = true;
        });
        if (hasBonus) {
          passiveSkills.push({
            name: k,
            bonuses: v.加成 || {},
            level: v.等级 || "I",
            skillType: "被动",
            active: true,
          });
        }
      });
      // 合并所有技能到 skills（保持向后兼容，用于被动加成计算）
      var gameSkills = [].concat(passiveSkills);
      gameData.skills = gameSkills;
      gameData.attackMethods = attackMethods;
      gameData.buffSkills = buffSkills;
      gameData.passiveSkills = passiveSkills;

      // 计算装备累乘加成
      var equipMultiplier = { str: 1, vit: 1, dex: 1, agi: 1, mag: 1 };
      var equipSlots2 = [
        "主手",
        "副手",
        "头部",
        "身体",
        "护手",
        "鞋子",
        "饰品1",
        "饰品2",
      ];
      equipSlots2.forEach(function (s) {
        var item = (pl.装备栏 || {})[s];
        if (!item) return;
        var bonuses = (item.装备属性 && item.装备属性.加成) || {};
        if (bonuses.力量 && bonuses.力量 !== 0)
          equipMultiplier.str *= 1 + bonuses.力量;
        if (bonuses.耐力 && bonuses.耐力 !== 0)
          equipMultiplier.vit *= 1 + bonuses.耐力;
        if (bonuses.灵巧 && bonuses.灵巧 !== 0)
          equipMultiplier.dex *= 1 + bonuses.灵巧;
        if (bonuses.敏捷 && bonuses.敏捷 !== 0)
          equipMultiplier.agi *= 1 + bonuses.敏捷;
        if (bonuses.魔力 && bonuses.魔力 !== 0)
          equipMultiplier.mag *= 1 + bonuses.魔力;
      });
      (pl.装备栏.特殊 || []).forEach(function (item) {
        if (!item) return;
        var bonuses = (item.装备属性 && item.装备属性.加成) || {};
        if (bonuses.力量 && bonuses.力量 !== 0)
          equipMultiplier.str *= 1 + bonuses.力量;
        if (bonuses.耐力 && bonuses.耐力 !== 0)
          equipMultiplier.vit *= 1 + bonuses.耐力;
        if (bonuses.灵巧 && bonuses.灵巧 !== 0)
          equipMultiplier.dex *= 1 + bonuses.灵巧;
        if (bonuses.敏捷 && bonuses.敏捷 !== 0)
          equipMultiplier.agi *= 1 + bonuses.敏捷;
        if (bonuses.魔力 && bonuses.魔力 !== 0)
          equipMultiplier.mag *= 1 + bonuses.魔力;
      });
      gameData.equipMult = equipMultiplier;

      // 收集队友数据
      var alliesData = [];
      var partyMap = sd.组队成员 || {};
      var npcList = sd.人物名录 || {};
      Object.keys(partyMap).forEach(function(name) {
        var npc = npcList[name];
        if (!npc) return;
        var ns = npc.状态 || {};
        alliesData.push({
          char: npc,
          name: name,
          hp: ns.HP当前值 != null ? ns.HP当前值 : (ns.HP上限 || 500),
          maxHp: ns.HP上限 || 100,
          sp: ns.SP当前值 != null ? ns.SP当前值 : (ns.SP上限 || 100),
          maxSp: ns.SP上限 || 100,
          mp: ns.MP当前值 != null ? ns.MP当前值 : (ns.MP上限 || 100),
          maxMp: ns.MP上限 || 100,
        });
      });
      gameData.allies = alliesData;

      topGame = new DungeonGame(gameData, {
        ...idMap,        // ✅ 展开所有 id
        doc: targetDoc,
        onDestroy: () => {
          if (topOverlay) {
            topOverlay.remove();
            topOverlay = null;
            topGame = null;
          }
        },
      });
      const closeBtn = topOverlay.querySelector(
        ".arcane-tome .explore-close-btn",
      );
      closeBtn.addEventListener("click", () => {
        if (topGame) {
          topGame.destroy();
        }
      });
    }

    class DungeonGame {
      constructor(data, ids) {
        this.data = data;
        this.ids = ids;
        this.doc = ids.doc || document;
        this.canvas = this.doc.getElementById(ids.canvasId);

        if (!this.canvas) {
          this.canvas = document.getElementById(ids.canvasId);
        }
        if (!this.canvas) {
          console.error("Canvas not found:", ids.canvasId);
          // 中止构造，避免后续操作报错
          throw new Error("Canvas not found, game cannot start");
        }
        this.ctx = this.canvas.getContext("2d");
        // ---- 动态构建 TILE 枚举（从 sysbox 颜色档位配置读取）----
        var combatConfig = this.getCombatConfig();
        var tiers = combatConfig.颜色档位 || [];
        this.tierConfigs = tiers;
        this.sysbox伟业换算 = _.get(getFullVariables(), "stat_data.sysbox.剧情相关.伟业换算") || 100;
        this.sysbox步时间 = _.get(getFullVariables(), "stat_data.sysbox.剧情相关.每步时间") || 1;
        this.sysbox战斗时间 = _.get(getFullVariables(), "stat_data.sysbox.剧情相关.每轮战斗时间") || 5;
        this.TILE = { EMPTY: "empty", PLAYER: "player", DOOR: "door" };
        this.tierTileValues = [];
        this.tierColorValues = []; // 存储每个档位的颜色值
        var _self = this;
        tiers.forEach(function (t, idx) {
          var tileVal = "tier_" + idx;
          _self.TILE[tileVal] = tileVal;
          _self.tierTileValues.push(tileVal);
          _self.tierColorValues.push(t.颜色值 || "#666");
        });
        var spCostPercentages = [0.01, 0.04, 0.08, 0.15, 0.2];
        var dropRateDefaults = [
          { common: 1, rare: 0, legendary: 0, unique: 0 },
          { common: 0.7, rare: 0.2, legendary: 0.1, unique: 0 },
          { common: 0.4, rare: 0.4, legendary: 0.2, unique: 0 },
          { common: 0, rare: 0.3, legendary: 0.6, unique: 0.1 },
          { common: 0, rare: 0, legendary: 0, unique: 1 },
        ];
        this.SP_COST = { step: 1 };
        this.DROP_RATES = {};
        this.tierTileValues.forEach(function (tileVal, idx) {
          var pct =
            spCostPercentages[Math.min(idx, spCostPercentages.length - 1)];
          _self.SP_COST[tileVal] = function () {
            return Math.max(1, Math.floor(_self.player.maxSp * pct));
          };
          _self.DROP_RATES[tileVal] =
            dropRateDefaults[Math.min(idx, dropRateDefaults.length - 1)];
        });
        this.player = { x: 4, y: 4, ...data };
        this.playerChar = data.char;
        this.config = { floor: data.floor, roomCount: data.roomCount };
        this.monsterTemplates = data.monsters;
        this.rooms = [];
        this.currentRoomIndex = 0;
        this.gameOver = false;
        this.loot = { common: 0, rare: 0, legendary: 0, unique: 0 };
        this.totalExp = 0;
        this.grid = [];
        this.explored = [];
        this.isMoving = false;
        this.movePath = [];
        this.enemyDataMap = [];
        this.selectedEnemyPos = null;
        // 保留从 data.skills 传入的 active 状态（被动默认激活，主动默认关闭）
        this.skills = (data.skills || []).map(function (s) {
          return { ...s, active: !!s.active };
        });
        // 攻击方式 + 加成技能系统（用于默认权重构建）
        this.attackMethods = data.attackMethods || [];
        this.buffSkills = (data.buffSkills || []).map(function (s) {
          return { ...s, active: !!s.active };
        });
        this._skillClickHandler = null;
        this.defeatedMonsters = [];
        this.allies = data.allies || [];
        this.selectedAllySkills = {};
        this.totalFeats = 0;
        this.timer = 0;
        this.combatSkillConfig = null;
        this.weightDeltas = {};
        this._boundEvents = {};
        this.init();
      }

      init() {
        // 从数据直接读取上限，不自行计算
        this.player.maxHp = this.player.maxHp || 500;
        this.player.maxSp = this.player.maxSp || 100;
        this.player.maxMp = this.player.maxMp || 50;
        this.player.hp = Math.min(this.player.hp, this.player.maxHp);
        this.player.sp = Math.min(this.player.sp, this.player.maxSp);
        this.player.mp = Math.min(this.player.mp, this.player.maxMp);
        this.generateAllRooms();
        this.drawMap();
        this.updateUI();
        this.bindEvents();
        this.addLog("✨ 探索开始");
      }

      destroy() {
        if (this.canvas) {
          this.canvas.removeEventListener("click", this._boundEvents.canvasClick);
        }
        this.canvas.removeEventListener(
          "click",
          this._boundEvents.canvasClick,
        );
        this.doc.removeEventListener(
          "click",
          this._boundEvents.skillModalClick,
        );
        const abortBtn = this.doc.getElementById(this.ids.abortBtnId);
        abortBtn?.removeEventListener("click", this._boundEvents.abort);
        this.doc.removeEventListener(
          "keydown",
          this._boundEvents.skillModalKeydown,
        );
        this.ids.onDestroy?.();
      }

      bindEvents() {
        this._boundEvents.canvasClick = (e) => {
          const rect = this.canvas.getBoundingClientRect();
          const scale = this.canvas.width / rect.width;
          const cx = (e.clientX - rect.left) * scale,
            cy = (e.clientY - rect.top) * scale;
          const cell = this.canvas.width / 9;
          this.moveTo(Math.floor(cx / cell), Math.floor(cy / cell));
        };
        this.canvas.addEventListener("click", this._boundEvents.canvasClick);

        // 技能弹窗点击事件（委托到文档，关闭遮罩）
        this._boundEvents.skillModalClick = (e) => {
          var closeBtn = e.target.closest(".skill-modal-close");
          var overlay = e.target.closest(".skill-modal-overlay");
          var isOverlayClick =
            overlay && !e.target.closest(".skill-modal-box");
          if (closeBtn || isOverlayClick) {
            overlay = overlay || e.target.closest(".skill-modal-overlay");
            if (overlay) overlay.remove();
            return;
          }
        };
        this.doc.addEventListener("click", this._boundEvents.skillModalClick);

        // ESC 键关闭技能弹窗
        this._boundEvents.skillModalKeydown = (e) => {
          if (e.key === "Escape") {
            var modal = this.doc.querySelector(".skill-modal-overlay");
            if (modal) modal.remove();
          }
        };
        this.doc.addEventListener(
          "keydown",
          this._boundEvents.skillModalKeydown,
        );

        // 战术配置按钮 → 弹窗
        var modalBtn = this.doc.getElementById("topSkillModalBtn");
        if (modalBtn) {
          modalBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            this.updateSkillUI();
          });
        }

        this._boundEvents.abort = () => this.abort();
        this.doc
          .getElementById(this.ids.abortBtnId)
          .addEventListener("click", this._boundEvents.abort);

        // Mini-tab 切换
        this._boundEvents.tabSwitch = (e) => {
          var btn = e.target.closest(".mini-tab-btn");
          if (!btn) return;
          var tab = btn.dataset.tab;
          this.doc.querySelectorAll(".mini-tab-btn").forEach(function (b) { b.classList.remove("active"); });
          btn.classList.add("active");
          this.doc.querySelectorAll(".mini-tab-panel").forEach(function (p) { p.classList.remove("active"); });
          var panel = this.doc.getElementById("tab-" + tab);
          if (panel) panel.classList.add("active");
          if (tab === "skills") this.renderActiveSkills();
        };
        var tabsEl = this.doc.querySelector(".mini-tabs");
        if (tabsEl) tabsEl.addEventListener("click", this._boundEvents.tabSwitch);
      }

      // 权重制技能配置弹窗：主角和队友各自独立配置伤害技能权重、主动技能权重、恢复阈值
      showCombatSetupModal() {
        var self = this;
        return new Promise(function(resolve) {
          var oldModal = self.doc.querySelector(".skill-modal-overlay");
          if (oldModal) oldModal.remove();

          var U = window.top.DungeonUtils;

          // 收集己方成员（主角 + 队友）
          var existingCfg = self.combatSkillConfig || {};
          var members = [];
          members.push({
            name: self.player.name || "主角",
            hp: self.player.hp, hpMax: self.player.maxHp,
            sp: self.player.sp, spMax: self.player.maxSp,
            mp: self.player.mp, mpMax: self.player.maxMp,
            isPlayer: true,
            position: (existingCfg[self.player.name || '主角'] || {}).position || null,
            // 主角技能来自已解析的 attackMethods 和 buffSkills
            damageSkills: (self.attackMethods || []).map(function(m) {
              return { name: m.name, costSP: Math.round((m.spCost || 0) * 100), costMP: Math.round((m.mpCost || 0) * 100), defaultWeight: 1, detail: m.desc, raw: m.rawSkill };
            }),
            activeSkills: [],
            healSkills: [],
          });

          // 从 buffSkills 分离出主动(buff)和恢复
          (self.buffSkills || []).forEach(function(bs) {
            var raw = bs.rawSkill || {};
            var isHeal = raw.回复HP比例 || raw.回复SP比例 || raw.回复MP比例;
            if (raw && U && U.isPureHeal && U.isPureHeal(raw)) {
              var ht = U.getHealTypes(raw);
              members[0].healSkills.push({
                name: bs.name, costSP: Math.round((bs.spCost || 0) * 100), costMP: Math.round((bs.mpCost || 0) * 100),
                defaultThreshold: 80, healsHP: ht.hp, healsSP: ht.sp, healsMP: ht.mp,
                detail: bs.desc, raw: raw,
              });
            } else {
              members[0].activeSkills.push({
                name: bs.name, costSP: Math.round((bs.spCost || 0) * 100), costMP: Math.round((bs.mpCost || 0) * 100),
                defaultWeight: 1, detail: bs.desc, raw: raw,
              });
            }
          });

          // 队友
          if (self.allies) {
            self.allies.forEach(function(a) {
              var dmg = [], act = [], heal = [];
              var skillMap = (a.char && a.char.基础信息 && a.char.基础信息.技能列表) || {};
              Object.keys(skillMap).forEach(function(skName) {
                var sk = skillMap[skName];
                if (sk.技能类型 !== "主动") return;
                var costSP = Math.round((sk.消耗SP百分比 || 0) * 100);
                var costMP = Math.round((sk.消耗MP百分比 || 0) * 100);
                var hasDmg = (sk.伤害比例 || 0) > 0;
                var hasHeal = (sk.回复HP比例 || 0) > 0 || (sk.回复SP比例 || 0) > 0 || (sk.回复MP比例 || 0) > 0;
                if (hasDmg) {
                  dmg.push({ name: skName, costSP: costSP, costMP: costMP, defaultWeight: 1, raw: sk });
                } else if (!hasDmg && hasHeal) {
                  heal.push({ name: skName, costSP: costSP, costMP: costMP, defaultThreshold: 80,
                    healsHP: (sk.回复HP比例 || 0) > 0, healsSP: (sk.回复SP比例 || 0) > 0, healsMP: (sk.回复MP比例 || 0) > 0, raw: sk });
                } else {
                  act.push({ name: skName, costSP: costSP, costMP: costMP, defaultWeight: 1, raw: sk });
                }
              });
              members.push({
                name: a.name,
                hp: a.hp, hpMax: a.maxHp,
                sp: a.sp, spMax: a.maxSp,
                mp: a.mp, mpMax: a.maxMp,
                isPlayer: false,
                position: (existingCfg[a.name] || {}).position || null,
                damageSkills: dmg,
                activeSkills: act,
                healSkills: heal,
              });
            });
          }

          // 构建弹窗HTML
          var overlay = self.doc.createElement("div");
          overlay.className = "skill-modal-overlay";

          var html = '';
          html += '<div class="skill-modal-box" style="max-width:540px;">';
          html += '<div class="skill-modal-close">✕</div>';
          html += '<div class="skill-modal-title">⚔️ 战术配置</div>';

          for (var mi = 0; mi < members.length; mi++) {
            var m = members[mi];
            html += '<div style="background:#1a1620;border:1px solid #4a3a2e;border-radius:6px;padding:10px 12px;margin-bottom:8px;">';
            html += '<div style="font-weight:bold;color:#ffe066;margin-bottom:2px;">' + m.name + '</div>';
            html += '<div style="font-size:10px;color:#8a8070;margin-bottom:6px;">HP ' + m.hp + '/' + m.hpMax + '  SP ' + m.sp + '/' + m.spMax + '  MP ' + m.mp + '/' + m.mpMax + '</div>';

            // 战术位置选择
            html += '<div style="font-size:11px;color:#b89b6b;margin-bottom:2px;">战术位置</div>';
            html += '<div style="display:flex;gap:4px;margin-bottom:4px;" id="_posGroup_' + mi + '">';
            ['前卫','中卫','后卫','策应'].forEach(function(pos) {
              var posIcons = { '前卫': '🛡', '中卫': '⚔', '后卫': '🏹', '策应': '🌀' };
              var posDescs = { '前卫': '被攻击+30% 减伤上限+5pp 耐力成长', '中卫': '暴击伤害+15pp 灵巧成长', '后卫': '被攻击-30% 速度压制+10pp 敏捷成长', '策应': '暴击率+10pp 灵巧+敏捷成长' };
              var activeClass = (m.position === pos) ? ' pos-active' : '';
              html += '<button class="_pos_btn' + activeClass + '" data-pos="' + pos + '" data-mi="' + mi + '" title="' + posDescs[pos] + '" style="flex:1;padding:4px 6px;background:#2a2430;border:1px solid #4a3a2e;border-radius:4px;color:#8a8070;cursor:pointer;font-size:11px;font-family:inherit;text-align:center;">' + posIcons[pos] + ' ' + pos + '</button>';
            });
            html += '</div>';

            // 伤害技能
            if (m.damageSkills.length > 0) {
              html += '<div style="font-size:11px;color:#e08060;margin-bottom:2px;margin-top:4px;">⚔ 伤害技能（权重，0=不使用）</div>';
              for (var dsi = 0; dsi < m.damageSkills.length; dsi++) {
                var ds = m.damageSkills[dsi];
                var defW = ds.defaultWeight != null ? ds.defaultWeight : 1;
                var costStr = (ds.costSP > 0 ? " SP" + ds.costSP : "") + (ds.costMP > 0 ? " MP" + ds.costMP : "");
                html += '<div style="display:flex;align-items:center;margin:2px 0 2px 8px;font-size:11px;color:#c0b090;">';
                html += '<span style="flex:1;">' + ds.name + (costStr ? ' <span style="color:#8a8070;">(' + costStr + ')</span>' : '') + '</span>';
                html += '<input type="number" id="_dmg_' + mi + '_' + dsi + '" value="' + defW + '" min="0" style="width:48px;padding:2px 4px;text-align:center;background:#2a2430;color:#ffe066;border:1px solid #b89b6b;border-radius:3px;font-family:inherit;font-size:11px;" /></div>';
              }
            }

            // 主动技能(buff)
            if (m.activeSkills.length > 0) {
              html += '<div style="font-size:11px;color:#7b68ee;margin-bottom:2px;margin-top:6px;">✨ 主动技能（权重，0=不使用）</div>';
              for (var asi = 0; asi < m.activeSkills.length; asi++) {
                var as_ = m.activeSkills[asi];
                var defW = as_.defaultWeight != null ? as_.defaultWeight : 1;
                var costStr = (as_.costSP > 0 ? " SP" + as_.costSP : "") + (as_.costMP > 0 ? " MP" + as_.costMP : "");
                html += '<div style="display:flex;align-items:center;margin:2px 0 2px 8px;font-size:11px;color:#c0b090;">';
                html += '<span style="flex:1;"><span style="color:#7b68ee;">[强化]</span> ' + as_.name + (costStr ? ' <span style="color:#8a8070;">(' + costStr + ')</span>' : '') + '</span>';
                html += '<input type="number" id="_act_' + mi + '_' + asi + '" value="' + defW + '" min="0" style="width:48px;padding:2px 4px;text-align:center;background:#2a2430;color:#ffe066;border:1px solid #b89b6b;border-radius:3px;font-family:inherit;font-size:11px;" /></div>';
              }
            }

            // 恢复技能(阈值)
            if (m.healSkills.length > 0) {
              html += '<div style="font-size:11px;color:#50c878;margin-bottom:2px;margin-top:6px;">💚 恢复技能（阈值%，留空=不使用）</div>';
              for (var hsi = 0; hsi < m.healSkills.length; hsi++) {
                var hs = m.healSkills[hsi];
                var defT = hs.defaultThreshold != null ? hs.defaultThreshold : 80;
                var costStr = (hs.costSP > 0 ? " SP" + hs.costSP : "") + (hs.costMP > 0 ? " MP" + hs.costMP : "");
                var healTypes = [];
                if (hs.healsHP) healTypes.push("HP");
                if (hs.healsSP) healTypes.push("SP");
                if (hs.healsMP) healTypes.push("MP");
                html += '<div style="display:flex;align-items:center;margin:2px 0 2px 8px;font-size:11px;color:#c0b090;">';
                html += '<span style="flex:1;"><span style="color:#50c878;">[恢复' + healTypes.join("/") + ']</span> ' + hs.name + (costStr ? ' <span style="color:#8a8070;">(' + costStr + ')</span>' : '') + '</span>';
                html += '<input type="number" id="_heal_' + mi + '_' + hsi + '" value="' + defT + '" min="0" max="100" placeholder="留空" style="width:48px;padding:2px 4px;text-align:center;background:#2a2430;color:#50c878;border:1px solid #b89b6b;border-radius:3px;font-family:inherit;font-size:11px;" />';
                html += '<span style="color:#8a8070;font-size:10px;margin-left:2px;">%</span>';
                html += '</div>';
              }
            }

            if (m.damageSkills.length === 0 && m.activeSkills.length === 0 && m.healSkills.length === 0) {
              html += '<div style="font-size:10px;color:#605040;">仅基本攻击可用</div>';
            }
            html += '</div>';
          }

          html += '<div style="text-align:center;margin-top:10px;">';
          html += '<button id="_combatSetupConfirm" style="background:#b89b6b;color:#1a0e0a;border:none;padding:8px 28px;border-radius:6px;font-weight:bold;font-family:inherit;cursor:pointer;font-size:13px;">确认配置</button>';
          html += '</div></div>';

          overlay.innerHTML = html;
          self.doc.body.appendChild(overlay);

          // 位置按钮点击事件
          overlay.querySelectorAll("._pos_btn").forEach(function(btn) {
            btn.onclick = function() {
              var mi = btn.dataset.mi;
              var group = overlay.querySelector("#_posGroup_" + mi);
              group.querySelectorAll("._pos_btn").forEach(function(b) {
                b.classList.remove("pos-active");
                b.style.background = "#2a2430";
                b.style.borderColor = "#4a3a2e";
                b.style.color = "#8a8070";
              });
              btn.classList.add("pos-active");
              btn.style.background = "#3a2a1a";
              btn.style.borderColor = "#ffe066";
              btn.style.color = "#ffe066";
            };
          });

          // 关闭逻辑
          overlay.querySelector(".skill-modal-close").onclick = function() { overlay.remove(); resolve(null); };
          overlay.addEventListener("click", function(e) {
            if (e.target === overlay && !e.target.closest(".skill-modal-box")) { overlay.remove(); resolve(null); }
          });

          // 确认按钮
          overlay.querySelector("#_combatSetupConfirm").onclick = function() {
            var config = {};
            for (var mi2 = 0; mi2 < members.length; mi2++) {
              var mem = members[mi2];
              var entry = { damageWeights: {}, activeWeights: {}, healThreshold: null, position: null };

              // 基本攻击默认权重5
              entry.damageWeights["基本攻击"] = 5;

              // 读取伤害技能权重
              for (var dsi2 = 0; dsi2 < mem.damageSkills.length; dsi2++) {
                var inp = overlay.querySelector("#_dmg_" + mi2 + "_" + dsi2);
                if (inp) {
                  var w = parseInt(inp.value);
                  if (isFinite(w) && w > 0) entry.damageWeights[mem.damageSkills[dsi2].name] = w;
                }
              }

              // 读取主动技能权重
              for (var asi2 = 0; asi2 < mem.activeSkills.length; asi2++) {
                var inp2 = overlay.querySelector("#_act_" + mi2 + "_" + asi2);
                if (inp2) {
                  var w2 = parseInt(inp2.value);
                  if (isFinite(w2) && w2 > 0) entry.activeWeights[mem.activeSkills[asi2].name] = w2;
                }
              }

              // 读取恢复阈值（取第一个有效的恢复技能阈值）
              for (var hsi2 = 0; hsi2 < mem.healSkills.length; hsi2++) {
                var inp3 = overlay.querySelector("#_heal_" + mi2 + "_" + hsi2);
                if (inp3) {
                  var t = parseInt(inp3.value);
                  if (isFinite(t) && inp3.value !== '') {
                    entry.healThreshold = t;
                    break;
                  }
                }
              }

              // 读取战术位置
              var posBtn = overlay.querySelector("#_posGroup_" + mi2 + " ._pos_btn.pos-active");
              if (posBtn) entry.position = posBtn.dataset.pos;

              config[mem.name] = entry;
            }
            overlay.remove();
            resolve(config);
          };
        });
      }

      // 等级补正：从 sysbox 读取
      getLevelCorrection(lv) {
        const cfg = this.getCombatConfig().等级补正 || {};
        const coeff = cfg.等级系数 ?? 1000;
        // 怪物等级补正：至少为 0
        return Math.max(0, (lv - 1) * coeff);
      }

      // 楼层补正：从 sysbox 动态行表匹配
      getFloorCorrection(floor) {
        const list = this.getCombatConfig().楼层补正 || [];
        for (const e of list) {
          if (floor >= e.层数最低 && floor <= e.层数最高) return e.补正值;
        }
        return 1.0;
      }

      // 稀有度抽选（楼层主不参与）
      pickRarity() {
        const r = this.getCombatConfig().稀有度补正 || {};
        const entries = [
          {
            name: "普通",
            coeff: r.普通?.系数 ?? 1,
            prob: r.普通?.概率 ?? 75,
          },
          {
            name: "精英",
            coeff: r.精英?.系数 ?? 1.2,
            prob: r.精英?.概率 ?? 20,
          },
          {
            name: "变异",
            coeff: r.变异?.系数 ?? 1.5,
            prob: r.变异?.概率 ?? 5,
          },
        ];
        const roll = Math.random() * 100;
        let cum = 0;
        for (const e of entries) {
          cum += e.prob;
          if (roll < cum) return e;
        }
        return entries[0];
      }

      // 怪物最终属性计算（新公式）
      calcMonsterFinalStat(baseStat, monsterLv, floor, rarityCoeff) {
        const levelCorr = this.getLevelCorrection(monsterLv);
        const floorCorr = this.getFloorCorrection(floor);
        const rc = rarityCoeff || 1;
        return Math.floor((levelCorr + baseStat) * floorCorr * rc);
      }

      getPlayerFinalStats() {
        var em = this.data.equipMult || {
          str: 1,
          vit: 1,
          dex: 1,
          agi: 1,
          mag: 1,
        };
        var sm = { str: 1, vit: 1, dex: 1, agi: 1, mag: 1 };
        (this.skills || []).forEach(function (s) {
          if (!s.active) return;
          var b = s.bonuses || {};
          if (b.力量 && b.力量 !== 0) sm.str *= 1 + b.力量;
          if (b.耐力 && b.耐力 !== 0) sm.vit *= 1 + b.耐力;
          if (b.灵巧 && b.灵巧 !== 0) sm.dex *= 1 + b.灵巧;
          if (b.敏捷 && b.敏捷 !== 0) sm.agi *= 1 + b.敏捷;
          if (b.魔力 && b.魔力 !== 0) sm.mag *= 1 + b.魔力;
        });
        var totalStats = _.get(this.playerChar, "个人属性.总能力", {});
        var pStr = totalStats.力量 || 0;
        var pVit = totalStats.耐力 || 0;
        var pDex = totalStats.灵巧 || 0;
        var pAgi = totalStats.敏捷 || 0;
        var pMag = totalStats.魔力 || 0;
        return {
          str: Math.floor(pStr * em.str * sm.str),
          vit: Math.floor(pVit * em.vit * sm.vit),
          dex: Math.floor(pDex * em.dex * sm.dex),
          agi: Math.floor(pAgi * em.agi * sm.agi),
          mag: Math.floor(pMag * em.mag * sm.mag),
        };
      }
      getPlayerTotalStats() {
        const f = this.getPlayerFinalStats();
        return f.str + f.vit + f.dex + f.agi + f.mag;
      }

      generateEnemyFromTemplate(tpl, rarity) {
        const lv = tpl.lv;
        const r = (min, max) =>
          Math.floor(Math.random() * (max - min + 1)) + min;
        const base = {
          str: r(tpl.statRanges.str.min, tpl.statRanges.str.max),
          vit: r(tpl.statRanges.vit.min, tpl.statRanges.vit.max),
          dex: r(tpl.statRanges.dex.min, tpl.statRanges.dex.max),
          agi: r(tpl.statRanges.agi.min, tpl.statRanges.agi.max),
          mag: r(tpl.statRanges.mag.min, tpl.statRanges.mag.max),
        };
        // 楼层主固定稀有度（系数读sysbox），其他随机roll
        var rarityInfo;
        if (rarity === '楼层主') {
          var rcCfg = (this.getCombatConfig().稀有度补正 || {});
          rarityInfo = { name: '楼层主', coeff: (rcCfg.楼层主?.系数 ?? 2.0) };
        } else {
          rarityInfo = rarity || this.pickRarity();
        }
        const rc = rarityInfo.coeff || 1;
        const floor = this.config.floor;
        const nameSuffix =
          rarityInfo.name === "普通" ? "" : "（" + rarityInfo.name + "）";

        // 计算最终属性
        const finalStr = this.calcMonsterFinalStat(base.str, lv, floor, rc);
        const finalVit = this.calcMonsterFinalStat(base.vit, lv, floor, rc);
        const finalDex = this.calcMonsterFinalStat(base.dex, lv, floor, rc);
        const finalAgi = this.calcMonsterFinalStat(base.agi, lv, floor, rc);
        const finalMag = this.calcMonsterFinalStat(base.mag, lv, floor, rc);

        // 怪物公式：完全没有基础值
        const maxHp = finalStr + finalVit;
        const maxSp = Math.floor(finalVit * 0.3);
        const maxMp = Math.floor(finalMag * 0.3);

        return {
          name: tpl.name + nameSuffix,
          lv,
          hp: maxHp,
          maxHp,
          finalStr,
          finalVit,
          finalDex,
          finalAgi,
          finalMag,
          maxSp,
          maxMp,
          sp: maxSp,
          mp: maxMp, // 小游戏内用 sp/mp 表示当前值
          rarity: rarityInfo.name,
          rarityCoeff: rc,
          // 注意：这里不需要记录 HP上限/SP上限/MP上限，因为小游戏只认 final* 和 hp/sp/mp/maxHp 等字段
        };
      }

      // ---- 辅助函数：从变量读取 sysbox 战斗系统配置 ----
      getCombatConfig() {
        try {
          const all = getFullVariables();
          const sd = _.get(all, "stat_data", {});
          return _.get(sd, "sysbox.战斗系统", {});
        } catch (e) {
          return {};
        }
      }

      getTierByColor(tileVal) {
        // tileVal 如 "tier_0" "tier_1" ...
        const idx = parseInt((tileVal || "").replace("tier_", ""));
        if (!isNaN(idx) && idx >= 0 && idx < this.tierConfigs.length) {
          return this.tierConfigs[idx];
        }
        return null;
      }

      calcEnemyReward(enemy, options) {
        // 组队模式：按战力占比分配总经验池
        if (options && options.groupExpPool != null && options.groupTotalPower > 0) {
          const share = options.groupExpPool * (options.myPower || 1) / options.groupTotalPower;
          const exp = Math.max(1, Math.round(share));
          const featDivisor = this.sysbox伟业换算 || 100;
          const feat = Math.floor(exp / featDivisor);
          return { exp: exp, feat: feat };
        }
        // 原有单只判定（向后兼容）
        const tier = this.getTierByColor(enemy.color);
        if (!tier) return { exp: 0, feat: 0 };
        const expMin = tier.经验值最低 || 0;
        const expMax = tier.经验值最高 || 0;
        const baseExp = expMax > expMin
          ? Math.floor(Math.random() * (expMax - expMin + 1)) + expMin
          : expMin;
        const rc = enemy.rarityCoeff || 1;
        const exp = Math.floor(baseExp * rc);
        const featDivisor = this.sysbox伟业换算 || 100;
        const feat = Math.floor(exp / featDivisor);
        return { exp, feat };
      }

      determineMonsterColor(enemy) {
        var totalE =
          enemy.finalStr +
          enemy.finalVit +
          enemy.finalDex +
          enemy.finalAgi +
          enemy.finalMag;
        var config = this.getCombatConfig();
        var playerTotal = this.getPlayerTotalStats();
        // 用战力比近似战损比来做展示颜色匹配
        var roughRatio = totalE > 0 ? playerTotal / totalE : 999;
        var match = U.matchColorTier(roughRatio, config);
        return this.tierTileValues[match.tierIndex] || this.TILE.EMPTY;
      }

      determineGroupColor(totalPower, totalHpMax) {
        var config = this.getCombatConfig();
        var teamEO = 0;
        var teamES = 0;

        // 主角
        var pStats = this.playerChar.个人属性?.总能力 || {};
        var pEo = (pStats.力量 || 0) + (pStats.耐力 || 0) + (pStats.灵巧 || 0) + (pStats.敏捷 || 0) + (pStats.魔力 || 0);
        teamEO += pEo;
        teamES += this.player.hp + this.player.sp * 0.5 + (this.player.mp > 0 ? 50 : 0);

        // 队友
        if (this.allies) {
          for (var i = 0; i < this.allies.length; i++) {
            var a = this.allies[i];
            var aStats = a.char.个人属性?.总能力 || {};
            var aEo = (aStats.力量 || 0) + (aStats.耐力 || 0) + (aStats.灵巧 || 0) + (aStats.敏捷 || 0) + (aStats.魔力 || 0);
            teamEO += aEo;
            teamES += (a.hp || 0) + (a.sp || 0) * 0.5 + ((a.mp || 0) > 0 ? 50 : 0);
          }
        }

        var turnsToKill = totalHpMax > 0 ? totalHpMax / teamEO : 0;
        var turnsToWipe = teamES > 0 ? teamES / totalPower : 0;
        var enduranceRatio = turnsToKill > 0 ? turnsToWipe / turnsToKill : 999;

        var match = U.matchColorTier(enduranceRatio, config);
        return {
          tierIndex: match.tierIndex,
          tileValue: this.tierTileValues[match.tierIndex] || this.TILE.EMPTY,
        };
      }

      calcGroupExpPool(tierIndex) {
        var tier = this.tierConfigs[tierIndex];
        if (!tier) return 0;
        var expMin = tier.经验值最低 || 0;
        var expMax = tier.经验值最高 || 0;
        return expMax > expMin
          ? Math.floor(Math.random() * (expMax - expMin + 1)) + expMin
          : expMin;
      }

      placeEnemyGroup(idx, x, y, tpl, count, rarity) {
        var members = [];
        var groupTotalPower = 0;
        var groupTotalHpMax = 0;
        for (var i = 0; i < count; i++) {
          var enemy = this.generateEnemyFromTemplate(tpl, rarity);
          groupTotalPower += enemy.finalStr + enemy.finalVit + enemy.finalDex + enemy.finalAgi + enemy.finalMag;
          groupTotalHpMax += enemy.maxHp;
          members.push(enemy);
        }
        // 聚合判定颜色和经验池
        var colorResult = this.determineGroupColor(groupTotalPower, groupTotalHpMax);
        var groupExpPool = this.calcGroupExpPool(colorResult.tierIndex);
        // 统一赋色
        members.forEach(function(m) {
          m.color = colorResult.tileValue;
        });
        var group = {
          members: members,
          isGroup: count > 1,
          tileColor: colorResult.tileValue,
          _rewardCache: {
            totalPower: groupTotalPower,
            totalHpMax: groupTotalHpMax,
            tierIndex: colorResult.tierIndex,
            expPool: groupExpPool,
          },
        };
        if (!this.enemyDataMap[idx]) this.enemyDataMap[idx] = new Map();
        this.enemyDataMap[idx].set(x + "," + y, group);
        return group;
      }

      generateRoom(idx, monsterCount) {
        var n = 9;
        var g = Array(n).fill().map(function() { return Array(n).fill(this.TILE.EMPTY); }.bind(this));
        var e = Array(n).fill().map(function() { return Array(n).fill(false); });
        var monsters = [];
        var door = null;
        if (idx < this.config.roomCount - 1) {
          var placedDoor = false;
          while (!placedDoor) {
            var dx = 1 + Math.floor(Math.random() * 7);
            var dy = 1 + Math.floor(Math.random() * 7);
            if (g[dy][dx] === this.TILE.EMPTY) {
              g[dy][dx] = this.TILE.DOOR;
              door = { x: dx, y: dy };
              placedDoor = true;
            }
          }
        }
        if (!this.enemyDataMap[idx]) this.enemyDataMap[idx] = new Map();

        // 计算队伍最大人数
        var partySize = 1 + (this.allies ? this.allies.length : 0);
        var maxGroupSize = partySize + 2;

        // 拆分落单和组队：随机决定每个敌方单位是落单还是组队
        var soloCount = 0;
        var groupCount = 0;
        var remaining = monsterCount;
        while (remaining > 0) {
          if (remaining >= 2 && Math.random() < 0.4) {
            // 组队：2 ~ maxGroupSize 个敌人
            var gs = Math.min(remaining, 2 + Math.floor(Math.random() * (maxGroupSize - 1)));
            groupCount++;
            remaining -= gs;
          } else {
            soloCount++;
            remaining--;
          }
        }

        // 重新计算并放置
        var placedCount = 0;
        var attempts = 0;
        var maxAttempts = 500;
        var soloRemaining = soloCount;
        var groupSizes = [];
        // 预计算所有组的大小
        remaining = monsterCount - soloCount;
        while (remaining > 0) {
          if (remaining >= 2 && Math.random() < 0.4) {
            var gs2 = Math.min(remaining, 2 + Math.floor(Math.random() * (maxGroupSize - 1)));
            groupSizes.push(gs2);
            remaining -= gs2;
          } else {
            groupSizes.push(1);
            remaining--;
          }
        }
        // 确保所有剩余的都算进去
        if (remaining > 0) groupSizes.push(remaining);
        // 简化：重新分配
        var allSlots = [];
        remaining = monsterCount;
        while (remaining > 0) {
          if (remaining >= 2 && Math.random() < 0.4) {
            var gs3 = Math.min(remaining, 2 + Math.floor(Math.random() * (maxGroupSize - 1)));
            allSlots.push(gs3);
            remaining -= gs3;
          } else {
            allSlots.push(1);
            remaining--;
          }
        }

        var self = this;
        allSlots.forEach(function(slotSize) {
          if (attempts >= maxAttempts) return;
          var placed = false;
          while (!placed && attempts < maxAttempts) {
            var tx = Math.floor(Math.random() * n);
            var ty = Math.floor(Math.random() * n);
            if (g[ty][tx] === self.TILE.EMPTY) {
              var tpl = self.monsterTemplates[Math.floor(Math.random() * self.monsterTemplates.length)];
              var isFloorBoss = tpl.rarity === '楼层主';
              var actualSlotSize = isFloorBoss ? 1 : slotSize;
              var group = self.placeEnemyGroup(idx, tx, ty, tpl, actualSlotSize, isFloorBoss ? '楼层主' : null);
              g[ty][tx] = group.tileColor;
              group.members.forEach(function(m) { monsters.push(m); });
              placed = true;
            }
            attempts++;
          }
        });

        return { grid: g, explored: e, doorPos: door, monsters: monsters };
      }

      generateAllRooms() {
        this.enemyDataMap = [];
        this.rooms = [];
        const total = this.config.roomCount * 10;
        const base = Math.floor(total / this.config.roomCount);
        let rem = total % this.config.roomCount;
        for (let i = 0; i < this.config.roomCount; i++) {
          let c = base;
          if (rem > 0) {
            c++;
            rem--;
          }
          this.rooms.push(this.generateRoom(i, c));
        }
        this.currentRoomIndex = 0;
        this.loadRoom(0, false);
      }

      loadRoom(index, fromDoor) {
        // 进入新房间时清理旧日志（保留最新5条）并添加分隔线
        var logBox = this.doc.getElementById(this.ids.logBoxId);
        if (logBox) {
          while (logBox.children.length > 5) {
            logBox.removeChild(logBox.firstChild);
          }
          // 添加房间分隔线
          var sep = document.createElement("div");
          sep.className = "log-entry system";
          sep.style.cssText = "text-align:center;color:#b89b6b;border-top:1px dashed #4a3a2e;margin:4px 0;padding-top:4px;";
          sep.textContent = "--- 进入房间 " + (index + 1) + " ---";
          logBox.appendChild(sep);
          logBox.scrollTop = logBox.scrollHeight;
        }
        const room = this.rooms[index];
        this.grid = room.grid.map((r) => [...r]);
        this.explored = room.explored.map((r) => [...r]);
        for (let y = 0; y < 9; y++)
          for (let x = 0; x < 9; x++)
            if (this.grid[y][x] === this.TILE.PLAYER)
              this.grid[y][x] = this.TILE.EMPTY;
        let placed = false;
        if (fromDoor && room.doorPos) {
          const { x: dx, y: dy } = room.doorPos;
          for (let [nx, ny] of [
            [dx + 1, dy],
            [dx - 1, dy],
            [dx, dy + 1],
            [dx, dy - 1],
          ]) {
            if (
              nx >= 0 &&
              nx < 9 &&
              ny >= 0 &&
              ny < 9 &&
              this.grid[ny][nx] === this.TILE.EMPTY
            ) {
              this.grid[ny][nx] = this.TILE.PLAYER;
              this.player.x = nx;
              this.player.y = ny;
              placed = true;
              break;
            }
          }
        }
        if (!placed) {
          for (let y = 0; y < 9; y++) {
            for (let x = 0; x < 9; x++) {
              if (this.grid[y][x] === this.TILE.EMPTY) {
                this.grid[y][x] = this.TILE.PLAYER;
                this.player.x = x;
                this.player.y = y;
                placed = true;
                break;
              }
            }
            if (placed) break;
          }
        }
        this.explored[this.player.y][this.player.x] = true;
        this.revealAdjacent(this.player.x, this.player.y);
        this.selectedEnemyPos = null;
        this.drawMap();
        if (fromDoor) {
          const hpRecover = Math.floor(this.player.maxHp * 0.2);
          const spRecover = Math.floor(this.player.maxSp * 0.2);
          this.player.hp = Math.min(this.player.hp + hpRecover, this.player.maxHp);
          this.player.sp = Math.min(this.player.sp + spRecover, this.player.maxSp);
          var allyRecoverMsg = '';
          if (this.allies && this.allies.length > 0) {
            this.allies.forEach(function(a) {
              var aHp = Math.floor((a.maxHp || 100) * 0.2);
              var aSp = Math.floor((a.maxSp || 100) * 0.2);
              a.hp = Math.min((a.hp || 0) + aHp, a.maxHp || 100);
              a.sp = Math.min((a.sp || 0) + aSp, a.maxSp || 100);
            });
            allyRecoverMsg = '（队友也恢复了）';
          }
          this.addLog('🛌 进入新房间，恢复了 ' + hpRecover + ' HP 和 ' + spRecover + ' SP' + allyRecoverMsg, "heal");
        }
        this.updateUI();
      }

      revealAdjacent(x, y) {
        for (let [dx, dy] of [
          [0, 0],
          [1, 0],
          [-1, 0],
          [0, 1],
          [0, -1],
        ]) {
          const nx = x + dx,
            ny = y + dy;
          if (nx >= 0 && nx < 9 && ny >= 0 && ny < 9)
            this.explored[ny][nx] = true;
        }
      }

      drawMap() {
        const cell = this.canvas.width / 9;
        var self = this;
        for (let y = 0; y < 9; y++)
          for (let x = 0; x < 9; x++) {
            let fill = "#153e55";
            if (this.explored[y][x]) {
              var tile = this.grid[y][x];
              if (tile === this.TILE.EMPTY || tile === this.TILE.PLAYER) {
                fill = "#1f5e7a";
              } else if (tile === this.TILE.DOOR) {
                fill = "#b5926a";
              } else if (tile && tile.startsWith("tier_")) {
                // 动态颜色档位格子
                var idx = parseInt(tile.replace("tier_", ""));
                if (
                  !isNaN(idx) &&
                  idx >= 0 &&
                  idx < self.tierColorValues.length
                ) {
                  fill = self.tierColorValues[idx];
                } else {
                  fill = "#666";
                }
              }
            }
            this.ctx.fillStyle = fill;
            this.ctx.fillRect(x * cell, y * cell, cell - 1, cell - 1);
            this.ctx.strokeStyle = "#195067";
            this.ctx.strokeRect(x * cell, y * cell, cell, cell);
            if (
              this.selectedEnemyPos &&
              this.selectedEnemyPos.x === x &&
              this.selectedEnemyPos.y === y
            ) {
              this.ctx.shadowColor = "#f5d742";
              this.ctx.shadowBlur = 10;
              this.ctx.strokeStyle = "#f5d742";
              this.ctx.lineWidth = 2;
              this.ctx.strokeRect(
                x * cell + 2,
                y * cell + 2,
                cell - 5,
                cell - 5,
              );
              this.ctx.shadowBlur = 0;
            }
            // 组队敌人显示数量标记
            if (this.explored[y][x] && tile && tile.startsWith("tier_")) {
              var group = this.enemyDataMap[this.currentRoomIndex] && this.enemyDataMap[this.currentRoomIndex].get(x + "," + y);
              if (group && group.isGroup && group.members.length > 1) {
                var aliveCount = group.members.filter(function(m) { return m.hp > 0; }).length;
                if (aliveCount > 0) {
                  this.ctx.fillStyle = "#fff";
                  this.ctx.font = "bold " + Math.floor(cell * 0.4) + "px serif";
                  this.ctx.textAlign = "center";
                  this.ctx.fillText("×" + aliveCount, x * cell + cell * 0.7, y * cell + cell * 0.35);
                }
              }
            }
            if (this.explored[y][x] && this.grid[y][x] === this.TILE.PLAYER) {
              this.ctx.beginPath();
              this.ctx.arc(
                x * cell + cell / 2,
                y * cell + cell / 2,
                cell * 0.35,
                0,
                2 * Math.PI,
              );
              this.ctx.fillStyle = "#f2e9c7";
              this.ctx.shadowColor = "#ffecb3";
              this.ctx.shadowBlur = 8;
              this.ctx.fill();
              this.ctx.shadowBlur = 0;
            }
          }
      }

      updateEnemyPanel(group) {
        var el = this.doc.getElementById(this.ids.enemyStatsId);
        if (!group || !group.members || !group.members.length) { el.innerHTML = '<div style="color:#6a9ab5;font-size:12px;">点击敌人显示能力值</div>'; return; }
        var rarityColors = { '普通': '#b9d0e0', '精英': '#5f9ed4', '变异': '#cc8ad9', '楼层主': '#eac268' };
        var html = '<div style="font-size:10px;color:#eac268;margin-bottom:2px;">' + (group.isGroup ? '👥 组队敌人 ×' + group.members.length : '👤 落单敌人') + '</div>';
        group.members.forEach(function(m) {
          var rarityColor = rarityColors[m.rarity] || '#b9d0e0';
          html +=
            '<div class="enemy-card" style="margin-bottom:4px;">' +
            '<div class="enemy-card-header">' +
            '<span class="enemy-card-name">👹 ' + m.name + ' Lv.' + m.lv + '</span>' +
            '<span class="enemy-card-rarity" style="color:' + rarityColor + ';">' + (m.rarity || '普通') + '</span>' +
            '</div>' +
            '<div class="mini-resource-bar" style="margin-bottom:4px;">' +
            '<span class="label" style="width:22px;">❤️</span>' +
            '<span class="outer" style="flex:1;height:10px;background:#03131e;border-radius:5px;overflow:hidden;">' +
            '<span class="fill hp" style="width:' + (m.maxHp > 0 ? Math.round(m.hp/m.maxHp*100) : 0) + '%;height:100%;display:block;border-radius:5px;"></span>' +
            '</span>' +
            '<span class="val" style="width:48px;text-align:right;color:#d4ead4;">' + m.hp + '/' + m.maxHp + '</span>' +
            '</div>' +
            '<div class="enemy-card-stats">' +
            '<span>⚔️ ' + (m.finalStr || 0) + '</span>' +
            '<span>🛡️ ' + (m.finalVit || 0) + '</span>' +
            '<span>✨ ' + (m.finalDex || 0) + '</span>' +
            '<span>⚡ ' + (m.finalAgi || 0) + '</span>' +
            '<span>🔮 ' + (m.finalMag || 0) + '</span>' +
            '</div></div>';
        });
        el.innerHTML = html;
      }

      combat(group) {
        this.timer += this.sysbox战斗时间 || 5;
        // ===== 0. 使用默认配置（若未设置）=====
        if (!this.combatSkillConfig) {
          this.combatSkillConfig = this._buildDefaultSkillConfig();
        }

        // ===== 1. 构建己方combatants（主角 + 队友） =====
        var U = window.top.DungeonUtils;
        var combatConfig = this.getCombatConfig();
        var floor = this.data.floor || 1;

        // 同步主角 HP/SP/MP 到 Zod 对象
        _.set(this.playerChar, "状态.HP当前值", this.player.hp);
        _.set(this.playerChar, "状态.SP当前值", this.player.sp);
        _.set(this.playerChar, "状态.MP当前值", this.player.mp);
        var allies = [];
        allies.push({ char: this.playerChar, name: this.player.name || '主角' });
        if (this.allies) {
          this.allies.forEach(function(a) {
            if (a.hp <= 1) return; // 保护至1血，暂时无法战斗，进房间回血后自动恢复
            // 同步队友 HP/SP/MP 到 Zod 对象
            _.set(a.char, "状态.HP当前值", a.hp);
            _.set(a.char, "状态.SP当前值", a.sp);
            _.set(a.char, "状态.MP当前值", a.mp);
            allies.push({ char: a.char, name: a.name });
          });
        }

        // ===== 2. 构建敌方combatants（仅当前组队的存活怪物）=====
        var enemies = [];
        var aliveMembers = (group && group.members) ? group.members.filter(function(m) { return m.hp > 0; }) : [];
        if (!aliveMembers.length) return false;
        aliveMembers.forEach(function(m) {
          var unit = U.buildEnemyCombatUnit({
            name: m.name, lv: m.lv, type: '怪物', rarity: m.rarity,
            abilities: { 力量: m.finalStr || 0, 耐力: m.finalVit || 0, 灵巧: m.finalDex || 0, 敏捷: m.finalAgi || 0, 魔力: m.finalMag || 0 },
            status: { HP上限: m.hpMax || m.hp, HP当前值: m.hp, SP上限: m.maxSp || 0, SP当前值: m.sp || 0, MP上限: m.maxMp || 0, MP当前值: m.mp || 0 },
          });
          unit._enemyRef = m;
          enemies.push(unit);
        });

        // ===== 3. 构建技能选择（从权重配置）=====
        var skillSelections = {};
        var plName = this.player.name || '主角';
        skillSelections[plName] = this.combatSkillConfig[plName] || { damageWeights: { "基本攻击": 5 }, activeWeights: {}, healThreshold: null };
        if (this.allies) {
          var self = this;
          this.allies.forEach(function(a) {
            var cfg = self.combatSkillConfig[a.name];
            if (cfg) {
              skillSelections[a.name] = cfg;
            } else {
              skillSelections[a.name] = { damageWeights: { "基本攻击": 5 }, activeWeights: {}, healThreshold: null };
            }
          });
        }

        // ===== 4. 调用统一战斗（1轮）=====
        var result = U.calcMultiCombat({
          allies: allies,
          enemies: enemies,
          combatConfig: combatConfig,
          floor: floor,
          maxRounds: 1,
          skillSelections: skillSelections,
        });

        // ===== 5. 处理结果 =====
        // 更新玩家
        var plResult = result.allyResults.find(function(a) { return a.name === (this.player.name || '主角'); }.bind(this));
        if (plResult) {
          this.player.hp = plResult.hpAfter;
          this.player.sp = plResult.spAfter;
          this.player.mp = plResult.mpAfter;
        }

        // 更新队友
        if (this.allies) {
          this.allies.forEach(function(a) {
            var aResult = result.allyResults.find(function(r) { return r.name === a.name; });
            if (aResult) {
              a.hp = aResult.hpAfter;
              a.sp = aResult.spAfter;
              a.mp = aResult.mpAfter;
            }
          });
        }

        // 更新怪物（按索引匹配，避免同名覆盖）
        var killedEnemies = [];
        result.enemyResults.forEach(function(e, i) {
          var unit = enemies[i];
          if (unit && unit._enemyRef) {
            unit._enemyRef.hp = e.hpAfter;
            if (e.defeated) killedEnemies.push(unit._enemyRef);
          }
        });

        // ===== 6. 战斗日志 =====
        result.rounds.forEach(function(r) {
          var side = r.attacker === (this.player.name || '主角') ? '👤' : (r.action === 'heal' ? '💚' : '⚔️');
          var log = side + ' ' + r.attacker;
          if (r.action === 'heal') {
            log += ' → ' + r.defender + '（' + r.skill;
            if (r.hpHealed) log += '，HP+' + r.hpHealed;
            if (r.spHealed) log += '，SP+' + r.spHealed;
            if (r.mpHealed) log += '，MP+' + r.mpHealed;
            log += '）';
          } else {
            log += ' → ' + r.defender + '（' + r.skill + '，伤害' + r.damage;
            if (r.crit) log += ' 暴击';
            if (r.agiBonus > 0) log += ' 速度压制';
            log += '，剩余HP:' + r.defenderRemaining + '）';
          }
          this.addLog(log, "damage");
        }.bind(this));

        // 检查主角是否被击败
        if (plResult && plResult.defeated) {
          this.gameOver = true;
          this.addLog("💀 力竭…", "defeat");
          this.updateUI();
          return false;
        }

        // 处理击败的怪物
        var anyKilled = false;
        killedEnemies.forEach(function(m) {
          this.addLoot(m.rarity);
          this.recordDefeat(m, group._rewardCache);
          this.addLog("🎉 击败 " + m.name, "defeat");
          anyKilled = true;
        }.bind(this));

        // 累积经验权重增量（含战术位置加成）
        var U2 = window.top.DungeonUtils;
        if (U2 && U2.calcExpWeightDeltas) {
          var aNames = [];
          aNames.push(this.player.name || '主角');
          if (this.allies) { this.allies.forEach(function(a) { aNames.push(a.name); }); }
          var roundDeltas = U2.calcExpWeightDeltas(result, aNames);
          // 追加战术位置经验权重加成
          var posCfg2 = U2.TACTICAL_POSITIONS;
          var skillCfg = this.combatSkillConfig || {};
          aNames.forEach(function(n) {
            if (!this.weightDeltas[n]) this.weightDeltas[n] = { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
            var src = roundDeltas[n] || {};
            var dst = this.weightDeltas[n];
            ["力量","耐力","灵巧","敏捷","魔力"].forEach(function(k) { dst[k] += src[k] || 0; });
            // 战术位置经验权重加成
            var charCfg = skillCfg[n];
            if (charCfg && charCfg.position && posCfg2 && posCfg2[charCfg.position]) {
              var posBonus = posCfg2[charCfg.position].expWeightBonus;
              if (posBonus) {
                ["力量","耐力","灵巧","敏捷","魔力"].forEach(function(k) { dst[k] += posBonus[k] || 0; });
              }
            }
          }.bind(this));
        }

        // 检查组队内所有敌人是否已全部被击败
        var allDead = aliveMembers.every(function(m) { return m.hp <= 0; });
        this.updateUI();
        return allDead;
      }
      addLoot(rarity) {
        var result = calcLootByRarity(rarity);
        this.loot[result]++;
        this.updateUI();
      }

      recordDefeat(enemy, rewardCache) {
        var myPower = (enemy.finalStr || 0) + (enemy.finalVit || 0) + (enemy.finalDex || 0) + (enemy.finalAgi || 0) + (enemy.finalMag || 0);
        var reward;
        if (rewardCache && rewardCache.expPool != null) {
          reward = this.calcEnemyReward(enemy, {
            groupTotalPower: rewardCache.totalPower,
            groupExpPool: rewardCache.expPool,
            myPower: myPower,
          });
        } else {
          reward = this.calcEnemyReward(enemy);
        }
        this.defeatedMonsters.push({
          name: enemy.name,
          lv: enemy.lv,
          rarity: enemy.rarity || "普通",
          exp: reward.exp,
          feat: reward.feat,
        });
        this.totalExp += reward.exp;
        this.totalFeats += reward.feat;
      }

      attackEnemyAt(tx, ty) {
        var map = this.enemyDataMap[this.currentRoomIndex];
        var group = map ? map.get(tx + "," + ty) : undefined;
        if (!group || !group.members || !group.members.length) return false;
        // 只用存活成员计算颜色消耗
        var aliveMembers = group.members.filter(function(m) { return m.hp > 0; });
        if (aliveMembers.length === 0) return false;
        var costColor = group.tileColor;
        var cost = typeof this.SP_COST[costColor] === "function" ? this.SP_COST[costColor]() : this.SP_COST[costColor];

        if (this.player.sp < cost) {
          this.addLog("体力不足");
          return false;
        }
        this.player.sp -= cost;
        this.playSound("hit");

        var allKilled = this.combat(group);
        // 致死直接触发 gameOver，直接退出
        if (this.gameOver) {
          this.updateUI();
          return true;
        }

        if (allKilled) {
          this.grid[ty][tx] = this.TILE.EMPTY;
          map.delete(tx + "," + ty);
          this.rooms[this.currentRoomIndex].grid[ty][tx] = this.TILE.EMPTY;
          this.selectedEnemyPos = null;
          this.updateEnemyPanel(null);
        } else {
          map.set(tx + "," + ty, group);
          if (this.selectedEnemyPos && this.selectedEnemyPos.x === tx && this.selectedEnemyPos.y === ty)
            this.updateEnemyPanel(group);
        }
        this.drawMap();
        this.updateUI();
        return true;
      }

      moveTo(tx, ty) {
        if (this.isMoving || this.gameOver) return;
        if (!this.explored[ty][tx]) return;
        const tile = this.grid[ty][tx];
        // 动态判断是否为颜色档位格子
        var isEnemyTile = tile && tile.startsWith("tier_");
        if (isEnemyTile) {
          if (
            this.selectedEnemyPos?.x === tx &&
            this.selectedEnemyPos?.y === ty
          )
            this.attackEnemyAt(tx, ty);
          else {
            this.selectedEnemyPos = { x: tx, y: ty };
            this.updateEnemyPanel(
              this.enemyDataMap[this.currentRoomIndex]?.get(`${tx},${ty}`),
            );
            this.playSound("select");
            this.drawMap();
          }
          return;
        }
        if (
          tile === this.TILE.DOOR &&
          this.currentRoomIndex < this.rooms.length - 1
        ) {
          this.currentRoomIndex++;
          this.loadRoom(this.currentRoomIndex, true);
          this.addLog(`进入房间 ${this.currentRoomIndex + 1}`);
          this.updateUI();
          return;
        }
        const path = this.findPath(this.player.x, this.player.y, tx, ty);
        if (path) {
          this.movePath = path;
          this.isMoving = true;
          this.stepMove();
          this.selectedEnemyPos = null;
          this.updateEnemyPanel(null);
        }
      }

      findPath(sx, sy, tx, ty) {
        if (sx === tx && sy === ty) return [];
        const q = [[sx, sy]],
          v = Array(9)
            .fill()
            .map(() => Array(9).fill(false)),
          p = Array(9)
            .fill()
            .map(() => Array(9).fill(null));
        v[sy][sx] = true;
        while (q.length) {
          const [cx, cy] = q.shift();
          for (let [dx, dy] of [
            [1, 0],
            [-1, 0],
            [0, 1],
            [0, -1],
          ]) {
            const nx = cx + dx,
              ny = cy + dy;
            if (
              nx < 0 ||
              ny < 0 ||
              nx >= 9 ||
              ny >= 9 ||
              !this.explored[ny][nx]
            )
              continue;
            if (nx === tx && ny === ty) {
              p[ny][nx] = [cx, cy];
              const path = [];
              let cur = [nx, ny];
              while (cur) {
                path.unshift(cur);
                cur = p[cur[1]][cur[0]];
              }
              return path.slice(1);
            }
            if (this.grid[ny][nx] === this.TILE.EMPTY && !v[ny][nx]) {
              v[ny][nx] = true;
              p[ny][nx] = [cx, cy];
              q.push([nx, ny]);
            }
          }
        }
        return null;
      }

      stepMove() {
        if (!this.isMoving || this.movePath.length === 0 || this.gameOver) {
          this.isMoving = false;
          return;
        }
        const [nx, ny] = this.movePath.shift();
        this.grid[this.player.y][this.player.x] = this.TILE.EMPTY;
        this.player.x = nx;
        this.player.y = ny;
        this.grid[ny][nx] = this.TILE.PLAYER;
        this.revealAdjacent(nx, ny);
        this.timer += this.sysbox步时间 || 1;
        this.drawMap();
        this.updateUI();
        if (this.movePath.length === 0) this.isMoving = false;
        else setTimeout(() => this.stepMove(), 80);
      }

      updateUI() {
        // HP/SP/MP 进度条
        var hpMax = this.player.maxHp || 1;
        var spMax = this.player.maxSp || 1;
        var mpMax = this.player.maxMp || 1;
        var hpPct = Math.max(0, Math.min(100, Math.round(this.player.hp / hpMax * 100)));
        var spPct = Math.max(0, Math.min(100, Math.round(this.player.sp / spMax * 100)));
        var mpPct = Math.max(0, Math.min(100, Math.round(this.player.mp / mpMax * 100)));
        var hpBar = this.doc.getElementById(this.ids.hpBarId);
        var spBar = this.doc.getElementById(this.ids.spBarId);
        var mpBar = this.doc.getElementById(this.ids.mpBarId);
        if (hpBar) hpBar.style.width = hpPct + '%';
        if (spBar) spBar.style.width = spPct + '%';
        if (mpBar) mpBar.style.width = mpPct + '%';
        this.doc.getElementById(this.ids.hpId).textContent = this.player.hp + '/' + hpMax;
        this.doc.getElementById(this.ids.spId).textContent = this.player.sp + '/' + spMax;
        this.doc.getElementById(this.ids.mpId).textContent = this.player.mp + '/' + mpMax;
        // 楼层和房间
        this.doc.getElementById(this.ids.dungeonFloorId).textContent =
          this.config.floor;
        this.doc.getElementById(this.ids.roomIndexId).textContent =
          this.currentRoomIndex + 1;
        this.doc.getElementById(this.ids.roomTotalId).textContent =
          this.rooms.length;
        // 战利品
        this.doc.getElementById(this.ids.commonId).textContent =
          this.loot.common;
        this.doc.getElementById(this.ids.rareId).textContent = this.loot.rare;
        this.doc.getElementById(this.ids.legendaryId).textContent =
          this.loot.legendary;
        this.doc.getElementById(this.ids.uniqueId).textContent =
          this.loot.unique;
        const expEl = this.doc.getElementById(this.ids.expValId);
        if (expEl) expEl.textContent = this.totalExp;
        const featsEl = this.doc.getElementById(this.ids.featsValId);
        if (featsEl) featsEl.textContent = this.totalFeats;
        // 计时器
        var timerEl = this.doc.getElementById(this.ids.timerId);
        if (timerEl) {
          var mins = Math.floor(this.timer);
          timerEl.textContent = '⏳ ' + String(Math.floor(mins / 60)).padStart(2, '0') + ':' + String(mins % 60).padStart(2, '0');
        }
        this.renderPartyStatus();
        this.renderActiveSkills();
      }

      renderPartyStatus() {
        var listEl = this.doc.getElementById("topPartyList");
        if (!listEl) return;
        var html = '';
        // 队友
        if (this.allies) {
          this.allies.forEach(function(a) {
            var aHpMax = a.maxHp || 1, aSpMax = a.maxSp || 1, aMpMax = a.maxMp || 1;
            html += '<div class="ally-card">';
            html += '<div class="ally-card-name">' + a.name + '</div>';
            html += '<div class="ally-card-bars">';
            html += this._makeMiniBar('❤️', 'hp', a.hp || 0, aHpMax);
            html += this._makeMiniBar('⚡', 'sp', a.sp || 0, aSpMax);
            html += this._makeMiniBar('✨', 'mp', a.mp || 0, aMpMax);
            html += '</div></div>';
          }.bind(this));
        }
        if (!this.allies || !this.allies.length) {
          html += '<div style="font-size:0.7em;color:#504030;">无队友同行</div>';
        }
        listEl.innerHTML = html;
      }

      _makeMiniBar(label, cls, cur, max) {
        var pct = max > 0 ? Math.round(cur / max * 100) : 0;
        return '<div class="mini-resource-bar">' +
          '<span class="label">' + label + '</span>' +
          '<span class="outer"><span class="fill ' + cls + '" style="width:' + pct + '%;"></span></span>' +
          '<span class="val">' + cur + '/' + max + '</span>' +
          '</div>';
      }

      // 构建默认技能权重配置（攻击方式权重5，其他默认）
      _buildDefaultSkillConfig() {
        var config = {};
        var plName = this.player.name || "主角";
        var plCfg = { damageWeights: { "基本攻击": 5 }, activeWeights: {}, healThreshold: null };
        (this.attackMethods || []).forEach(function(m) { plCfg.damageWeights[m.name] = 1; });
        (this.buffSkills || []).forEach(function(bs) {
          var raw = bs.rawSkill || {};
          var hasHeal = (raw.回复HP比例 || 0) > 0 || (raw.回复SP比例 || 0) > 0 || (raw.回复MP比例 || 0) > 0;
          var hasDmg = (raw.伤害比例 || 0) > 0;
          if (!hasDmg && hasHeal) {
            if (plCfg.healThreshold == null) plCfg.healThreshold = 80;
          } else {
            plCfg.activeWeights[bs.name] = 1;
          }
        });
        plCfg.position = null;
        config[plName] = plCfg;
        if (this.allies) {
          this.allies.forEach(function(a) { config[a.name] = { damageWeights: { "基本攻击": 5 }, activeWeights: {}, healThreshold: null, position: null }; });
        }
        return config;
      }

      updateSkillUI() {
        var self = this;
        this.showCombatSetupModal().then(function(config) {
          if (config) {
            self.combatSkillConfig = config;
            self.addLog("⚙ 战术配置已更新");
            self.renderActiveSkills();
          }
        });
      }

      // 渲染右侧被动技能栏（只显示 技能类型 === '被动' 的技能）
