        var listEl = this.doc.getElementById(this.ids.passiveListId);
        if (!listEl) return;

        var passiveSkills = (this.skills || []).filter(function (s) {
          return s.skillType === "被动";
        });
        if (passiveSkills.length === 0) {
          listEl.innerHTML =
            '<div style="color:#555;padding:4px 0;font-size:11px;">无被动技能</div>';
          return;
        }
        var html = passiveSkills
          .map(function (s) {
            var bonuses = s.bonuses || {};
            var bonusHtml = "";
            STAT_KEYS.forEach(function (bk) {
              var val = bonuses[bk];
              if (val && val !== 0) {
                var sign = val > 0 ? "+" : "";
                var rawPct = val * 100;
                var pctStr = Math.round(rawPct * 10) / 10;
                bonusHtml +=
                  '<span style="color:' +
                  (val > 0 ? "#50c878" : "#e05050") +
                  ';font-size:10px;margin-right:3px;">' +
                  (STAT_LABELS[bk] || bk) +
                  sign +
                  pctStr +
                  "%</span>";
              }
            });

            return (
              '<div style="padding:2px 0;border-bottom:1px dashed rgba(255,255,255,0.05);">' +
              '<div style="font-size:12px;color:#fff;font-weight:bold;">' +
              s.name +
              "</div>" +
              '<div style="font-size:10px;color:#aac9e0;margin-top:1px;">' +
              bonusHtml +
              "</div>" +
              "</div>"
            );
          })
          .join("");
        listEl.innerHTML = html;
      }

      // 渲染右侧"已启动"面板：显示当前攻击方式 + 已启动加成技能
      renderActiveSkills() {
        var listEl = this.doc.getElementById(this.ids.activeSkillsId);
        if (!listEl) return;
        var cfg = this.combatSkillConfig;
        if (!cfg) {
          listEl.innerHTML = '<div style="color:#555;padding:4px 0;font-size:11px;">未配置（使用默认权重）</div>';
          return;
        }
        var html = "";
        var plName = this.player.name || "主角";
        var plCfg = cfg[plName];
        if (plCfg) {
          html += '<div style="font-size:11px;color:#ffe066;font-weight:bold;margin-bottom:4px;">' + plName + '</div>';
          // 伤害技能权重
          var dw = plCfg.damageWeights || {};
          var dmgKeys = Object.keys(dw).filter(function(k) { return dw[k] > 0; });
