            });
          }
          // 主动技能权重
          var aw = plCfg.activeWeights || {};
          var actKeys = Object.keys(aw).filter(function(k) { return aw[k] > 0; });
          if (actKeys.length > 0) {
            html += '<div style="font-size:10px;color:#7b68ee;margin-bottom:2px;margin-top:4px;">✨ 主动技能（权重）</div>';
            actKeys.forEach(function(k) {
              html += '<div style="font-size:10px;color:#c0b090;padding:1px 0 1px 8px;">' + k + ' <span style="color:#ffe066;">×' + aw[k] + '</span></div>';
            });
          }
          // 恢复阈值
          if (plCfg.healThreshold != null) {
            html += '<div style="font-size:10px;color:#50c878;margin-top:4px;">💚 恢复阈值：<span style="color:#ffe066;">' + plCfg.healThreshold + '%</span></div>';
          }
          // 战术位置
          if (plCfg.position) {
            var posIcons2 = { '前卫': '🛡', '中卫': '⚔', '后卫': '🏹', '策应': '🌀' };
            html += '<div style="font-size:10px;color:#b89b6b;margin-top:2px;">📍 战术：' + (posIcons2[plCfg.position] || '') + ' ' + plCfg.position + '</div>';
