      addLog(msg, type) {
        type = type || "system";
        var mins = this.timer || 0;
        var ts = String(Math.floor(mins / 60)).padStart(2, "0") + ":" + String(mins % 60).padStart(2, "0");
        var div = document.createElement("div");
        div.className = "log-entry " + type;
        div.innerHTML = '<span class="log-timestamp">[' + ts + ']</span> ' + msg;
        var box = this.doc.getElementById(this.ids.logBoxId);
        if (box) { box.appendChild(div); box.scrollTop = box.scrollHeight; }
      }

      playSound(type) {
        try {
          if (!_audioCtx)
            _audioCtx = new (
              window.AudioContext || window.webkitAudioContext
            )();
          if (_audioCtx.state === "closed")
            _audioCtx = new (
              window.AudioContext || window.webkitAudioContext
            )();
          const ctx = _audioCtx;
          const o = ctx.createOscillator(),
            g = ctx.createGain();
          o.connect(g);
          g.connect(ctx.destination);
          o.type = "sine";
          if (type === "hit") {
            // --- 噪声层：刀刃破风声 ---
            const noiseLen = Math.floor(ctx.sampleRate * 0.07);
            const noiseBuf = ctx.createBuffer(1, noiseLen, ctx.sampleRate);
            const nd = noiseBuf.getChannelData(0);
            for (let i = 0; i < noiseLen; i++) {
              nd[i] = (Math.random() * 2 - 1) * Math.exp(-i / noiseLen * 6);
            }
            const noiseSrc = ctx.createBufferSource();
            noiseSrc.buffer = noiseBuf;
            const bp = ctx.createBiquadFilter();
            bp.type = "bandpass";
            bp.frequency.value = 1800;
            bp.Q.value = 0.8;
            const gn = ctx.createGain();
            gn.gain.setValueAtTime(0.1, ctx.currentTime);
            gn.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.07);
            noiseSrc.connect(bp); bp.connect(gn); gn.connect(ctx.destination);
            noiseSrc.start(); noiseSrc.stop(ctx.currentTime + 0.07);
            // --- 低频冲击：斩击沉重感 ---
            o.type = "triangle";
            o.frequency.setValueAtTime(400, ctx.currentTime);
            o.frequency.exponentialRampToValueAtTime(50, ctx.currentTime + 0.08);
            g.gain.setValueAtTime(0.2, ctx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.12);
            o.start();
            o.stop(ctx.currentTime + 0.12);
          } else if (type === "crit") {
            // --- 噪声层：更锐利 ---
            const noiseLen = Math.floor(ctx.sampleRate * 0.08);
            const noiseBuf = ctx.createBuffer(1, noiseLen, ctx.sampleRate);
            const nd = noiseBuf.getChannelData(0);
            for (let i = 0; i < noiseLen; i++) {
              nd[i] = (Math.random() * 2 - 1) * Math.exp(-i / noiseLen * 5);
            }
            const noiseSrc = ctx.createBufferSource();
            noiseSrc.buffer = noiseBuf;
            const bp = ctx.createBiquadFilter();
            bp.type = "highpass";
            bp.frequency.value = 2500;
            const gn = ctx.createGain();
            gn.gain.setValueAtTime(0.15, ctx.currentTime);
            gn.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
            noiseSrc.connect(bp); bp.connect(gn); gn.connect(ctx.destination);
            noiseSrc.start(); noiseSrc.stop(ctx.currentTime + 0.08);
            // --- 高频冲击 ---
            o.type = "sawtooth";
            o.frequency.setValueAtTime(600, ctx.currentTime);
            o.frequency.exponentialRampToValueAtTime(80, ctx.currentTime + 0.1);
            g.gain.setValueAtTime(0.18, ctx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.14);
            o.start();
            o.stop(ctx.currentTime + 0.14);
            // --- 二次低音余震 ---
            const o2 = ctx.createOscillator();
            const g2 = ctx.createGain();
            o2.type = "sine";
            o2.frequency.value = 55;
            g2.gain.setValueAtTime(0.13, ctx.currentTime + 0.04);
            g2.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.2);
            o2.connect(g2); g2.connect(ctx.destination);
            o2.start(ctx.currentTime + 0.04);
            o2.stop(ctx.currentTime + 0.2);
          } else if (type === "select") {
            o.frequency.value = 600;
            g.gain.setValueAtTime(0.08, ctx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.05);
            o.start();
            o.stop(ctx.currentTime + 0.05);
          }
          ctx.resume();
        } catch (e) { }
      }

      abort() {
        if (!this.gameOver) {
          this.gameOver = true;
          this.addLog("🏁 中止冒险");
          this.updateUI();
        }
        this.writeBackAllStatus();
        this.generateReportAndSend().then((sent) => {
          if (sent) this.destroy();
        });
      }

      writeBackAllStatus() {
        var allVars = getFullVariables();
        if (!allVars) return;
        var sd = _.get(allVars, "stat_data", {});
        var plName = this.player.name || "主角";
        // 写回主角状态
        _.set(sd, "主角.状态.HP当前值", this.player.hp);
        _.set(sd, "主角.状态.SP当前值", this.player.sp);
        _.set(sd, "主角.状态.MP当前值", this.player.mp);
        // 写回队友状态
        var partyMap = _.get(sd, "组队成员", {});
        var npcList = _.get(sd, "人物名录", {});
        if (this.allies) {
          this.allies.forEach(function(a) {
            var npc = npcList[a.name];
            if (npc) {
              _.set(npc, "状态.HP当前值", a.hp);
              _.set(npc, "状态.SP当前值", a.sp);
              _.set(npc, "状态.MP当前值", a.mp);
            }
          });
        }
        _.set(allVars, "stat_data", sd);
        saveVariablesToMvu(allVars);
      }

      async generateReportAndSend() {
        // ★ 每个击败的敌人单独写入敌人信息（Zod transform 检测到全击败后自动结算）
        if (this.defeatedMonsters.length > 0) {
          var allVars = getFullVariables();
          if (allVars) {
            var enemyList = _.get(allVars, "stat_data.敌人信息") || [];
            this.defeatedMonsters.forEach((m) => {
              enemyList.push({
                基础信息: { 姓名: m.name, 稀有度: m.rarity },
                是否击败: true,
                结算经验: m.exp,
                结算伟业: m.feat,
              });
            });
            _.set(allVars, "stat_data.敌人信息", enemyList);

            // 写入累积经验权重（必须在 saveVariablesToMvu 之前，确保 handle结算 可读取）
            var U3 = window.top.DungeonUtils;
            if (U3 && this.weightDeltas && Object.keys(this.weightDeltas).length > 0) {
              var self = this;
              // 主角
              var plWDelta = this.weightDeltas[this.player.name || '主角'];
              if (plWDelta) {
                var plExistW = _.get(allVars, "stat_data.主角.个人属性.经验权重") || { 力量:1, 耐力:1, 灵巧:1, 敏捷:1, 魔力:1 };
                var plW = {};
                ["力量","耐力","灵巧","敏捷","魔力"].forEach(function(k) {
                  plW[k] = Math.max(1, (plExistW[k] || 1) + (plWDelta[k] || 0));
                });
                _.set(allVars, "stat_data.主角.个人属性.经验权重", plW);
              }
              // 队友（含冒险者和怪物）
              if (this.allies) {
                this.allies.forEach(function(a) {
                  var aDelta = self.weightDeltas[a.name];
                  if (!aDelta) return;
                  var existW = _.get(allVars, "stat_data.人物名录." + a.name + ".个人属性.经验权重") || { 力量:1, 耐力:1, 灵巧:1, 敏捷:1, 魔力:1 };
                  var aW = {};
                  ["力量","耐力","灵巧","敏捷","魔力"].forEach(function(k) {
                    aW[k] = Math.max(1, (existW[k] || 1) + (aDelta[k] || 0));
                  });
                  _.set(allVars, "stat_data.人物名录." + a.name + ".个人属性.经验权重", aW);
                });
              }
            }

            saveVariablesToMvu(allVars);
          }
        }

        var mons = this.defeatedMonsters.length
          ? this.defeatedMonsters
              .map(function(m) { return m.name + " Lv." + m.lv + " (" + (m.rarity || "普通") + ")"; })
              .join("、")
          : "无";
        var parts = [];
        if (this.loot.common) parts.push("有瑕x" + this.loot.common);
        if (this.loot.rare) parts.push("良好x" + this.loot.rare);
        if (this.loot.legendary) parts.push("上等x" + this.loot.legendary);
        if (this.loot.unique) parts.push("异化x" + this.loot.unique);
        var lootText = parts.length ? parts.join("、") : "无";
        // 计时器转分钟
        var elapsedMins = this.timer || 0;
        var timeStr = elapsedMins > 60
          ? Math.floor(elapsedMins / 60) + "小时" + (elapsedMins % 60) + "分钟"
          : elapsedMins + "分钟";
        // 全队状态
        var plName = this.player.name || "主角";
        var partyStatus = plName + " HP:" + this.player.hp + "/" + this.player.maxHp + " SP:" + this.player.sp + "/" + this.player.maxSp + " MP:" + this.player.mp + "/" + this.player.maxMp;
        if (this.allies) {
          this.allies.forEach(function(a) {
            partyStatus += "；" + a.name + " HP:" + a.hp + "/" + a.maxHp + " SP:" + a.sp + "/" + a.maxSp + " MP:" + a.mp + "/" + a.maxMp;
          });
        }
        var statusLabel = this.player.hp <= 0 ? "重伤撤离" : partyStatus;
        var report =
          "【系统结算】\n" +
          "以下敌人已被击败并完成结算，请不要再将其写入敌人信息数组或进行任何修改！\n" +
          "冒险时长：约" + timeStr + "\n" +
          "击败敌人：" + mons + "\n" +
          "获得战利品：" + lootText + "\n" +
          "全队最终状态：" + statusLabel + "\n" +
          "请根据战报输出<victory_panel>，合理安排本次经过的时间（约" + timeStr + "）并在剧情中处理战利品获取（数量需完全一致），绝对不要修改敌人信息。呆在原地不允许离开。\n";

        // 战报预览弹窗
        var self = this;
        var C = window.top.CommandUtils || window.CommandUtils;
        var confirmed = false;
        if (C && C._showReportPreview) {
          confirmed = await C._showReportPreview("探索战报", report);
        } else {
          // 兜底：无预览函数时直接发送
          confirmed = true;
        }
        if (!confirmed) {
          this.addLog("📋 战报已取消（状态已保存）");
          return true;
        }

        try {
          const ta =
            window.top?.document?.querySelector("#send_textarea") ||
            document.querySelector("#send_textarea");
          const btn =
            window.top?.document?.querySelector("#send_but") ||
            document.querySelector("#send_but");
          if (ta && btn) {
            ta.value = report;
            ta.dispatchEvent(new Event("input", { bubbles: true }));
            btn.click();
            this.addLog("📤 战报已发送");
          } else {
            navigator.clipboard
              ?.writeText(report)
              .then(() => this.addLog("📋 战报已复制到剪贴板"));
          }
        } catch (e) {
          navigator.clipboard
            ?.writeText(report)
            .then(() => this.addLog("📋 战报已复制到剪贴板"));
        }
        return true;
      }
    }

    async function init() {
      await waitGlobalInitialized("Mvu");

      // 轮询等待直到能获取到当前楼层 ID 且 stat_data 存在
      while (true) {
        try {
          const id = getCurrentMessageId();
          if (id != null) {
            const vars = Mvu.getMvuData({ type: 'message', message_id: id });
            if (vars && _.has(vars, 'stat_data') && _.size(_.get(vars, 'stat_data')) > 0) break;
          }
        } catch (e) { /* 忽略，继续等待 */ }
        await new Promise(r => setTimeout(r, 200));
      }


      loadAvatar();
      populateCharacterData();

      eventOn(
        Mvu.events.VARIABLE_UPDATE_ENDED,
        function (new_vars, old_vars) {
          if (!old_vars || !new_vars) return;

          // 直接在 new_vars 上修改（MVU 框架会在事件完成后自动保存到正确楼层）
          scheduleRender();

          // 等级提升自动补满
          var oldPl = _.get(old_vars, "stat_data.主角", {});
          var newPl = _.get(new_vars, "stat_data.主角", {});
          var oldLevel = oldPl.个人属性?.等级 || 0;
          var newLevel = newPl.个人属性?.等级 || 0;

          if (newLevel > oldLevel) {
            var status = newPl.状态;
            status.HP当前值 = status.HP上限 ?? status.HP当前值;
            status.SP当前值 = status.SP上限 ?? status.SP当前值;
            status.MP当前值 = status.MP上限 ?? status.MP当前值;
            status.休息 = 0;
            _.set(new_vars, "stat_data.主角.状态", status);
          }

        },
      );

      $(".nav-btn").on("click", function () {
        var target = $(this).data("target");
        $(".nav-btn").removeClass("active");
        $(this).addClass("active");
        $(".tab-pane").removeClass("active");
        $("#tab-" + target).addClass("active");
      });

      $(document).on("click", ".item-toggle", function (e) {
        e.stopPropagation();
        $(this).find(".item-details, .tech-body").toggleClass("show");
      });

      $(document).on("click", ".item-toggle-npc", function (e) {
        e.stopPropagation();
        if (npcDeleteMode) {
          var name = $(this).data("npc-name");
          if (name) toggleNpcSelection(name);
          return;
        }
        $(this).toggleClass("expanded");
        $(this).find(".npc-details").toggleClass("show");
      });

      // 战斗记录卡片点击（删除模式）和展开
      $(document).on("click", ".item-toggle-record", function (e) {
        e.stopPropagation();
        if (recordsDeleteMode) {
          var idx = parseInt($(this).data("record-index"));
          if (!isNaN(idx)) toggleRecordsSelection(idx);
          return;
        }
      });

      // ===== 审查分页按钮事件委托 =====
      $(document).on("click", "[data-review-delete]", function (e) {
        e.stopPropagation();
        var idx = parseInt($(this).data("review-delete"));
        if (!isNaN(idx)) deleteReviewCommand(idx);
      });
      $(document).on("click", "[data-review-execute]", function (e) {
        e.stopPropagation();
        executeReviewedCommands();
      });
      $(document).on("click", "[data-review-clear]", function (e) {
        e.stopPropagation();
        clearAllReviewCommands();
      });

      // NPC 删除模式按钮事件
      $(document).on("click", "#npc-delete-toggle", function (e) {
        e.stopPropagation();
        enterNpcDeleteMode();
      });
      $(document).on("click", "#npc-delete-confirm", function (e) {
        e.stopPropagation();
        executeNpcDelete();
      });
      $(document).on("click", "#npc-delete-cancel", function (e) {
        e.stopPropagation();
        exitNpcDeleteMode();
      });

      // 战斗记录删除模式按钮事件
      $(document).on("click", "#records-delete-toggle", function (e) {
        e.stopPropagation();
        enterRecordsDeleteMode();
      });
      $(document).on("click", "#records-delete-confirm", function (e) {
        e.stopPropagation();
        executeRecordsDelete();
      });
      $(document).on("click", "#records-delete-cancel", function (e) {
        e.stopPropagation();
        exitRecordsDeleteMode();
      });

      DOM.invPrev.on("click", function () {
        if (invPage > 0) {
          invPage--;
          renderInventory();
        }
      });
      DOM.invNext.on("click", function () {
        invPage++;
        renderInventory();
      });

      DOM.npcPrev.on("click", function () {
        if (npcPage > 0) {
          npcPage--;
          renderNpcs();
        }
      });
      DOM.npcNext.on("click", function () {
        npcPage++;
        renderNpcs();
      });

      DOM.recordsPrev.on("click", function () {
        if (recordsPage > 0) {
          recordsPage--;
          renderRecords();
        }
      });
      DOM.recordsNext.on("click", function () {
        recordsPage++;
        renderRecords();
      });

      // ===== 继续战斗按钮 =====
      DOM.btnContinueBattle.on("click", async function () {
        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var U = window.top.DungeonUtils;
        if (!U) { alert("工具未加载，请刷新页面。"); return; }
        var ok = await U.fightBattle({ sd: sd, all: all, messageId: getCurrentMessageId(), maxRounds: 3, reportTitle: "继续战斗战报" });
        if (ok) scheduleRender();
      });

      // ===== 快速探索按钮 =====
      DOM.startExploreBtn.on("click", function () {
        startTopGame();
      });

      // ===== 清除地下城区域按钮 =====
      $(document).on("click", "#clear-dungeon-btn", async function () {
        if (!confirm("确定清除当前地下城区域？层数将重置为0。")) return;
        var all = getFullVariables();
        _.set(all, "stat_data.当前地下城区域", { 层数: 0 });
        await saveVariablesToMvu(all);
        scheduleRender();
      });

      // ===== 死斗按钮 =====
      DOM.btnDeathMatch.on("click", async function () {
        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var U = window.top.DungeonUtils;
        if (!U) { alert("工具未加载，请刷新页面。"); return; }
        var ok = await U.fightBattle({ sd: sd, all: all, messageId: getCurrentMessageId(), maxRounds: null, showRoundInput: false, title: "☠️ 死斗准备", confirmText: "确认死斗", reportTitle: "死斗战报" });
        if (ok) scheduleRender();
      });

      DOM.avatarBox.on("click", function () {
        DOM.avatarUpload.trigger("click");
      });
      DOM.avatarUpload.on("change", function (e) {
        var file = e.target.files[0];
        if (!file) return;
        var reader = new FileReader();
        reader.onload = function (ev) {
          try {
            if (typeof localStorage !== "undefined" && localStorage) {
              localStorage.setItem("danmachi_avatar", ev.target.result);
            }
          } catch (e) { }
          loadAvatar();
        };
        reader.readAsDataURL(file);
        // 重置input，允许再次选择相同文件
        this.value = "";
      });

      // ===== 刷新按钮 =====
      $(document).on("click", "#btn-refresh", function () {
populateCharacterData();
        // 默认选中：有待审指令→审查，有敌人→战斗记录，否则→个人属性
        var _allR = getFullVariables();
        var _sdR = _.get(_allR, "stat_data", {});
        var _pCmds = _sdR.操作指令 || [];
        var _eInf = _sdR.敌人信息 || [];
        $(".nav-btn").removeClass("active");
        $(".tab-pane").removeClass("active");
        if (_pCmds.length > 0) {
          $('.nav-btn[data-target="review"]').addClass("active");
          $("#tab-review").addClass("active");
        } else if (_eInf.length > 0) {
          $('.nav-btn[data-target="records"]').addClass("active");
          $("#tab-records").addClass("active");
        } else {
          $('.nav-btn[data-target="profile"]').addClass("active");
          $("#tab-profile").addClass("active");
        }
        // 重新检查敌人信息决定战报标签页显隐
        var _all5 = getFullVariables();
        var _sd5 = _.get(_all5, "stat_data", {});
        var _enemyInfo2 = _sd5.敌人信息 || [];
        var _recordsNavBtn2 = document.querySelector('.nav-btn[data-target="records"]');
        var _recordsTabPane2 = document.getElementById("tab-records");
        if (_enemyInfo2.length === 0) {
          if (_recordsNavBtn2) _recordsNavBtn2.style.display = "none";
          if (_recordsTabPane2) _recordsTabPane2.style.display = "none";
        } else {
          if (_recordsNavBtn2) _recordsNavBtn2.style.display = "";
          if (_recordsTabPane2) _recordsTabPane2.style.display = "";
        }
      });

      // ===== 根据敌人信息和审查指令控制 tab 的显示/隐藏与默认选中 =====
      var all4 = getFullVariables();
      var sd4 = _.get(all4, "stat_data", {});
      var enemyInfo = sd4.敌人信息 || [];
      var pendingCmds = sd4.操作指令 || [];
      var recordsNavBtn = document.querySelector('.nav-btn[data-target="records"]');
      var recordsTabPane = document.getElementById("tab-records");

      // 战斗记录：有敌人时显示
      if (enemyInfo.length === 0) {
        if (recordsNavBtn) recordsNavBtn.style.display = "none";
        if (recordsTabPane) recordsTabPane.style.display = "none";
      } else {
        if (recordsNavBtn) recordsNavBtn.style.display = "";
        if (recordsTabPane) recordsTabPane.style.display = "";
      }

      // 默认选中逻辑
      if (pendingCmds.length > 0) {
        // 有待审指令 → 选中审查分页
        $(".nav-btn").removeClass("active");
        $('.nav-btn[data-target="review"]').addClass("active");
        $(".tab-pane").removeClass("active");
        $("#tab-review").addClass("active");
      } else if (enemyInfo.length > 0) {
        // 有敌人 → 选中战斗记录分页
        $(".nav-btn").removeClass("active");
        $('.nav-btn[data-target="records"]').addClass("active");
        $(".tab-pane").removeClass("active");
        $("#tab-records").addClass("active");
      }
// ===== 装备栏交互事件绑定 =====

      // 卸下装备：点击 ✕ 按钮（常规装备 + 特殊装备）
      $(document).on(
        "click",
        "#storage-equip-slots .slot-unequip-btn, #storage-equip-special .slot-unequip-btn",
        function (e) {
          e.stopPropagation();
          var card = $(this).closest(".equip-slot-card");
          var slot = card.data("slot");
          var specialIndex = card.data("special-index");
          var success = unequipItem(
            slot,
            specialIndex != null ? parseInt(specialIndex) : -1,
          );
          if (success) {
            // 刷新显示
            renderStorageEquipBar();
            // 也刷新背包显示
            var all = getFullVariables();
            var sd = _.get(all, "stat_data", {});
            var rawInv = Object.entries(_.get(sd, "主角.持有物品", {}));
            invData = rawInv;
            invPage = 0;
            renderInventory();
            // 刷新个人属性页装备栏
            populateCharacterData();
          } else {
            console.warn("卸下装备失败");
          }
        },
      );

      // 切换分页时，如果切换到背包页签，渲染装备栏
      $(document).on("click", '.nav-btn[data-target="storage"]', function () {
        // 延迟一点点，等 tab 切换完成
        setTimeout(function () {
          renderStorageEquipBar();
        }, 50);
      });

      // 背包物品 — 点击使用按钮使用消耗品
      $(document).on("click", ".item-use-btn", function (e) {
        e.stopPropagation();
        var btn = $(this);
        var itemName = btn.data("item-name");
        if (!itemName) return;

        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var inv = _.get(sd, "主角.持有物品", {});
        var itemData = inv[itemName];
        if (!itemData) return;
        if (!isItemConsumable(itemData)) return;

        var success = useConsumableItem(itemName, itemData);
        if (success) {
          invData = Object.entries(inv);
          invPage = 0;
          renderInventory();
          populateCharacterData();
        } else {
          console.warn("使用消耗品失败");
        }
      });

      // 背包物品 — 点击装备按钮才执行装备
      $(document).on("click", ".item-equip-btn", function (e) {
        e.stopPropagation();
        var btn = $(this);
        var itemName = btn.data("item-name");
        if (!itemName) return;

        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var inv = _.get(sd, "主角.持有物品", {});
        var itemData = inv[itemName];
        if (!itemData) return;
        if (!isItemEquippable(itemData)) return;

        var success = equipItem(itemName, itemData);
        if (success) {
          renderStorageEquipBar();
          invData = Object.entries(inv);
          invPage = 0;
          renderInventory();
          populateCharacterData();
        } else {
          console.warn("装备失败");
        }
      });

      // 背包物品 — 删除物品
      $(document).on("click", ".item-delete-btn", function (e) {
        e.stopPropagation();
        e.preventDefault();
        var btn = $(this);
        var itemName = btn.data("item-name");
        if (!itemName) return;
        if (!confirm('确认删除物品 "' + itemName + '"？此操作不可撤销。')) return;

        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var inv = _.get(sd, "主角.持有物品", {});
        if (inv[itemName]) {
          delete inv[itemName];
          saveVariablesToMvu(all);
          invData = Object.entries(inv);
          invPage = 0;
          renderInventory();
          populateCharacterData();
        }
      });

      // ===== 物品转移 =====
      // 主角物品栏 — 打开转移弹窗
      $(document).on("click", ".item-transfer-btn", function (e) {
        e.stopPropagation();
        e.preventDefault();
        var itemName = $(this).data("item-name");
        if (!itemName) return;
        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var inv = _.get(sd, "主角.持有物品", {});
        var itemData = inv[itemName];
        if (!itemData || itemData.数量 <= 0) return;
        openItemTransferDialog("主角", itemName, itemData);
      });

      // 队友管理弹窗 — 打开转移弹窗
      $(document).on("click", ".party-manage-item-transfer-btn", function (e) {
        e.stopPropagation();
        e.preventDefault();
        var itemName = $(this).data("item-name");
        if (!itemName || !partyManageCharName) return;
        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var npc = _.get(sd, "人物名录." + partyManageCharName);
        if (!npc) return;
        var inv = npc.持有物品 || {};
        var itemData = inv[itemName];
        if (!itemData || itemData.数量 <= 0) return;
        openItemTransferDialog(partyManageCharName, itemName, itemData);
      });

      // 转移弹窗 — 关闭
      $(document).on("click", "#item-transfer-close", function () {
        $("#item-transfer-modal").hide();
        transferSourceChar = null;
        transferItemName = null;
      });

      // 转移弹窗 — 确认转移
      $(document).on("click", "#item-transfer-confirm", function () {
        executeItemTransfer();
      });

      // 组队成员 — 移出队伍
      $(document).on("click", ".party-remove-btn", function (e) {
        e.stopPropagation();
        e.preventDefault();
        var btn = $(this);
        var partyName = btn.data("party-name");
        if (!partyName) return;
        if (!confirm('确认将 "' + partyName + '" 移出队伍？此操作不会删除角色数据。')) return;

        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        _.unset(sd, "组队成员." + partyName);
        saveVariablesToMvu(all);

        all = getFullVariables();
        sd = _.get(all, "stat_data", {});
        renderParty(sd);
      });

      // 组队成员 — 打开管理弹窗
      $(document).on("click", ".party-manage-btn", function (e) {
        e.stopPropagation();
        e.preventDefault();
        var btn = $(this);
        var partyName = btn.data("party-name");
        if (!partyName) return;
        openPartyManageModal(partyName);
      });

      // 队友管理弹窗 — 关闭
      $(document).on("click", "#party-manage-close", function () {
        $("#party-manage-modal").hide();
      });

      // 队友管理弹窗 — 卸装
      $(document).on("click", ".party-manage-unequip-btn", function (e) {
        e.stopPropagation();
        var btn = $(this);
        var slotKey = btn.data("slot");
        var specialIndex = btn.data("special-index");
        if (slotKey === "特殊") {
          if (specialIndex == null) return;
          unequipItemForChar(partyManageCharName, slotKey, parseInt(specialIndex));
        } else {
          unequipItemForChar(partyManageCharName, slotKey, -1);
        }
        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var npc = _.get(sd, "人物名录." + partyManageCharName);
        if (npc) {
          renderPartyManageEquipBar(npc);
          partyManageInvData = Object.entries(_.get(npc, "持有物品", {}));
          renderPartyManageInventory();
        }
      });

      // 队友管理弹窗 — 使用消耗品
      $(document).on("click", ".party-manage-item-use-btn", function (e) {
        e.stopPropagation();
        e.preventDefault();
        var itemName = $(this).data("item-name");
        if (!itemName || !partyManageCharName) return;
        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var npc = _.get(sd, "人物名录." + partyManageCharName);
        if (!npc) return;
        var inv = npc.持有物品 || {};
        var itemData = inv[itemName];
        if (!itemData) return;
        if (useConsumableItem(itemName, itemData, partyManageCharName)) {
          all = getFullVariables();
          sd = _.get(all, "stat_data", {});
          npc = _.get(sd, "人物名录." + partyManageCharName);
          if (npc) {
            renderPartyManageEquipBar(npc);
            partyManageInvData = Object.entries(_.get(npc, "持有物品", {}));
            renderPartyManageInventory();
          }
        }
      });

      // 队友管理弹窗 — 装备物品
      $(document).on("click", ".party-manage-item-equip-btn", function (e) {
        e.stopPropagation();
        e.preventDefault();
        var itemName = $(this).data("item-name");
        if (!itemName || !partyManageCharName) return;
        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var npc = _.get(sd, "人物名录." + partyManageCharName);
        if (!npc) return;
        var inv = npc.持有物品 || {};
        var itemData = inv[itemName];
        if (!itemData) return;
        if (equipItemForChar(partyManageCharName, itemName, itemData)) {
          all = getFullVariables();
          sd = _.get(all, "stat_data", {});
          npc = _.get(sd, "人物名录." + partyManageCharName);
          if (npc) {
            renderPartyManageEquipBar(npc);
            partyManageInvData = Object.entries(_.get(npc, "持有物品", {}));
            renderPartyManageInventory();
          }
        }
      });

      // 队友管理弹窗 — 删除物品
      $(document).on("click", ".party-manage-item-delete-btn", function (e) {
        e.stopPropagation();
        e.preventDefault();
        var itemName = $(this).data("item-name");
        if (!itemName || !partyManageCharName) return;
        if (!confirm('确认删除物品 "' + itemName + '"？')) return;
        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        var npc = _.get(sd, "人物名录." + partyManageCharName);
        if (!npc || !npc.持有物品) return;
        delete npc.持有物品[itemName];
        saveVariablesToMvu(all);
        all = getFullVariables();
        sd = _.get(all, "stat_data", {});
        npc = _.get(sd, "人物名录." + partyManageCharName);
        if (npc) {
          renderPartyManageEquipBar(npc);
          partyManageInvData = Object.entries(_.get(npc, "持有物品", {}));
          partyManageInvPage = 0;
          renderPartyManageInventory();
        }
      });

      // 队友管理弹窗 — 保存并关闭
      $(document).on("click", "#party-manage-save", function () {
        $("#party-manage-modal").hide();
        var all = getFullVariables();
        var sd = _.get(all, "stat_data", {});
        renderParty(sd);
      });

      // 队友管理弹窗 — 物品分页
      $(document).on("click", "#party-manage-inv-prev", function () {
        if (partyManageInvPage > 0) { partyManageInvPage--; renderPartyManageInventory(); }
      });
      $(document).on("click", "#party-manage-inv-next", function () {
        var total = Math.ceil(partyManageInvData.length / PARTY_MANAGE_INV_PER_PAGE);
        if (partyManageInvPage < total - 1) { partyManageInvPage++; renderPartyManageInventory(); }
      });
    }

    $(errorCatched(init));
  </script>
</head>

