            };

            var html =
                '<div style="display:flex;align-items:center;margin-bottom:12px;">' +
                '<span style="color:#d4b8e0;font-size:1.3em;letter-spacing:3px;margin-right:12px;">✧ ' + charName + ' 恩惠更新 ✧</span>' +
