// danmachi_utils.js - 地错工具函数，挂载 window.top.DungeonUtils
(() => {
  const utils = {};

  // 数值 → 等级字母
  utils.getGrade = (value) => {
    if (value >= 1200) return "SSS";
    if (value >= 1000) return "SS";
    if (value >= 900) return "S";
    if (value >= 800) return "A";
    if (value >= 700) return "B";
    if (value >= 600) return "C";
    if (value >= 500) return "D";
    if (value >= 400) return "E";
    if (value >= 300) return "F";
    if (value >= 200) return "G";
    if (value >= 100) return "H";
    return "I";
  };

  /**
   * 对已排序（从大到小）的能力值数组应用多目标衰减
   * @param {number[]} powers - 从大到小排序的五维和能力数组
   * @returns {number} 衰减后的总和
   */
  /**
   * 确定性期望战斗模拟
   * 用一次确定性模拟替代简单公式，自动体现集火（锁定最低HP目标）、
   * 减员连锁（死一个→剩余人承受全部伤害）、速度排序和完整伤害链。
   * 我方使用裸装总能力，敌方使用总能力。
   *
   * @param {object[]} allAllies - 所有友方
   * @param {object[]} allEnemies - 所有存活敌人
   * @returns {{ turnsToKill: number, turnsToWipe: number, enduranceRatio: number }}
   */
  utils.simulateExpectedBattle = function(allAllies, allEnemies) {
    var units = [];

    // 我方：裸装总能力（不含装备/被动技能）
    for (var i = 0; i < allAllies.length; i++) {
      var ally = allAllies[i];
      var aType = ally.基础信息?.类型 || "主角";
      var aAttr = ally.个人属性?.总能力 || ally.个人属性?.基础能力 || {};
      var aHpSpMp = utils.calcEntityHpSpMp(aAttr, aType);
      units.push({
        name: ally.基础信息?.姓名 || "主角",
        side: "ally",
        stats: {
          力量: aAttr.力量 || 0, 耐力: aAttr.耐力 || 0,
          灵巧: aAttr.灵巧 || 0, 敏捷: aAttr.敏捷 || 0, 魔力: aAttr.魔力 || 0,
        },
        hp: aHpSpMp.hp, hpMax: aHpSpMp.hp,
        agi: aAttr.敏捷 || 0, defeated: false,
      });
    }

    // 敌方：总能力（怪物无装备分离，总能力即全装）
    for (var j = 0; j < allEnemies.length; j++) {
      var e = allEnemies[j];
      var eType = e.基础信息?.类型 || "怪物";
      var eStats = (e.个人属性 || {}).总能力 || {};
      var eHpSpMp = utils.calcEntityHpSpMp(eStats, eType);
      units.push({
        name: e.基础信息?.姓名 || "???",
        side: "enemy",
        stats: {
          力量: eStats.力量 || 0, 耐力: eStats.耐力 || 0,
          灵巧: eStats.灵巧 || 0, 敏捷: eStats.敏捷 || 0, 魔力: eStats.魔力 || 0,
        },
        hp: eHpSpMp.hp, hpMax: eHpSpMp.hp,
        agi: eStats.敏捷 || 0, defeated: false,
      });
    }

    // 按敏捷降序排列行动顺序
    units.sort(function(a, b) { return b.agi - a.agi; });

    var MAX_R = 50;
    var turnsToKill = 0;
    var turnsToWipe = 0;
    var totalAllyDpr = 0, roundsWithAllyDmg = 0;
    var totalEnemyDpr = 0, roundsWithEnemyDmg = 0;

    for (var round = 1; round <= MAX_R; round++) {
      // 存活单位，按敏捷降序
      var alive = units.filter(function(u) { return !u.defeated; });
      alive.sort(function(a, b) { return b.agi - a.agi; });

      var allyDmgRound = 0, enemyDmgRound = 0;

      for (var ai = 0; ai < alive.length; ai++) {
        var attacker = alive[ai];
        if (attacker.defeated) continue;

        // 找对方存活目标，锁定最低HP（模拟集火）
        var otherSide = attacker.side === "ally" ? "enemy" : "ally";
        var targets = alive.filter(function(u) { return u.side === otherSide && !u.defeated; });
        if (targets.length === 0) break;
        targets.sort(function(a, b) { return a.hp - b.hp; });
        var target = targets[0];

        // 完整伤害链（期望值）
        var atkS = attacker.stats, defS = target.stats;
        var atkStat = Math.max(atkS.力量 || 0, atkS.魔力 || 0);
        var defStat = defS.耐力 || 0;
        var mitigation = utils.calcMitigation(atkStat, defStat);
        var mitigatedDmg = Math.max(1, Math.floor(atkStat * (1 - mitigation)));
        var agiBonus = utils.calcAgilitySuppress(atkS.敏捷 || 0, defS.敏捷 || 0);
        var afterAgiDmg = Math.floor(mitigatedDmg * (1 + agiBonus));
        var critRate = utils.calcCritRate(atkS.灵巧 || 0, defS.敏捷 || 0);
        // 期望暴击：暴击率 × 1.5倍 + 非暴击率 × 1倍 = 1 + critRate × 0.5
        var expectedDmg = Math.floor(afterAgiDmg * (1 + critRate * 0.5));

        target.hp = Math.max(0, target.hp - expectedDmg);

        if (attacker.side === "ally") {
          allyDmgRound += expectedDmg;
        } else {
          enemyDmgRound += expectedDmg;
        }

        if (target.hp <= 0) target.defeated = true;
      }

      if (allyDmgRound > 0) { totalAllyDpr += allyDmgRound; roundsWithAllyDmg++; }
      if (enemyDmgRound > 0) { totalEnemyDpr += enemyDmgRound; roundsWithEnemyDmg++; }

      // 判定胜负
      var anyAllyAlive = false, anyEnemyAlive = false;
      for (var ci = 0; ci < units.length; ci++) {
        if (units[ci].defeated) continue;
        if (units[ci].side === "ally") anyAllyAlive = true;
        else anyEnemyAlive = true;
      }
      if (!anyEnemyAlive && turnsToKill === 0) turnsToKill = round;
      if (!anyAllyAlive && turnsToWipe === 0) turnsToWipe = round;
      if (!anyAllyAlive || !anyEnemyAlive) break;
    }

    // 兜底：maxRounds 内未全灭，按剩余HP ÷ 理论DPS估算
    // 辅助函数：计算单个单位对对方平均防御的理论期望伤害
    function calcUnitTheoreticalDpr(unit, avgDefVit, avgDefAgi) {
      var atkStat = Math.max(unit.stats.力量 || 0, unit.stats.魔力 || 0);
      var mitigation = utils.calcMitigation(atkStat, avgDefVit);
      var mitigatedDmg = Math.max(1, Math.floor(atkStat * (1 - mitigation)));
      var agiBonus = utils.calcAgilitySuppress(unit.stats.敏捷 || 0, avgDefAgi);
      var afterAgiDmg = Math.floor(mitigatedDmg * (1 + agiBonus));
      var critRate = utils.calcCritRate(unit.stats.灵巧 || 0, avgDefAgi);
      return Math.floor(afterAgiDmg * (1 + critRate * 0.5));
    }

    if (turnsToKill === 0) {
      var remEnemyHp = 0;
      for (var ri = 0; ri < units.length; ri++) {
        if (units[ri].side === "enemy" && !units[ri].defeated) remEnemyHp += Math.max(0, units[ri].hp);
      }
      var avgAllyDpr;
      if (roundsWithAllyDmg > 0) {
        avgAllyDpr = totalAllyDpr / roundsWithAllyDmg;
      } else {
        // 用存活敌人的平均防御计算己方理论DPS
        var aliveEnemies = units.filter(function(u) { return u.side === "enemy" && !u.defeated; });
        var avgEnemyVit = 0, avgEnemyAgi = 0;
        aliveEnemies.forEach(function(u) { avgEnemyVit += u.stats.耐力 || 0; avgEnemyAgi += u.stats.敏捷 || 0; });
        if (aliveEnemies.length > 0) { avgEnemyVit /= aliveEnemies.length; avgEnemyAgi /= aliveEnemies.length; }
        avgAllyDpr = 0;
        for (var ai2 = 0; ai2 < units.length; ai2++) {
          if (units[ai2].side === "ally" && !units[ai2].defeated) {
            avgAllyDpr += calcUnitTheoreticalDpr(units[ai2], avgEnemyVit, avgEnemyAgi);
          }
        }
      }
      turnsToKill = round + (avgAllyDpr > 0 ? remEnemyHp / avgAllyDpr : 999);
    }
    if (turnsToWipe === 0) {
      var remAllyHp = 0;
      for (var ra = 0; ra < units.length; ra++) {
        if (units[ra].side === "ally" && !units[ra].defeated) remAllyHp += Math.max(0, units[ra].hp);
      }
      var avgEnemyDpr;
      if (roundsWithEnemyDmg > 0) {
        avgEnemyDpr = totalEnemyDpr / roundsWithEnemyDmg;
      } else {
        // 用存活己方的平均防御计算敌方理论DPS
        var aliveAllies2 = units.filter(function(u) { return u.side === "ally" && !u.defeated; });
        var avgAllyVit = 0, avgAllyAgi = 0;
        aliveAllies2.forEach(function(u) { avgAllyVit += u.stats.耐力 || 0; avgAllyAgi += u.stats.敏捷 || 0; });
        if (aliveAllies2.length > 0) { avgAllyVit /= aliveAllies2.length; avgAllyAgi /= aliveAllies2.length; }
        avgEnemyDpr = 0;
        for (var ei2 = 0; ei2 < units.length; ei2++) {
          if (units[ei2].side === "enemy" && !units[ei2].defeated) {
            avgEnemyDpr += calcUnitTheoreticalDpr(units[ei2], avgAllyVit, avgAllyAgi);
          }
        }
      }
      turnsToWipe = round + (avgEnemyDpr > 0 ? remAllyHp / avgEnemyDpr : 999);
    }

    return {
      turnsToKill: turnsToKill,
      turnsToWipe: turnsToWipe,
      enduranceRatio: turnsToKill > 0 ? turnsToWipe / turnsToKill : 999,
    };
  };

  /**
   * 预计算战斗经验池（模拟一次战斗，roll 一次总经验池）
   *
   * @param {object[]} allAllies - 所有友方数组
   * @param {object[]} allEnemies - 所有存活敌人数组
   * @param {object} sysbox - sysbox
   * @returns {number} 总经验池
   */
  utils.calcEnemyExpPool = function (allAllies, allEnemies, sysbox) {
    var sim = utils.simulateExpectedBattle(allAllies, allEnemies);
    var combatConfig = sysbox.战斗系统 || {};
    var tier = utils.matchColorTier(sim.enduranceRatio, combatConfig);
    return tier.expMax > tier.expMin
      ? Math.floor(Math.random() * (tier.expMax - tier.expMin + 1)) + tier.expMin
      : tier.expMin;
  };

  /**
   * 计算单个敌人的经验和伟业
   *
   * @param {object} enemy - 当前敌人对象
   * @param {object[]} allEnemies - 战场上所有存活敌人的数组
   * @param {object[]} allAllies - 所有友方数组
   * @param {object} sysbox - sysbox
   * @param {number} floor - 当前楼层
   * @param {number} [preRolledPool] - 预计算的总经验池（传入时跳过 roll，直接按战力分配）
   * @returns {{ exp: number, feat: number }}
   */
  utils.calcEnemyExpFeat = function (
    enemy,
    allEnemies,
    allAllies,
    sysbox,
    floor,
    preRolledPool,
  ) {
    var combatConfig = sysbox.战斗系统 || {};
    // 1. 逐个收集敌方战力 + HP上限 + 汇总 + 定位当前敌人
    var enemyPowers = [];
    var totalEnemyPower = 0;
    var totalEnemyHpMax = 0;
    var enemyIdx = -1;

    for (var i = 0; i < allEnemies.length; i++) {
      var e = allEnemies[i];
      var type = e.基础信息?.类型 || "怪物";
      var attr = e.个人属性 || {};
      var stats = attr.总能力 || {};
      var power = (stats.力量 || 0) + (stats.耐力 || 0) + (stats.灵巧 || 0) + (stats.敏捷 || 0) + (stats.魔力 || 0);
      var hpSpMp = utils.calcEntityHpSpMp(stats, type);

      enemyPowers.push({ power: power, hpMax: hpSpMp.hp });
      totalEnemyPower += power;
      totalEnemyHpMax += hpSpMp.hp;

      if (e === enemy) {
        enemyIdx = i;
      } else if (enemyIdx < 0 && e.基础信息?.姓名 && enemy.基础信息?.姓名 && e.基础信息.姓名 === enemy.基础信息.姓名) {
        enemyIdx = i;
      }
    }
    if (enemyIdx < 0) enemyIdx = 0;

    // 2. 收集我方 EO 和 ES（裸装：总能力不含装备/技能，HP/SP/MP 从裸装推算）
    var teamEO = 0;
    var teamES = 0;
    for (var j = 0; j < allAllies.length; j++) {
      var ally = allAllies[j];
      var allyType = ally.基础信息?.类型 || "主角";
      var allyAttr = ally.个人属性?.总能力 || ally.个人属性?.基础能力 || {};
      var allyEo = (allyAttr.力量 || 0) + (allyAttr.耐力 || 0) + (allyAttr.灵巧 || 0) + (allyAttr.敏捷 || 0) + (allyAttr.魔力 || 0);

      var allyHp, allySp, allyMp;
      if (allyType === "NPC") {
        allyHp = 500; allySp = 100; allyMp = 100;
      } else {
        var allyHpSpMp = utils.calcEntityHpSpMp(allyAttr, allyType);
        allyHp = allyHpSpMp.hp;
        allySp = allyHpSpMp.sp;
        allyMp = allyHpSpMp.mp;
      }
      var allyEs = allyHp + allySp * 0.5 + (allyMp > 0 ? 50 : 0);
      teamEO += allyEo;
      teamES += allyEs;
    }

    // 3. 期望战斗模拟 → 战损比
    var sim = utils.simulateExpectedBattle(allAllies, allEnemies);

    // 4. 总经验池（preRolledPool 存在时跳过 roll，共享同一池）
    var totalPool;
    if (preRolledPool != null) {
      totalPool = preRolledPool;
    } else {
      var tier = utils.matchColorTier(sim.enduranceRatio, combatConfig);
      totalPool = tier.expMax > tier.expMin
        ? Math.floor(Math.random() * (tier.expMax - tier.expMin + 1)) + tier.expMin
        : tier.expMin;
    }

    // 5. 按战力占比分配
    var myPower = enemyPowers[enemyIdx].power;
    var share = totalEnemyPower > 0 ? totalPool * myPower / totalEnemyPower : totalPool;
    var exp = Math.max(1, Math.round(share));

    // 6. 越级补偿
    var enemyLv = enemy.个人属性?.等级 || 0;
    var maxAllyLv = 0;
    for (var k = 0; k < allAllies.length; k++) {
      var alv = allAllies[k].个人属性?.等级 || 0;
      if (alv > maxAllyLv) maxAllyLv = alv;
    }
    var levelDiff = enemyLv - maxAllyLv;
    if (levelDiff > 0) {
      var bonusPerLevel = sysbox.剧情相关?.越级经验补偿 || 500;
      exp += levelDiff * bonusPerLevel;
    }

    // 6.5. 楼层补正 × 稀有度系数（仅怪物）
    var enemyType = enemy.基础信息?.类型 || "怪物";
    if (enemyType === "怪物") {
      var floorCorr = utils.getFloorCorrection(combatConfig, floor);
      var rarityCorr = utils.getRarityCoeff(combatConfig, enemy.基础信息?.稀有度 || "普通");
      exp = Math.round(exp * floorCorr * rarityCorr);
    }

    // 7. 伟业换算
    var featDivisor = sysbox.剧情相关?.伟业换算 || 100;
    var feat = Math.floor(exp / featDivisor);

    return { exp: exp, feat: feat };
  };

  // ==================== 统一更新敌人经验并持久化（前端调用） ====================

  /**
   * 从 MVU 变量中获取当前楼层的数据，为所有未击败的敌人重新计算经验和伟业，
   * 并直接持久化保存到当前楼层变量。
   *
   * 调用方式：U.updateEnemyExp()
   *
   * @returns {object[]|null} 更新后的敌人信息数组，失败返回 null
   */
  utils.updateEnemyExp = function (messageId) {
    return window.top.CommandUtils?.updateEnemyExp?.(messageId) ?? null;
  };

  // ==================== 人物名录批量删除 ====================

  /**
   * 从人物名录中批量删除角色，同时清理组队成员引用
   * @param {string[]} names - 要删除的角色姓名数组
   * @param {string}  [messageId] - 消息ID，传入则优先使用；不传则尝试自动获取
   * @returns {boolean}
   */
  utils.removeCharactersFromDirectory = async function (names, messageId) {
    return await window.top.CommandUtils?.removeCharactersFromDirectory?.(names, messageId) ?? false;
  };

  // 获取等级系数
  utils.getLevelCoeff = (config) => {
    return config?.等级补正?.等级系数 ?? 1000;
  };

  // 楼层补正系数
  utils.getFloorCorrection = (config, floor) => {
    const list = config?.楼层补正 || [];
    for (const f of list) {
      if (floor >= (f.层数最低 || 0) && floor <= (f.层数最高 || 999)) {
        return f.补正值 || 1;
      }
    }
    return 1;
  };

  // 稀有度系数
  utils.getRarityCoeff = (config, rarity) => {
    const map = { 普通: 1, 精英: 1.2, 变异: 1.5, 楼层主: 2.0 };
    const custom = config?.稀有度补正?.[rarity]?.系数;
    return custom != null ? custom : map[rarity] || 1;
  };

  // 计算装备提供的五维乘数（累乘）
  utils.calcEquipMultiplier = (equip) => {
    const mult = { 力量: 1, 耐力: 1, 灵巧: 1, 敏捷: 1, 魔力: 1 };
    if (!equip) return mult;
    const slots = [
      "主手",
      "副手",
      "头部",
      "身体",
      "护手",
      "鞋子",
      "饰品1",
      "饰品2",
    ];
    const applyItem = (item) => {
      if (!item?.装备属性?.加成) return;
      const b = item.装备属性.加成;
      for (const k of Object.keys(mult)) {
        if (typeof b[k] === "number" && b[k] !== 0) {
          mult[k] *= 1 + b[k];
        }
      }
    };
    slots.forEach((s) => applyItem(equip[s]));
    (equip.特殊 || []).forEach(applyItem);
    return mult;
  };

  // 计算被动技能提供的五维乘数（累乘）
  utils.calcSkillMultiplier = (skillList) => {
    const mult = { 力量: 1, 耐力: 1, 灵巧: 1, 敏捷: 1, 魔力: 1 };
    if (!skillList) return mult;
    for (const skill of Object.values(skillList)) {
      if (skill.技能类型 !== "被动" || !skill.加成) continue;
      for (const k of Object.keys(mult)) {
        if (typeof skill.加成[k] === "number" && skill.加成[k] !== 0) {
          mult[k] *= 1 + skill.加成[k];
        }
      }
    }
    return mult;
  };

  // 根据统一人物模型计算最终五维（已含等级补正、潜在能力、装备、被动技能）
  // 薄封装：核心逻辑在 CommandUtils.calcEffectiveStats
  utils.calcFinalStats = (character, config, floor) => {
    const cmdUtils = window.top?.CommandUtils || window.CommandUtils;
    if (cmdUtils?.calcEffectiveStats) {
      return cmdUtils.calcEffectiveStats(character, config);
    }
    // fallback: 直接读总能力，乘装备和技能
    const attr = character.个人属性 || {};
    const equip = character.装备栏 || {};
    const skills = character.基础信息?.技能列表 || {};
    const totalPower = attr.总能力 || {};

    const equipMult = utils.calcEquipMultiplier(equip);
    const skillMult = utils.calcSkillMultiplier(skills);

    return {
      力量: Math.floor((totalPower.力量 || 0) * equipMult.力量 * skillMult.力量),
      耐力: Math.floor((totalPower.耐力 || 0) * equipMult.耐力 * skillMult.耐力),
      灵巧: Math.floor((totalPower.灵巧 || 0) * equipMult.灵巧 * skillMult.灵巧),
      敏捷: Math.floor((totalPower.敏捷 || 0) * equipMult.敏捷 * skillMult.敏捷),
      魔力: Math.floor((totalPower.魔力 || 0) * equipMult.魔力 * skillMult.魔力),
    };
  };

  // 根据总能力和人物类型计算 HP/SP/MP 上限（遵循新公式）
  utils.calcEntityHpSpMp = (totalStats, entityType = "怪物") => {
    const str = totalStats.力量 || 0;
    const vit = totalStats.耐力 || 0;
    const mag = totalStats.魔力 || 0;
    if (entityType === "冒险者" || entityType === "主角") {
      const maxHp = 500 + str + vit;
      const maxSp = 100 + Math.floor(vit * 0.3);
      const maxMp = 100 + Math.floor(mag * 0.3);
      return { hp: maxHp, maxHp, sp: maxSp, maxSp: maxSp, mp: maxMp, maxMp };
    } else {
      const maxHp = str + vit;
      const maxSp = Math.floor(vit * 0.3);
      const maxMp = Math.floor(mag * 0.3);
      return { hp: maxHp, maxHp, sp: maxSp, maxSp, mp: maxMp, maxMp };
    }
  };

  // 对齐颜色档位（按战损比降序匹配）
  utils.matchColorTier = function(enduranceRatio, config) {
    var tiers = config?.颜色档位 || [];
    if (!tiers.length) return { tierIndex: 0, tierColor: "#666", tierName: "???", expMin: 0, expMax: 0 };

    // 按战损比最低降序排列，匹配第一个满足条件的
    var sorted = tiers.slice().sort(function(a, b) { return b.战损比最低 - a.战损比最低; });
    for (var i = 0; i < sorted.length; i++) {
      if (enduranceRatio >= sorted[i].战损比最低) {
        // 在原数组中查找索引
        var origIdx = tiers.indexOf(sorted[i]);
        return {
          tierIndex: origIdx,
          tierColor: sorted[i].颜色值 || "#666",
          tierName: sorted[i].难度名称 || "???",
          expMin: sorted[i].经验值最低 || 0,
          expMax: sorted[i].经验值最高 || 0,
        };
      }
    }

    var last = tiers[tiers.length - 1];
    return {
      tierIndex: tiers.length - 1,
      tierColor: last ? last.颜色值 || "#666" : "#666",
      tierName: last ? (last.难度名称 || "???") : "???",
      expMin: last ? (last.经验值最低 || 0) : 0,
      expMax: last ? (last.经验值最高 || 0) : 0,
    };
  };


  utils.loadSysboxData = (messageId) => {
    try {
      const Mvu = window.top.Mvu;
      if (!Mvu) return null;
      const mid = messageId != null
        ? messageId
        : (typeof window.top.getCurrentMessageId === "function"
          ? window.top.getCurrentMessageId()
          : null);
      if (mid == null) return null;
      const variables = Mvu.getMvuData({ type: "message", message_id: mid });
      const sd = _.get(variables, "stat_data") || {};
      const sysbox = _.get(sd, "sysbox");
      return sysbox ? JSON.parse(JSON.stringify(sysbox)) : null;
    } catch (e) { return null; }
  };

  // ==================== 角色数据加载 ====================

  utils.loadCharacterData = (messageId) => {
    try {
      const Mvu = window.top.Mvu;
      if (!Mvu) return null;
      const mid = messageId != null
        ? messageId
        : (typeof window.top.getCurrentMessageId === "function"
          ? window.top.getCurrentMessageId()
          : null);
      if (mid == null) return null;
      const variables = Mvu.getMvuData({ type: "message", message_id: mid });
      const sd = _.get(variables, "stat_data") || {};
      const protagonist = sd.主角;
      const directory = sd.人物名录;
      // 深拷贝切断 Proxy 引用，避免后续访问触发大量 get 陷阱导致 runtime.lastError
      return {
        主角: protagonist ? JSON.parse(JSON.stringify(protagonist)) : {},
        人物名录: directory ? JSON.parse(JSON.stringify(directory)) : {},
      };
    } catch (e) { return null; }
  };




  // ==================== 技能数值随机生成 ====================

  /**
   * 根据 AI 提供的技能元数据和 sysbox 等级配置，随机生成完整技能对象
   * @param {object} config - 技能元数据 { name, type, grade, skill_type, dims, damage_type, desc }
   * @param {object} gradeConfig - 等级配置 { 加成最低, 加成最高, 伤害比例最低, 伤害比例最高, 消耗MP最低, 消耗MP最高, 消耗SP最低, 消耗SP最高 }
   * @returns {object} 完整 Skill 对象，可直接写入 技能列表
   */
  utils.rollSkillValues = function(config, gradeConfig) {
    var roll = function(lo, hi) { return hi > lo ? lo + Math.random() * (hi - lo) : lo; };
    var rollRound = function(lo, hi) { return hi > lo ? Math.round(roll(lo, hi) * 100) / 100 : lo; };
    var grade = gradeConfig || {};

    var skill = {
      名称: config.name,
      类型: config.type || "技能",
      等级: config.grade || "I",
      效果描述: config.desc || "",
      技能类型: config.skill_type || "被动",
      消耗MP百分比: 0,
      消耗SP百分比: 0,
      伤害比例: 0,
      回复HP比例: 0,
      回复SP比例: 0,
      回复MP比例: 0,
    };

    if (config.skill_type === "被动") {
      // 被动技能：对指定维度 roll 加成系数
      if (config.dims && config.dims.length > 0) {
        var bonus = {};
        config.dims.forEach(function(stat) {
          var coeff = roll(grade.加成最低 || 0, grade.加成最高 || 0);
          bonus[stat] = Math.round(coeff * 100) / 100;
        });
        if (Object.keys(bonus).length > 0) skill.加成 = bonus;
      }
    } else {
      // 主动技能：数组驱动 roll 消耗、伤害、回复（兼容旧格式）
      // 消耗：新格式 cost_types 数组 > 旧格式从 damage_type 推断
      var costTypes;
      if (Array.isArray(config.cost_types) && config.cost_types.length > 0) {
        costTypes = config.cost_types;
      } else {
        // 旧格式兼容：从 damage_type 字符串推断
        var oldDt = config.damage_type;
        if (!oldDt) { costTypes = ["SP","MP"]; }
        else if (oldDt === "物理") { costTypes = ["SP"]; }
        else if (oldDt === "魔法") { costTypes = ["MP"]; }
        else { costTypes = ["SP","MP"]; } // 混合
      }
      if (costTypes.includes("SP")) {
        skill.消耗SP百分比 = rollRound(grade.消耗SP最低 || 0, grade.消耗SP最高 || 0);
      }
      if (costTypes.includes("MP")) {
        skill.消耗MP百分比 = rollRound(grade.消耗MP最低 || 0, grade.消耗MP最高 || 0);
      }

      // 伤害：数组有值就 roll（兼容旧格式 damage_type 字符串）
      var hasDmg = (Array.isArray(config.damage_types) && config.damage_types.length > 0)
        || (typeof config.damage_type === "string" && config.damage_type !== "");
      if (hasDmg) {
        skill.伤害比例 = rollRound(grade.伤害比例最低 || 0, grade.伤害比例最高 || 0);
      }

      // 恢复：数组有值就 roll 对应资源
      if (Array.isArray(config.heal_types) && config.heal_types.length > 0) {
        if (config.heal_types.includes("HP")) {
          skill.回复HP比例 = rollRound(grade.回复HP最低 || 0, grade.回复HP最高 || 0);
        }
        if (config.heal_types.includes("SP")) {
          skill.回复SP比例 = rollRound(grade.回复SP最低 || 0, grade.回复SP最高 || 0);
        }
        if (config.heal_types.includes("MP")) {
          skill.回复MP比例 = rollRound(grade.回复MP最低 || 0, grade.回复MP最高 || 0);
        }
        // 吸收减半：同时有伤害和恢复
        if (skill.伤害比例 > 0) {
          skill.回复HP比例 = Math.round(skill.回复HP比例 * 50) / 100;
          skill.回复SP比例 = Math.round(skill.回复SP比例 * 50) / 100;
          skill.回复MP比例 = Math.round(skill.回复MP比例 * 50) / 100;
        }
      }

      // 主动技能也可能有加成维度
      if (config.dims && config.dims.length > 0) {
        var activeBonus = {};
        config.dims.forEach(function(stat) {
          var coeff = roll(grade.加成最低 || 0, grade.加成最高 || 0);
          activeBonus[stat] = Math.round(coeff * 100) / 100;
        });
        if (Object.keys(activeBonus).length > 0) skill.加成 = activeBonus;
      }
    }

    return skill;
  };


  // ==================== 统一多v多战斗计算 ====================

  var FIVE_KEYS = ["力量", "耐力", "灵巧", "敏捷", "魔力"];

  /** 战术位置配置 */
  utils.TACTICAL_POSITIONS = {
    '前卫': { aggroMult: 1.3, expWeightBonus: { 耐力: 10 }, mitigationCapBonus: 0.05 },
    '中卫': { aggroMult: 1.0, expWeightBonus: { 灵巧: 10 }, critDmgBonus: 0.15 },
    '后卫': { aggroMult: 0.7, expWeightBonus: { 敏捷: 10 }, agiSuppressCapBonus: 0.10 },
    '策应': { aggroMult: 0.85, expWeightBonus: { 灵巧: 5, 敏捷: 5 }, critRateFlat: 0.10 },
  };

  /** 获取角色实际速度（敏捷 + 装备 + 被动技能加成） */
  utils.getEffectiveSpeed = function(char, combatConfig, floor) {
    var stats = utils.calcFinalStats(char, combatConfig, floor);
    return stats.敏捷 || 0;
  };

  /**
   * 按实际速度降序排列参战者
   * @param {Array} combatants — [{char, name, side: 'ally'|'enemy'}]
   */
  utils.sortBySpeed = function(combatants, combatConfig, floor) {
    return combatants.sort(function(a, b) {
      var spdA = utils.getEffectiveSpeed(a.char, combatConfig, floor);
      var spdB = utils.getEffectiveSpeed(b.char, combatConfig, floor);
      return spdB - spdA;
    });
  };

  /**
   * 按速度分配受击概率 — 速度越低越容易被选中
   * @returns {Array} 概率数组，总和为 1
   */
  utils.calcHitProbability = function(targets, combatConfig, floor) {
    var speeds = targets.map(function(t) {
      return utils.getEffectiveSpeed(t.char, combatConfig, floor);
    });
    var invWeights = speeds.map(function(s) { return s > 0 ? 1 / s : 1; });
    var total = invWeights.reduce(function(sum, w) { return sum + w; }, 0);
    return invWeights.map(function(w) { return w / total; });
  };

  /** 按概率随机选择目标索引 */
  utils.pickTargetByProbability = function(targets, probs) {
    var r = Math.random();
    var cum = 0;
    for (var i = 0; i < probs.length; i++) {
      cum += probs[i];
      if (r <= cum) return i;
    }
    return targets.length - 1;
  };

  // ============ 战斗原子公式（与小游戏 combat() 一致）============

  /** 减伤率：Math.min(0.4 + capBonus, 防御属性/(防御属性+攻击属性)) */
  utils.calcMitigation = function(atkStat, defStat, capBonus) {
    var safeDef = Math.max(defStat, 1);
    return Math.min(0.4 + (capBonus || 0), safeDef / (safeDef + Math.max(atkStat, 0)));
  };

  /** 敏捷压制加成：速度比对手高时，获得最多50%+capBonus伤害加成 */
  utils.calcAgilitySuppress = function(atkAgi, defAgi, capBonus) {
    var ratio = atkAgi / Math.max(defAgi, 1);
    if (ratio <= 1) return 0;
    return Math.min((ratio - 1) * 0.5, 0.5 + (capBonus || 0));
  };

  /** 暴击率：灵巧/敏捷比三段公式 */
  utils.calcCritRate = function(dex, agi) {
    var ratio = dex / Math.max(agi, 1);
    if (ratio >= 4) return 1.0;
    if (ratio >= 1) return 0.15 + 0.85 * Math.pow((ratio - 1) / 3, 0.7);
    return 0.15 * ratio;
  };

  /** 暴击伤害：1.5倍 + critDmgBonus */
  utils.calcCritDamage = function(damage, critDmgBonus) {
    return Math.floor(damage * (1.5 + (critDmgBonus || 0)));
  };

  /** 敌方有效攻击力：取力量与魔力的较高者（怪物无物法区分） */
  utils.calcEffectiveAtk = function(stats) {
    return Math.max(stats.力量 || 0, stats.魔力 || 0);
  };

  /**
   * 计算单次攻击的最终伤害（完整的伤害链）
   * @param {object} atkStats — 攻击方五维（已应用buff加成后）
   * @param {object} defStats — 防御方五维
   * @param {object} opts — { damageType, skillRatio, dmgBuff, mitigationCapBonus, critDmgBonus, agiSuppressCapBonus, critRateFlat }
   * @returns {object} { damage, crit, critRate, mitigation, agiBonus }
   */
  utils.calcSingleHitDamage = function(atkStats, defStats, opts) {
    opts = opts || {};
    var dmgType = opts.damageType || '物理';
    var skillRatio = opts.skillRatio != null ? opts.skillRatio : 1;
    var dmgBuff = opts.dmgBuff || 1;

    var baseStat, defStat;
    if (dmgType === '魔法') {
      baseStat = atkStats.魔力 || 0;
      defStat = defStats.魔力 || 0;
    } else if (dmgType === '混合') {
      baseStat = Math.floor(((atkStats.力量 || 0) + (atkStats.魔力 || 0)) / 2);
      defStat = Math.floor(((defStats.耐力 || 0) + (defStats.魔力 || 0)) / 2);
    } else {
      baseStat = atkStats.力量 || 0;
      defStat = defStats.耐力 || 0;
    }
    var baseDmg = Math.floor(baseStat * skillRatio * dmgBuff);

    // 减伤
    var mitigation = utils.calcMitigation(baseStat, defStat, opts.mitigationCapBonus);
    var mitigatedDmg = Math.max(1, Math.floor(baseDmg * (1 - mitigation)));

    // 敏捷压制
    var agiBonus = utils.calcAgilitySuppress(atkStats.敏捷 || 0, defStats.敏捷 || 0, opts.agiSuppressCapBonus);
    var agilityBoostedDmg = Math.floor(mitigatedDmg * (1 + agiBonus));

    // 暴击
    var critRate = utils.calcCritRate(atkStats.灵巧 || 0, defStats.敏捷 || 0);
    if (opts.critRateFlat) {
      critRate = Math.min(1, Math.max(0, critRate + opts.critRateFlat));
    }
    var crit = Math.random() < critRate;
    var finalDmg = crit ? utils.calcCritDamage(agilityBoostedDmg, opts.critDmgBonus) : agilityBoostedDmg;

    return {
      damage: finalDmg,
      crit: crit,
      critRate: critRate,
      mitigation: mitigation,
      agiBonus: agiBonus,
    };
  };

  // ============ 战斗辅助函数 ============

  /** 技能分类：damage / heal / buff / passive */
  utils.getSkillCategory = function(skill) {
    if (skill.技能类型 === '被动') return 'passive';
    var hasDmg = (skill.伤害比例 || 0) > 0;
    var hasHeal = (skill.回复HP比例 || 0) > 0 || (skill.回复SP比例 || 0) > 0 || (skill.回复MP比例 || 0) > 0;
    var hasBonus = skill.加成 && FIVE_KEYS.some(function(k) { return skill.加成[k] !== 0; });
    if (hasDmg) return 'damage';
    if (hasHeal) return 'heal';
    if (hasBonus) return 'buff';
    return 'damage';
  };

  /** 从资源消耗推断伤害类型：物理（耗SP）/ 魔法（耗MP）/ 混合（两者都耗） */
  utils.inferDamageType = function(skillData) {
    if (!skillData) return '物理';
    var spCost = skillData.消耗SP百分比 || 0;
    var mpCost = skillData.消耗MP百分比 || 0;
    if (spCost > 0 && mpCost > 0) return '混合';
    if (mpCost > 0) return '魔法';
    return '物理';
  };

  /** 判断技能是否为纯恢复（有回复无伤害） */
  utils.isPureHeal = function(skill) {
    if (skill.技能类型 === '被动') return false;
    var hasDmg = (skill.伤害比例 || 0) > 0;
    var hasHeal = (skill.回复HP比例 || 0) > 0 || (skill.回复SP比例 || 0) > 0 || (skill.回复MP比例 || 0) > 0;
    return !hasDmg && hasHeal;
  };

  /** 获取技能的恢复资源类型 */
  utils.getHealTypes = function(skill) {
    return {
      hp: (skill.回复HP比例 || 0) > 0,
      sp: (skill.回复SP比例 || 0) > 0,
      mp: (skill.回复MP比例 || 0) > 0,
    };
  };

  /** 恢复目标选择：找己方对应资源百分比最低的存活角色 */
  utils.selectHealTarget = function(unit, skill, allies) {
    var alive = allies.filter(function(a) { return !a.defeated; });
    if (!alive.length) return null;
    var healsHP = (skill.回复HP比例 || 0) > 0;
    var healsSP = (skill.回复SP比例 || 0) > 0;
    var healsMP = (skill.回复MP比例 || 0) > 0;
    if (healsHP) {
      alive.sort(function(a, b) {
        return (a.hp / Math.max(a.hpMax, 1)) - (b.hp / Math.max(b.hpMax, 1));
      });
    } else if (healsSP) {
      alive.sort(function(a, b) {
        return (a.sp / Math.max(a.spMax, 1)) - (b.sp / Math.max(b.spMax, 1));
      });
    } else if (healsMP) {
      alive.sort(function(a, b) {
        return (a.mp / Math.max(a.mpMax, 1)) - (b.mp / Math.max(b.mpMax, 1));
      });
    } else {
      return unit;
    }
    return alive[0];
  };

  /** HP百分比 → 伤势描述 */
  utils.hpPercentToInjury = function(hpCur, hpMax) {
    if (hpMax <= 0) return '被击败';
    var pct = hpCur / hpMax;
    if (pct <= 0) return '被击败';
    if (pct < 0.03) return '濒死';
    if (pct < 0.15) return '重伤';
    if (pct < 0.5) return '中度受伤';
    if (pct < 0.8) return '轻伤';
    return '健康';
  };

  // ══════════════════════════════════════════════════════════════
  // 战斗属性计算（从 Zod updateCharacter 提取，供多处复用）
  // ══════════════════════════════════════════════════════════════

  /** 计算等级补正（主角/冒险者保底200，怪物无保底） */
  utils.calcLevelBonus = function(lv, type, levelCoeff) {
    if (type === '主角' || type === '冒险者') {
      if (lv >= 1) {
        return Math.max((lv - 1) * (levelCoeff || 100), 200);
      }
    }
    if (type === '怪物' && lv >= 1) {
      return Math.max(0, (lv - 1) * (levelCoeff || 100));
    }
    return 0;
  };

  /** 从基础能力 + 潜在能力 + 等级 → 总能力 */
  utils.calcTotalPower = function(baseAbilities, potentialAbilities, lv, type, levelCoeff) {
    var base = baseAbilities || {};
    var pot = potentialAbilities || {};
    var levelBonus = utils.calcLevelBonus(lv, type, levelCoeff);
    var result = {};
    ['力量', '耐力', '灵巧', '敏捷', '魔力'].forEach(function(k) {
      result[k] = (base[k] || 0) + (pot[k] || 0) + levelBonus;
    });
    return result;
  };

  /** 从总能力 → HP/SP/MP 上限（怪物无 500/100 底数） */
  utils.calcHpSpMp = function(totalPower, type) {
    if (type === '怪物') {
      return {
        HP上限: (totalPower.力量 || 0) + (totalPower.耐力 || 0),
        SP上限: Math.floor((totalPower.耐力 || 0) * 0.3),
        MP上限: Math.floor((totalPower.魔力 || 0) * 0.3),
      };
    }
    return {
      HP上限: 500 + (totalPower.耐力 || 0) + (totalPower.力量 || 0),
      SP上限: 100 + Math.floor((totalPower.耐力 || 0) * 0.3),
      MP上限: 100 + Math.floor((totalPower.魔力 || 0) * 0.3),
    };
  };

  /** 一站式：基础能力 + 等级 → 总能力 + HP/SP/MP 上限（敌方面板/外部敌人用） */
  utils.calcCombatStats = function(baseAbilities, lv, type, levelCoeff) {
    var totalPower = utils.calcTotalPower(baseAbilities, null, lv, type, levelCoeff);
    var hpSpMp = utils.calcHpSpMp(totalPower, type);
    return { 总能力: totalPower, HP上限: hpSpMp.HP上限, SP上限: hpSpMp.SP上限, MP上限: hpSpMp.MP上限 };
  };

  /**
   * 执行一轮多v多战斗计算
   * @param {object} params
   *   allies: [{char, name}]
   *   enemies: [{char, name}]
   *   combatConfig, floor, maxRounds
   * @returns {object} { rounds, allyResults, enemyResults, summary }
   */
  /** 战斗行为 → 经验权重映射（可配置） */
  utils.COMBAT_WEIGHT_RULES = {
    attack:   { 力量: 3, 耐力: 2 },   // 使用攻击技能（含基本攻击）
    mpSkill:  { 魔力: 5 },            // 消耗MP的技能（魔法/混合，叠加在attack上）
    wasHit:   { 耐力: 3 },            // 被攻击
    agiBonus: { 敏捷: 3, 灵巧: 2 },   // 速度压制（agiBonus>0）
    crit:     { 灵巧: 10 },           // 暴击
    perHit:   { 灵巧: 1 },            // 每次攻击命中（灵巧稳定增长）
  };

  utils.calcMultiCombat = function(params) {
    var combatConfig = params.combatConfig || {};
    var floor = params.floor || 1;
    var skillSelections = params.skillSelections || {};

    // 轮数：null/undefined → 死斗模式（50轮安全上限）；数字 → 最多N轮
    var MAX_ROUNDS;
    if (params.maxRounds != null && params.maxRounds > 0) {
      MAX_ROUNDS = params.maxRounds;
    } else {
      MAX_ROUNDS = 50;
    }

    // 1. 深拷贝状态快照
    var allies = params.allies.map(function(a) {
      var state = a.char.状态 || {};
      var hpMax = state.HP上限 || 100;
      var hpCur = state.HP当前值 != null ? state.HP当前值 : hpMax;
      var spMax = state.SP上限 || 100;
      var spCur = state.SP当前值 != null ? state.SP当前值 : spMax;
      var mpMax = state.MP上限 || 100;
      var mpCur = state.MP当前值 != null ? state.MP当前值 : mpMax;
      return {
        char: a.char,
        name: a.name,
        _initialHp: hpCur,
        _initialSp: spCur,
        _initialMp: mpCur,
        hp: hpCur,
        hpMax: hpMax,
        sp: spCur,
        spMax: spMax,
        mp: mpCur,
        mpMax: mpMax,
        defeated: false,
        _buffMult: { 力量: 1, 耐力: 1, 灵巧: 1, 敏捷: 1, 魔力: 1 },
        _dmgBuff: 1,
        _skillSets: null,
        _damageWeights: {},
        _activeWeights: {},
        _healThreshold: null,
        _isEnemy: false,
        _position: null,
        _positionMult: { 力量: 1, 耐力: 1, 灵巧: 1, 敏捷: 1, 魔力: 1 },
      };
    });

    var enemies = params.enemies.map(function(e) {
      var state = e.char.状态 || {};
      var hpMax = state.HP上限 || 100;
      var hpCur = state.HP当前值 != null ? state.HP当前值 : hpMax;
      var spMax = state.SP上限 || 100;
      var spCur = state.SP当前值 != null ? state.SP当前值 : spMax;
      var mpMax = state.MP上限 || 100;
      var mpCur = state.MP当前值 != null ? state.MP当前值 : mpMax;
      return {
        char: e.char,
        name: e.name,
        _initialHp: hpCur,
        _initialSp: spCur,
        _initialMp: mpCur,
        hp: hpCur,
        hpMax: hpMax,
        sp: spCur,
        spMax: spMax,
        mp: mpCur,
        mpMax: mpMax,
        defeated: false,
        _buffMult: { 力量: 1, 耐力: 1, 灵巧: 1, 敏捷: 1, 魔力: 1 },
        _dmgBuff: 1,
        _skillSets: null,
        _damageWeights: {},
        _activeWeights: {},
        _healThreshold: null,
        _isEnemy: true,
        _origIndex: e._origIndex,
        _position: null,
        _positionMult: { 力量: 1, 耐力: 1, 灵巧: 1, 敏捷: 1, 魔力: 1 },
      };
    });

    // 2. 为每个参战者预构建技能分类（damage / active / heals）
    function buildSkillSets(unit) {
      var allSkills = (unit.char.基础信息 && unit.char.基础信息.技能列表) || {};
      var damage = [{ name: '基本攻击', key: '__basic__', costSP: 5, costMP: 0, skillData: null, defaultWeight: 5 }];
      var active = [];
      var heals = [];
      Object.keys(allSkills).forEach(function(skName) {
        var skill = allSkills[skName];
        if (skill.技能类型 !== '主动') return;
        var entry = {
          name: skName,
          key: skName,
          costSP: Math.round((skill.消耗SP百分比 || 0) * 100),
          costMP: Math.round((skill.消耗MP百分比 || 0) * 100),
          skillData: skill,
        };
        if (utils.isPureHeal(skill)) {
          var ht = utils.getHealTypes(skill);
          entry.healsHP = ht.hp;
          entry.healsSP = ht.sp;
          entry.healsMP = ht.mp;
          entry.defaultThreshold = 80;
          heals.push(entry);
        } else if ((skill.伤害比例 || 0) > 0) {
          entry.defaultWeight = 1;
          damage.push(entry);
        } else {
          entry.defaultWeight = 1;
          active.push(entry);
        }
      });
      return { damage: damage, active: active, heals: heals };
    }

    // 为所有参战者构建技能集
    allies.forEach(function(a) { a._skillSets = buildSkillSets(a); });
    enemies.forEach(function(e) { e._skillSets = buildSkillSets(e); });

    // 3. 解析技能选择（权重/阈值）+ 战术位置
    function resolveSelection(unit, sideSelections) {
      var sel = sideSelections || {};
      var sets = unit._skillSets;
      // 伤害技能权重
      var dmgW = sel.damageWeights || {};
      unit._damageWeights = {};
      sets.damage.forEach(function(sk) {
        var w = dmgW[sk.name];
        if (w == null) w = sk.defaultWeight;
        w = Number(w);
        if (isFinite(w) && w > 0) unit._damageWeights[sk.name] = w;
      });
      // 如果没有有效权重，确保基本攻击权重为5
      if (Object.keys(unit._damageWeights).length === 0 && sets.damage.length > 0) {
        unit._damageWeights[sets.damage[0].name] = 5;
      }
      // 主动技能权重
      var actW = sel.activeWeights || {};
      unit._activeWeights = {};
      sets.active.forEach(function(sk) {
        var w = actW[sk.name];
        if (w == null) w = sk.defaultWeight;
        w = Number(w);
        if (isFinite(w) && w > 0) unit._activeWeights[sk.name] = w;
      });
      // 恢复阈值
      if (sets.heals.length > 0) {
        var th = sel.healThreshold;
        unit._healThreshold = (th != null && th !== '') ? Number(th) : 80;
      } else {
        unit._healThreshold = null;
      }
      // 战术位置
      var pos = sel.position;
      if (pos && utils.TACTICAL_POSITIONS[pos]) {
        unit._position = pos;
        var posCfg = utils.TACTICAL_POSITIONS[pos];
        unit._positionMult = {};
        FIVE_KEYS.forEach(function(k) {
          unit._positionMult[k] = 1 + (posCfg.statMods ? (posCfg.statMods[k] || 0) : 0);
        });
      }
    }

    // 己方：使用用户选择
    allies.forEach(function(a) {
      var sel = skillSelections[a.name] || {};
      resolveSelection(a, sel);
    });

    // 敌方：自动设置默认权重和阈值
    enemies.forEach(function(e) {
      var sets = e._skillSets;
      e._damageWeights = {};
      sets.damage.forEach(function(sk, i) {
        e._damageWeights[sk.name] = (i === 0) ? 5 : ((i === 1) ? 3 : 1); // 基本攻击5，第一个主动伤害技能3，其余1
      });
      if (Object.keys(e._damageWeights).length === 0 && sets.damage.length > 0) {
        e._damageWeights[sets.damage[0].name] = 5;
      }
      e._activeWeights = {};
      sets.active.forEach(function(sk) {
        e._activeWeights[sk.name] = 1;
      });
      e._healThreshold = sets.heals.length > 0 ? 60 : null;
    });

    // 4. 加权随机选择辅助函数
    function weightedPick(weights, skillSet) {
      var entries = [];
      var totalW = 0;
      skillSet.forEach(function(sk) {
        var w = weights[sk.name] || 0;
        if (w > 0) {
          entries.push({ skill: sk, w: w });
          totalW += w;
        }
      });
      if (entries.length === 0) return null;
      var r = Math.random() * totalW;
      var cum = 0;
      for (var ei = 0; ei < entries.length; ei++) {
        cum += entries[ei].w;
        if (r <= cum) return entries[ei].skill;
      }
      return entries[entries.length - 1].skill;
    }

    // 5. 获取角色应用buff后的最终属性
    function getBuffedStats(unit) {
      var base = utils.calcFinalStats(unit.char, combatConfig, floor);
      var bm = unit._buffMult;
      return {
        力量: Math.floor((base.力量 || 0) * bm.力量),
        耐力: Math.floor((base.耐力 || 0) * bm.耐力),
        灵巧: Math.floor((base.灵巧 || 0) * bm.灵巧),
        敏捷: Math.floor((base.敏捷 || 0) * bm.敏捷),
        魔力: Math.floor((base.魔力 || 0) * bm.魔力),
      };
    }

    // 6. 构建速度排序（每轮重新排序：已击败的排到最后）
    function buildSpeedOrder() {
      var all = [];
      allies.forEach(function(a, i) {
        all.push({ unit: a, side: 'ally', idx: i });
      });
      enemies.forEach(function(e, i) {
        all.push({ unit: e, side: 'enemy', idx: i });
      });
      all.sort(function(a, b) {
        if (a.unit.defeated && !b.unit.defeated) return 1;
        if (!a.unit.defeated && b.unit.defeated) return -1;
        if (a.unit.defeated && b.unit.defeated) return 0;
        var spdA = utils.getEffectiveSpeed(a.unit.char, combatConfig, floor);
        var spdB = utils.getEffectiveSpeed(b.unit.char, combatConfig, floor);
        return spdB - spdA;
      });
      return all;
    }

    // 7. 获取主动技能效果描述
    function describeActiveEffect(skillData) {
      if (!skillData) return '';
      var parts = [];
      if (skillData.加成) {
        FIVE_KEYS.forEach(function(k) {
          if (skillData.加成[k]) parts.push(k + (skillData.加成[k] > 0 ? '+' : '') + skillData.加成[k].toFixed(2));
        });
      }
      if (skillData.伤害比例) parts.push('伤害比例+' + skillData.伤害比例.toFixed(2));
      return parts.join(',');
    }

    // 8. 执行回合
    var rounds = [];
    var roundCount = 0;
    while (roundCount < MAX_ROUNDS) {
      var anyAllyAlive = allies.some(function(a) { return !a.defeated; });
      var anyEnemyAlive = enemies.some(function(e) { return !e.defeated; });
      if (!anyAllyAlive || !anyEnemyAlive) break;

      roundCount++;

      var speedOrder = buildSpeedOrder();
      for (var ci = 0; ci < speedOrder.length; ci++) {
        var combatant = speedOrder[ci];
        var unit = combatant.unit;
        if (unit.defeated) continue;

        // SP不足时跳过本轮，恢复10SP
        if (unit.sp < 5) {
          unit.sp = Math.min(unit.spMax, unit.sp + 10);
          rounds.push({
            round: roundCount,
            attacker: unit.name,
            defender: null,
            skill: null, damage: 0, crit: false, critRate: 0, mitigation: 0, agiBonus: 0,
            defenderRemaining: null, defeated: false,
            activeSkill: null, activeTarget: null, activeDetail: null,
            healHP: 0, healSP: 10, healMP: 0,
            damageType: null,
            skipped: true,
          });
          continue;
        }

        var ownSide = combatant.side === 'ally' ? allies : enemies;
        var otherSide = combatant.side === 'ally' ? enemies : allies;
        var aliveOthers = otherSide.filter(function(o) { return !o.defeated; });
        if (!aliveOthers.length) continue;

        var activeDetail = '';
        var activeTargetName = '';
        var healHP = 0, healSP = 0, healMP = 0;
        var activeSkillUsed = null;

        // ---- 8a. 检查恢复（阈值触发，HP→SP→MP顺序）----
        var healTriggered = false;
        if (unit._healThreshold != null && unit._skillSets.heals.length > 0) {
          var threshold = unit._healThreshold / 100;
          // 按 HP→SP→MP 顺序检查是否有己方资源低于阈值
          var checkOrder = ['hp', 'sp', 'mp'];
          for (var oi = 0; oi < checkOrder.length && !healTriggered; oi++) {
            var resType = checkOrder[oi];
            var needy = null;
            for (var ai = 0; ai < ownSide.length; ai++) {
              var ally = ownSide[ai];
              if (ally.defeated) continue;
              var cur, max;
              if (resType === 'hp') { cur = ally.hp; max = ally.hpMax; }
              else if (resType === 'sp') { cur = ally.sp; max = ally.spMax; }
              else { cur = ally.mp; max = ally.mpMax; }
              if (max > 0 && cur / max < threshold) {
                needy = ally;
                break;
              }
            }
            if (needy) {
              // 找第一个能恢复该资源且资源够用的技能
              for (var hi = 0; hi < unit._skillSets.heals.length; hi++) {
                var healSkill = unit._skillSets.heals[hi];
                var matches = false;
                if (resType === 'hp') matches = healSkill.healsHP;
                else if (resType === 'sp') matches = healSkill.healsSP;
                else matches = healSkill.healsMP;
                if (!matches) continue;
                if (unit.sp < healSkill.costSP || unit.mp < healSkill.costMP) continue;
                // 执行恢复
                var sdHeal = healSkill.skillData;
                if (sdHeal.回复HP比例) {
                  healHP = Math.round(needy.hpMax * sdHeal.回复HP比例);
                  needy.hp = Math.min(needy.hpMax, needy.hp + healHP);
                }
                if (sdHeal.回复SP比例) {
                  healSP = Math.round(needy.spMax * sdHeal.回复SP比例);
                  needy.sp = Math.min(needy.spMax, needy.sp + healSP);
                }
                if (sdHeal.回复MP比例) {
                  healMP = Math.round(needy.mpMax * sdHeal.回复MP比例);
                  needy.mp = Math.min(needy.mpMax, needy.mp + healMP);
                }
                unit.sp = Math.max(0, unit.sp - healSkill.costSP);
                unit.mp = Math.max(0, unit.mp - healSkill.costMP);
                activeSkillUsed = healSkill;
                activeTargetName = needy.name;
                activeDetail = describeActiveEffect(sdHeal);
                healTriggered = true;
                break;
              }
            }
          }
        }

        // ---- 8b. 未触发恢复则 roll 主动技能 ----
        if (!healTriggered && Object.keys(unit._activeWeights).length > 0) {
          var rolledActive = weightedPick(unit._activeWeights, unit._skillSets.active);
          if (rolledActive && unit.sp >= rolledActive.costSP && unit.mp >= rolledActive.costMP) {
            unit.sp = Math.max(0, unit.sp - rolledActive.costSP);
            unit.mp = Math.max(0, unit.mp - rolledActive.costMP);
            var sdAct = rolledActive.skillData;
            if (sdAct && sdAct.加成) {
              FIVE_KEYS.forEach(function(k) {
                if (sdAct.加成[k]) unit._buffMult[k] *= 1 + sdAct.加成[k];
              });
            }
            if (sdAct && sdAct.伤害比例) {
              unit._dmgBuff += sdAct.伤害比例;
            }
            activeSkillUsed = rolledActive;
            activeTargetName = unit.name;
            activeDetail = describeActiveEffect(sdAct);
          }
        }

        // ---- 8c. 伤害技能（加权随机）----
        var skillUsed = weightedPick(unit._damageWeights, unit._skillSets.damage);
        if (!skillUsed) skillUsed = unit._skillSets.damage[0];
        if (skillUsed.costSP > 0 && unit.sp < skillUsed.costSP) skillUsed = unit._skillSets.damage[0];
        if (skillUsed.costMP > 0 && unit.mp < skillUsed.costMP) skillUsed = unit._skillSets.damage[0];

        // 选攻击目标（按对方速度倒数加权 × 战术位置aggro系数）
        var speeds = aliveOthers.map(function(o) {
          return utils.getEffectiveSpeed(o.char, combatConfig, floor);
        });
        var invWeights = speeds.map(function(s, i) {
          var baseWeight = s > 0 ? 1 / s : 1;
          if (aliveOthers[i]._position) {
            var posCfg2 = utils.TACTICAL_POSITIONS[aliveOthers[i]._position];
            if (posCfg2 && posCfg2.aggroMult) baseWeight *= posCfg2.aggroMult;
          }
          return baseWeight;
        });
        var totalW = invWeights.reduce(function(sum, w) { return sum + w; }, 0);
        var probs = invWeights.map(function(w) { return w / totalW; });
        var pickIdx = utils.pickTargetByProbability(aliveOthers, probs);
        var target = aliveOthers[pickIdx];

        // 推断伤害类型
        var damageType = utils.inferDamageType(skillUsed.skillData);

        var posCfg = (unit._position && utils.TACTICAL_POSITIONS[unit._position]) || {};
        var atkStats = getBuffedStats(unit);
        var defStats = getBuffedStats(target);
        var hitResult = utils.calcSingleHitDamage(atkStats, defStats, {
          damageType: damageType,
          skillRatio: skillUsed.skillData ? (skillUsed.skillData.伤害比例 || 1) : 1,
          dmgBuff: unit._dmgBuff,
          mitigationCapBonus: posCfg.mitigationCapBonus || 0,
          critDmgBonus: posCfg.critDmgBonus || 0,
          agiSuppressCapBonus: posCfg.agiSuppressCapBonus || 0,
          critRateFlat: posCfg.critRateFlat || 0,
        });

        target.hp = Math.max(0, target.hp - hitResult.damage);
        unit.sp = Math.max(0, unit.sp - skillUsed.costSP);
        unit.mp = Math.max(0, unit.mp - skillUsed.costMP);

        // HP安全规则
        if (target.hp <= 0) {
          target.defeated = true;
          if (combatant.side === 'enemy') {
            target.hp = 1;
          } else {
            target.hp = 0;
          }
        }

        rounds.push({
          round: roundCount,
          attacker: unit.name,
          defender: target.name,
          skill: skillUsed.name,
          damage: hitResult.damage,
          crit: hitResult.crit,
          critRate: hitResult.critRate,
          mitigation: hitResult.mitigation,
          agiBonus: hitResult.agiBonus,
          defenderRemaining: target.hp,
          defeated: target.defeated,
          activeSkill: activeSkillUsed ? activeSkillUsed.name : null,
          activeTarget: activeTargetName,
          activeDetail: activeDetail,
          healHP: healHP,
          healSP: healSP,
          healMP: healMP,
          damageType: damageType,
        });
      }
    }

    // 8. 组装结果
    var positions = {};
    allies.forEach(function(a) {
      if (a._position) positions[a.name] = a._position;
    });
    return {
      rounds: rounds,
      positions: positions,
      allyResults: allies.map(function(a) {
        return {
          name: a.name,
          hpBefore: a._initialHp, hpAfter: a.hp, hpMax: a.hpMax,
          spBefore: a._initialSp, spAfter: a.sp,
          mpBefore: a._initialMp, mpAfter: a.mp,
          defeated: a.defeated,
          injury: utils.hpPercentToInjury(a.hp, a.hpMax),
        };
      }),
      enemyResults: enemies.map(function(e) {
        return {
          name: e.name,
          _origIndex: e._origIndex,
          hpBefore: e._initialHp, hpAfter: e.hp, hpMax: e.hpMax,
          spBefore: e._initialSp, spAfter: e.sp,
          mpBefore: e._initialMp, mpAfter: e.mp,
          defeated: e.defeated,
          injury: utils.hpPercentToInjury(e.hp, e.hpMax),
        };
      }),
      summary: {
        totalAllyHpLost: allies.reduce(function(s, a) { return s + (a._initialHp - a.hp); }, 0),
        totalAllySpUsed: allies.reduce(function(s, a) { return s + (a._initialSp - a.sp); }, 0),
        totalAllyMpUsed: allies.reduce(function(s, a) { return s + (a._initialMp - a.mp); }, 0),
        totalEnemyHpLost: enemies.reduce(function(s, e) { return s + (e._initialHp - e.hp); }, 0),
        defeatedEnemies: enemies.filter(function(e) { return e.defeated; }).map(function(e) { return e.name; }),
        defeatedAllies: allies.filter(function(a) { return a.defeated; }).map(function(a) { return a.name; }),
        rounds: roundCount,
        allyVictory: enemies.every(function(e) { return e.defeated; }),
        enemyVictory: allies.every(function(a) { return a.defeated; }),
      },
    };
  };

  /** 根据战斗回合数据计算各角色的经验权重增量 */
  utils.calcExpWeightDeltas = function(result, allyNames) {
    var rules = utils.COMBAT_WEIGHT_RULES;
    var deltas = {};
    allyNames.forEach(function(name) {
      deltas[name] = { 力量: 0, 耐力: 0, 灵巧: 0, 敏捷: 0, 魔力: 0 };
    });

    (result.rounds || []).forEach(function(r) {
      if (r.skipped) return;

      var dA = deltas[r.attacker];
      var dD = deltas[r.defender];

      // 攻击方（为己方时）
      if (dA) {
        // 攻击技能
        dA.力量 += rules.attack.力量;
        dA.耐力 += rules.attack.耐力;
        // 消耗MP的技能
        if (r.damageType === '魔法' || r.damageType === '混合') {
          dA.魔力 += rules.mpSkill.魔力;
        }
        // 速度压制
        if (r.agiBonus > 0) {
          dA.敏捷 += rules.agiBonus.敏捷;
          dA.灵巧 += rules.agiBonus.灵巧;
        }
        // 暴击
        if (r.crit) {
          dA.灵巧 += rules.crit.灵巧;
        }
        // 每次命中
        dA.灵巧 += rules.perHit.灵巧;
      }

      // 防守方（为己方且受到伤害时）
      if (dD && r.damage > 0) {
        dD.耐力 += rules.wasHit.耐力;
      }
    });

    return deltas;
  };

  /** 统一构造敌方战斗单元（保证总能力正确，所有战斗路径共用） */
  utils.buildEnemyCombatUnit = function(spec) {
    var stats = utils.calcCombatStats(spec.abilities || {}, spec.lv || 1, spec.type || '怪物');
    var st = spec.status || {};
    var hpMax = st.HP上限 || stats.HP上限;
    var spMax = st.SP上限 || stats.SP上限;
    var mpMax = st.MP上限 || stats.MP上限;
    return {
      char: {
        基础信息: { 姓名: spec.name, 类型: spec.type || '怪物', 稀有度: spec.rarity || '普通' },
        个人属性: {
          等级: spec.lv || 1,
          基础能力: {
            力量: (spec.abilities && spec.abilities.力量) || 0,
            耐力: (spec.abilities && spec.abilities.耐力) || 0,
            灵巧: (spec.abilities && spec.abilities.灵巧) || 0,
            敏捷: (spec.abilities && spec.abilities.敏捷) || 0,
            魔力: (spec.abilities && spec.abilities.魔力) || 0,
          },
          总能力: stats.总能力,
        },
        状态: {
          HP上限: hpMax,
          HP当前值: st.HP当前值 != null ? st.HP当前值 : hpMax,
          SP上限: spMax,
          SP当前值: st.SP当前值 != null ? st.SP当前值 : spMax,
          MP上限: mpMax,
          MP当前值: st.MP当前值 != null ? st.MP当前值 : mpMax,
        },
      },
      name: spec.name,
    };
  };

  /** 便捷：直接根据 stat_data 执行战斗计算 */
  utils.calcCombatFromData = function(sd, maxRounds, skillSelections) {
    var combatConfig = (sd.sysbox && sd.sysbox.战斗系统) || {};
    var floor = sd.当前地下城区域 ? sd.当前地下城区域.层数 : 1;
    if (floor == null) floor = 1;

    var allies = [];
    var pl = sd.主角;
    if (pl) allies.push({ char: pl, name: (pl.基础信息 && pl.基础信息.姓名) || '主角' });
    var partyMap = sd.组队成员 || {};
    var npcList = sd.人物名录 || {};
    Object.keys(partyMap).forEach(function(name) {
      var npc = npcList[name];
      if (npc) allies.push({ char: npc, name: name });
    });

    var enemies = [];
    (sd.敌人信息 || []).forEach(function(e, i) {
      if (!e.是否击败) {
        enemies.push({ char: e, name: (e.基础信息 && e.基础信息.姓名) || '???', _origIndex: i });
      }
    });

    return utils.calcMultiCombat({ allies: allies, enemies: enemies, combatConfig: combatConfig, floor: floor, maxRounds: maxRounds, skillSelections: skillSelections || {} });
  };

  // ══════════════════════════════════════════════════════════════
  // 统一战斗入口（面板/继续战斗/死斗 共用）
  // ══════════════════════════════════════════════════════════════

  // 构建单个角色的战前准备参数（技能选择 + HP/SP/MP 状态）
  utils.buildCharSetupOpts = function(char, name) {
    var st = char.状态 || {};
    var skillList = (char.基础信息 && char.基础信息.技能列表) || {};
    var skills = [];
    Object.keys(skillList).forEach(function(skName) {
      var sk = skillList[skName];
      if (sk.技能类型 !== '主动') return;
      var isPureHeal = utils.isPureHeal(sk);
      var hasDmg = (sk.伤害比例 || 0) > 0;
      var cat;
      if (isPureHeal) {
        cat = 'heal';
      } else if (hasDmg) {
        cat = 'damage';
      } else {
        cat = 'active';
      }
      var ht = utils.getHealTypes(sk);
      var entry = {
        name: skName,
        category: cat,
        costSP: Math.round((sk.消耗SP百分比 || 0) * 100),
        costMP: Math.round((sk.消耗MP百分比 || 0) * 100),
        detail: (sk.伤害比例 ? '伤害x' + sk.伤害比例.toFixed(1) : '') +
                (sk.回复HP比例 ? ' 回复HP' : '') +
                (sk.回复SP比例 ? ' 回复SP' : '') +
                (sk.回复MP比例 ? ' 回复MP' : ''),
        defaultWeight: isPureHeal ? undefined : (hasDmg ? 1 : 1),
        defaultThreshold: isPureHeal ? 80 : undefined,
        healsHP: ht.hp,
        healsSP: ht.sp,
        healsMP: ht.mp,
      };
      skills.push(entry);
    });
    skills.unshift({ name: '基本攻击', category: 'damage', costSP: 0, costMP: 0, detail: '', defaultWeight: 5 });
    return {
      name: name,
      hpCur: st.HP当前值 != null ? st.HP当前值 : st.HP上限,
      hpMax: st.HP上限,
      spCur: st.SP当前值 != null ? st.SP当前值 : st.SP上限,
      spMax: st.SP上限,
      mpCur: st.MP当前值 != null ? st.MP当前值 : st.MP上限,
      mpMax: st.MP上限,
      skills: skills,
    };
  };

  // 构建战前准备弹窗参数（己方 + 敌方角色状态）
  utils.buildCombatSetupOpts = function(sd, externalEnemies) {
    var allies = [];
    var pl = sd.主角;
    if (pl) allies.push(utils.buildCharSetupOpts(pl, (pl.基础信息 && pl.基础信息.姓名) || '主角'));
    var partyMap = sd.组队成员 || {};
    var npcList = sd.人物名录 || {};
    Object.keys(partyMap).forEach(function(name) {
      var npc = npcList[name];
      if (npc) allies.push(utils.buildCharSetupOpts(npc, name));
    });

    var enemies;
    if (externalEnemies) {
      enemies = externalEnemies.map(function(e) {
        var st = e.status || {};
        var cs = utils.calcCombatStats(e.abilities || {}, e.lv || 1, e.type || '怪物');
        var eHpMax = st.HP上限 || cs.HP上限;
        var eHpCur = st.HP当前值 != null ? st.HP当前值 : eHpMax;
        var eSpMax = st.SP上限 || cs.SP上限;
        var eMpMax = st.MP上限 || cs.MP上限;
        return {
          name: e.name,
          hpCur: eHpCur, hpMax: eHpMax,
          spCur: st.SP当前值 != null ? st.SP当前值 : eSpMax,
          spMax: eSpMax,
          mpCur: st.MP当前值 != null ? st.MP当前值 : eMpMax,
          mpMax: eMpMax,
        };
      });
    } else {
      enemies = (sd.敌人信息 || []).filter(function(e) { return !e.是否击败; }).map(function(e) {
        var st = e.状态 || {};
        return {
          name: (e.基础信息 && e.基础信息.姓名) || '???',
          hpCur: st.HP当前值 != null ? st.HP当前值 : st.HP上限,
          hpMax: st.HP上限,
          spCur: st.SP当前值 != null ? st.SP当前值 : st.SP上限,
          spMax: st.SP上限,
          mpCur: st.MP当前值 != null ? st.MP当前值 : st.MP上限,
          mpMax: st.MP上限,
        };
      });
    }

    return { allies: allies, enemies: enemies, defaultRounds: 3 };
  };

  // 构建战斗战报
  utils.buildBattleReport = function(result, enemyNames, maxRounds, actualRounds) {
    var report = '【系统结算】\n';
    if (maxRounds != null && maxRounds > 0) {
      report += '经过 ' + result.summary.rounds + ' 轮战斗（最多 ' + (actualRounds || maxRounds) + ' 轮）：\n';
    } else {
      report += '死斗经过 ' + result.summary.rounds + ' 轮：\n';
    }
    report += '敌方: ' + enemyNames + '\n\n';

    report += '战斗经过：\n';
    var defeatRecords = [];
    // 按轮次分组
    var roundGroups = {};
    result.rounds.forEach(function(r) {
      if (!roundGroups[r.round]) roundGroups[r.round] = [];
      roundGroups[r.round].push(r);
      if (r.defeated) {
        defeatRecords.push(r.attacker + ' 击败了 ' + r.defender);
      }
    });

    Object.keys(roundGroups).sort(function(a, b) { return a - b; }).forEach(function(rn) {
      report += '第' + rn + '轮：\n';
      roundGroups[rn].forEach(function(r) {
        if (r.skipped) {
          report += '  ' + r.attacker + ' SP不足，跳过行动并恢复了' + r.healSP + 'SP\n';
          return;
        }
        // 主动/恢复部分
        var activePart = '';
        if (r.activeSkill) {
          var isHeal = r.healHP > 0 || r.healSP > 0 || r.healMP > 0;
          if (isHeal) {
            var healParts = [];
            if (r.healHP > 0) healParts.push('+' + r.healHP + 'HP');
            if (r.healSP > 0) healParts.push('+' + r.healSP + 'SP');
            if (r.healMP > 0) healParts.push('+' + r.healMP + 'MP');
            activePart = '用 ' + r.activeSkill + ' 恢复了 ' + (r.activeTarget || '?') + '(' + healParts.join(',') + ')，';
          } else {
            activePart = '激活了 ' + r.activeSkill + (r.activeDetail ? '(' + r.activeDetail + ')' : '') + '，';
          }
        }
        // 攻击部分
        var atkPart = '用 ' + r.skill + ' 攻击了 ' + r.defender;
        var dmgDetail = '造成' + r.damage + '伤害';
        if (r.mitigation > 0) dmgDetail += ', 减伤' + Math.round(r.mitigation * 100) + '%';
        if (r.agiBonus > 0) dmgDetail += ', 速度压制+' + Math.round(r.agiBonus * 100) + '%';
        if (r.crit) dmgDetail += ', 暴击(率' + Math.round(r.critRate * 100) + '%)';
        if (r.defeated) dmgDetail += ', 击败';
        report += '  ' + r.attacker + ' ' + activePart + atkPart + '(' + dmgDetail + ')\n';
      });
    });

    if (defeatRecords.length > 0) {
      report += '\n击败记录：\n';
      defeatRecords.forEach(function(dr) {
        report += '  ' + dr + '\n';
      });
    }

    report += '\n战斗结束时局势：\n己方：\n';
    result.allyResults.forEach(function(a) {
      var injury = a.injury || utils.hpPercentToInjury(a.hpAfter, a.hpMax);
      report += '  ' + a.name + '：HP ' + a.hpBefore + '→' + a.hpAfter + '（' + injury + '）';
      if (a.spBefore !== a.spAfter) report += '，SP ' + a.spBefore + '→' + a.spAfter;
      if (a.mpBefore !== a.mpAfter) report += '，MP ' + a.mpBefore + '→' + a.mpAfter;
      if (a.defeated) report += ' [无法战斗]';
      report += '\n';
    });
    report += '敌方：\n';
    result.enemyResults.forEach(function(e) {
      var injury = e.injury || utils.hpPercentToInjury(e.hpAfter, e.hpMax);
      report += '  ' + e.name + '：' + injury;
      if (!e.defeated) report += '（HP ' + e.hpAfter + '）';
      report += '\n';
    });

    if (result.summary.allyVictory) report += '\n敌方全灭，己方胜利。';
    else if (result.summary.enemyVictory) report += '\n己方全灭，敌方胜利。';
    else report += '\n战斗未分胜负。';

    report += '\n\n---\n请根据以上内容创作一段详细的战斗剧情，并让剧情在战斗结果处停下。';

    return report;
  };

  // 统一战斗入口
  utils.fightBattle = async function(options) {
    var C = window.top.CommandUtils;
    if (!C) throw new Error('CommandUtils 未加载');

    var sd = options.sd;
    var all = options.all;
    var externalEnemies = options.enemies;
    var messageId = options.messageId;
    var maxRounds = options.maxRounds;
    var showRoundInput = options.showRoundInput !== false;
    var title = options.title || '⚔️ 战前准备';
    var confirmText = options.confirmText || '确认开战';
    var reportTitle = options.reportTitle || '战斗战报';

    // 0. 前置检查：无外部敌人时检查存活敌人
    if (!externalEnemies) {
      var aliveEnemies = (sd.敌人信息 || []).filter(function(e) { return !e.是否击败; });
      if (!aliveEnemies.length) {
        alert('当前没有可战斗的敌人。');
        return false;
      }
    }

    // 1. 构建战前准备参数
    var setupOpts = utils.buildCombatSetupOpts(sd, externalEnemies);
    setupOpts.defaultRounds = maxRounds != null ? maxRounds : 3;
    setupOpts.showRoundInput = showRoundInput;
    if (title) setupOpts.title = title;
    if (confirmText) setupOpts.confirmText = confirmText;

    // 2. 显示战前准备弹窗
    var setup = await C._showCombatSetup(setupOpts);
    if (!setup) return false;

    // 3. 执行战斗
    var result;
    if (externalEnemies) {
      var combatConfig = (sd.sysbox && sd.sysbox.战斗系统) || {};
      var floor = (sd.当前地下城区域 && sd.当前地下城区域.层数) || 1;

      var allies = [];
      var pl = sd.主角;
      if (pl) allies.push({ char: pl, name: (pl.基础信息 && pl.基础信息.姓名) || '主角' });
      var partyMap = sd.组队成员 || {};
      var npcList = sd.人物名录 || {};
      Object.keys(partyMap).forEach(function(name) {
        var npc = npcList[name];
        if (npc) allies.push({ char: npc, name: name });
      });

      var enemies = externalEnemies.map(function(e) {
        return utils.buildEnemyCombatUnit({
          name: e.name, lv: e.lv, type: e.type, rarity: e.rarity,
          abilities: e.abilities || {},
          status: e.status || {},
        });
      });

      result = utils.calcMultiCombat({
        allies: allies, enemies: enemies, combatConfig: combatConfig, floor: floor,
        maxRounds: setup.rounds, skillSelections: setup.selections,
      });
    } else {
      result = utils.calcCombatFromData(sd, setup.rounds, setup.selections);
    }

    // 4. 构建战报
    var enemyNames;
    if (externalEnemies) {
      enemyNames = externalEnemies.map(function(e) { return e.name; }).join('、');
    } else {
      enemyNames = (sd.敌人信息 || []).map(function(e) { return (e.基础信息 && e.基础信息.姓名) || '???'; }).join('、');
    }
    var report = utils.buildBattleReport(result, enemyNames, maxRounds, setup.rounds);

    // 5. 结算（预览 + 发送 + 写回）—— 唯一 Mvu 写入口在 CommandUtils.applyCombatResult
    var enemyInfo = sd.敌人信息 || [];
    return await C.applyCombatResult(all, result, enemyInfo, report, reportTitle, messageId);
  };

  // ==================== 世界书模板数据库 ====================

  // ★ 世界书配置 — 改这里即可切换世界书
  var WB_CONFIG = {
    worldbook: "_地错DanMachi-NEW",
    // 条目名称关键词（用于匹配世界书内的条目名）
    entryKeywords: {
      character: "地错人物数据",
      dungeon: "地错地下城数据",
      equip: "地错装备数据",
      skill: "地错技能数据",
    },
  };

  /**
   * 内部：查找指定名称的世界书是否存在
   */
  async function findWorldbookName() {
    try {
      var names = await getWorldbookNames();
      for (var i = 0; i < names.length; i++) {
        if (names[i] === WB_CONFIG.worldbook) return names[i];
      }
      return null;
    } catch (e) { return null; }
  }

  /**
   * 内部：根据 category 获取对应的条目 content，解析为对象
   * @returns {Promise<object|null>} - 解析后的 content 对象，如 {"艾丝": {...}, "贝尔": {...}}
   */
  async function getEntryContentByCategory(category) {
    var keyword = WB_CONFIG.entryKeywords[category];
    if (!keyword) return null;
    var wbName = await findWorldbookName();
    if (!wbName) return null;
    try {
      var entries = await getWorldbook(wbName);
      for (var i = 0; i < entries.length; i++) {
        if (entries[i].name.includes(keyword)) {
          var content = entries[i].content;
          if (!content) return null;
          try { return JSON.parse(content); } catch (e) { return null; }
        }
      }
      return null;
    } catch (e) { return null; }
  }

  /**
   * 按名称查找模板
   * @param {string} name - 角色名/技能名等（content 对象中的 key）
   * @param {"character"|"enemy"|"equip"|"skill"} category
   * @returns {Promise<object|null>} - 模板数据
   */
  utils.findTemplate = async function(name, category) {
    var map = await getEntryContentByCategory(category);
    return map ? map[name] || null : null;
  };

  /**
   * 加载指定类型的所有模板
   * @param {"character"|"enemy"|"equip"|"skill"} category
   * @returns {Promise<Array<{name: string, extra: object}>>}
   */
  utils.loadTemplates = async function(category) {
    var map = await getEntryContentByCategory(category);
    if (!map) return [];
    var result = [];
    var keys = Object.keys(map);
    for (var i = 0; i < keys.length; i++) {
      result.push({ name: keys[i], extra: map[keys[i]] });
    }
    return result;
  };

  // ==================== 从模板创建游戏对象 ====================

  /**
   * 从世界书模板创建完整角色对象（可直接写入人物名录）
   * @param {string} name - 角色名
   * @param {object} sysbox - sysbox 配置（用于 roll 装备/技能数值）
   * @returns {Promise<object|null>} - 完整角色对象
   */
  utils.createCharacterFromTemplate = async function(name, sysbox) {
    var extra = await utils.findTemplate(name, "character");
    if (!extra) return null;

    var char = {};

    // 基础信息
    char.基础信息 = {
      姓名: name,
      类型: extra.类型 || "NPC",
      种族: extra.种族 || "人类",
      性别: extra.性别 || "未知",
      性格: extra.性格 || [],
      样貌: extra.样貌 || "",
      发型: extra.发型 || "",
      身材: extra.身材 || "",
      服装: extra.服装 || "",
      气质: extra.气质 || "",
      心境: extra.心境 || "平静",
      所在位置: extra.所在位置 || "未知",
      资产: { 存款: extra.存款 ?? 0 },
      负面状态: extra.负面状态 || [],
      技能列表: {},
    };
    if (extra.类型 === "怪物" && extra.稀有度) {
      char.基础信息.稀有度 = extra.稀有度;
    }

    // 状态（初始满状态，由 recalcAndSettle 计算具体值）
    char.状态 = {};
    if (extra.评价) char.状态.评价 = extra.评价;

    // 个人属性
    var charType = extra.类型 || "NPC";
    var attr = {
      所属眷族: extra.所属眷族 || "",
      身份职业: extra.身份职业 || [],
      到达层数: extra.到达层数 || 0,
    };
    if (charType === "冒险者" || charType === "怪物") {
      attr.等级 = extra.等级 || (charType === "怪物" ? 1 : 0);
      attr.基础能力 = extra.基础能力 || { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      attr.潜在能力 = extra.潜在能力 || { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      attr.积累经验值 = extra.积累经验值 || { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      attr.当前伟业 = extra.当前伟业 ?? 0;
      if (charType === "冒险者") {
        attr.成长期望 = extra.成长期望 || { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
        attr.破限 = extra.破限 || false;
      }
    }
    char.个人属性 = attr;

    // 关系
    char.关系 = {
      当前关系: extra.当前关系 || "陌生",
      情深值: extra.情深值 || 0,
    };

    // 技能列表（从模板元数据 roll 出完整技能）
    if (extra.技能列表) {
      var skillConfig = sysbox?.技能系统?.等级配置;
      if (skillConfig) {
        var skillNames = Object.keys(extra.技能列表);
        for (var si = 0; si < skillNames.length; si++) {
          var skName = skillNames[si];
          var skMeta = extra.技能列表[skName];
          if (!skMeta) continue;
          var gradeConfig = skillConfig[skMeta.等级];
          if (!gradeConfig) continue;
          var skill = utils.rollSkillValues({
            name: skName,
            type: skMeta.类型,
            grade: skMeta.等级,
            skill_type: skMeta.技能类型,
            dims: skMeta.加成维度,
            damage_types: skMeta.伤害类型,
            cost_types: skMeta.消耗类型,
            heal_types: skMeta.恢复类型,
            desc: skMeta.效果描述,
          }, gradeConfig);
          char.基础信息.技能列表[skName] = skill;
        }
      }
    }

    // 装备栏（从模板元数据 roll 出完整装备）
    if (extra.装备栏) {
      var equipConfig = sysbox?.装备系统?.品质配置;
      char.装备栏 = {};
      var equipSlots = Object.keys(extra.装备栏);
      for (var ei = 0; ei < equipSlots.length; ei++) {
        var slot = equipSlots[ei];
        var eqMeta = extra.装备栏[slot];
        if (!eqMeta || !equipConfig) continue;
        var qc = equipConfig[eqMeta.品质];
        if (!qc) continue;
        // roll 加成数值
        var bonus = {};
        var dims = eqMeta.加成维度;
        if (Array.isArray(dims)) {
          for (var di = 0; di < dims.length; di++) {
            var coeff = qc.加成最高 > qc.加成最低
              ? qc.加成最低 + Math.random() * (qc.加成最高 - qc.加成最低)
              : qc.加成最低;
            bonus[dims[di]] = Math.round(coeff * 100) / 100;
          }
        }
        char.装备栏[slot] = {
          名称: eqMeta.名称 || slot,
          数量: 1,
          描述: eqMeta.物品描述 || "",
          效果描述: "",
          品质: eqMeta.品质 || 1,
          类别: eqMeta.类别 || "装备",
          单价: eqMeta.价格 || 0,
          装备属性: { 部位: slot, 加成: bonus },
        };
        if (eqMeta.效果名称) char.装备栏[slot].装备属性.效果名称 = eqMeta.效果名称;
      }
    }

    // 持有物品
    if (extra.持有物品) {
      char.持有物品 = JSON.parse(JSON.stringify(extra.持有物品));
    }

    return char;
  };

  /**
   * 从世界书模板创建完整敌人对象（含总能力/HP/SP/MP 计算）
   * 先查人物数据（冒险者敌人），再查怪物数据
   * @param {string} name - 敌人名
   * @param {object} sysbox - sysbox 配置
   * @returns {Promise<object|null>} - 完整敌人对象，未找到返回 null
   */
  utils.createEnemyFromTemplate = async function(name, sysbox) {
    // 先查人物数据（冒险者敌人）
    var charExtra = await utils.findTemplate(name, "character");
    if (charExtra) {
      // 用角色模板创建，但返回敌人格式
      var char = await utils.createCharacterFromTemplate(name, sysbox);
      if (char) {
        var attr = char.个人属性 || {};
        var levelCoeff = sysbox?.战斗系统?.等级补正?.等级系数 ?? 1000;
        var stats = utils.calcCombatStats(attr.基础能力 || {}, attr.等级 || 1, char.基础信息?.类型 || "冒险者", levelCoeff);
        return {
          基础信息: {
            姓名: name,
            类型: char.基础信息?.类型 || "冒险者",
            种族: char.基础信息?.种族 || "人类",
            稀有度: "精英",
            技能列表: char.基础信息?.技能列表 || {},
          },
          状态: {
            HP上限: stats.HP上限,
            HP当前值: stats.HP上限,
            SP上限: stats.SP上限,
            SP当前值: stats.SP上限,
            MP上限: stats.MP上限,
            MP当前值: stats.MP上限,
          },
          个人属性: {
            等级: attr.等级 || 1,
            基础能力: attr.基础能力 || {},
            成长期望: attr.成长期望 ? Object.assign({}, attr.成长期望) : { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
            总能力: stats.总能力,
            潜在能力: { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
            积累经验值: { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
            当前伟业: 0,
          },
          是否击败: false,
        };
      }
    }
    // 怪物数据已整合到地下城数据中，需通过 lookupDungeonMonster(floor, name) 按楼层查找
    return null;
  };

  /**
   * 从世界书模板 + 品质配置 roll 完整装备对象
   * @param {string} name - 装备名
   * @param {object} sysbox - sysbox.装备系统.品质配置
   * @returns {Promise<object|null>} - 完整 InventoryItem
   */
  utils.createEquipFromTemplate = async function(name, sysbox) {
    var extra = await utils.findTemplate(name, "equip");
    if (!extra) return null;
    var equipConfig = sysbox?.装备系统?.品质配置;
    if (!equipConfig) return null;
    var qc = equipConfig[extra.品质];
    if (!qc) return null;

    var bonus = {};
    var dims = extra.加成维度;
    if (Array.isArray(dims)) {
      for (var i = 0; i < dims.length; i++) {
        var coeff = qc.加成最高 > qc.加成最低
          ? qc.加成最低 + Math.random() * (qc.加成最高 - qc.加成最低)
          : qc.加成最低;
        bonus[dims[i]] = Math.round(coeff * 100) / 100;
      }
    }

    var item = {
      名称: name,
      数量: 1,
      描述: extra.物品描述 || "",
      效果描述: "",
      品质: extra.品质 || 1,
      类别: extra.类别 || "装备",
      单价: extra.价格 || 0,
      装备属性: {
        部位: extra.部位,
        加成: bonus,
      },
    };
    if (extra.效果名称) item.装备属性.效果名称 = extra.效果名称;
    return item;
  };

  /**
   * 从世界书模板 + 等级配置 roll 完整技能对象
   * @param {string} name - 技能名
   * @param {object} sysbox - sysbox.技能系统.等级配置
   * @returns {Promise<object|null>} - 完整 Skill 对象
   */
  utils.createSkillFromTemplate = async function(name, sysbox) {
    var extra = await utils.findTemplate(name, "skill");
    if (!extra) return null;
    var skillConfig = sysbox?.技能系统?.等级配置;
    if (!skillConfig) return null;
    var gradeConfig = skillConfig[extra.等级];
    if (!gradeConfig) return null;

    return utils.rollSkillValues({
      name: name,
      type: extra.类型,
      grade: extra.等级,
      skill_type: extra.技能类型,
      dims: extra.加成维度,
      damage_types: extra.伤害类型,
      cost_types: extra.消耗类型,
      heal_types: extra.恢复类型,
      desc: extra.效果描述,
    }, gradeConfig);
  };

  // ==================== 地下城数据查找与校验 ====================

  /**
   * 同步查找地下城怪物模板（子串匹配）
   * 从 CommandUtils 的预加载缓存中读取，需先调用 preloadTemplates
   * @param {number} floor - 当前楼层
   * @param {string} monsterName - AI提供的怪物名（如"哥布林A"）
   * @returns {{ key: string, data: object } | null} - 匹配到的模板key和data
   */
  utils.lookupDungeonMonster = function(floor, monsterName) {
    var cache = window.top?.CommandUtils?._getTemplateCache?.();
    if (!cache || !cache.dungeon) return null;
    var floorData = cache.dungeon[String(floor)];
    if (!floorData) return null;
    var keys = Object.keys(floorData);
    for (var i = 0; i < keys.length; i++) {
      if (monsterName.includes(keys[i])) {
        return { key: keys[i], data: floorData[keys[i]] };
      }
    }
    return null;
  };

  /**
   * 范围校验 + 重roll：检查AI数据是否在模板范围内，超出则重roll
   * @param {string} aiName - AI提供的怪物名
   * @param {object} aiData - AI提供的数据 { 等级, 基础能力 }
   * @param {object} template - lookupDungeonMonster 返回的 { key, data }
   * @returns {object} { 等级, 基础能力, 稀有度, 种族, 技能列表, 来源 }
   */
  utils.validateAndRollMonster = function(aiName, aiData, template) {
    var tpl = template.data;
    var levelRange = tpl.等级范围 || {};
    var statRanges = tpl.能力值范围 || {};

    var aiLevel = aiData.等级 || 1;
    var aiStats = aiData.基础能力 || {};

    var FIVE_KEYS = ["力量","耐力","灵巧","敏捷","魔力"];

    // 检查AI数据是否在模板范围内
    var levelOk = aiLevel >= (levelRange.最低 != null ? levelRange.最低 : 1)
      && aiLevel <= (levelRange.最高 != null ? levelRange.最高 : 99);
    var statsOk = true;
    for (var i = 0; i < FIVE_KEYS.length; i++) {
      var k = FIVE_KEYS[i];
      var range = statRanges[k];
      if (range) {
        var val = aiStats[k] || 0;
        if (val < (range.最低 || 0) || val > (range.最高 || 9999)) {
          statsOk = false;
          break;
        }
      }
    }

    if (levelOk && statsOk) {
      // AI数据在范围内，直接使用
      return {
        等级: aiLevel,
        基础能力: {
          力量: aiStats.力量 || 0,
          耐力: aiStats.耐力 || 0,
          灵巧: aiStats.灵巧 || 0,
          敏捷: aiStats.敏捷 || 0,
          魔力: aiStats.魔力 || 0,
        },
        稀有度: tpl.稀有度 || "普通",
        种族: tpl.种族 || "未知",
        技能列表: tpl.技能列表 || null,
        来源: "AI数据(校验通过)",
      };
    }

    // 超出范围，在模板范围内重roll
    var rollInt = function(lo, hi) {
      return hi > lo ? Math.floor(lo + Math.random() * (hi - lo + 1)) : lo;
    };

    var newLevel = rollInt(
      levelRange.最低 != null ? levelRange.最低 : 1,
      levelRange.最高 != null ? levelRange.最高 : 99
    );
    var newStats = {};
    for (var j = 0; j < FIVE_KEYS.length; j++) {
      var sk = FIVE_KEYS[j];
      var sr = statRanges[sk] || {};
      newStats[sk] = rollInt(sr.最低 || 0, sr.最高 || 0);
    }

    return {
      等级: newLevel,
      基础能力: newStats,
      稀有度: tpl.稀有度 || "普通",
      种族: tpl.种族 || "未知",
      技能列表: tpl.技能列表 || null,
      来源: "模板重roll",
    };
  };

  // 挂载到全局（顶层窗口）
  if (typeof window !== "undefined" && window.top) {
    window.top.DungeonUtils = utils;
    window.top.__DungeonUtilsReady = true;
  } else {
    window.DungeonUtils = utils;
  }
})();

// zod函数工具.js - 操作指令处理函数，挂载 window.top.CommandUtils
(() => {
