    var equip = char.装备栏 || {};
    var skills = char.基础信息?.技能列表 || {};

    var keys = ["力量","耐力","灵巧","敏捷","魔力"];
    var totalPower = attr.总能力 || {};
    var raw = keys.map(function(k) { return totalPower[k] || 0; });

    // 装备加成（累乘）
    var equipMult = { 力量:1, 耐力:1, 灵巧:1, 敏捷:1, 魔力:1 };
    if (equip) {
      var applyItem = function(item) {
        if (!item?.装备属性?.加成) return;
        var b = item.装备属性.加成;
        keys.forEach(function(k) {
          if (typeof b[k] === "number" && b[k] !== 0) equipMult[k] *= 1 + b[k];
        });
      };
      EQUIP_SLOTS.forEach(function(s) { applyItem(equip[s]); });
      (equip.特殊 || []).forEach(applyItem);
    }

    // 被动技能加成（累乘）
    var skillMult = { 力量:1, 耐力:1, 灵巧:1, 敏捷:1, 魔力:1 };
    if (skills) {
      Object.values(skills).forEach(function(skill) {
        if (skill.技能类型 !== "被动" || !skill.加成) return;
        keys.forEach(function(k) {
          if (typeof skill.加成[k] === "number" && skill.加成[k] !== 0) skillMult[k] *= 1 + skill.加成[k];
        });
      });
    }

    var result = {};
    keys.forEach(function(k, i) {
      result[k] = Math.floor(raw[i] * equipMult[k] * skillMult[k]);
    });
    return result;
  };

  /** 计算实际总能力值之和（用于排名比较） */
  cmd.calcEffectiveTotal = function(char, combatConfig) {
    var stats = cmd.calcEffectiveStats(char, combatConfig);
    return stats.力量 + stats.耐力 + stats.灵巧 + stats.敏捷 + stats.魔力;
  };

  // ==================== 指令处理函数 ====================

  // ---------- 恩惠更新 ----------
  cmd.handle恩惠更新 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const char = target.char;
    const attr = ensurePath(char, "个人属性", {});
    const type = char.基础信息?.类型 || "NPC";
    if (type === "NPC") return;

    var exp = attr.积累经验值 || {};
    var base = ensurePath(attr, "基础能力", {});
    var polian = attr.破限 || false;
    var isAdventurer = type === "冒险者";

    var DILUTION_TIERS = [
      { threshold: 1200, divisor: 10 },
      { threshold: 1500, divisor: 100 },
      { threshold: 2000, divisor: 1000 },
    ];

    FIVE_KEYS.forEach(function(k) {
      var expRemaining = exp[k] || 0;
      var current = base[k] || 0;
      var growth = (attr.成长期望 && attr.成长期望[k]) ? attr.成长期望[k] : 0;

      if (expRemaining <= 0) {
        // 无经验但也要检查：之前溢出的可能留在积累经验值里
        if (attr.积累经验值 && (attr.积累经验值[k] || 0) === 0) return;
        return;
      }

      // 渐进稀释：若当前值已过档位，先一次性稀释
      for (var t = 0; t < DILUTION_TIERS.length; t++) {
        var tier = DILUTION_TIERS[t];
        if (current >= tier.threshold) {
          expRemaining = Math.floor(expRemaining / tier.divisor);
          break;
        }
      }

      // 从当前值开始，逐档推进
      var newVal = current;
      for (var t = 0; t < DILUTION_TIERS.length; t++) {
        var tier = DILUTION_TIERS[t];
        if (newVal < tier.threshold && expRemaining > 0) {
          var needed = tier.threshold - newVal;
          if (expRemaining <= needed) {
            newVal += expRemaining;
            expRemaining = 0;
            break;
          }
          newVal = tier.threshold;
          expRemaining -= needed;
          expRemaining = Math.floor(expRemaining / tier.divisor);
        }
      }
      newVal += expRemaining;

      // 封顶检查
      if (!polian) {
        var cap = 999;
        if (isAdventurer && growth > 0 && growth < cap) cap = growth;
        if (newVal > cap) {
          if (!attr.积累经验值) attr.积累经验值 = {};
          attr.积累经验值[k] = newVal - cap;
          newVal = cap;
        } else {
          if (attr.积累经验值) attr.积累经验值[k] = 0;
        }
      } else {
        // 破限=true：更新成长期望
        if (isAdventurer && newVal > growth) {
          if (!attr.成长期望) attr.成长期望 = {};
          attr.成长期望[k] = newVal;
        }
        if (attr.积累经验值) attr.积累经验值[k] = 0;
      }

      if (newVal > 9999) newVal = 9999;
      base[k] = newVal;
    });
  };

  // ---------- 升级 ----------
  cmd.handle升级 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const char = target.char;
    const attr = ensurePath(char, "个人属性", {});
    const status = ensurePath(char, "状态", {});
    const type = char.基础信息?.类型 || "NPC";
    if (type === "NPC") return;

    const lv = attr.等级 || 0;
    const isPlayer = target.isPlayer;

    // 1. 恩惠更新：Lv > 0 时先转换积累经验值（初次升级跳过）
    if (lv > 0) {
      cmd.handle恩惠更新(instruction, data);
    }

    // 2. 主角专属：非初次升级时计算潜在能力并归零基础
    if (isPlayer && lv >= 1) {
      const base = attr.基础能力 || {};
      const potential = ensurePath(attr, "潜在能力", {});
      FIVE_KEYS.forEach(k => {
        potential[k] = Math.floor((base[k] || 0) / 2);
        base[k] = 0;
      });
    }

    // 3. 冒险者专属：基础能力归零
    if (!isPlayer && type === "冒险者") {
      const base = ensurePath(attr, "基础能力", {});
      FIVE_KEYS.forEach(k => { base[k] = 0; });
    }

    // 4. 伟业归零，等级+1
    attr.当前伟业 = 0;
    attr.等级 = lv + 1;

    // 4.5 新等级后再次恩惠更新，将溢出经验写入新基础能力
    cmd.handle恩惠更新(instruction, data);

    // 5. 满血满蓝
    status.HP变动百分比 = 100;
    status.SP变动百分比 = 100;
    status.MP变动百分比 = 100;
  };

  // ---------- 获得恩惠 ----------
  cmd.handle获得恩惠 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;

    // 主角：直接升级
    if (target.isPlayer) {
      cmd.handle升级(instruction, data);
      return;
    }

    const char = target.char;

    char.基础信息.类型 = "冒险者";

    // 重建完整冒险者能力结构
    char.个人属性 = {
      等级: 0,
      基础能力: { 力量: 0, 耐力: 0, 灵巧: 0, 敏捷: 0, 魔力: 0 },
      潜在能力: { 力量: 0, 耐力: 0, 灵巧: 0, 敏捷: 0, 魔力: 0 },
      积累经验值: { 力量: 0, 耐力: 0, 灵巧: 0, 敏捷: 0, 魔力: 0 },
      当前伟业: 0,
      成长期望: { 力量: 0, 耐力: 0, 灵巧: 0, 敏捷: 0, 魔力: 0 },
      破限: false,
      身份职业: char.个人属性?.身份职业 || [],
      所属眷族: char.个人属性?.所属眷族 || "",
      到达层数: char.个人属性?.到达层数 || 0,
    };

    // 补全冒险者专属状态字段
    if (!char.状态) char.状态 = {};
    if (char.状态.身体状况 === undefined) char.状态.身体状况 = 100;
    if (char.状态.评价 === undefined) char.状态.评价 = "";

    // 确保关系字段存在
    if (!char.关系) char.关系 = { 当前关系: "陌生", 情深值: 0 };

    // 转为冒险者后自动执行初次升级（Lv.0 → Lv.1，满状态）
    cmd.handle升级(instruction, data);
  };

  // ---------- 穿戴装备 ----------
  cmd.handle穿戴装备 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const char = target.char;
    const itemName = instruction.装备名称;
    const slot = instruction.部位;
    if (!itemName || !slot) return;

    const found = findInInventory(char, itemName);
    if (!found || found.item.数量 <= 0) return;

    // 验证装备部位匹配
    const equipSlot = found.item.装备属性?.部位;
    if (equipSlot && equipSlot !== "无法装备" && equipSlot !== slot) return;

    if (!char.装备栏) char.装备栏 = {};

    // 1. 卸下旧装备
    const oldEquip = slot === "特殊"
      ? null // 特殊槽是数组，不自动卸
      : char.装备栏[slot];
    if (oldEquip && slot !== "特殊") {
      addToInventory(char, Object.assign({}, oldEquip, { 数量: 1 }));
    }

    // 2. 新装备从持有物品移除
    decrementItem(char, found, 1);

    // 3. 放入槽位
    const newItem = Object.assign({}, found.item, { 数量: 1 });
    if (slot === "特殊") {
      if (!char.装备栏.特殊) char.装备栏.特殊 = [];
      char.装备栏.特殊.push(newItem);
    } else {
      char.装备栏[slot] = newItem;
    }
  };

  // ---------- 卸下装备 ----------
  cmd.handle卸下装备 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const char = target.char;
    const slot = instruction.部位;
    if (!slot) return;
    if (!char.装备栏) return;

    if (slot === "特殊") {
      // 特殊槽整个清空
      (char.装备栏.特殊 || []).forEach(item => {
        addToInventory(char, Object.assign({}, item, { 数量: 1 }));
      });
      char.装备栏.特殊 = [];
    } else {
      const equip = char.装备栏[slot];
      if (equip) {
        addToInventory(char, Object.assign({}, equip, { 数量: 1 }));
        char.装备栏[slot] = null;
      }
    }
  };

  // ---------- 使用消耗品 ----------
  cmd.handle使用消耗品 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const itemName = instruction.物品名称;
    if (!itemName) return;

    // 物品所属：默认等于目标，可指定其他角色（使用别人的物品）
    const ownerName = instruction.物品所属 || instruction.目标;
    const owner = resolveTarget(ownerName, data);
    if (!owner) return;

    const found = findInInventory(owner.char, itemName);
    if (!found || found.item.数量 <= 0) return;

    const effect = found.item.消耗效果;
    if (!effect) return;

    const status = ensurePath(target.char, "状态", {});

    // 仅处理百分比字段（ConsumableEffectSchema 已精简）
    if (effect.回复HP百分比) {
      status.HP变动百分比 = (status.HP变动百分比 || 0) + Math.round(effect.回复HP百分比 * 100);
    }
    if (effect.回复SP百分比) {
      status.SP变动百分比 = (status.SP变动百分比 || 0) + Math.round(effect.回复SP百分比 * 100);
    }
    if (effect.回复MP百分比) {
      status.MP变动百分比 = (status.MP变动百分比 || 0) + Math.round(effect.回复MP百分比 * 100);
    }

    // 从物品所属角色扣数量
    decrementItem(owner.char, found, 1);
  };

  // ---------- 物品转移 ----------
  cmd.handle物品转移 = function(instruction, data) {
    const source = resolveTarget(instruction.来源, data);
    if (!source) return;
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const itemName = instruction.物品名称;
    if (!itemName) return;
    const quantity = instruction.数量 || 1;
    if (quantity <= 0) return;

    const found = findInInventory(source.char, itemName);
    if (!found || found.item.数量 < quantity) return;

    decrementItem(source.char, found, quantity);

    const transferItem = Object.assign({}, found.item, { 数量: quantity });
    addToInventory(target.char, transferItem);
  };

  // ---------- 加入眷族 ----------
  cmd.handle加入眷族 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const godName = instruction.主神;
    if (!godName) return;
    const familiaFullName = godName + "眷族";
    if (!target.char.个人属性) target.char.个人属性 = {};
    target.char.个人属性.所属眷族 = familiaFullName;

    // 主角加入时同步更新 眷族情况
    if (target.isPlayer) {
      if (!data.眷族情况) data.眷族情况 = {};
      data.眷族情况.主神 = godName;
    }
  };

  // ---------- 离开眷族 ----------
  cmd.handle离开眷族 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    if (target.char.个人属性) {
      target.char.个人属性.所属眷族 = "无";
    }
    // 主角离开时清空 眷族情况
    if (target.isPlayer && data.眷族情况) {
      data.眷族情况.主神 = "";
      data.眷族情况.成员名单 = [];
      data.眷族情况.成员数 = 0;
    }
  };

  // ---------- 组队加入 ----------
  cmd.handle组队加入 = function(instruction, data) {
    const name = instruction.目标;
    const protagonistName = data.主角?.基础信息?.姓名;
    if (!name || name === "主角" || name === protagonistName) return;
    // 必须在人物名录中存在
    if (!data.人物名录 || !data.人物名录[name]) return;
    if (!data.组队成员) data.组队成员 = {};
    data.组队成员[name] = {};
  };

  // ---------- 组队离开 ----------
  cmd.handle组队离开 = function(instruction, data) {
    const name = instruction.目标;
    const protagonistName = data.主角?.基础信息?.姓名;
    if (!name || name === "主角" || name === protagonistName) return;
    if (data.组队成员 && data.组队成员[name]) {
      delete data.组队成员[name];
    }
  };


  // ---------- 队伍解散 ----------
  cmd.handle队伍解散 = function(instruction, data) {
    if (data.组队成员) {
      data.组队成员 = {};
    }
  };

  // ---------- 敌人被击败 ----------
  cmd.handle敌人被击败 = function(instruction, data) {
    if (!data.敌人信息 || data.敌人信息.length === 0) return;
    const target = instruction.目标;

    let enemy;
    // 支持索引或名称
    if (/^\d+$/.test(String(target))) {
      const idx = parseInt(target, 10);
      enemy = data.敌人信息[idx];
    } else {
      enemy = data.敌人信息.find(e => e.基础信息?.姓名 === target);
    }

    if (!enemy || enemy.是否击败) return;
    enemy.是否击败 = true;
  };

  // ---------- 使用技能 ----------
  cmd.handle使用技能 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const char = target.char;
    const skillName = instruction.技能名称;
    if (!skillName) return;

    const skillList = char.基础信息?.技能列表;
    if (!skillList || !skillList[skillName]) return;

    const skill = skillList[skillName];
    if (skill.技能类型 !== "主动") return; // 被动技能无消耗

    const status = ensurePath(char, "状态", {});

    // MP 消耗（百分比转百分制）
    const mpPct = skill.消耗MP百分比 || 0;
    if (mpPct > 0) {
      status.MP变动百分比 = (status.MP变动百分比 || 0) - Math.round(mpPct * 100);
    }

    // SP 消耗（百分比转百分制）
    const spPct = skill.消耗SP百分比 || 0;
    if (spPct > 0) {
      status.SP变动百分比 = (status.SP变动百分比 || 0) - Math.round(spPct * 100);
    }
  };

  // ==================== 战斗结算 ====================

  /**
   * 自动战斗结算：所有敌人被击败时触发
   * 按实际总能力排名（含装备+被动技能），最强拿100%经验，其余70%
   * 每人独立稀释，各自换算伟业
   */
  cmd.handle结算 = function(data) {
    var enemyList = data.敌人信息;
    if (!enemyList || enemyList.length === 0) return;
    var allDefeated = enemyList.every(function(e) { return e.是否击败 === true; });
    if (!allDefeated) return;

    // 1. 汇总总经验
    var totalExp = 0;
    enemyList.forEach(function(e) { totalExp += e.结算经验 || 0; });
    if (totalExp <= 0) { data.敌人信息 = []; return; }

    var combatConfig = data.sysbox || {};
    var npcList = data.人物名录 || {};
    var STRONG_RATIO = 1.0;
    var WEAK_RATIO = 0.7;
    var featDivisor = (data.sysbox?.剧情相关?.伟业换算) || 100;
    var attrKeys = ["力量","耐力","灵巧","敏捷","魔力"];

    // 2. 收集所有参与者
    var participants = [];
    var pl = data.主角;
    if (pl) {
      participants.push({
        char: pl,
        name: "主角",
        total: cmd.calcEffectiveTotal(pl, combatConfig),
        isPlayer: true
      });
    }
    var partyMap = data.组队成员 || {};
    Object.keys(partyMap).forEach(function(name) {
      var m = npcList[name];
      if (!m) return;
      var mType = m.基础信息?.类型;
      if (mType !== "冒险者" && mType !== "怪物") return;
      participants.push({
        char: m,
        name: name,
        total: cmd.calcEffectiveTotal(m, combatConfig),
        isPlayer: false,
        isMonster: mType === "怪物"
      });
    });

    if (participants.length === 0) { data.敌人信息 = []; return; }

    // 3. 找最强
    var strongest = participants[0];
    for (var i = 1; i < participants.length; i++) {
      if (participants[i].total > strongest.total) strongest = participants[i];
    }

    // 4. 每人分配经验 + 稀释 + 伟业
    participants.forEach(function(p) {
      var ratio = (p === strongest) ? STRONG_RATIO : WEAK_RATIO;
      var pool = Math.floor(totalExp * ratio);
      if (pool <= 0) pool = 1; // 保底至少1点经验

      var char = p.char;
      var attr = char.个人属性 || {};
      var base = attr.基础能力 || {};
      var polian = attr.破限 || false;
      var expAcc = attr.积累经验值 || {};
      if (!attr.积累经验值) attr.积累经验值 = expAcc;

      // 权重：主角用经验权重，冒险者优先经验权重→成长期望，怪物用经验权重
      var weights;
      if (p.isPlayer) {
        weights = attr.经验权重 || { 力量:1, 耐力:1, 灵巧:1, 敏捷:1, 魔力:1 };
      } else if (p.isMonster) {
        weights = attr.经验权重 || { 力量:1, 耐力:1, 灵巧:1, 敏捷:1, 魔力:1 };
      } else {
        weights = attr.经验权重 || attr.成长期望 || {};
      }
      var wTotal = (weights.力量||0)+(weights.耐力||0)+(weights.灵巧||0)+(weights.敏捷||0)+(weights.魔力||0);
      if (wTotal <= 0) return;

      // 按权重比例分配，余数按权重排序逐个补1
      var dist = { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      var allocated = 0;
      attrKeys.forEach(function(a) {
        var w = weights[a] || 0;
        if (w <= 0) return;
        var share = Math.floor(pool * w / wTotal);
        dist[a] = share;
        allocated += share;
      });
      var remainder = pool - allocated;
      var sorted = attrKeys.slice().sort(function(a,b) { return (weights[b]||0)-(weights[a]||0); });
      for (var ri = 0; remainder > 0 && ri < sorted.length; ri++) {
        var a = sorted[ri];
        if ((weights[a] || 0) > 0) {
          dist[a] += 1;
          remainder--;
        }
      }

      // 战斗阶段稀释 + 累加
      var dilutedTotal = 0;
      if (p.isMonster) {
        // 怪物：经验直接加到基础能力
        attrKeys.forEach(function(a) {
          var e = dist[a];
          if (e > 0) {
            var bv = base[a] || 0;
            if (bv >= 2000) e = Math.floor(e / 1000);
            else if (bv >= 1500) e = Math.floor(e / 100);
            else if (bv >= 1200) e = Math.floor(e / 10);
          }
          dilutedTotal += e;
          base[a] = (base[a] || 0) + e;
        });
      } else {
        // 冒险者：经验积累到积累经验值
        attrKeys.forEach(function(a) {
          var e = dist[a];
          if (e > 0) {
            var bv = base[a] || 0;
            if (bv >= 2000) e = Math.floor(e / 1000);
            else if (bv >= 1500) e = Math.floor(e / 100);
            else if (bv >= 1200) e = Math.floor(e / 10);
          }
          dilutedTotal += e;
          expAcc[a] = (expAcc[a] || 0) + e;
        });
        // 伟业换算（仅冒险者/主角）
        if (dilutedTotal > 0) {
          var feats = Math.floor(dilutedTotal / featDivisor);
          if (feats > 0) {
            var curFeat = attr.当前伟业 || 0;
            attr.当前伟业 = Math.round((curFeat + feats) * 10) / 10;
          }
        }
      }
    });

    // 5. 重置所有参与者经验权重
    participants.forEach(function(p) {
      var attr = p.char.个人属性;
      if (attr) {
        attr.经验权重 = { 力量:1, 耐力:1, 灵巧:1, 敏捷:1, 魔力:1 };
      }
    });

    // 6. 清空敌人
    data.敌人信息 = [];
  };

  // ==================== MVU 直接操作函数 ====================

  // ---------- 更新敌人经验（Mvu 直接操作版）----------
  cmd.updateEnemyExp = function(messageId) {
    try {
      const Mvu = window.top.Mvu;
      if (!Mvu) { console.warn("[updateEnemyExp] MVU 未就绪"); return null; }

      const mid = messageId != null
        ? messageId
        : (typeof window.top.getCurrentMessageId === "function"
          ? window.top.getCurrentMessageId()
          : null);
      if (mid == null) { console.warn("[updateEnemyExp] 无法获取楼层ID"); return null; }

      const vars = Mvu.getMvuData({ type: "message", message_id: mid });
      if (!vars || !_.has(vars, "stat_data")) { console.warn("[updateEnemyExp] stat_data 不存在"); return null; }

      const sd = vars.stat_data;
      const enemies = sd.敌人信息;
      if (!enemies || enemies.length === 0) return enemies || [];

      const sysbox = sd.sysbox || {};
      const area = sd.当前地下城区域 || {};
      const floor = area.层数 || 1;

      const allies = [sd.主角];
      const partyMap = sd.组队成员 || {};
      const npcList = sd.人物名录 || {};
      for (const name of Object.keys(partyMap)) {
        const npc = npcList[name];
        if (npc) allies.push(npc);
      }

      const aliveEnemies = enemies.filter(function(e) { return !e.是否击败; });

      const U = window.top.DungeonUtils;
      if (!U || !U.calcEnemyExpFeat || !U.calcEnemyExpPool) { console.warn("[updateEnemyExp] 经验计算函数未就绪"); return enemies; }

      const totalPool = U.calcEnemyExpPool(allies, aliveEnemies, sysbox);

      for (const enemy of enemies) {
        if (enemy.是否击败) continue;

        const result = U.calcEnemyExpFeat(enemy, aliveEnemies, allies, sysbox, floor, totalPool);
        enemy.结算经验 = Math.max(1, result.exp);
        enemy.结算伟业 = result.feat;
      }

      cmd.saveData(vars, { type: "message", message_id: mid });
      return enemies;
    } catch (e) {
      console.error("[updateEnemyExp] 错误:", e);
      return null;
    }
  };

  // ---------- 批量删除角色（Mvu 直接操作版）----------
  cmd.removeCharactersFromDirectory = async function(names, messageId) {
    try {
      const Mvu = window.top.Mvu;
      if (!Mvu || !names || !names.length) return false;

      const mid = messageId != null
        ? messageId
        : (typeof window.top.getCurrentMessageId === "function"
          ? window.top.getCurrentMessageId()
          : null);
      if (mid == null) { console.warn("[removeCharactersFromDirectory] 无法获取消息ID"); return false; }

      const vars = Mvu.getMvuData({ type: "message", message_id: mid });
      const sd = vars?.stat_data;
      if (!sd) return false;

      let changed = false;
      names.forEach(function(name) {
        if (sd.人物名录?.[name]) { _.unset(sd, "人物名录." + name); changed = true; }
        if (sd.组队成员?.[name]) { _.unset(sd, "组队成员." + name); changed = true; }
      });

      if (changed) { await cmd.saveData(vars, { type: "message", message_id: mid }); return true; }
      return false;
    } catch (e) {
      console.error("[removeCharactersFromDirectory] 错误:", e);
      return false;
    }
  };

