  // ---------- 一键检定全部技能（编排函数）----------
  cmd.rollAllStatusSkills = function(buttonEl) {
    try {
      var raw = buttonEl.dataset.skillConfig;
      var decoded;
      try { decoded = decodeURIComponent(raw); } catch(e) { decoded = raw; }
      var configs = JSON.parse(decoded);
      if (!configs || !configs.length) { alert("无技能可检定。"); return; }

      var mid = configs[0]._mid;
      if (mid == null) { alert("无法获取消息ID，请刷新后重试。"); return; }

      var Mvu = window.top.Mvu;
      if (!Mvu) { alert("MVU 未就绪，请刷新后重试。"); return; }

      var vars = Mvu.getMvuData({ type: "message", message_id: mid });
      var sd = vars?.stat_data;
      if (!sd) { alert("无法读取变量数据。"); return; }

      var U = window.top.DungeonUtils;
      if (!U || !U.rollSkillValues) { alert("DungeonUtils 未就绪。"); return; }

      var results = [];
      for (var i = 0; i < configs.length; i++) {
        var c = configs[i];
        var gradeKey = c.is_upgrade ? c.new_grade : c.grade;
        var gradeConfig = sd.sysbox?.技能系统?.等级配置?.[gradeKey];
        if (!gradeConfig) { alert("未找到等级 " + gradeKey + " 的配置（技能：" + c.name + "）"); return; }
        var rollConfig = {
          name: c.name, type: c.type,
          grade: c.is_upgrade ? c.new_grade : c.grade,
          skill_type: c.skill_type, dims: c.dims,
          damage_type: c.damage_type, damage_types: c.damage_types,
          heal_types: c.heal_types, cost_types: c.cost_types,
          desc: c.desc,
        };
        results.push({ config: c, rolled: U.rollSkillValues(rollConfig, gradeConfig) });
      }

      var origText = buttonEl.textContent;
      buttonEl.disabled = true;
      buttonEl.textContent = "...";

      var self = this;
      self._showBatchPreview(results).then(function(confirmed) {
        if (!confirmed) {
          buttonEl.disabled = false;
          buttonEl.textContent = origText;
          return;
        }
        var allOk = true;
        for (var i = 0; i < results.length; i++) {
          var r = results[i];
          if (!self.writeRolledSkill(mid, r.config.char_name, r.config.name, r.rolled)) allOk = false;
        }
        if (allOk) {
          buttonEl.textContent = "✓";
          buttonEl.disabled = true;
          buttonEl.style.background = "#2a2430";
          buttonEl.style.borderColor = "#9b7bb5";
          buttonEl.style.color = "#ffe066";
          // 同时禁用所有单个按钮
          var panel = buttonEl.closest(".status-panel");
          var btns = panel ? panel.querySelectorAll(".skill-roll-btn") : [];
          for (var j = 0; j < btns.length; j++) {
            btns[j].disabled = true;
            btns[j].textContent = "✓";
            btns[j].style.background = "#2a2430";
            btns[j].style.borderColor = "#9b7bb5";
            btns[j].style.color = "#ffe066";
          }
        } else {
          alert("部分技能写入失败，请检查。");
          buttonEl.disabled = false;
          buttonEl.textContent = origText;
        }
      }).catch(function(err) {
        console.error("[rollAllStatusSkills] Promise失败:", err);
        alert("技能检定失败: " + (err && err.message ? err.message : String(err)));
        buttonEl.disabled = false;
        buttonEl.textContent = origText;
      });
    } catch (e) {
      console.error("[rollAllStatusSkills] 错误:", e);
      alert("技能检定失败: " + e.message);
      buttonEl.disabled = false;
      buttonEl.textContent = "🎲 一键检定全部技能";
    }
  };

  // ---------- 技能roll结果写入（Mvu 直接操作版）----------
  cmd.writeRolledSkill = function(messageId, charName, skillName, skillData) {
    try {
      var Mvu = window.top.Mvu;
      if (!Mvu) { console.warn("[writeRolledSkill] MVU 未就绪"); return false; }

      if (messageId == null) { console.warn("[writeRolledSkill] 无法获取消息ID"); return false; }

      var vars = Mvu.getMvuData({ type: "message", message_id: messageId });
      var sd = vars?.stat_data;
      if (!sd) return false;

      var target;
      var protagonistName = sd.主角?.基础信息?.姓名;
      if (charName === "主角" || charName === protagonistName) {
        target = sd.主角;
      } else if (sd.人物名录 && sd.人物名录[charName]) {
        target = sd.人物名录[charName];
      }
      if (!target) { console.warn("[writeRolledSkill] 目标角色不存在: " + charName); return false; }

      if (!target.基础信息) target.基础信息 = {};
      if (!target.基础信息.技能列表) target.基础信息.技能列表 = {};

      if (target.基础信息.技能列表[skillName]) {
        delete target.基础信息.技能列表[skillName];
      }
      target.基础信息.技能列表[skillName] = skillData;

      cmd.saveData(vars, { type: "message", message_id: messageId });
      return true;
    } catch (e) {
      console.error("[writeRolledSkill] 错误:", e);
      return false;
    }
  };

