      console.error("[rollStatusSkill] 错误:", e);
      alert("技能检定失败: " + e.message);
      buttonEl.disabled = false;
      buttonEl.textContent = "🎲";
    }
  };

  // ==================== transform 版 handler（操作 data 对象）====================

  // ---------- 装备生成 ----------
  cmd.handle装备生成 = function(instruction, data) {
    const equipConfig = data.sysbox?.装备系统?.品质配置;
    if (!equipConfig) return;
    const qualityConfig = equipConfig[instruction.品质];
    if (!qualityConfig) return;

    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const char = target.char;

    // 构建装备加成（五维）— 存储系数，与 sysbox 装备编辑器一致
    var bonus = {};
    if (Array.isArray(instruction.加成维度)) {
      instruction.加成维度.forEach(function(stat) {
        var coeffMin = qualityConfig.加成最低 || 0;
        var coeffMax = qualityConfig.加成最高 || 0;
        var coeff = coeffMax > coeffMin
          ? coeffMin + Math.random() * (coeffMax - coeffMin)
          : coeffMin;
        bonus[stat] = Math.round(coeff * 100) / 100;
      });
    }

    // 组装 InventoryItem（描述与效果描述分开存储）
    var item = {
      名称: instruction.名称,
      数量: 1,
      描述: instruction.物品描述 || "",
      效果描述: instruction.效果描述 || "",
      品质: instruction.品质,
      类别: instruction.类别 || "装备",
      单价: instruction.价格 || 0,
      装备属性: {
        部位: instruction.部位,
        加成: bonus,
      },
    };
    if (instruction.效果名称) item.装备属性.效果名称 = instruction.效果名称;

    // 直接装备：不入持有物品，直接把旧装备放回背包
    if (instruction.直接装备) {
      var slot = instruction.部位;
      if (!EQUIP_SLOTS.includes(slot) && slot !== "特殊") {
        throw new Error(
          "无效的装备部位 \"" + slot + "\"。有效部位: " + EQUIP_SLOTS.concat(["特殊"]).join("、")
        );
      }
      if (!char.装备栏) char.装备栏 = {};
      if (slot === "特殊") {
        if (!Array.isArray(char.装备栏.特殊)) char.装备栏.特殊 = [];
        char.装备栏.特殊.push(item);
      } else {
        var oldItem = char.装备栏[slot];
        char.装备栏[slot] = item;
        if (oldItem && oldItem.名称) {
          addToInventory(char, oldItem);
        }
      }
    } else {
      // 不直接装备：放入持有物品
      if (!char.持有物品) char.持有物品 = {};
      addToInventory(char, item);
    }
  };

  // ---------- 技能生成 ----------
  cmd.handle技能生成 = function(instruction, data) {
    var skillConfig = data.sysbox?.技能系统?.等级配置;
    if (!skillConfig) return;
    var gradeConfig = skillConfig[instruction.等级];
    if (!gradeConfig) return;

    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const char = target.char;

    // 构建加成对象（存储系数/比例，非绝对值）
    var bonus = {};
    if (Array.isArray(instruction.加成维度) && instruction.加成维度.length > 0) {
      instruction.加成维度.forEach(function(stat) {
        var coeffMin = gradeConfig.加成最低 || 0;
        var coeffMax = gradeConfig.加成最高 || 0;
        var coeff = coeffMax > coeffMin
          ? coeffMin + Math.random() * (coeffMax - coeffMin)
          : coeffMin;
        bonus[stat] = Math.round(coeff * 100) / 100;
      });
    }

    // 主动技能：数组驱动 roll 消耗、伤害、回复
    var damageRatio = 0, mpCost = 0, spCost = 0;
    var hpHeal = 0, spHeal = 0, mpHeal = 0;
    if (instruction.技能类型 === "主动") {
      var rollRange = function(lo, hi) { return hi > lo ? Math.round((lo + Math.random() * (hi - lo)) * 100) / 100 : lo; };

      // 消耗：不传默认 ["SP","MP"]
      var costTypes = instruction.消耗类型;
      if (!Array.isArray(costTypes) || costTypes.length === 0) costTypes = ["SP","MP"];
      if (costTypes.includes("SP")) {
        spCost = rollRange(gradeConfig.消耗SP最低 || 0, gradeConfig.消耗SP最高 || 0);
      }
      if (costTypes.includes("MP")) {
        mpCost = rollRange(gradeConfig.消耗MP最低 || 0, gradeConfig.消耗MP最高 || 0);
      }

      // 伤害：数组有值就 roll
      var dmgTypes = instruction.伤害类型;
      if (Array.isArray(dmgTypes) && dmgTypes.length > 0) {
        damageRatio = instruction.伤害比例 != null
          ? instruction.伤害比例
          : rollRange(gradeConfig.伤害比例最低 || 0, gradeConfig.伤害比例最高 || 0);
      }

      // 恢复：数组有值就 roll 对应资源
      var healTypes = instruction.恢复类型;
      if (Array.isArray(healTypes) && healTypes.length > 0) {
        if (healTypes.includes("HP")) {
          hpHeal = rollRange(gradeConfig.回复HP最低 || 0, gradeConfig.回复HP最高 || 0);
        }
        if (healTypes.includes("SP")) {
          spHeal = rollRange(gradeConfig.回复SP最低 || 0, gradeConfig.回复SP最高 || 0);
        }
        if (healTypes.includes("MP")) {
          mpHeal = rollRange(gradeConfig.回复MP最低 || 0, gradeConfig.回复MP最高 || 0);
        }
        // 吸收减半：同时有伤害和恢复
        if (damageRatio > 0) {
          hpHeal = Math.round(hpHeal * 50) / 100;
          spHeal = Math.round(spHeal * 50) / 100;
          mpHeal = Math.round(mpHeal * 50) / 100;
        }
      }
    }

    // 组装完整技能对象
    var skillName = instruction.名称;
    var skill = {
      名称: skillName,
      类型: instruction.类型,
      等级: instruction.等级,
      效果描述: instruction.效果描述 || "",
      技能类型: instruction.技能类型,
      消耗MP百分比: mpCost,
      消耗SP百分比: spCost,
      伤害比例: damageRatio,
      回复HP比例: hpHeal,
      回复SP比例: spHeal,
      回复MP比例: mpHeal,
    };
    if (Object.keys(bonus).length > 0) {
      skill.加成 = bonus;
    }

    // 写入目标角色的技能列表
    if (!char.基础信息) char.基础信息 = {};
    if (!char.基础信息.技能列表) char.基础信息.技能列表 = {};
    if (char.基础信息.技能列表[skillName]) {
      delete char.基础信息.技能列表[skillName];
    }
    char.基础信息.技能列表[skillName] = skill;
  };

  // ---------- 物品添加 ----------
  cmd.handle物品添加 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const char = target.char;

    var item = {
      名称: instruction.名称,
      数量: instruction.数量 || 1,
      描述: instruction.物品描述 || "",
      效果描述: instruction.效果描述 || "",
      品质: instruction.品质 || 1,
      类别: instruction.类别 || "杂物",
      单价: instruction.价格 || 0,
    };
    if (instruction.类别 === "消耗品") {
      const consumableConfig = data.sysbox?.消耗品系统?.品质配置;
      const qc = consumableConfig?.[instruction.品质 || 1];
      const restoreTypes = instruction.恢复类型 || ["HP"];
      if (qc) {
        item.消耗效果 = {
          回复HP百分比: restoreTypes.includes("HP") ? (qc.回复HP || 0) : 0,
          回复SP百分比: restoreTypes.includes("SP") ? (qc.回复SP || 0) : 0,
          回复MP百分比: restoreTypes.includes("MP") ? (qc.回复MP || 0) : 0,
        };
      } else {
        item.消耗效果 = { 回复HP百分比: 0, 回复SP百分比: 0, 回复MP百分比: 0 };
      }
    }

    addToInventory(char, item);
  };

  // ---------- 物品增减 ----------
  cmd.handle物品增减 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const char = target.char;

    const itemName = instruction.物品名称;
    const delta = instruction.数量 || 0;
    if (!itemName || delta === 0) return;

    const found = findInInventory(char, itemName);
    if (found) {
      found.item.数量 = (found.item.数量 || 0) + delta;
      if (found.item.数量 <= 0) {
        delete char.持有物品[itemName];
      }
    } else if (delta > 0) {
      if (!char.持有物品) char.持有物品 = {};
      char.持有物品[itemName] = {
        名称: itemName,
        数量: delta,
        描述: instruction.物品描述 || "",
        品质: instruction.品质 || 1,
        类别: instruction.类别 || "杂物",
        单价: instruction.价格 || 0,
      };
    }
  };

  // ---------- 更新敌人经验（transform 版）----------
  cmd.handle更新敌人经验 = function(instruction, data) {
    const enemies = data.敌人信息;
    if (!enemies || enemies.length === 0) return;

    const sysbox = data.sysbox || {};
    const area = data.当前地下城区域 || {};
    const floor = area.层数 || 1;

    const allies = [data.主角];
    const partyMap = data.组队成员 || {};
    const npcList = data.人物名录 || {};
    for (const name of Object.keys(partyMap)) {
      const npc = npcList[name];
      if (npc) allies.push(npc);
    }

    const aliveEnemies = enemies.filter(function(e) { return !e.是否击败; });

    const U = window.top.DungeonUtils;
    if (!U || !U.calcEnemyExpFeat || !U.calcEnemyExpPool) return;

    const totalPool = U.calcEnemyExpPool(allies, aliveEnemies, sysbox);

    for (const enemy of enemies) {
      if (enemy.是否击败) continue;

      const result = U.calcEnemyExpFeat(enemy, aliveEnemies, allies, sysbox, floor, totalPool);
      enemy.结算经验 = Math.max(1, result.exp);
      enemy.结算伟业 = result.feat;
    }
  };

  // ---------- 删除角色（transform 版）----------
  cmd.handle删除角色 = function(instruction, data) {
    const names = instruction.名单;
    if (!names || !names.length) return;

    names.forEach(function(name) {
      if (data.人物名录?.[name]) delete data.人物名录[name];
      if (data.组队成员?.[name]) delete data.组队成员[name];
    });
  };

  // ---------- 状态变动 ----------
  cmd.handle状态变动 = function(instruction, data) {
    const targetName = instruction.目标;
    if (!targetName) return;

    // 敌人目标："敌人N" 格式
    const enemyMatch = /^敌人(\d+)$/.exec(targetName);
    if (enemyMatch) {
      const idx = parseInt(enemyMatch[1], 10);
      const enemy = data.敌人信息?.[idx];
      if (!enemy) return;
      const st = ensurePath(enemy, "状态", {});
      if (instruction.HP变动 != null) st.HP变动百分比 = (st.HP变动百分比 || 0) + instruction.HP变动;
      if (instruction.SP变动 != null) st.SP变动百分比 = (st.SP变动百分比 || 0) + instruction.SP变动;
      if (instruction.MP变动 != null) st.MP变动百分比 = (st.MP变动百分比 || 0) + instruction.MP变动;
      return;
    }

    const target = resolveTarget(targetName, data);
    if (!target) return;
    const st = ensurePath(target.char, "状态", {});

    if (instruction.HP变动 != null) st.HP变动百分比 = (st.HP变动百分比 || 0) + instruction.HP变动;
    if (instruction.SP变动 != null) st.SP变动百分比 = (st.SP变动百分比 || 0) + instruction.SP变动;
    if (instruction.MP变动 != null) st.MP变动百分比 = (st.MP变动百分比 || 0) + instruction.MP变动;

    // 身体状况：仅人物名录角色
    if (instruction.身体状况变动 != null && !target.isPlayer) {
      st.身体状况 = Math.max(0, Math.min(100, (st.身体状况 ?? 100) + instruction.身体状况变动));
    }

    // 灵魂纯洁度：仅主角
    if (instruction.灵魂纯洁度变动 != null && target.isPlayer) {
      st.灵魂纯洁度 = Math.max(-100, Math.min(100, (st.灵魂纯洁度 ?? 0) + instruction.灵魂纯洁度变动));
    }

    // 声誉值：仅主角
    if (instruction.声誉值变动 != null && target.isPlayer) {
      st.声誉值 = (st.声誉值 || 0) + instruction.声誉值变动;
    }
  };

  // ---------- 存款变更 ----------
  cmd.handle存款变更 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const delta = instruction.变动;
    if (delta == null || delta === 0) return;
    const assets = ensurePath(target.char, "基础信息.资产", { 存款: 0 });
    assets.存款 = (assets.存款 || 0) + delta;
  };

  // ---------- 属性设置 ----------
  cmd.handle属性设置 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const attr = ensurePath(target.char, "个人属性", {});
    const type = target.char.基础信息?.类型 || "NPC";

    if (instruction.到达层数 != null) attr.到达层数 = instruction.到达层数;
    if (instruction.破限 != null) attr.破限 = instruction.破限;
    if (instruction.身份职业 != null) attr.身份职业 = instruction.身份职业;
    if (instruction.移除身份职业 != null && Array.isArray(instruction.移除身份职业) && attr.身份职业) {
      const removeSet = {};
      instruction.移除身份职业.forEach(function(s) { removeSet[s] = true; });
      attr.身份职业 = attr.身份职业.filter(function(s) { return !removeSet[s]; });
    }
    if (instruction.所属眷族 != null) attr.所属眷族 = instruction.所属眷族;

    // 成长期望：仅冒险者
    if (instruction.成长期望 != null && type === "冒险者") {
      attr.成长期望 = Object.assign({}, instruction.成长期望);
    }

    // 伟业变动：仅冒险者
    if (instruction.伟业变动 != null && (type === "冒险者" || type === "主角")) {
      attr.当前伟业 = Math.round(((attr.当前伟业 || 0) + instruction.伟业变动) * 10) / 10;
    }
  };

  // ---------- 经验积累 ----------
  cmd.handle经验积累 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const type = target.char.基础信息?.类型 || "NPC";
    if (type === "NPC") return;
    const attr = ensurePath(target.char, "个人属性", {});
    const exp = ensurePath(attr, "积累经验值", {});

    FIVE_KEYS.forEach(function(k) {
      const v = instruction[k];
      if (v != null && v > 0) {
        exp[k] = (exp[k] || 0) + v;
      }
    });
  };

  // ---------- 角色信息 ----------
  cmd.handle角色信息 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target) return;
    const info = ensurePath(target.char, "基础信息", {});

    if (instruction.负面状态 != null) info.负面状态 = instruction.负面状态;
    if (instruction.移除负面状态 != null && Array.isArray(instruction.移除负面状态) && info.负面状态) {
      const removeSet = {};
      instruction.移除负面状态.forEach(function(s) { removeSet[s] = true; });
      info.负面状态 = info.负面状态.filter(function(s) { return !removeSet[s]; });
    }
    if (instruction.所在位置 != null && !target.isPlayer) info.所在位置 = instruction.所在位置;
    if (instruction.心境 != null && !target.isPlayer) info.心境 = instruction.心境;
    if (instruction.评价 != null && !target.isPlayer) {
      const st = ensurePath(target.char, "状态", {});
      st.评价 = instruction.评价;
    }

    // 称号：仅主角
    if (instruction.称号 != null && target.isPlayer) {
      target.char.称号 = instruction.称号;
    }
  };

  // ---------- 关系变更 ----------
  cmd.handle关系变更 = function(instruction, data) {
    const target = resolveTarget(instruction.目标, data);
    if (!target || target.isPlayer) return;
    const rel = ensurePath(target.char, "关系", { 当前关系: "陌生", 情深值: 0 });

    if (instruction.情深变动 != null) {
      rel.情深值 = Math.round(Math.max(-100, Math.min(100, (rel.情深值 || 0) + instruction.情深变动)) * 100) / 100;
    }
    if (instruction.当前关系 != null) {
      rel.当前关系 = instruction.当前关系;
    }
  };

  // ---------- 眷族设置 ----------
  cmd.handle眷族设置 = function(instruction, data) {
    const fam = ensurePath(data, "眷族情况", {});
    if (instruction.据点 != null) fam.据点 = instruction.据点;
    if (instruction.眷族等级 != null) fam.眷族等级 = instruction.眷族等级;
    if (instruction.到达层数 != null) fam.到达层数 = instruction.到达层数;
    if (instruction.财务变动 != null) {
      fam.财务 = (fam.财务 || 0) + instruction.财务变动;
    }
  };

  // ---------- 地下城设置 ----------
  cmd.handle地下城设置 = function(instruction, data) {
    const area = ensurePath(data, "当前地下城区域", {});
    if (instruction.层数 != null) {
      area.层数 = instruction.层数;
      area.怪物 = [];  // 换层或离开时一律清空旧怪物
    }
    if (instruction.怪物 != null) {
      area.怪物 = instruction.怪物;
    }
  };

  // ---------- 角色创建 ----------
  cmd.handle角色创建 = function(instruction, data) {
    const name = instruction.目标;
    if (!name || name === "主角") return;
    if (instruction._skip) return; // augmentInstruction 标记跳过
    if (!data.人物名录) data.人物名录 = {};
    if (data.人物名录[name]) return; // 已存在，不覆盖

    const charType = instruction.角色类型 || "NPC";
    const npc = {};
    data.人物名录[name] = npc;

    // Step 1: 基础信息
    npc.基础信息 = {
      姓名: name,
      类型: charType,
      种族: instruction.种族 || "人类",
      性别: instruction.性别 || "未知",
      性格: instruction.性格 || [],
      样貌: instruction.样貌 || "",
      发型: instruction.发型 || "",
      身材: instruction.身材 || "",
      服装: instruction.服装 || "",
      气质: instruction.气质 || "",
      心境: instruction.心境 || "平静",
      所在位置: instruction.所在位置 || "未知",
      资产: { 存款: instruction.存款 || 0 },
      负面状态: instruction.负面状态 || [],
      技能列表: {},
    };
    if (charType === "怪物" && instruction.稀有度) {
      npc.基础信息.稀有度 = instruction.稀有度;
    }

    // Step 2: 状态
    npc.状态 = {};
    if (instruction.评价) npc.状态.评价 = instruction.评价;

    // Step 3: 个人属性
    const attr = {
      所属眷族: instruction.所属眷族 || "",
      身份职业: instruction.身份职业 || [],
      到达层数: instruction.到达层数 || 0,
    };
    if (charType === "冒险者") {
      attr.等级 = instruction.等级 || 0;
      attr.基础能力 = instruction.基础能力 || { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      attr.潜在能力 = { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      attr.积累经验值 = instruction.积累经验值 || { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      attr.当前伟业 = 0;
      attr.成长期望 = instruction.成长期望 || { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      attr.破限 = instruction.破限 || false;
    } else if (charType === "怪物") {
      attr.等级 = instruction.等级 || 1;
      attr.基础能力 = instruction.基础能力 || { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      attr.潜在能力 = { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      attr.积累经验值 = instruction.积累经验值 || { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
      attr.当前伟业 = 0;
    }
    // NPC: 仅含 所属眷族/身份职业/到达层数，不含能力字段
    npc.个人属性 = attr;

    // Step 4: 关系
    npc.关系 = {
      当前关系: instruction.当前关系 || "陌生",
      情深值: instruction.情深值 || 0,
    };

    // Step 5: 模板附带的技能/装备/物品（仅来自世界书模板）
    if (instruction._fromTemplate && instruction._templateExtra) {
      var extra = instruction._templateExtra;

      // 5a: 技能列表 — 逐条调用 handle技能生成 以应用等级配置
      var skillList = extra.技能列表;
      if (skillList) {
        var skillNames = Object.keys(skillList);
        for (var si = 0; si < skillNames.length; si++) {
          var skName = skillNames[si];
          var skMeta = skillList[skName];
          cmd.handle技能生成({
            指令: "技能生成",
            目标: name,
            名称: skName,
            类型: skMeta.类型,
            等级: skMeta.等级,
            技能类型: skMeta.技能类型,
            效果描述: skMeta.效果描述 || "",
            加成维度: skMeta.加成维度 || [],
            伤害类型: skMeta.伤害类型 || [],
            消耗类型: skMeta.消耗类型 || [],
            恢复类型: skMeta.恢复类型 || [],
          }, data);
        }
      }

      // 5b: 装备栏 — 逐条调用 handle装备生成（直接装备模式）
      var equipSlots = extra.装备栏;
      if (equipSlots) {
        var slotNames = Object.keys(equipSlots);
        for (var ei = 0; ei < slotNames.length; ei++) {
          var slot = slotNames[ei];
          var eqMeta = equipSlots[slot];
          if (!eqMeta || !eqMeta.名称) continue;
          cmd.handle装备生成({
            指令: "装备生成",
            目标: name,
            名称: eqMeta.名称,
            品质: eqMeta.品质 != null ? eqMeta.品质 : 1,
            部位: eqMeta.部位 || slot,
            类别: eqMeta.类别 || "装备",
            加成维度: eqMeta.加成维度 || [],
            价格: eqMeta.价格 || 0,
            物品描述: eqMeta.物品描述 || "",
            效果名称: eqMeta.效果名称 || null,
            直接装备: true,
          }, data);
        }
      }

      // 5c: 持有物品 — 逐条调用 handle物品添加
      var items = extra.持有物品;
      if (items) {
        var itemNames = Object.keys(items);
        for (var ii = 0; ii < itemNames.length; ii++) {
          var itName = itemNames[ii];
          var itMeta = items[itName];
          if (!itMeta) continue;
          cmd.handle物品添加({
            指令: "物品添加",
            目标: name,
            名称: itMeta.名称 || itName,
            数量: itMeta.数量 || 1,
            品质: itMeta.品质 || 1,
            类别: itMeta.类别 || "杂物",
            单价: itMeta.单价 || 0,
          }, data);
        }
      }
    }
  };

  // ---------- 敌人创建 ----------
  cmd.handle敌人创建 = function(instruction, data) {
    const enemyName = instruction.姓名;
    if (!enemyName) return;
    if (!data.敌人信息) data.敌人信息 = [];

    // Priority 1: 从人物名录已有角色复制为敌人
    if (instruction._fromCharacter && instruction._charData) {
      var src = instruction._charData;
      var srcInfo = src.基础信息 || {};
      var srcAttr = src.个人属性 || {};
      var srcStatus = src.状态 || {};

      // 深拷贝基础能力
      var copiedStats = {};
      var srcBase = srcAttr.基础能力 || {};
      FIVE_KEYS.forEach(function(k) { copiedStats[k] = srcBase[k] || 0; });

      var enemy = {
        基础信息: {
          姓名: enemyName,
          类型: srcInfo.类型 || "冒险者",
          种族: srcInfo.种族 || "未知",
          稀有度: instruction.稀有度 || "精英",
          技能列表: srcInfo.技能列表 ? JSON.parse(JSON.stringify(srcInfo.技能列表)) : {},
        },
        状态: {
          HP上限: srcStatus.HP上限 || 500,
          SP上限: srcStatus.SP上限 || 100,
          MP上限: srcStatus.MP上限 || 100,
          HP当前值: srcStatus.HP上限 || 500,
          SP当前值: srcStatus.SP上限 || 100,
          MP当前值: srcStatus.MP上限 || 100,
        },
        个人属性: {
          等级: srcAttr.等级 || instruction.等级 || 1,
          基础能力: copiedStats,
          成长期望: srcAttr.成长期望 ? Object.assign({}, srcAttr.成长期望) : { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
          潜在能力: { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
          积累经验值: { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
          当前伟业: 0,
        },
        是否击败: false,
      };

      // 复制装备栏
      if (src.装备栏) {
        enemy.装备栏 = JSON.parse(JSON.stringify(src.装备栏));
      }

      data.敌人信息.push(enemy);
      return;
    }

    // Priority 2/3/4: 模板数据或AI数据构建敌人
    // 类型：AI传入角色类型 > 模板类别推断 > 默认怪物
    var enemyType = instruction.角色类型
      || (instruction._templateCategory === "character" ? "冒险者" : null)
      || "怪物";
    // 成长期望：模板 > AI传入 > 默认全零
    var growth = { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 };
    if (instruction._templateCategory === "character" && instruction._templateExtra && instruction._templateExtra.成长期望) {
      growth = Object.assign({}, instruction._templateExtra.成长期望);
    } else if (enemyType === "冒险者" && instruction.成长期望) {
      growth = Object.assign({}, instruction.成长期望);
    }
    var enemy = {
      基础信息: {
        姓名: enemyName,
        类型: enemyType,
        种族: instruction.种族 || "未知",
        稀有度: instruction.稀有度 || (enemyType === "冒险者" ? "精英" : "普通"),
        技能列表: {},
      },
      状态: {},
      个人属性: {
        等级: instruction.等级 || 1,
        基础能力: instruction.基础能力 || { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
        成长期望: growth,
        潜在能力: { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
        积累经验值: { 力量:0, 耐力:0, 灵巧:0, 敏捷:0, 魔力:0 },
        当前伟业: 0,
      },
      是否击败: false,
    };
    data.敌人信息.push(enemy);

    // 模板附带的技能列表
    if (instruction._fromTemplate && instruction._templateExtra) {
      var skillList = instruction._templateExtra.技能列表;
      if (skillList) {
        var skillNames = Object.keys(skillList);
        for (var si = 0; si < skillNames.length; si++) {
          var skName = skillNames[si];
          var skMeta = skillList[skName];
          // 直接构建技能对象（敌人不需要写入人物名录，就地构建）
          var skillObj = {
            名称: skName,
            类型: skMeta.类型 || "技能",
            等级: skMeta.等级 || "I",
            效果描述: skMeta.效果描述 || "",
            技能类型: skMeta.技能类型 || "主动",
          };
          // roll 数值
          var gradeConfig = data.sysbox?.技能系统?.等级配置;
          if (gradeConfig) {
            var gc = gradeConfig[skillObj.等级];
            if (gc) {
              var bonus = {};
              var dims = skMeta.加成维度 || [];
              for (var di = 0; di < dims.length; di++) {
                var stat = dims[di];
                var cMin = gc.加成最低 || 0;
                var cMax = gc.加成最高 || 0;
                bonus[stat] = Math.round((cMax > cMin ? cMin + Math.random() * (cMax - cMin) : cMin) * 100) / 100;
              }
              if (Object.keys(bonus).length > 0) skillObj.加成 = bonus;

              if (skillObj.技能类型 === "主动") {
                var costTypes = skMeta.消耗类型 || [];
                var dmgTypes = skMeta.伤害类型 || [];
                var healTypes = skMeta.恢复类型 || [];
                var rollRange = function(lo, hi) { return hi > lo ? Math.round((lo + Math.random() * (hi - lo)) * 100) / 100 : lo; };
                skillObj.消耗SP百分比 = costTypes.includes("SP") ? rollRange(gc.消耗SP最低 || 0, gc.消耗SP最高 || 0) : 0;
                skillObj.消耗MP百分比 = costTypes.includes("MP") ? rollRange(gc.消耗MP最低 || 0, gc.消耗MP最高 || 0) : 0;
                skillObj.伤害比例 = dmgTypes.length > 0 ? rollRange(gc.伤害比例最低 || 0, gc.伤害比例最高 || 0) : 0;
                skillObj.回复HP比例 = healTypes.includes("HP") ? rollRange(gc.回复HP最低 || 0, gc.回复HP最高 || 0) : 0;
                skillObj.回复SP比例 = healTypes.includes("SP") ? rollRange(gc.回复SP最低 || 0, gc.回复SP最高 || 0) : 0;
                skillObj.回复MP比例 = healTypes.includes("MP") ? rollRange(gc.回复MP最低 || 0, gc.回复MP最高 || 0) : 0;
              }
            }
          }
          enemy.基础信息.技能列表[skName] = skillObj;
        }
      }

      // 模板附带的装备栏
      var equipSlots = instruction._templateExtra.装备栏;
      if (equipSlots) {
        enemy.装备栏 = {};
        var slotNames = Object.keys(equipSlots);
        for (var ei = 0; ei < slotNames.length; ei++) {
          var slot = slotNames[ei];
          var eqMeta = equipSlots[slot];
          if (!eqMeta || !eqMeta.名称) continue;
          var eqBonus = {};
          var eqDims = eqMeta.加成维度 || [];
          var qualityConfig = data.sysbox?.装备系统?.品质配置;
          var qc = qualityConfig ? qualityConfig[eqMeta.品质 || 1] : null;
          for (var di = 0; di < eqDims.length; di++) {
            var stat = eqDims[di];
            if (qc) {
              var cMin = qc.加成最低 || 0;
              var cMax = qc.加成最高 || 0;
              eqBonus[stat] = Math.round((cMax > cMin ? cMin + Math.random() * (cMax - cMin) : cMin) * 100) / 100;
            } else {
              eqBonus[stat] = 0;
            }
          }
          enemy.装备栏[slot] = {
            名称: eqMeta.名称,
            数量: 1,
            描述: eqMeta.物品描述 || "",
            效果描述: "",
            品质: eqMeta.品质 || 1,
            类别: eqMeta.类别 || "装备",
            单价: eqMeta.价格 || 0,
            装备属性: {
              部位: eqMeta.部位 || slot,
              加成: eqBonus,
            },
          };
          if (eqMeta.效果名称) enemy.装备栏[slot].装备属性.效果名称 = eqMeta.效果名称;
        }
      }
    }
  };

  // ---------- 敌人移除 ----------
  cmd.handle敌人移除 = function(instruction, data) {
    const target = instruction.目标;
    if (!target || !data.敌人信息?.length) return;

    if (target === "全部") {
      data.敌人信息 = [];
      return;
    }

    const idx = parseInt(target, 10);
    if (isNaN(idx) || idx < 0 || idx >= data.敌人信息.length) return;
    data.敌人信息.splice(idx, 1);
  };

  // ==================== 辅助 getter 函数 ====================

  cmd.getGradeFromValue = function(v) {
    var fn = window.top?.DungeonUtils?.getGrade;
    return fn ? fn(v) : "I";
  };

  cmd.chrName = function(c) { return c?.基础信息?.姓名 || ""; };
  cmd.chrBase = function(c) { return c?.个人属性?.基础能力 || {}; };
  cmd.chrStatus = function(c) { return c?.状态 || {}; };
  cmd.chrInventory = function(c) { return c?.持有物品 || {}; };
  cmd.chrSkills = function(c) { return c?.基础信息?.技能列表 || {}; };
  cmd.chrEquip = function(c) { return c?.装备栏 || {}; };

  // ==================== 指令摘要（供 AI 回顾上轮操作） ====================

  /**
   * 将单条操作指令转为简短摘要字符串
   * @param {object} inst - 操作指令对象
   * @returns {string}
   */
  function summarizeInstruction(inst) {
    if (!inst || !inst.指令) return "";
    const target = inst.目标 || "";
    const parts = [];
    switch (inst.指令) {
      case "状态变动":
        if (inst.HP变动 != null) parts.push("HP " + (inst.HP变动 > 0 ? "+" : "") + inst.HP变动 + "%");
        if (inst.SP变动 != null) parts.push("SP " + (inst.SP变动 > 0 ? "+" : "") + inst.SP变动 + "%");
        if (inst.MP变动 != null) parts.push("MP " + (inst.MP变动 > 0 ? "+" : "") + inst.MP变动 + "%");
        if (inst.身体状况变动 != null) parts.push("身体状况 " + (inst.身体状况变动 > 0 ? "+" : "") + inst.身体状况变动);
        if (inst.灵魂纯洁度变动 != null) parts.push("灵魂纯洁度 " + (inst.灵魂纯洁度变动 > 0 ? "+" : "") + inst.灵魂纯洁度变动);
        if (inst.声誉值变动 != null) parts.push("声誉 " + (inst.声誉值变动 > 0 ? "+" : "") + inst.声誉值变动);
        break;
      case "存款变更":
        if (inst.变动 != null) parts.push((inst.变动 > 0 ? "+" : "") + inst.变动 + " 法利");
        break;
      case "属性设置":
        if (inst.所属眷族 != null) parts.push("眷族→" + inst.所属眷族);
        if (inst.到达层数 != null) parts.push("到达层数→" + inst.到达层数);
        if (inst.破限 != null) parts.push("破限→" + inst.破限);
        if (inst.伟业变动 != null) parts.push("伟业 " + (inst.伟业变动 > 0 ? "+" : "") + inst.伟业变动);
        if (inst.身份职业 != null) parts.push("职业→" + inst.身份职业.join(","));
        if (inst.移除身份职业 != null) parts.push("移除职业: " + inst.移除身份职业.join(","));
        if (inst.成长期望 != null) parts.push("成长期望已设置");
        break;
      case "经验积累":
        FIVE_KEYS.forEach(function(k) {
          if (inst[k] != null && inst[k] > 0) parts.push(k + " +" + inst[k]);
        });
        break;
      case "角色信息":
        if (inst.称号 != null) parts.push("称号→" + inst.称号);
        if (inst.所在位置 != null) parts.push("位置→" + inst.所在位置);
        if (inst.心境 != null) parts.push("心境→" + inst.心境);
        if (inst.评价 != null) parts.push("评价→" + inst.评价);
        if (inst.负面状态 != null) parts.push("负面状态: " + inst.负面状态.join(","));
        if (inst.移除负面状态 != null) parts.push("移除负面: " + inst.移除负面状态.join(","));
        break;
      case "关系变更":
        if (inst.情深变动 != null) parts.push("情深 " + (inst.情深变动 > 0 ? "+" : "") + inst.情深变动);
        if (inst.当前关系 != null) parts.push("关系→" + inst.当前关系);
        break;
      case "眷族设置":
        if (inst.据点 != null) parts.push("据点→" + inst.据点);
        if (inst.财务变动 != null) parts.push("财务 " + (inst.财务变动 > 0 ? "+" : "") + inst.财务变动);
        if (inst.眷族等级 != null) parts.push("等级→" + inst.眷族等级);
        if (inst.到达层数 != null) parts.push("到达层数→" + inst.到达层数);
        break;
      case "地下城设置":
        if (inst.层数 != null) parts.push("进入第" + inst.层数 + "层");
        if (inst.怪物 != null) parts.push(inst.怪物.length + "种怪物");
        break;
      case "角色创建":
        parts.push((inst.角色类型 || "NPC") + " | " + (inst.种族 || "?"));
        if (inst.性别) parts.push(inst.性别);
        if (inst.等级 != null) parts.push("Lv." + inst.等级);
        break;
      case "敌人创建":
        parts.push("Lv." + (inst.等级 || "?") + " | " + (inst.种族 || "?"));
        if (inst.稀有度) parts.push(inst.稀有度);
        break;
      case "敌人移除":
        parts.push("移除 " + (target || "?"));
        break;
      case "敌人被击败":
        parts.push("击败 " + (target || "?"));
        break;
      case "组队加入":
        parts.push((target || "?") + " 加入队伍");
        break;
      case "组队离开":
        parts.push((target || "?") + " 离开队伍");
        break;
      case "队伍解散":
        break;
      case "加入眷族":
        parts.push("主神: " + (inst.主神 || "?"));
        break;
      case "离开眷族":
        break;
      case "装备生成":
        parts.push((inst.名称 || "?") + " | " + (inst.部位 || ""));
        if (inst.品质) parts.push("品质" + inst.品质);
        break;
      case "穿戴装备":
        if (inst.装备名) parts.push("穿戴 " + inst.装备名);
        if (inst.部位) parts.push("→" + inst.部位);
        break;
      case "卸下装备":
        if (inst.部位) parts.push("卸下 " + inst.部位);
        break;
      case "技能生成":
        parts.push((inst.名称 || "?") + " | " + (inst.类型 || ""));
        if (inst.等级) parts.push(inst.等级);
        break;
      case "使用消耗品":
        if (inst.消耗品名称) parts.push(inst.消耗品名称);
        break;
      case "使用技能":
        if (inst.技能名) parts.push(inst.技能名);
        break;
      case "物品添加":
        parts.push((inst.名称 || "?") + " x" + (inst.数量 || 1));
        break;
      case "物品增减":
        parts.push((inst.物品名称 || "?") + " " + (inst.数量 > 0 ? "+" : "") + (inst.数量 || 0));
        break;
      case "物品转移":
        parts.push((inst.物品名称 || "?") + " ← " + (inst.来源 || "?"));
        break;
      case "删除角色":
        break;
      case "更新敌人经验":
        break;
      case "升级":
        break;
      case "获得恩惠":
        break;
      case "恩惠更新":
        break;
      default:
        // 未知指令：列出所有非空参数
        Object.keys(inst).forEach(function(k) {
          if (k === "指令" || k === "目标") return;
          var v = inst[k];
          if (v != null && v !== "" && v !== false) {
            if (Array.isArray(v)) parts.push(k + ": [" + v.join(",") + "]");
            else if (typeof v === "object") parts.push(k + ": {...}");
            else parts.push(k + ": " + v);
          }
        });
    }
    var detail = parts.length > 0 ? " | " + parts.join(" | ") : "";
    var label = target ? (inst.指令 + " → " + target) : inst.指令;
    return label + detail;
  }

  // ==================== 主入口 ====================

  /**
   * 消费 data.操作指令 数组，依次执行每条指令
   * @param {object} data - Zod transform 中的根数据对象（plain object，非 Proxy）
   */
  cmd.processCommands = function(data) {
    if (!data.操作指令 || !Array.isArray(data.操作指令) || data.操作指令.length === 0) return;
    const instructions = [...data.操作指令]; // 浅拷贝防止迭代时修改
    instructions.forEach(instruction => {
      if (!instruction.指令) return;
      try {
        const handler = cmd["handle" + instruction.指令];
        if (!handler) {
          console.warn("[CommandUtils] 未知指令:", instruction.指令);
          return;
        }
        // 目标为数组时自动展开为多条独立指令
        if (Array.isArray(instruction.目标)) {
          instruction.目标.forEach(targetName => {
            handler({ ...instruction, 目标: targetName }, data);
          });
        } else {
          handler(instruction, data);
        }
      } catch (e) {
        console.error("[CommandUtils] 指令执行失败:", instruction.指令, e);
      }
    });
    data.操作指令 = [];
  };

  // ==================== 世界书模板增强 ====================

  /**
   * 在指令执行前，按三级优先级用世界书模板增强指令字段：
   *   人物名录已有角色 → 世界书模板 → AI 提供的数据（指令自带）
   * 角色创建：查 人物名录 跳过 / 世界书人物模板覆盖
   * 敌人创建：查 人物名录 复制 / 世界书人物模板 / 世界书怪物模板 覆盖
   * 装备生成/技能生成：查对应世界书模板覆盖元数据
   * @param {object} inst - 单条操作指令
   * @param {object} data - stat_data 对象
   */
  function augmentInstruction(inst, data) {
    var cmdType = inst.指令;
    if (!cmdType) return;

    if (cmdType === "角色创建") {
      var charName = inst.目标;
      if (!charName || charName === "主角") return;

      // Priority 1: 人物名录已有 → 标记跳过
      if (data.人物名录 && data.人物名录[charName]) {
        inst._skip = true;
        return;
      }

      // Priority 2: 世界书人物模板
      var charTmpl = lookupTemplate(charName, "character");
      if (charTmpl) {
        // 完整覆盖 AI 提供的字段（模板数据优先）
        inst.角色类型 = charTmpl.类型 || inst.角色类型;
        inst.种族 = charTmpl.种族 || inst.种族;
        inst.性别 = charTmpl.性别 || inst.性别;
        inst.性格 = charTmpl.性格 || inst.性格;
        inst.样貌 = charTmpl.样貌 || inst.样貌;
        inst.发型 = charTmpl.发型 || inst.发型;
        inst.身材 = charTmpl.身材 || inst.身材;
        inst.服装 = charTmpl.服装 || inst.服装;
        inst.气质 = charTmpl.气质 || inst.气质;
        if (charTmpl.等级 != null) inst.等级 = charTmpl.等级;
        inst.所属眷族 = charTmpl.所属眷族 || inst.所属眷族;
        inst.身份职业 = charTmpl.身份职业 || inst.身份职业;
        if (charTmpl.到达层数 != null) inst.到达层数 = charTmpl.到达层数;
        if (charTmpl.基础能力) inst.基础能力 = charTmpl.基础能力;
        if (charTmpl.成长期望) inst.成长期望 = charTmpl.成长期望;
        if (charTmpl.破限 != null) inst.破限 = charTmpl.破限;
        inst.当前关系 = charTmpl.当前关系 || inst.当前关系;
        if (charTmpl.情深值 != null) inst.情深值 = charTmpl.情深值;
        inst.存款 = charTmpl.存款 != null ? charTmpl.存款 : inst.存款;
        inst.所在位置 = charTmpl.所在位置 || inst.所在位置;
        inst._fromTemplate = true;
        inst._templateExtra = charTmpl;
        return;
      }
      // Priority 3: AI 数据（指令自带字段，无需处理）
    }

    else if (cmdType === "敌人创建") {
      var enemyName = inst.姓名;
      if (!enemyName) return;

      // Priority 1: 人物名录已有冒险者/怪物 → 标记为从名录复制
      if (data.人物名录 && data.人物名录[enemyName]) {
        var existing = data.人物名录[enemyName];
        var etype = existing.基础信息?.类型;
        if (etype === "冒险者" || etype === "怪物") {
          inst._fromCharacter = true;
          inst._charData = existing;
          return;
        }
      }

      // Priority 2: 世界书人物模板（冒险者作为敌人）— 完整总能力对比，取强者
      var charTmpl = lookupTemplate(enemyName, "character");
      if (charTmpl) {
        var levelCoeff = data.sysbox?.战斗系统?.等级补正?.等级系数 ?? 1000;

        // 计算模板方总能力
        var tplLv = charTmpl.等级 || 0;
        var tplBase = charTmpl.基础能力 || {};
        var tplGrowth = charTmpl.成长期望 || {};
        var tplBonus = tplLv >= 1 ? Math.max((tplLv - 1) * levelCoeff, 200) : 0;
        var tplTotal = 0;
        FIVE_KEYS.forEach(function(k) {
          var pot = Math.floor((Math.max(0, tplLv - 1) * (tplGrowth[k] || 0)) / 2);
          tplTotal += (tplBase[k] || 0) + pot + tplBonus;
        });

        // 计算AI方总能力（含成长期望，若AI未传则为0）
        var aiLv = inst.等级 || 0;
        var aiBase = inst.基础能力 || {};
        var aiGrowth = inst.成长期望 || {};
        var aiBonus = aiLv >= 1 ? Math.max((aiLv - 1) * levelCoeff, 200) : 0;
        var aiTotal = 0;
        FIVE_KEYS.forEach(function(k) {
          var aiPot = Math.floor((Math.max(0, aiLv - 1) * (aiGrowth[k] || 0)) / 2);
          aiTotal += (aiBase[k] || 0) + aiPot + aiBonus;
        });

        if (tplTotal > aiTotal) {
          // 模板更强 → 用模板数据
          inst.种族 = charTmpl.种族 || inst.种族;
          if (charTmpl.等级 != null) inst.等级 = charTmpl.等级;
          if (charTmpl.基础能力) inst.基础能力 = charTmpl.基础能力;
          inst.稀有度 = inst.稀有度 || "精英";
          inst._fromTemplate = true;
          inst._templateExtra = charTmpl;
          inst._templateCategory = "character";
        }
        // AI更强或相等 → 保持AI数据，不覆盖
        return;
      }

      // Priority 3: 地下城数据 — 子串匹配 + 范围校验/重roll
      var floor = data.当前地下城区域?.层数 || 1;
      var dungeonMatch = lookupDungeonMonster(floor, enemyName);
      if (dungeonMatch) {
        var validated = validateAndRollMonster(enemyName, {
          等级: inst.等级,
          基础能力: inst.基础能力 || {},
        }, dungeonMatch);
        inst.等级 = validated.等级;
        inst.基础能力 = validated.基础能力;
        inst.稀有度 = validated.稀有度 || inst.稀有度;
        inst.种族 = validated.种族 || inst.种族;
        inst._fromTemplate = true;
        inst._templateExtra = { 技能列表: validated.技能列表 };
        inst._templateCategory = "dungeon";
        inst._validatedSource = validated.来源;
        return;
      }
      // Priority 4: AI 数据直接使用（无需处理）
    }

    else if (cmdType === "装备生成") {
      var equipName = inst.名称;
      if (!equipName) return;

      var equipTmpl = lookupTemplate(equipName, "equip");
      if (equipTmpl) {
        if (equipTmpl.品质 != null) inst.品质 = equipTmpl.品质;
        inst.部位 = equipTmpl.部位 || inst.部位;
        inst.类别 = equipTmpl.类别 || inst.类别;
        if (equipTmpl.价格 != null) inst.价格 = equipTmpl.价格;
        inst.物品描述 = equipTmpl.物品描述 || inst.物品描述;
        inst.加成维度 = equipTmpl.加成维度 || inst.加成维度;
        inst.效果名称 = equipTmpl.效果名称 || inst.效果名称;
        inst._fromTemplate = true;
      }
    }

    else if (cmdType === "技能生成") {
      var skillName = inst.名称;
      if (!skillName) return;

      var skillTmpl = lookupTemplate(skillName, "skill");
      if (skillTmpl) {
        inst.类型 = skillTmpl.类型 || inst.类型;
        inst.等级 = skillTmpl.等级 || inst.等级;
        inst.技能类型 = skillTmpl.技能类型 || inst.技能类型;
        inst.效果描述 = skillTmpl.效果描述 || inst.效果描述;
        inst.加成维度 = skillTmpl.加成维度 || inst.加成维度;
        inst.伤害类型 = skillTmpl.伤害类型 || inst.伤害类型;
        inst.消耗类型 = skillTmpl.消耗类型 || inst.消耗类型;
        inst.恢复类型 = skillTmpl.恢复类型 || inst.恢复类型;
        inst._fromTemplate = true;
      }
    }

    else if (cmdType === "地下城设置") {
      var aiMonsters = inst.怪物 || [];
      var floor = inst.层数 || (data.当前地下城区域 && data.当前地下城区域.层数) || 1;

      // 获取世界书该楼层的全部怪物数据
      var floorData = (_templateCache && _templateCache.dungeon) ? _templateCache.dungeon[String(floor)] : null;
      var wbNames = floorData ? Object.keys(floorData) : [];
      var aiCount = aiMonsters.length;
      var wbCount = wbNames.length;

      // 辅助：用世界书数据构建单个怪物条目
      function buildMonsterEntry(name, tplData, aiData) {
        var entry = {
          名字: name,
          等级范围: tplData.等级范围 || (aiData ? aiData.等级范围 : null) || {},
          能力值范围: tplData.能力值范围 || (aiData ? aiData.能力值范围 : null) || {},
        };
        if (tplData.稀有度 != null) entry.稀有度 = tplData.稀有度;
        else if (aiData && aiData.稀有度 != null) entry.稀有度 = aiData.稀有度;
        if (tplData.种族 != null) entry.种族 = tplData.种族;
        else if (aiData && aiData.种族 != null) entry.种族 = aiData.种族;

        // 技能列表：AI更丰富用AI，否则世界书覆盖
        var aiSkills = (aiData && aiData.技能列表 && typeof aiData.技能列表 === "object") ? aiData.技能列表 : null;
        if (tplData.技能列表) {
          var tplSkCount = Object.keys(tplData.技能列表).length;
          var aiSkCount = aiSkills ? Object.keys(aiSkills).length : 0;
          entry.技能列表 = aiSkCount > tplSkCount ? aiSkills : tplData.技能列表;
        } else if (aiSkills) {
          entry.技能列表 = aiSkills;
        }
        entry._fromBestiary = true;
        return entry;
      }

      // 辅助：在AI列表中查找匹配某名字的怪物
      function findAiMatch(name) {
        if (!aiMonsters.length) return null;
        for (var j = 0; j < aiMonsters.length; j++) {
          var am = aiMonsters[j];
          if (am.名字 && (am.名字.includes(name) || name.includes(am.名字))) {
            return am;
          }
        }
        return null;
      }

      if (wbCount === 0) {
        // 世界书无此楼层数据 → 保留AI列表，逐个尝试子串匹配补充
        for (var mi = 0; mi < aiMonsters.length; mi++) {
          var m = aiMonsters[mi];
          if (!m.名字) continue;
          var dm = lookupDungeonMonster(floor, m.名字);
          if (dm && dm.data) {
            var merged = buildMonsterEntry(m.名字, dm.data, m);
            // 保留AI原有字段中世界书没有的
            for (var k in m) {
              if (!(k in merged) && m.hasOwnProperty(k)) merged[k] = m[k];
            }
            aiMonsters[mi] = merged;
          }
        }
        return;
      }

      if (aiCount > wbCount) {
        // AI传了更多怪物 → 以AI列表为基底，世界书数据补充/覆盖同名怪物
        for (var mj = 0; mj < aiMonsters.length; mj++) {
          var am = aiMonsters[mj];
          if (!am.名字) continue;
          var dm2 = lookupDungeonMonster(floor, am.名字);
          if (dm2 && dm2.data) {
            var merged2 = buildMonsterEntry(am.名字, dm2.data, am);
            for (var k2 in am) {
              if (!(k2 in merged2) && am.hasOwnProperty(k2)) merged2[k2] = am[k2];
            }
            aiMonsters[mj] = merged2;
          }
        }
      } else {
        // 世界书怪物更多或相等 → 以世界书为基底，AI数据补充细节
        var mergedList = [];
        for (var wi = 0; wi < wbNames.length; wi++) {
          var wbName = wbNames[wi];
          var wbData = floorData[wbName];
          var aiMatch = findAiMatch(wbName);
          var entry = buildMonsterEntry(wbName, wbData, aiMatch);
          // 补充AI独有字段
          if (aiMatch) {
            for (var ak in aiMatch) {
              if (!(ak in entry) && aiMatch.hasOwnProperty(ak)) entry[ak] = aiMatch[ak];
            }
          }
          mergedList.push(entry);
        }
        // 追加AI有但世界书没有的怪物
        for (var aj = 0; aj < aiMonsters.length; aj++) {
          var aim = aiMonsters[aj];
          if (!aim.名字) continue;
          var found = false;
          for (var wj = 0; wj < wbNames.length; wj++) {
            if (aim.名字.includes(wbNames[wj]) || wbNames[wj].includes(aim.名字)) {
              found = true;
              break;
            }
          }
          if (!found) {
            aim._fromBestiary = true;
            mergedList.push(aim);
          }
        }
        inst.怪物 = mergedList;
      }
    }
  }

  // ==================== 完整 Transform：指令执行 + 属性重算 + 结算 ====================

  /**
   * 完整变量更新流程，替代 地错zod.js 中的 .transform() 主体逻辑
   * - zod transform 调用：cmd.fullTransform(data)
   * - 前端审查执行调用：cmd.fullTransform(sd, { forceExecute: true })
   * @param {object} data - stat_data 对象
   * @param {object} [opts] - 选项
   * @param {boolean} [opts.forceExecute] - 强制执行指令（绕过手动审查检查）
   */
  cmd.fullTransform = function(data, opts) {
    if (!window.top?.DungeonUtils && !window.DungeonUtils) return;
    opts = opts || {};
    // Step 0: 用世界书模板增强指令（模板优先于AI数据）
    if (data.操作指令?.length > 0) {
      for (var i = 0; i < data.操作指令.length; i++) {
        augmentInstruction(data.操作指令[i], data);
      }
    }
    // Step 1: 执行操作指令（审查模式下跳过，除非强制）
    const 手动审查 = data.sysbox?.剧情相关?.手动审查;
    if (opts.forceExecute || !手动审查) {
      if (data.操作指令?.length > 0) {
        // 保存副本用于生成上轮指令摘要（processCommands 会清空数组）
        const snapshot = [...data.操作指令];
        cmd.processCommands(data);
        // 生成上轮指令摘要，供 AI 下轮参考
        data.上轮指令 = snapshot.map(function(inst) {
          return summarizeInstruction(inst);
        }).filter(Boolean);
      }
    }
    // Step 2-6: 属性重算 + 结算
    cmd.recalcAndSettle(data);
  };

  /**
   * 属性重算 + 百分比变动生效 + 敌人经验 + 战斗结算 + 眷族同步
   * 不含操作指令执行（由 fullTransform 在上层控制）
   */
  /**
   * 封装 replaceMvuData + recalcAndSettle
   * 所有外部写回都应调用此函数，确保派生字段（HP/SP/MP/总能力等）被重新计算
   * @param {object} vars - MVU 变量对象（含 stat_data）
   * @param {object} opts - MVU 选项 { type, message_id }
   */
  cmd.saveData = async function(vars, opts) {
    var sd = vars.stat_data;
    if (sd) {
      try { cmd.recalcAndSettle(sd); } catch (e) { console.warn("[CommandUtils] recalc 失败:", e); }
    }
    await window.top.Mvu.replaceMvuData(vars, opts);
  };

  cmd.recalcAndSettle = function(data) {
    const utils = window.top?.DungeonUtils || window.DungeonUtils;
    if (!utils) return;
    const 等级系数 = data.sysbox?.战斗系统?.等级补正?.等级系数 ?? 1000;

    const updateCharacter = (char) => {
      if (!char?.基础信息?.类型) return;
      const type = char.基础信息.类型;
      const status = char.状态;

      // ========== NPC：仅处理状态，不触碰任何能力字段 ==========
      if (type === "NPC") {
        var npcAttr = char.个人属性;
        if (npcAttr) {
          delete npcAttr.等级;
          delete npcAttr.基础能力;
          delete npcAttr.潜在能力;
          delete npcAttr.积累经验值;
          delete npcAttr.总能力;
          delete npcAttr.整体评价;
          delete npcAttr.当前伟业;
          delete npcAttr.成长期望;
        }
        status.HP上限 = 500;
        status.SP上限 = 100;
        status.MP上限 = 100;
        status.HP当前值 = Math.max(0, Math.min(status.HP当前值 ?? 500, 500));
        status.SP当前值 = Math.max(0, Math.min(status.SP当前值 ?? 100, 100));
        status.MP当前值 = Math.max(0, Math.min(status.MP当前值 ?? 100, 100));
        return;
      }

      // ========== 主角 / 冒险者 / 怪物：需要完整能力计算 ==========
      const lv = char.个人属性?.等级 ?? 0;
      const 基础 = char.个人属性?.基础能力 ?? {};
      const 潜在 = char.个人属性?.潜在能力 ?? {};

      const 等级补正 = utils.calcLevelBonus(lv, type, 等级系数);

      if (type === "冒险者") {
        const 成长期望 = char.个人属性?.成长期望 ?? {};
        FIVE_KEYS.forEach((key) => {
          潜在[key] = Math.floor(
            (Math.max(0, lv - 1) * (成长期望[key] || 0)) / 2,
          );
        });
        char.个人属性.潜在能力 = 潜在;
      }

      const 总能力 = utils.calcTotalPower(基础, 潜在, lv, type, 等级系数);

      if (type === "怪物") {
        const combatCfg = data.sysbox?.战斗系统;
        const floor =
          char.是否击败 !== undefined
            ? data.当前地下城区域?.层数 || 1
            : char.个人属性?.到达层数 || data.当前地下城区域?.层数 || 1;
        const floorCorr = utils.getFloorCorrection(combatCfg, floor);
        const rarity = char.基础信息?.稀有度 || "普通";
        const rc = utils.getRarityCoeff(combatCfg, rarity);
        FIVE_KEYS.forEach((k) => {
          总能力[k] = Math.floor(总能力[k] * floorCorr * rc);
        });
      }

      char.个人属性.总能力 = 总能力;

      const hpSpMp = utils.calcHpSpMp(总能力, type);
      status.HP上限 = hpSpMp.HP上限;
      status.SP上限 = hpSpMp.SP上限;
      status.MP上限 = hpSpMp.MP上限;

      if (type !== "怪物") {
        status.HP当前值 = Math.max(0, Math.min(status.HP当前值 ?? status.HP上限, status.HP上限));
        status.SP当前值 = Math.max(0, Math.min(status.SP当前值 ?? status.SP上限, status.SP上限));
        status.MP当前值 = Math.max(0, Math.min(status.MP当前值 ?? status.MP上限, status.MP上限));
      } else {
        status.HP当前值 = status.HP当前值 ?? status.HP上限;
        status.SP当前值 = status.SP当前值 ?? status.SP上限;
        status.MP当前值 = status.MP当前值 ?? status.MP上限;
      }

      // 整体评价
      if (type === "主角" || type === "冒险者") {
        const 最高 = Math.max(基础.力量 || 0, 基础.耐力 || 0, 基础.灵巧 || 0, 基础.敏捷 || 0, 基础.魔力 || 0);
        char.个人属性.整体评价 = cmd.getGradeFromValue(最高);
      } else if (type === "怪物") {
        const 最高 = Math.max(基础.力量 || 0, 基础.耐力 || 0, 基础.灵巧 || 0, 基础.敏捷 || 0, 基础.魔力 || 0);
        char.个人属性.整体评价 = cmd.getGradeFromValue(最高);
      }
    };

    // ==================== 处理 AI 传入的百分比变动 ====================
    const applyPercentChange = (char) => {
      if (!char?.状态) return;
      const status = char.状态;

      if (status.HP变动百分比 != null) {
        const diff = Math.round(((status.HP上限 || 0) * status.HP变动百分比) / 100);
        const cur = status.HP当前值 ?? status.HP上限 ?? 0;
        status.HP当前值 = Math.max(0, Math.min(status.HP上限, cur + diff));
        status.HP变动百分比 = 0;
      }
      if (status.SP变动百分比 != null) {
        const diff = Math.round(((status.SP上限 || 0) * status.SP变动百分比) / 100);
        const cur = status.SP当前值 ?? status.SP上限 ?? 0;
        status.SP当前值 = Math.max(0, Math.min(status.SP上限, cur + diff));
        status.SP变动百分比 = 0;
      }
      if (status.MP变动百分比 != null) {
        const diff = Math.round(((status.MP上限 || 0) * status.MP变动百分比) / 100);
        const cur = status.MP当前值 ?? status.MP上限 ?? 0;
        status.MP当前值 = Math.max(0, Math.min(status.MP上限, cur + diff));
        status.MP变动百分比 = 0;
      }
    };

    // 先计算动态属性（总能力/HP等），再应用百分比变动
    if (data.主角) {
      updateCharacter(data.主角);
      applyPercentChange(data.主角);
    }
    if (data.人物名录)
      Object.values(data.人物名录).forEach((c) => {
        updateCharacter(c);
        applyPercentChange(c);
      });
    if (data.敌人信息) {
      data.敌人信息.forEach((c) => {
        updateCharacter(c);
        applyPercentChange(c);
      });

      // 敌人经验锁定
      const enemies = data.敌人信息;
      const aliveEnemies = enemies.filter(function(e) { return !e.是否击败; });
      if (aliveEnemies.length > 0) {
        const U2 = window.top?.DungeonUtils || window.DungeonUtils;
        if (U2?.calcEnemyExpFeat && U2?.calcEnemyExpPool) {
          const sysbox = data.sysbox || {};
          const area = data.当前地下城区域 || {};
          const floor = area.层数 || 1;
          const allies = [data.主角];
          const partyMap = data.组队成员 || {};
          const npcList = data.人物名录 || {};
          for (const name of Object.keys(partyMap)) {
            const npc = npcList[name];
            if (npc) allies.push(npc);
          }
          const totalPool = U2.calcEnemyExpPool(allies, aliveEnemies, sysbox);
          for (const enemy of enemies) {
            if (enemy.是否击败) continue;
            const result = U2.calcEnemyExpFeat(enemy, aliveEnemies, allies, sysbox, floor, totalPool);
            enemy.结算经验 = Math.max(1, result.exp);
            enemy.结算伟业 = result.feat;
          }
        }
      }
    }

    // ========== 自动战斗结算 ==========
    if (cmd.handle结算) {
      cmd.handle结算(data);
    }

    // ========== 眷族成员同步 ==========
    if (data.眷族情况) {
      const familia = data.主角?.个人属性?.所属眷族;
      if (familia && familia !== "无") {
        const members = [data.主角?.基础信息?.姓名 || "主角"];
        for (const [name, c] of Object.entries(data.人物名录 || {})) {
          if (c?.个人属性?.所属眷族 === familia) {
            members.push(name);
          }
        }
        data.眷族情况.成员名单 = members;
        data.眷族情况.成员数 = members.length;
      } else {
        data.眷族情况.成员名单 = [];
        data.眷族情况.成员数 = 0;
      }
    }
  };

  // ==================== 战报预览弹窗 + 轮数输入弹窗 ====================

  /**
   * 战报预览弹窗 — JS 像素定位，Promise 返回
   * @param {string} title - 弹窗标题
   * @param {string} report - 战报文本（支持 \n 换行）
   * @returns Promise<boolean> — 确认 true，取消 false
   */
  cmd._showReportPreview = function(title, report) {
    var doc = window.top.document;
    return new Promise(function(resolve, reject) {
      try {
        var scrollY = window.top.scrollY || window.top.pageYOffset || 0;
        var vw = window.top.innerWidth;
        var vh = window.top.innerHeight;
        var overlay = doc.createElement("div");
        overlay.style.cssText = "position:absolute;left:0;top:" + scrollY + "px;width:" + vw + "px;height:" + vh + "px;background:rgba(0,0,0,0.7);z-index:99999999;display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;font-family:'Times New Roman',serif;";

        var card = doc.createElement("div");
        card.style.cssText = "background:#1a1620;border:2px solid #b89b6b;border-radius:8px;padding:20px 24px;min-width:340px;max-width:520px;max-height:80vh;overflow-y:auto;box-shadow:0 0 20px rgba(184,155,107,0.3);color:#f0e6d2;";

        var reportHtml = cmd._escHtml(report).replace(/\n/g, "<br>");

        card.innerHTML =
          "<div style='font-size:1.1em;color:#d4b8e0;letter-spacing:2px;margin-bottom:14px;border-bottom:1px solid #b89b6b;padding-bottom:8px;'>" + cmd._escHtml(title) + "</div>" +
          "<div style='background:#1f1a1a;border:1px solid #4a3a2e;border-radius:6px;padding:14px 16px;max-height:50vh;overflow-y:auto;font-size:13px;line-height:1.7;color:#f0e6d2;white-space:pre-wrap;'>" + reportHtml + "</div>" +
          "<div style='margin-top:16px;display:flex;gap:10px;justify-content:flex-end;'>" +
            "<button id='_rp_cancel' style='background:#3a3040;color:#a090a0;border:1px solid #5a4a60;border-radius:4px;padding:6px 16px;cursor:pointer;font-family:inherit;'>取消</button>" +
            "<button id='_rp_confirm' style='background:#4a3a2a;color:#c0e0c0;border:1px solid #6b5a3e;border-radius:4px;padding:6px 16px;cursor:pointer;font-family:inherit;'>确认发送</button>" +
          "</div>";

        overlay.appendChild(card);
        doc.body.appendChild(overlay);

        var cleanup = function(result) {
          overlay.remove();
          resolve(result);
        };

        overlay.addEventListener("click", function(e) { if (e.target === overlay) cleanup(false); });
        card.querySelector("#_rp_cancel").addEventListener("click", function() { cleanup(false); });
        card.querySelector("#_rp_confirm").addEventListener("click", function() { cleanup(true); });
      } catch(e) {
        console.error("[_showReportPreview] 内部错误:", e);
        reject(e);
      }
    });
  };

  /**
   * 轮数输入弹窗 — JS 像素定位，Promise 返回
   * @param {number} defaultRounds - 默认轮数
   * @returns Promise<number|null> — 确认返回整数轮数，取消返回 null
   */
  cmd._showRoundInput = function(defaultRounds) {
    var doc = window.top.document;
    var defVal = defaultRounds || 3;
    return new Promise(function(resolve, reject) {
      try {
        var scrollY = window.top.scrollY || window.top.pageYOffset || 0;
        var vw = window.top.innerWidth;
        var vh = window.top.innerHeight;
        var overlay = doc.createElement("div");
        overlay.style.cssText = "position:absolute;left:0;top:" + scrollY + "px;width:" + vw + "px;height:" + vh + "px;background:rgba(0,0,0,0.7);z-index:99999999;display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;font-family:'Times New Roman',serif;";

        var card = doc.createElement("div");
        card.style.cssText = "background:#1a1620;border:2px solid #b89b6b;border-radius:8px;padding:24px 30px;min-width:280px;max-width:360px;box-shadow:0 0 20px rgba(184,155,107,0.3);color:#f0e6d2;text-align:center;";

        card.innerHTML =
          "<div style='font-size:1.1em;color:#ffe066;letter-spacing:2px;margin-bottom:18px;'>⚔️ 战斗轮数设置</div>" +
          "<div style='margin-bottom:8px;font-size:13px;color:#b89b6b;'>请输入战斗轮数（整数 ≥1）</div>" +
          "<input id='_ri_input' type='number' min='1' value='" + defVal + "' style='width:80px;padding:6px 10px;font-size:1.2em;text-align:center;background:#2a2430;color:#ffe066;border:1px solid #b89b6b;border-radius:4px;font-family:inherit;' />" +
          "<div id='_ri_error' style='margin-top:6px;font-size:12px;color:#e05050;min-height:18px;'></div>" +
          "<div style='margin-top:20px;display:flex;gap:10px;justify-content:center;'>" +
            "<button id='_ri_cancel' style='background:#3a3040;color:#a090a0;border:1px solid #5a4a60;border-radius:4px;padding:6px 20px;cursor:pointer;font-family:inherit;'>取消</button>" +
            "<button id='_ri_confirm' style='background:#4a3a2a;color:#c0e0c0;border:1px solid #6b5a3e;border-radius:4px;padding:6px 20px;cursor:pointer;font-family:inherit;'>确认</button>" +
          "</div>";

        overlay.appendChild(card);
        doc.body.appendChild(overlay);

        var input = card.querySelector("#_ri_input");
        var errorDiv = card.querySelector("#_ri_error");

        var doConfirm = function() {
          var val = parseInt(input.value, 10);
          if (!isFinite(val) || val < 1 || val !== parseFloat(input.value)) {
            errorDiv.textContent = "请输入有效的正整数";
            return;
          }
          overlay.remove();
          resolve(val);
        };

        overlay.addEventListener("click", function(e) { if (e.target === overlay) { overlay.remove(); resolve(null); } });
        card.querySelector("#_ri_cancel").addEventListener("click", function() { overlay.remove(); resolve(null); });
        card.querySelector("#_ri_confirm").addEventListener("click", doConfirm);
        input.addEventListener("keydown", function(e) { if (e.key === "Enter") doConfirm(); });
        setTimeout(function() { input.focus(); input.select(); }, 50);
      } catch(e) {
        console.error("[_showRoundInput] 内部错误:", e);
        reject(e);
      }
    });
  };

  /**
   * 战前准备弹窗：技能选择 + 资源预览 + 轮数设置
   * @param {object} opts
   *   allies: [{name, hpCur, hpMax, spCur, spMax, mpCur, mpMax, skills: [{name, category, costSP, costMP, detail}]}]
   *   enemies: [{name, hpCur, hpMax, spCur, spMax, mpCur, mpMax}]
   *   defaultRounds: number
   *   showRoundInput: boolean (默认 true)
   *   title: string (可选，默认 "⚔️ 战前准备")
   *   confirmText: string (可选，默认 "确认开战")
   * @returns Promise<{rounds, selections} | null>
   */
  cmd._showCombatSetup = function(opts) {
    var doc = window.top.document;
    var allies = opts.allies || [];
    var enemies = opts.enemies || [];
    var defaultRounds = opts.defaultRounds || 3;
    var showRoundInput = opts.showRoundInput !== false;
    var title = opts.title || (showRoundInput ? '⚔️ 战前准备' : '⚔️ 死斗准备');
    var confirmText = opts.confirmText || (showRoundInput ? '确认开战' : '确认死斗');

    return new Promise(function(resolve, reject) {
      try {
        var scrollY = window.top.scrollY || window.top.pageYOffset || 0;
        var vw = window.top.innerWidth;
        var vh = window.top.innerHeight;
        var overlay = doc.createElement("div");
        overlay.style.cssText = "position:absolute;left:0;top:" + scrollY + "px;width:" + vw + "px;height:" + vh + "px;background:rgba(0,0,0,0.7);z-index:99999999;display:flex;align-items:flex-start;justify-content:center;padding:40px 20px;box-sizing:border-box;font-family:'Times New Roman',serif;overflow-y:auto;";

        var card = doc.createElement("div");
        card.style.cssText = "background:#1a1620;border:2px solid #b89b6b;border-radius:8px;padding:20px 24px;max-width:520px;width:100%;box-shadow:0 0 20px rgba(184,155,107,0.3);color:#f0e6d2;margin-bottom:40px;";

        // ---- 构建HTML ----
        var html = '';
        html += "<div style='font-size:1.2em;color:#ffe066;letter-spacing:2px;margin-bottom:16px;text-align:center;'>" + title + "</div>";

        // 己方角色区域
        html += "<div style='margin-bottom:12px;'>";
        html += "<div style='font-size:0.95em;color:#b89b6b;margin-bottom:8px;'>👥 己方</div>";
        for (var ai = 0; ai < allies.length; ai++) {
          var ally = allies[ai];
          var aSkills = ally.skills || [];
          var dmgSkills = aSkills.filter(function(s) { return s.category === 'damage'; });
          var activeSkills = aSkills.filter(function(s) { return s.category === 'active'; });
          var healSkills = aSkills.filter(function(s) { return s.category === 'heal'; });

          html += "<div style='background:#231b12;border:1px solid #4a3a2e;border-radius:6px;padding:10px 12px;margin-bottom:8px;'>";
          // 角色名 + 资源
          html += "<div style='font-weight:bold;color:#f0e6d2;margin-bottom:4px;'>" + ally.name + "</div>";
          html += "<div style='font-size:0.8em;color:#8a8070;margin-bottom:6px;'>";
          html += "HP " + (ally.hpCur || 0) + "/" + (ally.hpMax || 0);
          html += "  SP " + (ally.spCur || 0) + "/" + (ally.spMax || 0);
          html += "  MP " + (ally.mpCur || 0) + "/" + (ally.mpMax || 0);
          html += "</div>";

          // 战术位置选择
          html += "<div style='font-size:0.8em;color:#b89b6b;margin-bottom:2px;'>战术位置</div>";
          html += "<div style='display:flex;gap:4px;margin-bottom:4px;' id='_csPosGroup_" + ai + "'>";
          ['前卫','中卫','后卫','策应'].forEach(function(pos) {
            var posIcons3 = { '前卫': '🛡', '中卫': '⚔', '后卫': '🏹', '策应': '🌀' };
            var posDescs3 = { '前卫': '被攻击+30% 减伤上限+5pp 耐力成长', '中卫': '暴击伤害+15pp 灵巧成长', '后卫': '被攻击-30% 速度压制+10pp 敏捷成长', '策应': '暴击率+10pp 灵巧+敏捷成长' };
            html += "<button class='_cs_pos_btn' data-pos='" + pos + "' data-ai='" + ai + "' title='" + posDescs3[pos] + "' style='flex:1;padding:4px 6px;background:#2a2430;border:1px solid #4a3a2e;border-radius:4px;color:#8a8070;cursor:pointer;font-size:11px;font-family:inherit;text-align:center;'>" + posIcons3[pos] + " " + pos + "</button>";
          });
          html += "</div>";

          // 伤害技能（权重输入，0=不使用）
          if (dmgSkills.length > 0) {
            html += "<div style='font-size:0.8em;color:#e08060;margin-bottom:3px;margin-top:4px;'>伤害技能（权重，0=不使用）</div>";
            for (var dsi = 0; dsi < dmgSkills.length; dsi++) {
              var ds = dmgSkills[dsi];
              var defW = ds.defaultWeight != null ? ds.defaultWeight : 1;
              var costInfo = (ds.costSP > 0 ? " SP" + ds.costSP : "") + (ds.costMP > 0 ? " MP" + ds.costMP : "");
              html += "<div style='display:flex;align-items:center;margin:2px 0 2px 8px;font-size:0.78em;color:#c0b090;'>";
              html += "<span style='flex:1;'>" + ds.name + (costInfo ? " <span style='color:#8a8070;'>(" + costInfo + ")</span>" : "") + (ds.detail ? " <span style='color:#8a8070;'>· " + ds.detail + "</span>" : "") + "</span>";
              html += "<input type='number' id='_dmg_" + ai + "_" + dsi + "' value='" + defW + "' min='0' style='width:50px;padding:2px 4px;text-align:center;background:#2a2430;color:#ffe066;border:1px solid #b89b6b;border-radius:3px;font-family:inherit;font-size:0.9em;' />";
              html += "</div>";
            }
          }

          // 主动技能（权重输入，0=不使用）
          if (activeSkills.length > 0) {
            html += "<div style='font-size:0.8em;color:#7b68ee;margin-bottom:3px;margin-top:6px;'>主动技能（权重，0=不使用）</div>";
            for (var asi = 0; asi < activeSkills.length; asi++) {
              var as = activeSkills[asi];
              var defW = as.defaultWeight != null ? as.defaultWeight : 1;
              var costInfo = (as.costSP > 0 ? " SP" + as.costSP : "") + (as.costMP > 0 ? " MP" + as.costMP : "");
              html += "<div style='display:flex;align-items:center;margin:2px 0 2px 8px;font-size:0.78em;color:#c0b090;'>";
              html += "<span style='flex:1;'><span style='color:#7b68ee;font-size:0.8em;'>[强化]</span> " + as.name + (costInfo ? " <span style='color:#8a8070;'>(" + costInfo + ")</span>" : "") + (as.detail ? " <span style='color:#8a8070;'>· " + as.detail + "</span>" : "") + "</span>";
              html += "<input type='number' id='_act_" + ai + "_" + asi + "' value='" + defW + "' min='0' style='width:50px;padding:2px 4px;text-align:center;background:#2a2430;color:#ffe066;border:1px solid #b89b6b;border-radius:3px;font-family:inherit;font-size:0.9em;' />";
              html += "</div>";
            }
          }

          // 恢复技能（阈值%输入，留空=不使用）
          if (healSkills.length > 0) {
            html += "<div style='font-size:0.8em;color:#50c878;margin-bottom:3px;margin-top:6px;'>恢复技能（阈值%，留空=不使用）</div>";
            for (var hsi = 0; hsi < healSkills.length; hsi++) {
              var hs = healSkills[hsi];
              var defT = hs.defaultThreshold != null ? hs.defaultThreshold : 80;
              var costInfo = (hs.costSP > 0 ? " SP" + hs.costSP : "") + (hs.costMP > 0 ? " MP" + hs.costMP : "");
              var healTypes = [];
              if (hs.healsHP) healTypes.push("HP");
              if (hs.healsSP) healTypes.push("SP");
              if (hs.healsMP) healTypes.push("MP");
              html += "<div style='display:flex;align-items:center;margin:2px 0 2px 8px;font-size:0.78em;color:#c0b090;'>";
              html += "<span style='flex:1;'><span style='color:#50c878;font-size:0.8em;'>[恢复" + healTypes.join("/") + "]</span> " + hs.name + (costInfo ? " <span style='color:#8a8070;'>(" + costInfo + ")</span>" : "") + (hs.detail ? " <span style='color:#8a8070;'>· " + hs.detail + "</span>" : "") + "</span>";
              html += "<input type='number' id='_heal_" + ai + "_" + hsi + "' value='" + defT + "' min='0' max='100' placeholder='留空' style='width:50px;padding:2px 4px;text-align:center;background:#2a2430;color:#50c878;border:1px solid #b89b6b;border-radius:3px;font-family:inherit;font-size:0.9em;' />";
              html += "<span style='color:#8a8070;font-size:0.85em;margin-left:2px;'>%</span>";
              html += "</div>";
            }
          }

          if (dmgSkills.length === 0 && activeSkills.length === 0 && healSkills.length === 0) {
            html += "<div style='font-size:0.75em;color:#605040;'>无主动技能</div>";
          }
          html += "</div>";
        }
        html += "</div>";

        // 敌方角色区域（折叠）
        if (enemies.length > 0) {
          html += "<div style='margin-bottom:12px;border-top:1px dashed #4a3a2e;padding-top:10px;'>";
          html += "<div id='_cs_enemy_toggle' style='font-size:0.95em;color:#b89b6b;cursor:pointer;user-select:none;'>👹 敌方预览 ▸</div>";
          html += "<div id='_cs_enemy_body' style='display:none;margin-top:6px;'>";
          for (var ei = 0; ei < enemies.length; ei++) {
            var en = enemies[ei];
            html += "<div style='font-size:0.8em;color:#a09080;margin:2px 0;'>";
            html += en.name + "：HP " + (en.hpCur || 0) + "/" + (en.hpMax || 0) + "  SP " + (en.spCur || 0) + "/" + (en.spMax || 0) + "  MP " + (en.mpCur || 0) + "/" + (en.mpMax || 0);
            html += "</div>";
          }
          html += "<div style='font-size:0.72em;color:#605040;margin-top:4px;'>敌方技能自动选择（权重默认，恢复阈值60%）</div>";
          html += "</div></div>";
        }

        // 轮数设置
        if (showRoundInput) {
          html += "<div style='text-align:center;margin:12px 0;'>";
          html += "<span style='font-size:0.9em;color:#b89b6b;'>战斗轮数：</span>";
          html += "<input id='_cs_rounds' type='number' min='1' value='" + defaultRounds + "' style='width:70px;padding:4px 8px;font-size:1em;text-align:center;background:#2a2430;color:#ffe066;border:1px solid #b89b6b;border-radius:4px;font-family:inherit;' />";
          html += "</div>";
        } else {
          html += "<div style='text-align:center;margin:12px 0;font-size:0.85em;color:#806040;'>死斗模式：战斗至一方全灭</div>";
        }

        // 底部按钮
        html += "<div style='margin-top:16px;display:flex;gap:10px;justify-content:center;'>";
        html += "<button id='_cs_cancel' style='background:#3a3040;color:#a090a0;border:1px solid #5a4a60;border-radius:4px;padding:8px 24px;cursor:pointer;font-family:inherit;'>取消</button>";
        html += "<button id='_cs_confirm' style='background:#4a3a2a;color:#c0e0c0;border:1px solid #6b5a3e;border-radius:4px;padding:8px 24px;cursor:pointer;font-family:inherit;font-weight:bold;'>" + confirmText + "</button>";
        html += "</div>";

        card.innerHTML = html;
        overlay.appendChild(card);
        doc.body.appendChild(overlay);

        // 位置按钮点击事件
        card.querySelectorAll("._cs_pos_btn").forEach(function(btn) {
          btn.addEventListener("click", function() {
            var ai = btn.dataset.ai;
            var group = card.querySelector("#_csPosGroup_" + ai);
            group.querySelectorAll("._cs_pos_btn").forEach(function(b) {
              b.classList.remove("pos-active");
              b.style.background = "#2a2430";
              b.style.borderColor = "#4a3a2e";
              b.style.color = "#8a8070";
            });
            btn.classList.add("pos-active");
            btn.style.background = "#3a2a1a";
            btn.style.borderColor = "#ffe066";
            btn.style.color = "#ffe066";
          });
        });

        // 敌方折叠交互
        var enemyToggle = card.querySelector("#_cs_enemy_toggle");
        var enemyBody = card.querySelector("#_cs_enemy_body");
        if (enemyToggle && enemyBody) {
          enemyToggle.addEventListener("click", function() {
            if (enemyBody.style.display === "none") {
              enemyBody.style.display = "block";
              enemyToggle.textContent = "👹 敌方预览 ▾";
            } else {
              enemyBody.style.display = "none";
              enemyToggle.textContent = "👹 敌方预览 ▸";
            }
          });
        }

        // 收集结果（权重/阈值格式）
        var doConfirm = function() {
          var selections = {};
          for (var ai2 = 0; ai2 < allies.length; ai2++) {
            var allyName = allies[ai2].name;
            var allySkills = allies[ai2].skills || [];
            var dmgSkills2 = allySkills.filter(function(s) { return s.category === 'damage'; });
            var activeSkills2 = allySkills.filter(function(s) { return s.category === 'active'; });
            var healSkills2 = allySkills.filter(function(s) { return s.category === 'heal'; });

            // 读取伤害技能权重
            var damageWeights = {};
            for (var dsi2 = 0; dsi2 < dmgSkills2.length; dsi2++) {
              var input = card.querySelector("#_dmg_" + ai2 + "_" + dsi2);
              if (input) {
                var w = parseInt(input.value, 10);
                if (isFinite(w) && w >= 0) {
                  damageWeights[dmgSkills2[dsi2].name] = w;
                }
              }
            }

            // 读取主动技能权重
            var activeWeights = {};
            for (var asi2 = 0; asi2 < activeSkills2.length; asi2++) {
              var input = card.querySelector("#_act_" + ai2 + "_" + asi2);
              if (input) {
                var w = parseInt(input.value, 10);
                if (isFinite(w) && w >= 0) {
                  activeWeights[activeSkills2[asi2].name] = w;
                }
              }
            }

            // 读取恢复阈值（取第一个有值的恢复技能阈值）
            var healThreshold = null;
            if (healSkills2.length > 0) {
              for (var hsi2 = 0; hsi2 < healSkills2.length; hsi2++) {
                var input = card.querySelector("#_heal_" + ai2 + "_" + hsi2);
                if (input && input.value !== '' && input.value !== null) {
                  var t = parseInt(input.value, 10);
                  if (isFinite(t) && t >= 0 && t <= 100) {
                    healThreshold = t;
                    break;
                  }
                }
              }
            }

            // 读取战术位置
            var posBtn = card.querySelector("#_csPosGroup_" + ai2 + " ._cs_pos_btn.pos-active");
            var position = posBtn ? posBtn.dataset.pos : null;

            selections[allyName] = {
              damageWeights: damageWeights,
              activeWeights: activeWeights,
              healThreshold: healThreshold,
              position: position
            };
          }

          var rounds = null;
          if (showRoundInput) {
            var roundsInput = card.querySelector("#_cs_rounds");
            var val = parseInt(roundsInput.value, 10);
            if (!isFinite(val) || val < 1 || val !== parseFloat(roundsInput.value)) {
              alert("请输入有效的正整数轮数");
              return;
            }
            rounds = val;
          }

          overlay.remove();
          resolve({ rounds: rounds, selections: selections });
        };

        overlay.addEventListener("click", function(e) { if (e.target === overlay) { overlay.remove(); resolve(null); } });
        card.querySelector("#_cs_cancel").addEventListener("click", function() { overlay.remove(); resolve(null); });
        card.querySelector("#_cs_confirm").addEventListener("click", doConfirm);
      } catch(e) {
        console.error("[_showCombatSetup] 内部错误:", e);
        reject(e);
      }
    });
  };

  // ==================== 战斗结算统一入口（供三个按钮共用）====================

  /**
   * 统一战斗结算：预览战报 → 发送 → 写回 HP/SP/MP + 敌人击败标记
   * @param {object} all - 完整的 MVU 变量对象（含 stat_data）
   * @param {object} result - calcMultiCombat / calcCombatFromData 的返回值
   * @param {object[]} enemyInfo - sd.敌人信息 数组引用
   * @param {string} report - 战报文本
   * @param {string} reportTitle - 预览弹窗标题
   * @returns {Promise<boolean>} 是否成功
   */
  cmd.applyCombatResult = async function(all, result, enemyInfo, report, reportTitle, messageId) {
    var Mvu = window.top.Mvu;
    var mid = messageId != null
      ? messageId
      : (typeof window.top.getCurrentMessageId === "function"
        ? window.top.getCurrentMessageId()
        : null);

    // 1. 预览
    var confirmed = await cmd._showReportPreview(reportTitle, report);
    if (!confirmed) return false;

    // 2. 发送战报到 textarea
    try {
      var ta = window.top.document.querySelector("#send_textarea");
      var btnSend = window.top.document.querySelector("#send_but");
      if (ta && btnSend) {
        ta.value = report;
        ta.dispatchEvent(new Event("input", { bubbles: true }));
        btnSend.click();
      }
    } catch(e) { /* 忽略发送错误 */ }

    // 3. 写回 HP/SP/MP + 敌人击败标记
    if (all && mid != null) {
      var sd = _.get(all, "stat_data", {});

      // 主角
      var plNew = _.get(all, "stat_data.主角", {});
      var plStatus = plNew.状态 || {};
      var plResult = result.allyResults.find(function(a) { return a.name === (plNew.基础信息?.姓名 || "主角"); });
      if (plResult) {
        plStatus.HP当前值 = plResult.defeated ? 1 : plResult.hpAfter;
        plStatus.SP当前值 = plResult.spAfter;
        plStatus.MP当前值 = plResult.mpAfter;
        _.set(all, "stat_data.主角.状态", plStatus);
      }

      // 队友
      var partyMap = sd.组队成员 || {};
      var npcList = sd.人物名录 || {};
      Object.keys(partyMap).forEach(function(name) {
        var aResult = result.allyResults.find(function(a) { return a.name === name; });
        if (!aResult) return;
        var npcPath = "stat_data.人物名录." + name + ".状态";
        var npcStatus = _.get(all, npcPath) || {};
        npcStatus.HP当前值 = aResult.defeated ? 1 : aResult.hpAfter;
        npcStatus.SP当前值 = aResult.spAfter;
        npcStatus.MP当前值 = aResult.mpAfter;
        _.set(all, npcPath, npcStatus);
      });

      // 敌人
      result.enemyResults.forEach(function(e) {
        var enemyIdx = e._origIndex != null ? e._origIndex : enemyInfo.findIndex(function(ei) { return (ei.基础信息?.姓名 || "???") === e.name; });
        if (enemyIdx >= 0) {
          var ep = "stat_data.敌人信息." + enemyIdx + ".状态";
          var eStatus = _.get(all, ep) || {};
          eStatus.HP当前值 = e.defeated ? 0 : e.hpAfter;
          eStatus.SP当前值 = e.spAfter;
          eStatus.MP当前值 = e.mpAfter;
          _.set(all, ep, eStatus);
          if (e.defeated) {
            _.set(all, "stat_data.敌人信息." + enemyIdx + ".是否击败", true);
          }
        }
      });

      // 写入战斗行为衍生的经验权重（必须在 replaceMvuData 之前）
      var U = window.top.DungeonUtils;
      if (U && U.calcExpWeightDeltas) {
        var allyNames = [];
        var plName = plNew.基础信息?.姓名 || "主角";
        allyNames.push(plName);
        Object.keys(partyMap).forEach(function(name) { allyNames.push(name); });

        var allDeltas = U.calcExpWeightDeltas(result, allyNames);
        var positions = result.positions || {};
        var posCfg = U.TACTICAL_POSITIONS || {};

        // 主角
        var plDelta = allDeltas[plName];
        if (plDelta) {
          var plExistW = _.get(all, "stat_data.主角.个人属性.经验权重") || { 力量:1, 耐力:1, 灵巧:1, 敏捷:1, 魔力:1 };
          var plPosBonus = (positions[plName] && posCfg[positions[plName]]) ? (posCfg[positions[plName]].expWeightBonus || {}) : {};
          var plW = {};
          ["力量","耐力","灵巧","敏捷","魔力"].forEach(function(k) {
            plW[k] = Math.max(1, (plExistW[k] || 1) + (plDelta[k] || 0) + (plPosBonus[k] || 0));
          });
          _.set(all, "stat_data.主角.个人属性.经验权重", plW);
        }

        // 队友（含冒险者和怪物）
        Object.keys(partyMap).forEach(function(name) {
          var nd = allDeltas[name];
          if (!nd) return;
          var npcPath = "stat_data.人物名录." + name + ".个人属性";
          var npcAttr = _.get(all, npcPath) || {};
          var existW = npcAttr.经验权重 || { 力量:1, 耐力:1, 灵巧:1, 敏捷:1, 魔力:1 };
          var aPosBonus = (positions[name] && posCfg[positions[name]]) ? (posCfg[positions[name]].expWeightBonus || {}) : {};
          var nw = {};
          ["力量","耐力","灵巧","敏捷","魔力"].forEach(function(k) {
            nw[k] = Math.max(1, (existW[k] || 1) + (nd[k] || 0) + (aPosBonus[k] || 0));
          });
          _.set(all, npcPath + ".经验权重", nw);
        });
      }

      // 正确参数顺序：data 在前，options 在后
      await cmd.saveData(all, { type: "message", message_id: mid });
    }
    return true;
  };

  // ==================== 挂载到全局 ====================
  if (typeof window !== "undefined" && window.top) {
    window.top.CommandUtils = cmd;
  } else {
    window.CommandUtils = cmd;
  }

  // 页面首次加载时自动预加载世界书模板（后续调用会被 _cacheLoaded 跳过）
  cmd.preloadTemplates().catch(function() {});
})();

