  // ===================== 本地 JSON 修复器 =====================
  function miniJSONRepair(str) {
    if (!str || typeof str !== "string") return str;
    // 1. 将字符串内所有未转义的真实换行、制表符转义
    let result = "";
    let inString = false;
    let escaped = false;
    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      if (inString) {
        if (escaped) {
          // 如果前一个字符是反斜杠，当前字符是转义的一部分，直接输出
          result += ch;
          escaped = false;
        } else if (ch === "\\") {
          result += ch;
          escaped = true;
        } else if (ch === '"') {
          result += ch;
          inString = false;
        } else if (ch === "\n" || ch === "\r" || ch === "\t") {
          // 未转义的控制字符转义
          result += ch === "\n" ? "\\n" : ch === "\r" ? "\\r" : "\\t";
        } else {
          result += ch;
        }
      } else {
        result += ch;
        if (ch === '"') inString = true;
      }
    }
    // 2. 给缺少双引号的键名补引号 (中文/字母/下划线开头)
    result = result.replace(
      /([{,]\s*)([\u4e00-\u9fa5_a-zA-Z][\u4e00-\u9fa5_a-zA-Z0-9]*)\s*:/g,
      '$1"$2":',
    );
    // 3. 去除尾随逗号
    result = result.replace(/,\s*([}\]])/g, "$1");
    return result;
  }

  // ===================== 内置修复函数（优化版） =====================
  function builtInFixJSON(str) {
    str = str.trim();
    if (!str) return null;
    // 全角符号替换
    str = str
      .replace(/[""]/g, '"')
      .replace(/['']/g, "'")
      .replace(/，/g, ",")
      .replace(/：/g, ":")
      .replace(/；/g, ";")
      .replace(/！/g, "!")
      .replace(/（/g, "(")
      .replace(/）/g, ")")
      .replace(/[\u2018\u2019]/g, "'")
      .replace(/[\u201C\u201D]/g, '"');
    // 处理引号包裹问题：分别检测双引号和单引号包裹
    if (str.startsWith('"') && str.endsWith('"')) {
      // 已经是双引号包裹，不处理
    } else if (str.startsWith("'") && str.endsWith("'")) {
      str = str.replace(/^'/, '"').replace(/'$/, '"');
    }
    // 清理键名末尾的多余冒号、空格、全角符号等（保留键名内部的合法冒号）
    str = str.replace(/"([^"]*?)[：: 　,，；;]+"\s*:\s*/g, '"$1":');
    // 转义未完成的引号
    str = str.replace(/(\\")(")(?=\s*[,}\]])/g, "$1");
    // 字符串内真实换行转义
    str = str.replace(/"([^"]*?)\n([^"]*?)"/g, '"$1\\n$2"');
    // 补全缺失的括号
    let openBrackets = (str.match(/\[/g) || []).length;
    let closeBrackets = (str.match(/\]/g) || []).length;
    while (closeBrackets < openBrackets) {
      str += "]";
      closeBrackets++;
    }
    let openBraces = (str.match(/\{/g) || []).length;
    let closeBraces = (str.match(/\}/g) || []).length;
    while (closeBraces < openBraces) {
      str += "}";
      closeBraces++;
    }
    str = str.replace(/,\s*([}\]])/g, "$1");
    str = str.replace(
      /([{,]\s*)([\u4e00-\u9fa5_a-zA-Z][\u4e00-\u9fa5_a-zA-Z0-9]*)\s*:/g,
      '$1"$2":',
    );
    // 纯单引号包围且内部无引号的字符串，统一替换为双引号
    if (/^'[\s\S]*'$/.test(str) && str.indexOf('"') === -1) {
      str = str.replace(/'/g, '"');
    }
    //str = str.replace(/"([^"]*?)\s*[:：]\s*"\s*:/g, '"$1":');
    return str;
  }

