            return false;
          const state = value.状态 || {};
          if (
            state.HP变动百分比 == null &&
            state.SP变动百分比 == null &&
            state.MP变动百分比 == null
          ) {
            state.HP变动百分比 = 100;
            state.SP变动百分比 = 100;
            state.MP变动百分比 = 100;
            value.状态 = state;
            return true;
          }
          return false;
        },
      },
      {
        id: "clean-object-keys",
        description: "清理对象键名末尾的非法字符（空格、冒号等）",
        pathPattern: ".*",
        ops: ["insert", "replace"], // 不需要加 add，日志已证明是 insert
        action: "fix",
        fix: (parsed, cmd, context) => {
          const value = parsed.value;
          if (!value || typeof value !== "object" || Array.isArray(value))
            return false;

          const cleanKeys = (obj, prefix = "") => {
            if (!obj || typeof obj !== "object" || Array.isArray(obj))
              return obj;
            const newObj = {};
            let changed = false;
            Object.keys(obj).forEach((key) => {
              const cleanKey = key.replace(/[\s\u3000：:；;！!，,。]+$/g, "");
              const finalKey = cleanKey.replace(/[:：]+$/g, "");
              const originalVal = obj[key];
              const childIsObject =
                originalVal &&
                typeof originalVal === "object" &&
                !Array.isArray(originalVal);
              const newVal = childIsObject
                ? cleanKeys(originalVal, prefix + finalKey + ".")
                : originalVal;

              // 关键修复：子对象变化或键名变化都要标记 changed
              if (newVal !== originalVal || finalKey !== key) {
                changed = true;
                if (finalKey !== key && context.fixMessages) {
                  context.fixMessages.push(
                    `字段名清洗: 路径 ${prefix}, "${key}" → "${finalKey}"`,
                  );
                }
              }
              newObj[finalKey] = newVal;
            });
            return changed ? newObj : obj;
          };

          const cleaned = cleanKeys(value);
          if (cleaned !== value) {
            parsed.value = cleaned;
            return true;
          }
          return false;
        },
      },
      {
        id: "clean-string-values",
        description: "清洗字符串值末尾多余的转义双引号（仅高置信度情况）",
        pathPattern: ".*",
        ops: ["insert", "replace"],
        action: "fix",
        fix: (parsed, cmd, context) => {
          const value = parsed.value;
          if (!value || typeof value !== "object" || Array.isArray(value))
            return false;

          const cleanStringTail = (str) => {
            if (typeof str !== "string") return str;

            // 1. 处理末尾 \" （转义引号）
            if (str.endsWith('\\"')) {
              const before = str.slice(0, -2);
              // 内部已包含双引号 → 可能是合法内容，跳过
              if (before.includes('"')) return str;
              // 计算末尾反斜杠数量，确保 \" 是孤立的多余字符
              let slashCount = 0;
              for (let i = before.length - 1; i >= 0; i--) {
                if (before[i] === "\\") slashCount++;
                else break;
              }
              if (slashCount % 2 === 0) {
                if (context.fixMessages) {
                  context.fixMessages.push(`字符串值清洗: 移除末尾多余 \\"`);
                }
                return before;
              }
            }

            // 2. 新增：处理末尾普通双引号 " （解析后残留的裸露引号）
            if (str.endsWith('"')) {
              const before = str.slice(0, -1);
              // 仅当字符串内部完全没有其他双引号时才移除，避免破坏对话引用
              if (!before.includes('"')) {
                if (context.fixMessages) {
                  context.fixMessages.push(
                    `字符串值清洗: 移除末尾多余普通引号`,
                  );
                }
                return before;
              }
            }

            return str;
          };

          const cleanValues = (obj) => {
            if (!obj || typeof obj !== "object" || Array.isArray(obj))
              return obj;
            const newObj = {};
            let changed = false;
            Object.keys(obj).forEach((key) => {
              const originalVal = obj[key];
              if (typeof originalVal === "string") {
                const cleaned = cleanStringTail(originalVal);
                if (cleaned !== originalVal) changed = true;
                newObj[key] = cleaned;
              } else if (
                originalVal &&
                typeof originalVal === "object" &&
                !Array.isArray(originalVal)
              ) {
                const cleaned = cleanValues(originalVal);
                if (cleaned !== originalVal) changed = true;
                newObj[key] = cleaned;
              } else if (Array.isArray(originalVal)) {
                const newArr = originalVal.map((item) => {
                  if (
                    item &&
                    typeof item === "object" &&
                    !Array.isArray(item)
                  ) {
                    const c = cleanValues(item);
                    if (c !== item) changed = true;
                    return c;
                  }
                  if (typeof item === "string") {
                    const c = cleanStringTail(item);
                    if (c !== item) changed = true;
                    return c;
                  }
                  return item;
                });
                if (newArr.some((v, i) => v !== originalVal[i])) changed = true;
                newObj[key] = newArr;
              } else {
                newObj[key] = originalVal;
              }
            });
            return changed ? newObj : obj;
          };

          const cleaned = cleanValues(value);
          if (cleaned !== value) {
            parsed.value = cleaned;
            return true;
          }
          return false;
        },
      },
    ],
  };

  // ===================== JSON 修复入口 =====================
  function fixJSON(str) {
    if (!str) return { result: null, method: "none" };

    // 1. 直接解析
    try {
      JSON.parse(str);
      return { result: str, method: "直接解析" };
    } catch (e) {}

    // 2. CDN jsonrepair（优先使用强力外部库）
    if (window.jsonrepair) {
      try {
        const repaired = window.jsonrepair(str);
        JSON.parse(repaired);
        return { result: repaired, method: "CDN jsonrepair" };
      } catch (e) {}
    }

    // 3. JSON5 兜底
    if (window.JSON5) {
      try {
        const obj = window.JSON5.parse(str);
        const repaired = JSON.stringify(obj);
        return { result: repaired, method: "JSON5" };
      } catch (e) {}
    }

    // 4. 本地轻量修复（miniJSONRepair）
    let repaired = miniJSONRepair(str);
    if (repaired) {
      try {
        JSON.parse(repaired);
        return { result: repaired, method: "本地轻量修复" };
      } catch (e) {}
    }

    // 5. 内置修复（builtInFixJSON）
    repaired = builtInFixJSON(str);
    if (repaired) {
      try {
        JSON.parse(repaired);
        return { result: repaired, method: "内置修复" };
      } catch (e) {}
    }

    // 6. 组合：本地修复后再用内置修复
    repaired = miniJSONRepair(str);
    repaired = builtInFixJSON(repaired);
    if (repaired) {
      try {
        JSON.parse(repaired);
        return { result: repaired, method: "本地 + 内置修复" };
      } catch (e) {}
    }

    return { result: null, method: "none" };
  }

  // ===================== 路径修正工具 =====================
  function buildPathTable(statData) {
    const paths = new Set();
    const pathFields = {};

    function collect(obj, prefix) {
      if (obj === null || typeof obj !== "object") {
        paths.add(prefix);
        return;
      }
      if (Array.isArray(obj)) {
        paths.add(prefix);
        if (obj.length > 0 && typeof obj[0] === "object") {
          const fields = Object.keys(obj[0]);
          pathFields[prefix] = new Set(fields);
          for (const key of fields) {
            collect(obj[0][key], prefix + "." + key);
          }
        }
      } else {
        const fields = Object.keys(obj);
        pathFields[prefix] = new Set(fields);
        paths.add(prefix);
        for (const key of fields) {
          collect(obj[key], prefix ? prefix + "." + key : key);
        }
      }
    }
    collect(statData, "");
    return { paths, pathFields };
  }

  function levenshtein(a, b) {
    const an = a.length,
      bn = b.length;
    const matrix = Array.from({ length: an + 1 }, (_, i) => [i]);
    for (let j = 0; j <= bn; j++) matrix[0][j] = j;
    for (let i = 1; i <= an; i++) {
      for (let j = 1; j <= bn; j++) {
        if (a[i - 1] === b[j - 1]) matrix[i][j] = matrix[i - 1][j - 1];
        else
          matrix[i][j] =
            Math.min(matrix[i - 1][j], matrix[i][j - 1], matrix[i - 1][j - 1]) +
            1;
      }
    }
    return matrix[an][bn];
  }

  function similarity(a, b) {
    const dist = levenshtein(a, b);
    const maxLen = Math.max(a.length, b.length);
    return maxLen === 0 ? 1 : 1 - dist / maxLen;
  }

  // 增强版：增加第二名差距检查，避免误伤
  function bestMatchInSet(input, candidatesSet, threshold = 0.7) {
    const candidates = Array.from(candidatesSet);
    let best = null,
      bestScore = 0,
      secondBestScore = 0;
    for (const cand of candidates) {
      const score = similarity(input, cand);
      if (score > bestScore) {
        secondBestScore = bestScore;
        bestScore = score;
        best = cand;
      } else if (score > secondBestScore) {
        secondBestScore = score;
      }
    }
    // 最高分必须 ≥ 阈值，且与第二名差距明显 (>0.15)
    if (best && bestScore >= threshold && secondBestScore < bestScore - 0.15) {
      return best;
    }
    return null;
  }

  function matchPathPattern(pattern, path) {
    // .* 表示匹配所有路径，直接放行，应无条件匹配所有路径，避免点号转义导致误判
    if (pattern === ".*") return true;

    let regexStr = pattern
      .replace(/\./g, "\\.")
      .replace(/\*\*/g, ".*")
      .replace(/\*/g, "[^.]+");
    return new RegExp("^" + regexStr + "$").test(path);
  }

  function matchDynamicRule(rule, op, cleanPath, value, context) {
    if (!matchPathPattern(rule.pathPattern, cleanPath)) return true;
    if (!rule.forbidOps || !rule.forbidOps.includes(op)) return true;
    if (rule.check) return rule.check(op, cleanPath, value, context);
    if (rule.valueCheck) return rule.valueCheck(op, value, context);
    return false;
  }

  // 就地修改 cmd.args，避免格式破坏
  function updateCmdArgs(cmd, parsed) {
    const op = parsed.op;
    const path = (parsed.path || "").replace(/^\//, "").replace(/\//g, ".");
    switch (op) {
      case "replace":
      case "add":
      case "delta":
        cmd.args[0] = path;
        cmd.args[1] = JSON.stringify(parsed.value);
        break;
      case "insert": {
        const segments = _.toPath(path);
        const parent = segments.slice(0, -1).join(".");
        const last = segments[segments.length - 1];
        if (cmd.args.length >= 3) {
          cmd.args[0] = parent;
          // 保持原来键名的引号风格
          const origKey = cmd.args[1];
          if (
            typeof origKey === "string" &&
            (origKey.startsWith("'") || origKey.startsWith('"'))
          ) {
            const quote = origKey[0];
            cmd.args[1] = quote + last + quote;
          } else if (/^\d+$/.test(last) || last === "-") {
            cmd.args[1] = last;
          } else {
            cmd.args[1] = `'${last}'`; // 默认单引号
          }
          cmd.args[2] = JSON.stringify(parsed.value);
        }
        break;
      }
      case "remove":
        cmd.args[0] = path;
        break;
      case "move": {
        const from = (parsed.from || "").replace(/^\//, "").replace(/\//g, ".");
        const to = (parsed.to || "").replace(/^\//, "").replace(/\//g, ".");
        cmd.args[0] = from;
        cmd.args[1] = to;
        break;
      }
    }
  }

  // ===================== 全局缓存 =====================
  let cachedFixedCommands = null;
  let cachedFixReports = [];

  // ===================== COMMAND_PARSED 核心护栏 =====================
  eventOn(Mvu.events.COMMAND_PARSED, function (newVars, commands, description) {
    // 每次新命令解析时清空缓存，避免跨消息污染
    cachedFixedCommands = null;
    cachedFixReports = [];

    if (!Array.isArray(commands)) return;

    const { paths: validPaths, pathFields } = buildPathTable(newVars.stat_data);
    const fixMessages = [];
    let blocked = 0;
    let enemyPatched = 0;
    let jsonRepairCount = 0;

    for (let i = commands.length - 1; i >= 0; i--) {
      const cmd = commands[i];
      let raw = cmd.full_match || "";
      if (!raw) continue;

      // ------- JSON 修复阶段 -------
      const { result: fixedRaw, method } = fixJSON(raw);
      if (!fixedRaw) {
        fixMessages.push(`❌ JSON 修复失败: ${raw.slice(0, 50)}...`);
        commands.splice(i, 1);
        blocked++;
        continue;
      }
      if (fixedRaw !== raw) {
        jsonRepairCount++;
        // 仅记录到控制台，不再污染业务修正计数
        let repairPath = "未知";
        try {
          const tmp = JSON.parse(fixedRaw);
          repairPath = (tmp.path || "").replace(/^\//, "").replace(/\//g, ".");
        } catch {}
        console.log(`[MVU Guard] JSON 预修复 (${method}) 路径: ${repairPath}`);
      }

      // ------- 解析阶段 -------
      let parsed;
      try {
        parsed = JSON.parse(fixedRaw);
      } catch (e) {
        fixMessages.push(
          `❌ JSON 修复后仍无法解析: ${fixedRaw.slice(0, 50)}...`,
        );
        commands.splice(i, 1);
        blocked++;
        continue;
      }

      // 【关键修复】无论后续是否触发路径/字段修正，都先将修复后的结果写回 cmd
      cmd.full_match = JSON.stringify(parsed);
      updateCmdArgs(cmd, parsed);

      const op = parsed.op;
      let path = parsed.path || "";
      let value = parsed.value;
      let cleanPath = path.replace(/^\//, "").replace(/\//g, ".");

      // ----- 路径修正（仅当路径不存在时启用） -----
      const pathExists = validPaths.has(cleanPath);
      if (!pathExists) {
        if (op === "insert") {
          const segments = cleanPath.split(".");
          const parentPath = segments.slice(0, -1).join(".");
          if (parentPath && !validPaths.has(parentPath)) {
            const parentSegments = parentPath.split(".");
            let wrongIdx = -1;
            for (let s = parentSegments.length - 1; s >= 0; s--) {
              if (!/^\d+$/.test(parentSegments[s])) {
                wrongIdx = s;
                break;
              }
            }
            if (wrongIdx >= 0) {
              const wrongSegment = parentSegments[wrongIdx];
              const prefixPath = parentSegments.slice(0, wrongIdx).join(".");
              const candidateFields = pathFields[prefixPath];
              if (candidateFields && candidateFields.size > 0) {
                const corrected = bestMatchInSet(wrongSegment, candidateFields);
                if (corrected && corrected !== wrongSegment) {
                  parentSegments[wrongIdx] = corrected;
                  const newParentPath = parentSegments.join(".");
                  const newPath =
                    newParentPath + "." + segments[segments.length - 1];
                  fixMessages.push(
                    `路径修正 (insert父路径): "${cleanPath}" → "${newPath}"`,
                  );
                  cleanPath = newPath;
                  path = "/" + newPath.replace(/\./g, "/");
                  parsed.path = path;
                  // 再次写回，确保全量一致
                  cmd.full_match = JSON.stringify(parsed);
                  updateCmdArgs(cmd, parsed);
                }
              }
            }
          }
        } else {
          const segments = cleanPath.split(".");
          let wrongIdx = -1;
          for (let s = segments.length - 1; s >= 0; s--) {
            if (!/^\d+$/.test(segments[s])) {
              wrongIdx = s;
              break;
            }
          }
          if (wrongIdx >= 0) {
            const wrongSegment = segments[wrongIdx];
            const prefixPath = segments.slice(0, wrongIdx).join(".");
            const candidateFields = pathFields[prefixPath];
            if (candidateFields && candidateFields.size > 0) {
              const corrected = bestMatchInSet(wrongSegment, candidateFields);
              if (corrected && corrected !== wrongSegment) {
                segments[wrongIdx] = corrected;
                const newPath = segments.join(".");
                fixMessages.push(
                  `路径修正 (replace/delta): "${cleanPath}" → "${newPath}"`,
                );
                cleanPath = newPath;
                path = "/" + newPath.replace(/\./g, "/");
                parsed.path = path;
                cmd.full_match = JSON.stringify(parsed);
                updateCmdArgs(cmd, parsed);
              }
            }
          }
        }
      }

      // ----- 字段名修正 -----
      if (
        value &&
        typeof value === "object" &&
        !Array.isArray(value) &&
        (op === "insert" || op === "replace")
      ) {
        //  追踪哪些命令进入了字段修正环节
        //console.log(
        //  `[MVU Guard] 🔍 字段修正入口: op=${op}, path=${cleanPath}, dirtyCheck=true`,
        //);
        let targetFields = null;
        const lookupPath = cleanPath.replace(/\.\d+$/, "");
        if (pathFields[lookupPath]) targetFields = pathFields[lookupPath];
        else if (pathFields[cleanPath]) targetFields = pathFields[cleanPath];

        if (targetFields) {
          const newValue = {};
          let changed = false;
          for (const key of Object.keys(value)) {
            if (targetFields.has(key)) {
              newValue[key] = value[key];
              continue;
            }
            const alias = GUARD_CONFIG.FIXED_FIELD_ALIASES[key];
            if (alias && targetFields.has(alias)) {
              newValue[alias] = value[key];
              fixMessages.push(
                `字段修正: "${key}" → "${alias}"，路径 ${cleanPath}`,
              );
              changed = true;
              continue;
            }
            const bestField = bestMatchInSet(key, targetFields);
            if (bestField && bestField !== key) {
              newValue[bestField] = value[key];
              fixMessages.push(
                `字段修正: "${key}" → "${bestField}"，路径 ${cleanPath}`,
              );
              changed = true;
            } else {
              // 仅在 targetFields 存在但 key 既不是合法字段、也不是别名、也无法通过 bestMatch 修正时才告警
              if (!targetFields.has(key)) {
                console.log(
                  `[MVU Guard] ⚠️ 字段修正无法匹配: key="${key}", path=${cleanPath}`,
                );
              }
              newValue[key] = value[key];
            }
          }
          if (changed) {
            parsed.value = newValue;
            cmd.full_match = JSON.stringify(parsed);
            updateCmdArgs(cmd, parsed);
          }
        }
      }

      // [长期诊断] 捕获命令意外丢失的情况
      if (!commands[i]) {
        console.warn(
          `[MVU Guard] ⚠️ 命令已被移除! path=${cleanPath}，发生在字段修正之后、黑名单/动态规则之前`,
        );
      } else {
        // 静默通过，仅在需要追踪数据流完整性时取消注释：
        // console.log(`[MVU Guard] 🔍 字段修正结束: path=${cleanPath}, commandStillInQueue=true`);
      }

      // ----- 静态黑名单 -----
      const matchedBlacklist = GUARD_CONFIG.STATIC_BLACKLIST.find((p) =>
        cleanPath.startsWith(p),
      );
      if (matchedBlacklist) {
        fixMessages.push(
          `🚫 黑名单拦截: ${cleanPath}（匹配规则: ${matchedBlacklist}）`,
        );
        commands.splice(i, 1);
        blocked++;
        continue;
      }

      // ----- 动态规则 -----
      let ruleBlocked = false;
      for (const rule of GUARD_CONFIG.DYNAMIC_RULES) {
        if (rule.action === "fix") {
          const matched =
            matchPathPattern(rule.pathPattern, cleanPath) &&
            (rule.ops?.includes(op) ?? false);
          if (matched) {
            const result = rule.fix(parsed, cmd, { newVars, fixMessages });
            if (result) {
              cmd.full_match = JSON.stringify(parsed);
              updateCmdArgs(cmd, parsed);
              if (rule.id === "enemy-patch") enemyPatched++;
            }
          }
          continue;
        }
        if (!matchDynamicRule(rule, op, cleanPath, value, { newVars })) {
          fixMessages.push(
            `🚫 动态拦截: ${cleanPath}（原因: ${rule.description}）`,
          );
          commands.splice(i, 1);
          blocked++;
          ruleBlocked = true;
          break;
        }
      }

      // ----- 最终 JSON 语法修复（兜底）-----
      const finalRaw = cmd.full_match;
      if (finalRaw) {
        const { result: finalFixed, method: finalMethod } = fixJSON(finalRaw);
        if (finalFixed && finalFixed !== finalRaw) {
          try {
            const finalParsed = JSON.parse(finalFixed);
            // 更新 parsed 和 cmd
            Object.assign(parsed, finalParsed);
            cmd.full_match = finalFixed;
            updateCmdArgs(cmd, parsed);
            fixMessages.push(`最终 JSON 语法修复 (${finalMethod})`);
          } catch (e) {
            // 修复失败，保留原样
          }
        }
      }

      if (ruleBlocked) continue;
    }

    // 汇总修复报告
    if (enemyPatched > 0) {
      fixMessages.push(
        `🔧 已为 ${enemyPatched} 个新敌人自动计算HP/SP/MP上限与当前值`,
      );
    }

    // 汇总消息不计入业务修正条数
    const summaryOffset = enemyPatched > 0 ? 1 : 0;
    const fixCount = fixMessages.length - summaryOffset;
    const passCount = commands.length;
    // 新格式：业务修正和 JSON 修复分开列出
    fixMessages.push(
      `✅ 检查完毕 · 拦截 ${blocked} 条 · 业务修正 ${fixCount} 条 · JSON 修复 ${jsonRepairCount} 条 · 通过 ${passCount} 条`,
    );

    cachedFixedCommands = commands
      .map((cmd) => {
        try {
          return JSON.parse(cmd.full_match);
        } catch {
          return null;
        }
      })
      .filter(Boolean);
    cachedFixReports = fixMessages;

    if (fixMessages.length > 0) {
      console.log(`[MVU Guard] 智能修正了 ${fixMessages.length} 项`);
      fixMessages.forEach((m) => console.log("  🔧", m));
    }
    if (blocked > 0) {
      console.log(`[MVU Guard] 变量层拦截 ${blocked} 条命令`);
      try {
        toastr.warning(`已拦截 ${blocked} 条非法修改`, "MVU Guard", {
          timeOut: 3000,
        });
      } catch {}
    }
  });

  // ===================== BEFORE_MESSAGE_UPDATE 显示层 =====================
  eventOn(Mvu.events.BEFORE_MESSAGE_UPDATE, (e) => {
    // 取出缓存并立即清空，防止污染后续消息
    const fixedCmds = cachedFixedCommands;
    const reports = cachedFixReports;
    cachedFixedCommands = null;
    cachedFixReports = [];

    if (
      !e.message_content?.includes("<JSONPatch>") ||
      e.message_content.includes("<mvu-fix-report>")
    )
      return;

    let content = e.message_content;

    // 用修正后的命令直接替换原有 JSONPatch 内容
    if (fixedCmds && fixedCmds.length > 0) {
      const compactCommands = fixedCmds
        .map((c) => JSON.stringify(c))
        .join("\n");
      content = content.replace(
        /<JSONPatch>[\s\S]*?<\/JSONPatch>/gi,
        `<JSONPatch>\n${compactCommands}\n</JSONPatch>`,
      );
    }

    // 追加修复报告
    if (reports && reports.length > 0) {
