          /<\/JSONPatch>/i,
          `</JSONPatch>\n${fixReportBlock}`,
        );
      } else {
        content += `\n${fixReportBlock}`;
      }
    }

    e.message_content = content;
    console.log("[MVU Guard] 已更新前端显示（使用修正后命令）");
  });

  console.log("[MVU Guard] 智能修正版监听就绪");
})();

window.top.assessCombatDifficulty = async function (args) {
  // ========== 0. 等待 DungeonUtils 就绪 ==========
  const MAX_WAIT = 15000;
  const start = Date.now();
  while (!window.top.DungeonUtils || !window.top.__DungeonUtilsReady) {
    if (Date.now() - start > MAX_WAIT) {
      throw new Error("[战力评估] DungeonUtils 加载超时，请刷新页面");
    }
    await new Promise((r) => setTimeout(r, 200));
  }
  const U = window.top.DungeonUtils;

  // ========== 1. 读取全局状态 ==========
  const Mvu = window.top.Mvu || window.Mvu;
  const { enemies } = args;

  const vars = Mvu.getMvuData({ type: "message", message_id: -1 });
  const sd = vars?.stat_data || {};
  const pl = sd.主角;
  const combatConfig = sd.sysbox?.战斗系统 || {};
  const area = sd.当前地下城区域 || {};
  const floor = area.层数 != null ? area.层数 : 1;

  // ========== 2. 辅助函数 ==========
  function calcES(state) {
    const hp = state.HP当前值 ?? state.HP上限 ?? 0;
    const sp = state.SP当前值 ?? state.SP上限 ?? 0;
    const mpCur = state.MP当前值;
    const mpMax = state.MP上限;
    const hasMp = (mpCur != null && mpCur > 0) || (mpMax != null && mpMax > 0);
    return hp + sp * 0.5 + (hasMp ? 50 : 0);
  }

  function calcEO(finalStats) {
    return (
      finalStats.力量 +
      finalStats.耐力 +
      finalStats.灵巧 +
      finalStats.敏捷 +
      finalStats.魔力
    );
  }

  // ========== 3. 主角 ==========
  const plFinal = U.calcFinalStats(pl, combatConfig, floor);
  const plEO = calcEO(plFinal);
  const plState = pl.状态 || {};
  const plES = calcES(plState);

  // ========== 4. 队友 ==========
  const partyMap = sd.组队成员 || {};
  const npcList = sd.人物名录 || {};
  const memberEOs = [plEO];
  const memberProfiles = [{ name: "主角", eo: plEO, es: plES, isPlayer: true }];

  for (const name of Object.keys(partyMap)) {
    const npc = npcList[name];
    if (!npc) {
      console.warn(`[战力评估] 队伍成员 "${name}" 在人物名录中未找到，已忽略`);
      continue;
    }
    const finalStats = U.calcFinalStats(npc, combatConfig, floor);
    const eo = calcEO(finalStats);
    memberEOs.push(eo);
    memberProfiles.push({
      name,
      eo,
      es: calcES(npc.状态 || {}),
      isPlayer: false,
    });
  }

  // 我方生存能力合计
  const teamES = memberProfiles.reduce((sum, p) => sum + p.es, 0);

  // ========== 5. 敌人分析 ==========
  const enemyEOs = [];
  let enemyTotalHP = 0;

  for (const enemy of enemies) {
    const info = enemy.基础信息 || {};
    const state = enemy.状态 || {};
    const type = info.类型 || "怪物";

    var attr = enemy.个人属性 || {};
    var finalValues = attr.总能力 || {};

    const enemyPower = Object.values(finalValues).reduce((a, b) => a + b, 0);
    enemyEOs.push(enemyPower);

    // 敌人当前 HP（优先当前值，缺失取上限，再缺失动态计算上限兜底）
    let hpCur = state.HP当前值;
    if (hpCur == null) {
      hpCur = state.HP上限;
      if (hpCur == null) {
        const hpSpMp = U.calcEntityHpSpMp(finalValues, type);
        hpCur = hpSpMp.hp; // 上限
      }
    }
    enemyTotalHP += hpCur;
  }

  // ========== 6. 直接计算战损比 + 匹配颜色档位 ==========
  var teamEO = memberEOs.reduce(function(s, v) { return s + v; }, 0);
  var enemyTotalOutput = enemyEOs.reduce(function(s, v) { return s + v; }, 0);
  var turnsToKill = enemyTotalHP > 0 ? enemyTotalHP / teamEO : 0;
  var turnsToWipe = teamES > 0 ? teamES / enemyTotalOutput : 0;
  var enduranceRatio = turnsToKill > 0 ? turnsToWipe / turnsToKill : 999;

  var tier = U.matchColorTier(enduranceRatio, combatConfig);

  // ========== 7. 构造返回信息 ==========
  const enemyNames = enemies
    .map((e) => e.名字 || e.基础信息?.姓名 || "???")
    .join("、");

  return JSON.stringify({
    difficulty: tier.tierName,
    reason: `我方总输出 ${Math.round(teamEO)}，敌方总输出 ${Math.round(enemyTotalOutput)}；我方生存力 ${Math.round(teamES)}，敌方总生命 ${Math.round(enemyTotalHP)}；战损比 ${enduranceRatio.toFixed(2)}（${enemyNames}，${enemies.length}个敌人，${floor}层）→ ${tier.tierName}`,
    hp_cost_estimate: "-",
    sp_cost_estimate: "-",
    mp_cost_estimate: "-",
    teamPower: Math.round(teamEO),
    totalThreat: Math.round(enemyTotalOutput),
    ratio: enduranceRatio.toFixed(2),
    // 以下字段用于前端将经验/伟业写入敌人信息（不影响战报文本）
    _exp_per_enemy: undefined,
    _feat_per_enemy: undefined,
  });
};

