  // ── 辅助：两数取默认 ──
  function n(v, d) { return v != null ? v : d; }

  // ── 辅助：格式化持有物品 ──
  function fmtItem(item) {
    if (!item) return "";
    const q = n(item.品质, 1);
    const cat = item.类别 || "杂物";
    const price = item.单价 != null ? item.单价 + "法利" : "??法利";
    return { 数量: n(item.数量, 0), 品质: q, 类别: cat, 单价: price };
  }

  // ── 装备插槽 ──
  const equipSlots = ["主手","副手","头部","身体","护手","鞋子","饰品1","饰品2"];

