    const monsters = (area.怪物 || []).map(m => m.名字 || "???").join(", ");
    lines.push(`- **怪物**: ${monsters || "无"}`);
  }

  return lines.join("\n");
});

// 注册 status_summary 宏
// AI 在系统提示或世界书中使用 {{status_summary}} 即可获取精简角色状态

registerMacroLike(/{{status_summary}}/gi, () => {
  const vars = getVariables({ type: "message" });
  const sd = _.get(vars, "stat_data");
  if (!sd) return "无法读取角色状态。";

  const pl = sd.主角;
  if (!pl) return "角色数据缺失。";

  const area = sd.当前地下城区域 || {};
  const status = pl.状态 || {};
  const attr = pl.个人属性 || {};
  const base = attr.基础能力 || {};
  const total = attr.总能力 || {};
  const exp = attr.积累经验值 || {};

  // ── 辅助函数 ──

  function formatStatLine(stats) {
    const map = { 力量: "力", 耐力: "耐", 灵巧: "灵", 敏捷: "敏", 魔力: "魔" };
    return Object.entries(map)
      .map(([k, abbr]) => `${abbr}${stats[k] || 0}`)
      .join(" ");
  }

  function formatSkills(skillsObj) {
    const entries = Object.entries(skillsObj || {});
    if (!entries.length) return "  无";
    return entries
      .map(([name, s]) => {
        const level = s.等级 || "I";
        const type = s.技能类型 || "被动";
        const desc = s.效果描述 || "";
        const bonuses = s.加成 || {};
        const bonusText = Object.entries(bonuses)
          .filter(([, v]) => v != null && v !== 0 && v !== "")
          .map(([k, v]) => {
            if (k === "特殊") return `特殊:${v}`;
            if (typeof v === "number") {
              const sign = v > 0 ? "+" : "";
              const pct = Math.round(v * 100);
              return `${k}:${sign}${pct}%`;
            }
            return `${k}:${v}`;
          })
          .join(" ");
        return `  ${name} · ${level} · ${type}\n    ${desc}${bonusText ? "\n    加成：" + bonusText : ""}`;
      })
      .join("\n");
  }

  function formatEquip(equip) {
    if (!equip) return "无";
    const slots = [
      "主手",
      "副手",
      "头部",
      "身体",
      "护手",
      "鞋子",
      "饰品1",
      "饰品2",
    ];
    const names = [];
    slots.forEach((slot) => {
      const item = equip[slot];
      if (item?.名称) names.push(item.名称);
    });
    (equip.特殊 || []).forEach((item) => {
      if (item?.名称) names.push(`✨${item.名称}`);
    });
    return names.length ? names.join("、") : "无";
  }

  function formatGoods(goodsObj) {
    const entries = Object.entries(goodsObj || {});
    if (!entries.length) return "无";
    return entries
      .map(([name, item]) => {
        const qty = item.数量 ?? 0;
        const cat = item.类别 || "杂物";
        const price = item.单价 != null ? item.单价 + "法利" : "??法利";
        return `${name}x${qty}(${cat},${price})`;
      })
      .join("、");
  }

  function formatBag(inv) {
    const entries = Object.entries(inv || {});
    if (!entries.length) return "空";
    return entries
      .map(([name, item]) => {
        const qty = item.数量 ?? 0;
        const price = item.单价 != null ? item.单价 + "法利" : "??法利";
        return `${name}x${qty}(${price})`;
      })
      .join("、");
  }

  // ── 主角状态 ──

  const lines = [];
  const grade = attr.整体评价 || "I";
  const hp = status.HP当前值 ?? 0;
  const hpMax = status.HP上限 ?? 0;
  const sp = status.SP当前值 ?? 0;
  const spMax = status.SP上限 ?? 0;
  const mp = status.MP当前值 ?? 0;
  const mpMax = status.MP上限 ?? 0;
  const wallet = _.get(pl, "基础信息.资产.存款", 0);
  const title = pl.称号 || "无";
  const lv = attr.等级 || 0;
  const job = (attr.身份职业 || []).join("、") || "无";
  const familia = attr.所属眷族 || "无";
  const deepest = attr.到达层数 || 0;

  lines.push("[主角状态]");
  lines.push(`Lv.${lv} ${job} | 整体评价 ${grade} | 称号 ${title}`);
  lines.push(`所属眷族：${familia} | 到达楼层：第${deepest}层`);
  lines.push("");
  lines.push(
    `HP ${hp}/${hpMax} | SP ${sp}/${spMax} | MP ${mp}/${mpMax}`,
  );
  lines.push(`灵魂纯洁度 ${status.灵魂纯洁度 ?? 0}`);
  lines.push(`基础能力：${formatStatLine(base)}`);
  lines.push(`总能力：${formatStatLine(total)}`);
  lines.push(`积累经验：${formatStatLine(exp)}`);
  lines.push(`现金：${wallet} 法利`);
  lines.push("");
  lines.push(`装备：${formatEquip(pl.装备栏)}`);
  lines.push(`背包：${formatBag(pl.持有物品)}`);
  lines.push("技能：");
  lines.push(formatSkills(pl.基础信息?.技能列表));

  // ── 队伍 ──
  const party = sd.组队成员 || {};
  const npcs = sd.人物名录 || {};
  lines.push("");
  lines.push("[队伍]");
  const partyNames = Object.keys(party);
  if (!partyNames.length) {
    lines.push("无");
  } else {
    partyNames.forEach((name) => {
      const npc = npcs[name];
      const st = npc?.状态 || {};
      const curHp = st.HP当前值 ?? 0;
      const maxHp = st.HP上限 ?? 0;
      const curSp = st.SP当前值 ?? 0;
      const maxSp = st.SP上限 ?? 0;
      const curMp = st.MP当前值 ?? 0;
      const maxMp = st.MP上限 ?? 0;
      lines.push(
        `${name} HP ${curHp}/${maxHp} SP ${curSp}/${maxSp} MP ${curMp}/${maxMp}`,
      );
    });
  }

  // ── 敌人 ──
  const enemies = sd.敌人信息 || [];
  lines.push("");
  lines.push("[敌人]");
  if (!enemies.length) {
    lines.push("无");
  } else {
    enemies.forEach((e) => {
      const eName = e.基础信息?.姓名 || "???";
      const eLv = e.个人属性?.等级 || "?";
      const eSt = e.状态 || {};
      const eHp = eSt.HP当前值 ?? 0;
      const eHpMax = eSt.HP上限 ?? 0;
      const eSp = eSt.SP当前值 ?? 0;
      const eSpMax = eSt.SP上限 ?? 0;
      const eMp = eSt.MP当前值 ?? 0;
      const eMpMax = eSt.MP上限 ?? 0;
      const eStatus = e.是否击败 ? "已击败" : "";
      lines.push(
        `${eName} Lv.${eLv} HP ${eHp}/${eHpMax} SP ${eSp}/${eSpMax} MP ${eMp}/${eMpMax}${eStatus ? " (" + eStatus + ")" : ""}`,
      );
    });
  }

  // ── 人物名录 ──
  lines.push("");
  lines.push("[人物名录]");
  if (!Object.keys(npcs).length) {
    lines.push("无");
  } else {
    Object.entries(npcs).forEach(([name, npc]) => {
      const info = npc.基础信息 || {};
      const npcStatus = npc.状态 || {};
      const relation = npc.关系 || {};
      const npcAttr = npc.个人属性 || {};
      const identity =
        (npcAttr.身份职业 || []).join("、") || npcStatus.评价 || "";
      const mood = info.心境 || "--";
      const fam = npcAttr.所属眷族 || "";
      const relationType = relation.当前关系 || "陌生";
      const intimacy = relation.情深值 || 0;

      lines.push(
        `${name} · ${identity || "未知身份"}${fam ? " | " + fam : ""}`,
      );
      lines.push(
        `  心情：${mood} | 关系：${relationType} · 情深值 ${intimacy}`,
      );
      // HP/SP/MP（所有角色）
      const curHp2 = npcStatus.HP当前值 ?? 0;
      const maxHp2 = npcStatus.HP上限 ?? 0;
      const curSp2 = npcStatus.SP当前值 ?? 0;
      const maxSp2 = npcStatus.SP上限 ?? 0;
      const curMp2 = npcStatus.MP当前值 ?? 0;
      const maxMp2 = npcStatus.MP上限 ?? 0;
      lines.push(`  HP ${curHp2}/${maxHp2} | SP ${curSp2}/${maxSp2} | MP ${curMp2}/${maxMp2}`);

      // 等级信息
      const isAdventurer = info.类型 === "冒险者";
      const isMonster = info.类型 === "怪物";
      if (isAdventurer || isMonster) {
        const npcLv = npcAttr.等级 ?? "?";
        const npcGrade = npcAttr.整体评价 || "?";
        const npcFloor = npcAttr.到达层数 ?? 0;
        lines.push(`  Lv.${npcLv} | 整体评价 ${npcGrade} | 到达 ${npcFloor}层`);
      } else {
        const bodyCondition = npcStatus.身体状况;
        if (bodyCondition != null) lines.push(`  身体状况：${bodyCondition}/100`);
      }

      // 存款（所有角色都有）
      const deposit = _.get(npc, "基础信息.资产.存款") ?? 0;
      lines.push(`  存款：${deposit} 法利`);

      // 冒险者/怪物专属：基础能力、积累经验、总能力
      if (isAdventurer || isMonster) {
        const npcExp = npcAttr.积累经验值 || {};
        const npcTotal = npcAttr.总能力 || {};
        const npcBase = npcAttr.基础能力 || {};
        lines.push(`  基础能力：${formatStatLine(npcBase)}`);
        lines.push(`  积累经验：${formatStatLine(npcExp)}`);
        lines.push(`  总能力：${formatStatLine(npcTotal)}`);
        // 成长期望仅冒险者
        if (isAdventurer) {
          const npcGrowth = npcAttr.成长期望 || {};
          lines.push(`  成长期望：${formatStatLine(npcGrowth)}`);
        }
      }

      lines.push(`  装备：${formatEquip(npc.装备栏)}`);
      lines.push(`  持有物品：${formatGoods(npc.持有物品)}`);
      lines.push("  技能：");
      lines.push(formatSkills(npc.基础信息?.技能列表));
    });
  }

  return lines.join("\n");
});

